INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(10, '누락된 텍스트'),
(15, '"잘 지내십니까, 모건 형님.\r\n\r\n이곳 골드샤이어에서는 사업이 아주 번창하고 있습니다. 너무 사업이 잘 되다 보니 형님께 짐을 보낼 시간조차 없었네요.\r\n\r\n사람을 시켜 이 쪽지와 함께 대형 밀랍 양초 한 짐을 보냅니다. 코볼트들이 모자에 달고 다니는 바로 그 양초지요.\r\n\r\n짐을 가져가는 이에게 감사 인사와 함께 적당히 사례해 주셨으면 합니다."'),
(16, '"존경하는 크릴리안 교장님께,\r\n\r\n최근 이 제자가 어떤 일을 하고 있는지 궁금하실 것 같아 편지를 드립니다. 스승님의 조언대로 저는 정든 스톰윈드를 떠나 여행하면서 지식과 지혜를 쌓기 위해 노력하고 있습니다. 많은 곳을 여행한 끝에 결국 이곳 아름다운 문브룩 마을에 정착하기로 결심했습니다. 서부 몰락지대 주변의 들녘은 추수기가 다가오면서 정말 아름다운 자태를 드러내고 있습니다."'),
(17, '"이곳에 온 지 며칠 안 돼 저는 근처 농장의 아이들을 가르치기 시작했습니다. 수업이 잘 진행되자 마을의 시장님께서는 제게 학교 운영을 맡기셨고 새로운 학교를 건설하기 시작했습니다! 은빛소나무 숲에서 스톰윈드, 그리고 이제 문브룩에 이르기까지, 제가 이렇게 아제로스 곳곳을 여행하게 될 줄 누가 알았겠습니까!\r\n\r\n부디 건강히 지내십시오.\r\n\r\n스탈반 미스트맨틀 올림"'),
(18, '"친애하는 귀족 나리께,\r\n\r\n귀하의 자녀를 가르칠 가정 교사를 구하신다는 소식이 이곳 골드샤이어에 있는 저에게까지 전해졌습니다. 저는 이곳의 사자무리 여관에 임시로 묵고 있습니다. 이 지역에 닥친 불행한 사태로 인해 저는 문브룩 학교의 교장 직책을 버릴 수밖에 없었습니다. 부디 귀댁 자제의 가정 교사로 채용해 주시기 바랍니다. 필요하다면 크릴리안 교장님께서 제 능력에 대해 보증해 주실 것입니다."'),
(19, '"겨울비가 그치고 다시 도로 상황이 좋아지면 제가 직접 찾아 뵙도록 하겠습니다.\r\n\r\n그때까지 안녕히 계십시오.\r\n\r\n은빛소나무의 스탈반 미스트맨틀 올림."'),
(20, '...길리스라는 사내 아이는 좀 다루기 힘들어 보이는데 가르치기가 만만치 않을 것 같다. 하지만 누나 틸로아는 대단히 똑똑한 것 같다. 그리고 그녀의 매혹적인 아름다움 또한 말하지 않을 수 없다. 틸로아는 지금 여자로서 최고의 절정기에 있는 것 같다. 아마 영주는 내년쯤 그녀를 결혼시킬 계획인 것 같지만 난 솔직히 그러지 않았으면 한다. 이번 주에 난 이 가족들과 함께 붉은마루 산맥에서 가까운 엘윈 숲의 동부 벌목지 근처 그들의 작은 여름 별장으로 함께 여행을 떠난다. 그곳에 있는 동안 좀 더 많은 내용을 쓸 수 있길...'),
(21, '...정말 이상하고 자제할 수 없는 기분이다. 지금까지 오늘과 같은 기분은 느껴 본 적이 없다. 길리스에게 역사를 가르치는 동안 틸로아는 밖에서 꽃밭을 돌보고 있었다. 몇 분 후 그녀는 안으로 들어와 붉은 베고니아를 내 손바닥 위에 놓고는 나에게 미소를 지었다. 그때 내 심장은 터질 듯이 뛰고 있었다...'),
(22, '. . 그녀가 나에게 똑같은 감정을 공유하고 있음을 확신해라. 그녀는 심지어 오늘 아침에 내 손을 댔다. 그녀가 미소를 지을 때, 그녀의 눈은 빛나는 다이아몬드처럼 빛납니다. 무언의 말은 우리 사이를지나갑니다. 나는 두근 거리는 가슴과 뜨거운 혈관에서 그녀를 느낄 수 있습니다.'),
(23, '...내가 상상도 못 했던 분노와 격노가 치밀어 올랐다! 감히 어떻게 그럴 수가 있지? 내가 자일스에게 숫자의 의미를 가르치고 있는데, 틸로아가 구혼자와 손을 잡고 내 앞에 나타나다니! 정말 무례한 젊은이군. 틸로아는 나를 제대로 소개하는 대신, "아, 저분은 제 가정교사이신 스탈반 삼촌이세요. 좋은 분이시죠."라고만 말했다. 노인이라고? 그 말에 내 얼굴은 화끈거렸다. 겨우 몇 살 더 많을 뿐인데, 그녀는 나를 배신하다니...'),
(24, '절망의 나락으로 떨어지고 있어. 처음에는 날 조롱하더니 이제는 약혼까지 했잖아. 그 파렴치한 사기꾼은 날 사랑하는 척했지만, 사실은 처음부터 날 괴롭히고 싶었던 거였어. 내 안에는 검은 공허함이 도사리고 있고, 깨어나는 매 순간마다 그 공허함은 점점 더 커져만 간다. 내가 흘릴 피는 내가 흘린 눈물에 비하면 아무것도 아닐 거야.'),
(25, '"사랑하는 토미 조,\r\n매 순간 당신이 곁에 없다는 사실로 내 심장은 시들어 가고 있답니다. 아, 당신 가족과 우리 가족이 서로에게 했던 어리석은 죄를 넘어설 수 있다면... 진정한 죄악이 바로 증오라는 것을 깨닫게 된다면 더 바랄 것이 없겠어요. 이런 암울한 시기에 당신과 나의 가족들뿐만 아니라 더 많은 이들이 증오에 사로잡히게 될까봐 두려워요. 그들 모두 이런 사실을 깨닫게 된다면, 마침내 우리도 함께할 수 있게 될 텐데... 저는 그날을 꿈꾸며, 그날을 위해 살겠어요.\r\n당신의 사랑, 메이벨"'),
(26, '"잘 지내시는가, 윌리엄.\r\n\r\n우리가 얼굴을 맞대고 얘기해 본 지도 벌써 여러 해가 됐지만, 자네 형제가 잘 지내고 있을 뿐만 아니라 하고 있는 연금술 사업이 날로 번창하고 있으리라 믿고 있네.\r\n\r\n윌리엄, 자네에게 부탁이 한 가지 있다네. 간단히 말해서, 내 손자 토미 조가 아름다운 메이벨 맥클루어에게 마음을 뺏기고 말았네. 하지만 아무리 서로 사랑한다 하더라도 우리 양가는 수년 동안 서로 앙숙으로 지내 오고 있으니..."'),
(27, '윌리엄, 안녕. 오랜만에 연락이 닿네. 자네와 자네 동생 모두 잘 지내고 있겠지. 자네 약국도 잘 되고 있고. 윌리엄, 부탁 하나만 들어줄래? 간단히 말해서, 내 손자 토미 조가 메이벨 맥루어라는 젊은 여자에게 푹 빠졌거든. 둘이 서로 너무 좋아하지만… 우리 집안끼리는… 아주 오랫동안 원수지간이었네.'),
(28, '"아거스,\r\n\r\n자네도 알다시피 나는 군대의 수리 요청으로 눈코 뜰 새 없다네. 일이 많다고 불평할 순 없는 거지만 이제는 철마저 거의 바닥나서 말 편자에 사용할 철이 부족하네.\r\n\r\n자네는 항상 많은 철을 확보하고 있다고 알고 있네. 그러니 내가 다음번 철괴 상자를 받게 될 때까지 편자 50개를 빌려 준다면 정말 고맙겠네.\r\n\r\n- 베르너"'),
(29, '"상자에 다음과 같은 내용의 쪽지가 붙어 있습니다.\r\n\r\n""베르너 - 붉은마루 산맥에서 그런 문제가 발생했다니 정말 유감일세. 자네가 부탁한 편자를 보내네. 곧 자네 사정이 허락하는 대로 1골드 지급해 주기 바라네.""\r\n\r\n""원한다면 얇은 새끼용 비늘로 지급해줘도 상관없네. 붉은마루 산맥에는 새끼용이 흔하다고 들었네. 우린 친구 사이이니 특별히 비늘 6개만 받겠네. 그럼 이만.\r\n-- 아거스"""'),
(30, '"장군,\r\n\r\n전쟁이 일어났습니다. 우리의 멸망이 눈앞에 다가온 것입니다.\r\n\r\n국왕 폐하의 최동부 영토에서 진행되고 있는 최근 군사 활동을 보고하는 것이 레이크샤이어의 집정관으로서의 제 임무입니다. 이 보고서에는 붉은마루 산맥에 자리 잡은 레이크샤이어의 현재 상황에 대한 설명이 포함되어 있습니다."'),
(31, '돌망루 요새를 뺏긴 것은 심각한 일입니다. 이전에 드린 보고서에서 검은바위라는 오크족과 모건스라 알려진 흑마법사 간의 연합에 대해 자세히 말씀 드린 바 있습니다. 끔찍할 정도로 잔인하게 싸우는 검은바위부족 오크는 모건스의 사악한 마법의 지원을 받은 게 분명합니다. 폐하의 용감한 수많은 병사들이 요새를 방어하다 죽어갔지만 결국 아무 소용이 없었습니다.'),
(32, '이상한 점은 놈들이 비열한 승리를 거둔 직후 모건스가 갑자기 자신의 오크 군대를 공격했다는 점입니다. 이 흑마법사는 북동 지역에 괴이한 탑을 건설하고 자신의 힘을 이용해 소규모의 잿빛가죽놀 군대를 구성하여 자신의 사악한 명령을 따르도록 하고 있습니다. 오크와 인간이 모두 이 흑마법사를 따르는 더러운 짐승들에게 희생을 당하고 있는 것입니다. 모건스와 검은바위부족의 지휘관인 가스일조그 사이에 어떤 배신 행위가 있었는지에 대해서는 현재로선 추측만 가능한 상황입니다.'),
(33, '또한 위험한 사실은 이 괘씸한 오크들이 폐하의 선량한 백성들을 해치는 데 총력을 다하고 있다는 점입니다. 2주 전 검은바위부족은 레이크샤이어에 무자비한 공격을 감행했습니다. 끔찍했던 이날 수많은 우리의 전사들이 목숨을 잃었습니다. 오크 군대는 무서운 속도와 기세로 진군하여 영원의 호수와 연결되는 다리가 붕괴되고 말았습니다. 아군은 전쟁 보급품이 크게 줄어들었습니다. 부상자의 상처를 치료할 붕대가 부족합니다.'),
(34, '레이크샤이어의 선량한 주민들을 위해 필요한 물자를 지원해 주시기를 폐하께 간곡히 부탁 드립니다. 또한 영토를 방어할 신병과 전장에서 유실된 장비를 대체할 새 장비가 필요합니다. 식량과 건설 자재 역시 거의 바닥난 상태입니다. 부디 인간과 저 비열한 오크 사이에 남아있는 마지막 요새를 든든히 지킬 수 있도록 도와주십시오. 기필코 스톰윈드 왕국을 적의 손으로부터 지켜 내야만 합니다.'),
(35, '"이미 악의 온상이 되어 버린 북부 지역에서 더 크고 심각한 악의 세력이 자라나고 있을까 우려됩니다. 우리 모두가 희생되거나 적의 노예가 되지 않으려면 반드시 우리 스톰윈드 왕국이 행동을 취해야 합니다.\r\n\r\n서명\r\n스톰윈드 왕국\r\n레이크샤이어 마을\r\n집정관 솔로몬"'),
(36, '"집정관 솔로몬 귀하.\r\n\r\n죽은 이들에 대해 심심한 조의를 표하는 바이네. 국왕 폐하께서 이러한 상황을 파악하고 계신지 직접 알아보도록 하겠네. 그리고 레이크샤이어에 증원군을 보낼 수 있게 되기를 진심으로 바라고 있네. 귀하를 믿고 하는 이야기지만, 폐하는 요즘 뵙기 어려울 뿐 아니라 좀 이상한 행동을 보이고 계시네.\r\n\r\n다시 소식 전할 때까지 부디 안녕히.\r\n\r\n스톰윈드 왕국 장군\r\n마커스 조나단"'),
(38, '"스타우트맨틀 경 -\r\n데피아즈단 문제를 논의하는데 어떻게 생판 모르는 자를 보낼 수 있습니까? 경은 이전에 제 생명을 구해 놓고는 이제 와서 큰 위험에 빠뜨리는군요. 어쨌든 당신에게 빚이 있으니 도와드리도록 하겠습니다. 데피아즈단은 생각보다 훨씬 거대한 조직입니다. 서부 몰락지대에서 엘윈 숲에 이르는 모든 광산이 놈들의 수중에 들어갔습니다. 게다가 코볼트와 놀들이 놈들의 더러운 일에 동참하고 있습니다. 또한 지역 주민들의 미신을 없애기 위해 고블린을 시켜서 금속 괴물을 만들어 서부 몰락지대 들판에 갖다 놓도록 하고 있습니다."'),
(39, '"놈들은 경이 알고 있는 것보다 훨씬 큰 규모의 거대 지하 망을 구축했습니다. 이 지하 망은 무법항에서 곧장 스톰윈드 왕궁까지 연결됩니다. 경이 놈들을 지하에 몰아넣으면 그만이라고 생각한다면 용감한 성기사에서 둘도 없는 바보가 될 겁니다. 또한 놈들은 대량 살상 무기까지 만들고 있습니다. 아무튼 석공들이 아는 거라곤 뭐든 크게 만드는 것뿐이니까... 설마 이제 이걸 호박 농장이나 포도밭에서 생기는 하찮은 문제라 생각하지는 않겠지요? 경에게 진 빚은 갚았으니, 이제 그만 날 내버려 둬 주세요!\r\n- 와일리"'),
(41, '"스타우트맨틀 경 -\r\n\r\n에드윈 밴클리프가 이끄는 석공 길드는 인간 최고의 건축가들로 구성되어 있었습니다. 이 석공들은 첫 번째 전쟁 동안 오크들에 의해 파괴된 스톰윈드의 도시 재건을 도왔습니다. 밴클리프와 그의 숙련공들은 비길 데 없는 건축가들이며 그들의 기술과 예술성은 빛의 대성당과 스톰윈드 왕국 건축물만 봐도 여실히 확인할 수 있습니다."'),
(42, '하지만 엘윈 숲과 가시덤불 골짜기에 이르는 왕국 군대의 무모한 팽창으로 스톰윈드의 귀족들은 막대한 부채를 떠안고 있습니다. 이 막대한 부채로 인해 왕국의 재정이 흔들리고 밴클리프와 그의 석공들은 약속된 보수를 받지 못했습니다. 석공들은 수년 동안 영광스러운 도시의 재건을 위해 애쓰고도 한푼의 보수도 받지 못해 파산 상태로 도시의 부패한 관리들로부터 외면당했지요.'),
(43, '"평생 동안 에드윈 밴클리프와 개인적인 친분이 있는 사람으로서, 감히 말씀드리건대 그를 적으로 돌리는 것은 위험천만한 일입니다. 아시다시피, 그는 제 죽마고우로 언젠가 저와 함께 일하게 될 것이라 생각해서 제가 직접 남모르게 그를 훈련시켰습니다. 밴클리프가 데피아즈단을 이끌게 된다면 신께서 우리에게 자비를 베푸시기를 바랄 수밖에 없습니다.\r\n\r\n스톰윈드 암살단 길드\r\n단장 마티아스 쇼"'),
(44, '평생 에드윈 밴클리프를 알고 지낸 사람으로서 말씀드리건대, 그를 적으로 상대하는 일은 결코 만만치 않습니다. 그는 제 어린 시절 친구였고, 언젠가는 저와 같은 길을 걷게 되리라 생각해 제가 직접 그림자 속에서 싸우는 법을 가르쳤습니다. 밴클리프가 정말 데피아즈단을 이끌고 있다면, 빛이여, 부디 우리 영혼에 자비를 베푸소서. 수장 마티아스 쇼, 스톰윈드 암살단'),
(45, '"제법이군 그래, 친구! 이제 정동 쪽을 향해 갈 차례요. 동쪽 절벽 위의 길을 따라 동쪽으로 가시오. 길가에서 낡은 굴뚝의 잔해를 발견하게 되면 다음 단서가 들어 있는 낡은 통을 발견하게 될 것이오."'),
(46, '이 통에서 북쪽을 향해. 까마귀가 날아가듯 곧장 걸어가다 보면 바닷가 절벽의 외딴 풍차 옆에 빈 술병 하나가 보일 거야. 그 병 주변을 잘 뒤져 보면 네가 찾는 게 나올지도 모르지.'),
(47, '내 낡은 위스키 병까지 찾았다면 보물은 이제 코앞이야! 병을 등지고 서쪽으로 향해 해안까지 내려가. 물에 닿아도 멈추지 말고 계속 가! 그대로 서쪽으로 헤엄치면 내 보물상자가 있는 섬을 찾게 될 거야!'),
(48, '"검은발톱에게\r\n\r\n바다가 우리를 기다리고 있다. 우리는 북쪽에서 보내 오는 그대들의 보급품이 필요하다. 모든 철로와 물통 등 모든 걸 약탈하도록 하라. 우리는 금속이 필요하다. 무법항에서 물자가 오기로 했으나 이미 오랫동안 지체되고 있다. 검은발톱이여, 나를 위해 힘을 내라. 이번에는 보급품을 창고로 직접 보내도록 하라. 지체할 시간이 없다.\r\n\r\n- 밴클리프"'),
(49, '"스타우트맨틀 경 귀하\r\n\r\n레이크샤이어는 정중히 귀하의 민병대에 지원을 요청하는 바입니다. 이 글을 쓰고 있는 지금 우리는 검은바위부족 오크와 모건스의 잿빛가죽놀에게 포위되어 있습니다. 이 정도로 상황이 심각하지 않았다면 이런 청을 드리지 않았을 것입니다. 현재 스톰윈드로부터의 증원군을 기다리고 있기는 하지만 증원군이 도착할 때까지 힘을 빌려 주시기 바랍니다. 왕국이 침략당한다면 모든 인간들이 위험에 빠지게 됩니다.\r\n\r\n집정관 솔로몬\r\n"'),
(50, '존경하는 판사님— 서부 몰락지대의 모든 사람들이 당신의 죽음을 애도하고 있습니다. 하지만 저희 서부 몰락지대 역시 내전으로 고통받고 있습니다. 농부들은 도적과 기계 골렘들에게 쫓겨났고, 스톰윈드는 군대를 철수시켜 백성들을 무방비 상태로 내버려 두었습니다. 스톰윈드의 철수 이후, 저는 이 땅에 남은 것을 지키기 위해 민병대를 소집했습니다. 민병대를 이끌고 붉은마루로 향하는 것은 서부 몰락지대에 파멸을 의미할 것입니다. 깊은 애도를 표하며, 그리안 스타우트맨틀'),
(51, '에본록 경--- 레이크샤이어 마을은 어둠의 순찰대의 도움을 간곡히 요청합니다. 저희는 검은바위 오크와 모르간의 그림자가죽 놀의 공격을 받고 있습니다. 상황이 심각하지 않았다면 이렇게 도움을 청하지 않았을 것입니다. 스톰윈드의 지원을 기다리고 있지만, 지원군이 도착할 때까지 부디 도움을 주시기를 간곡히 부탁드립니다. 왕국이 함락되면 모든 인류가 위험에 처할 것입니다.- 치안판사 솔로몬'),
(52, '"존경하는 집정관 귀하\r\n\r\n현재 어둠의 순찰대는 다크샤이어의 위수 지역을 이탈할 수 없음을 전해 드리게 되어 유감입니다. 스톰윈드가 더 이상 이 지역에 군사 지원을 하지 않는다는 사실을 모르고 계신 것 같습니다. 어둠의 순찰대는 스톰윈드가 철수한 다크샤이어를 방어하기 위해 순수하게 그늘숲 주민들로 조직되고 훈련된 부대입니다. 어둠의 순찰대가 자리를 비우게 되면 마을은 파괴될 것입니다. 귀하가 계신 곳의 상황이 좋아지기를 바랍니다.\r\n\r\n- 엘로 이본로크 경"'),
(53, '이 쪽지의 글자는 표면 전체에서 깜박이고 춤추는 것처럼 보입니다. 그들에게서 의미를 수집하는 것은 불가능합니다 ...'),
(54, '다크샤이어의 시장 엘로 에본록에게 안부를 전합니다. 유감스럽게도 당신의 마을에 끔찍한 소식이 있습니다.\n\n저는 창조자입니다. 이 편지를 가진 자를 속여 제 최신작이자 가장 끔찍한 창조물, 살과 뼈, 그리고 뒤틀린 금속으로 이루어진 악마를 만드는 데 가담하게 했습니다! 당신이 이 편지를 읽는 지금쯤이면, 그 악마는 제 누추한 집 밖에서 이를 갈며 제 명령이 내려지기를 기다리고 있을 겁니다.\n\n하지만 곧 알게 되실 겁니다.\n\n-시체방부처리사'),
(55, '"이것은 서부 몰락지대 내의 토지에 대한 등기 권리증입니다. 이 증서는 아래에 명시된 이들에게 지정된 지역과 지역 경계 내에서 생산되는 모든 재화와 건축된 모든 구조물에 대한 소유권을 부여합니다.\r\n\r\n서명인: 시어도어 펄브로우, 베르나 펄브로우"'),
(56, '"[증서의 뒷면에 아래 내용이 급히 휘갈겨 쓰여 있습니다.]\r\n\r\n우리는 펄브로우를 위협해 놈에게서 땅문서를 받아 냈다. 이곳 땅 중 일부를 손에 넣으려면 이 방법이 가장 편리할 거라 생각됐다. 펄브로우 가족은 더 이상 우리에게 문제를 일으키지 않을 것이다. 마지막으로 그들을 본 게 서부 몰락지대를 떠나는 길에 마차가 고장 나 꼼짝 못하고 있는 모습이었다."'),
(58, '"골짜기의 달은 밝게 빛나리\r\n조국과 신성한 영토를 수호하라는 부름에\r\n귀 기울이는 자랑스러운 전사들이 있는\r\n정글 위를 밝게 비추고 있나니\r\n골짜기의 달은 밝게 빛나리\r\n저 높은 곳에서\r\n적과 아군이 함께 피 흘리는\r\n전투의 울음소리를 비추고 있나니"'),
(59, '"그리고 우리 형제들이\r\n미지의 땅을 지날 때\r\n골짜기 아래 깊은 곳에서\r\n그들의 영혼이 강건해지리\r\n\r\n그리고 우리 형제들이\r\n산맥의 신전을 지날 때\r\n우리는 신성한 파란 수정 속에 깃든\r\n그들의 영원한 영혼을 지켜야 하리\r\n\r\n그리고 우리 형제들이 지날 때\r\n골짜기의 달은 밝게 빛나리"'),
(62, '"달과 불로,\r\n살과 뼈로,\r\n피로 쓰고,\r\n돌에 새길지니.\r\n이 땅을 떠나거나\r\n너의 운명을 맞으라\r\n너의 죽음으로\r\n제왕의 무덤을 지키리라."'),
(63, '카레빈 님, 이 편지를 지닌 자는 $g 자신이:자신이; 빛의 뜻을 굳건히 따르며 그늘숲 경계를 위협하는 언데드와 악마에 맞설 능력이 있고, 카레빈 가문과 함께 빛의 대의를 따를 의지가 있음을 증명했습니다. 그러므로 이 빛의 전사에게 더 많은 임무를 맡겨 주시기를 권합니다. 예를 들어 빛의 적들을 돕는다는 의심을 받는 마을 사람들을 조사하는 일 말입니다. 충실한 벗, 칼로르 '),
(64, '"모건 래디모어는 선량한 사람들과 가난한 자들, 그리고 고통 받는 이들을 보호하기 위해 싸웠던 위대하고 고귀한 기사였다. 여러 해 동안 그는 아제로스 외곽 지역에서 열심히 싸우며 고통받는 자들의 짐을 덜어 주고 악한 자들에게는 신속히 정의의 심판을 내렸다.\r\n\r\n그는 18세 되던 해 여름, 리스라는 어린 소녀와 결혼했다. 그들은 서로 깊이 사랑했으며 아들 하나와 딸 둘, 모두 세 아이를 낳았다."'),
(65, '"로데론에서 전쟁이 발발하던 당시 모건은 32세였다. 모건은 전설적인 성기사인 빛의 수호자 우서 경의 부름을 받아 그와 함께 오크와 언데드에 맞서 싸웠다. 아내와 아이들을 안전한 집에 남겨두고 모건은 전쟁터로 향했다.\r\n\r\n전쟁은 몇 해가 흐르도록 계속되었고, 모건은 은빛 성기사단의 해체, 우서의 죽음, 역병의 확산과 같은 많은 끔찍한 일들을 겪었다. 그가 온전한 정신을 유지할 수 있었던 것은 오직 언젠가 아내와 아이들을 다시 만나게 되리라는 희망 때문이었다."'),
(66, '"마침내 모건은 고향으로 돌아왔지만 그가 기억하는 고향과는 전혀 다른 모습뿐이었다. 울창했던 숲은 오염되어 언데드와 다른 악의 세력이 창궐해 있었다. 어딜 가나 파괴된 집과 농장이 즐비했고, 까마귀 언덕 근처의 공동 묘지가 이제 지역의 대부분을 차지하고 있었다. 놀라고 당황한 모건은 집으로 향했으나 그곳엔 폐허만이 있을 뿐이었다."'),
(67, '고향에 무슨 일이 일어난 것인지 알 수 없었던 그는 아내와 아이들을 만나게 되길 바라면서 사정을 알아보기 위해 마을로 향했다. 모건은 가족에 대해 수소문해 봤으나 아무도 아는 이가 없었다. 그러던 중 그는 다크샤이어라 불리는 곳의 한 사제로부터 까마귀 언덕에 있는 묘지에서 묘비를 찾아보라는 말을 듣게 되었다. 모건은 가족이 세상을 떠났으리라고는 생각지 못하고 그늘숲의 모든 농장과 집을 계속 찾아다녔지만 소용이 없었다.'),
(68, '그는 혹시 가족이 안전을 위해 도피했을지도 모른다는 생각에 다크샤이어에서 근방의 레이크샤이어로 가 보았다.  도중에 그는 혹시나 하는 마음으로 까마귀 언덕 묘지에 들르기로 했다. 묘비들 사이를 몇 시간 동안 헤매던 모건은 전에 알던 사람들의 이름을 많이 발견하고 점점 더 깊은 불안에 빠져 갔다. 결국 많은 무덤 가운데 아무렇게나 방치되어 있는 작은 땅덩이와 세 개의 작은 묘비를 보게 되었다. 가까이 다가갈수록 공포가 그를 엄습했다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(69, '"모건은 그 중 가장 큰 묘비의 먼지를 쓸어내고 묘비에 쓰인 이름을 확인했다. 무덤 위에 단출하게 새겨져 있는 다음과 같은 글자는 그의 끔찍한 공포를 현실로 확인시켜 주었다.\r\n리스 래디모어\r\n한 남자의 사랑스런 아내이자 아이들의 어머니, 여기 잠들다\r\n모건의 불안은 경악으로 바뀌었고, 그리고 다시 그것은 깊은 슬픔이 되었다. 그는 무릎을 꿇고 앉아 눈물을 흘리기 시작했다. 여러 시간 동안 그 무덤을 바라보며 차가운 묘비에 흐느껴 울며 용서를 빌었다."'),
(70, '그리고 몇 시간이 흐른 뒤 그는 안에서 뭔가가 번쩍한 듯 급히 움직이기 시작했다. 검집에서 검을 꺼내 들자 묘비 위로 비바람이 일기 시작했고 그는 분노로 울부짖었다. 분노에 사로잡힌 그는 거친 몸짓으로 검을 크게 휘둘렀고 세 명의 묘지기의 눈에 띄게 되었다. 그들이 그를 진정시키려 하자 그는 죄 없는 묘지기들을 향해 비난의 말을 퍼붓고는 모두 죽여 버렸다.'),
(71, '잠시 후 분노가 가라앉고 정신을 차린 모건의 눈에는 묘지기 중 한 명의 가슴에 박힌 피 묻은 그의 검이 들어왔다. 복받치는 감정을 이기지 못한 그는 허리에 차고 있던 칼을 꺼내 자신의 심장을 찔렀다. 이튿날 모건 래디모어의 시신과 그에게 희생된 다른 세 구의 시신이 발견되었다. 그는 장례식도 없이 묘지 한쪽 구석에 급히 만든 무덤에 바로 매장되었다. 평소 그의 신념이나 본성과는 정반대로 죄 없는 이들을 살해했다는 사실과'),
(72, '가족을 지키지 못했다는 슬픔으로 모건은 평온하게 죽을 수 없었고 편히 잠들지 못하는 영혼으로 남게 되었다. 불과 며칠 후에 그의 무덤이 다시 파헤쳐졌으나 시신을 찾을 수 없었다. 모건은 이제 아내와 아이들을 잃은 슬픔과 자기 혐오로 스스로를 질책하며 그늘숲을 떠돌고 있다. 스스로를 모르라딤이라 칭하며 어리석은 복수심과 증오에 눈이 멀어 무차별적으로 살인을 저지르는 것으로 알려져 있다.'),
(73, '지난 몇 주 동안의 공포는 참기 힘든 것이었다. 하지만 내가 본 것을 기록해 두면 마음이 조금은 편안해질 것 같다. 그래서 이렇게 글을 쓰는 것이다. 그리고 이것이 이 암울한 날에 내가 찾을 수 있는 유일한 위안이다.'),
(74, '"첫째 날\r\n수습생과 나는 오늘 눈마루 골짜기에 도착했다. 동굴을 통해 여행하는 동안에는 거의 아무 일도 없었다. 트롤이 모여 있다는 동굴에서 적당히 떨어진 곳에 야영지를 설치했다.\r\n둘째 날\r\n그 괴로운 늑대 울음소리 때문에 거의 한숨도 자지 못했다. 며칠 내에 새로운 늑대 가죽 옷을 얻게 될 것이다. 오늘 수습생이 트로그와 맞붙어 용감히 싸웠다."'),
(78, '이 갑옷 문장을 동부 벌목지에 있는 팀버레인 가족에게 가져가면 가죽이나 헝겊으로 만든 갑옷과 교환할 수 있습니다.'),
(79, '"아래 내용은 엘윈의 광산들에서 서부 몰락지대의 우리 본부까지 데피아즈단이 황금을 징수하는 과정과 일정이다.\r\n \r\n징수 일정:\r\n\r\n일요일 오후 12시 30분\r\n\r\n수요일 오후 12시 30분\r\n\r\n각 지정일까지 엘윈의 광산에서 채굴된 황금을 브랙웰 호박밭으로 수거한다. 수거 담당자인 `징세관`은 문자가 새겨진 반지로 확인할 수 있다. 그 반지는 내가 그에게 준 것이다."'),
(80, '"그렐린,\r\n\r\n난 앞으로 살아갈 날이 얼마 남지 않았고 많은 골칫거리들이 내 수명을 재촉하고 있군그래. 부디 트롤에 대한 자네의 조사만은 순조롭게 진행되길 바라네. 트롤을 상대하는 데 필요하다면 언제든지 내 권위를 사용할 수 있도록 허락하지. 그렇게 해서 적절한 해결책을 찾을 수 있다면 말일세.\r\n\r\n마그니 브론즈비어드"'),
(81, '"간신히 그 추한 짐승들을 물리쳤지만 팔에 심한 상처를 입고 지금 치료 중이다. 한동안은 자잘한 일들을 내가 직접 해야 할 것 같다.\r\n셋째 날\r\n춥다. 정오 무렵에 눈이 조금 내렸다.\r\n넷째 날\r\n오늘 수습생이 다시 원기를 회복했고, 우리는 처음으로 트롤들을 살펴보았다. 몸에 있는 반점과 몸에 걸친 여러 가지 장신구들 때문에 나는 그들을 서리갈기트롤이라 부르기로 했다."'),
(82, '"다섯째 날\r\n수습생에게 야영지를 지키도록 하고 나는 몰래 동굴로 숨어 들어가 주변을 살펴보았다. 트롤의 수는 다소 우려될 정도였다. 동굴을 점령하고 있는 트롤을 모두 몰아내려면 산악경비대를 대거 소집해야 할 것 같다.\r\n한동안 트로그에 대해서는 언급하지 않은 것 같다. 이 지역에 출몰하는 트로그의 수는 트롤보다 많지만 너무 미개하여 그다지 큰 위협이 되지는 않는다. 내 판단이 옳은지는 좀 더 두고봐야 할 것이다."'),
(83, '"그리고 거의 일주일 동안 에일 맥주는 한 방울도 입에 대지 못했다.\r\n여섯째 날\r\n오늘도 춥고 눈이 내린다. 트롤을 봤고 에일 맥주는 마시지 못했다.\r\n일곱째 날\r\n눈이 새하얗게 쌓였다. 하늘이 정말 파랗다. 밤에는 늑대가 또 울부짖을 것이다. 그리고 여전히 맥주는 입에 대지도 못했다."'),
(84, '"여덟째 날\r\n우리가 처음에 생각했던 것처럼 트롤들이 큰 문제가 되지 않을지도 모르겠다. 그 수는 상당하지만 무기가 형편 없고 조직적이지도 못하다. 적은 수의 병력으로도 충분히 놈들을 상대할 수 있을 것이다."'),
(85, '"내 일지\r\n\r\n지난 몇 주 동안의 공포는 참기 힘든 것이었다. 이렇게 일지를 기록하면서 미치지 않고 버틸 수 있게 되는 이유는 무엇일까? 마치 아무 말도 하지 않는 동료에게 죄를 고백하는 것이 마음 속의 괴로운 생각들을 종이 위에 풀어놓고 덮어두는 것과 마찬가지이기 때문일지도 모르겠다. 전에도 일지를 썼었지만 그 일지는 내가 돌아갈 수 없는 곳에 남겨져 있다. 그래서 새로 일지를 작성하는 것이다. 하지만 이번에는 진정 처음부터 시작하리라."'),
(86, '"눈마루 골짜기 전역의 서리갈기트롤에 대한 보고서\r\n\r\n작성: 그렐린 화이트비어드, 원로원 특사\r\n\r\n그 동안 눈마루 골짜기 지역에서 서리갈기트롤들의 동태를 조사한 결과, 이들이 해당 지역에 거주하는 드워프의 안전에 큰 위협은 되지 않는다는 결론에 이르렀습니다. 또한 이들은 소수의 군병력만 추가로 지원된다면 제거할 수 있을 정도로 그리 위협적이지는 않습니다."'),
(87, '"이미 눈마루 골짜기에 배치된 산악경비대와 용병들의 지원으로 문제가 신속히 해결될 것이라 믿고 있습니다. 이들은 제가 파견하기 전 원로원에서 배정한 예산으로 고용되었습니다.\r\n\r\n이 조치는 브론즈비어드 폐하께서 제게 부여하신 권한에 의거해 실행되었습니다."'),
(88, '"던 모로 전역의 서리갈기트롤에 대한 보고서\r\n\r\n던 모로의 트롤들은 서쪽 변방의 산속 동굴인 서리갈기 소굴에 대거 집결해 있습니다. 그들의 수는 우려가 될 만큼 많지만 동굴에서 나올 생각은 없는 듯합니다. 또 다시 드워프의 분노를 자극해 몰살당하는 일이 없도록 하려는 것임이 분명합니다. 그들의 활동은 대체로 지역적으로 제한돼 있다고 볼 수 있으며"'),
(89, '"우리가 그들의 영역을 침범하지 않는 한 우리에게 큰 위협이 되지는 않을 것이라 판단됩니다. 이것이 드워프 주민들에게는 별 상관없는 상황이겠지만, 병력이 분산되어 있다는 점을 감안할 때 트롤을 전멸시키는 문제의 중요성은 조금 낮추고 트로그와 검은무쇠 드워프의 위협에 계속 초점을 맞추는 것이 현명할 것입니다.\r\n제 동생인 그렐린이 앤빌마에 대해 쓴 보고서 한 부를 동봉합니다.\r\n\r\n서명: 세니르 화이트비어드"'),
(90, '"눈마루 골짜기 전역의 서리갈기트롤에 대한 보고서\r\n\r\n작성: 그렐린 화이트비어드, 원로원 특사\r\n\r\n그 동안 눈마루 골짜기 지역에서 서리갈기트롤들의 동태를 조사한 결과, 이들이 해당 지역에 거주하는 드워프의 안전에 큰 위협은 되지 않는다는 결론에 이르렀습니다. 또한 이들은 소수의 군병력만 추가로 지원된다면 제거할 수 있을 정도의 위협입니다. 이미 눈마루 골짜기에 배치된 산악경비대와"'),
(91, '"용병들의 지원으로 문제가 신속히 해결될 것이라 믿고 있습니다. 이들은 제가 파견되기 전에 원로원에서 배정한 예산으로 고용되었습니다.\r\n\r\n이 조치는 브론즈비어드 폐하께서 제게 부여하신 권한에 의해 실행되었습니다."'),
(92, '"사랑하는 타렐에게\r\n서둘러 답장을 써서 미안해요. 하지만 지금 이곳에서는 시간이 넉넉지 않답니다.\r\n\r\n발굴단은 상당한 진척을 이루어 중요한 티탄 유물들을 발굴해 냈어요. 그런데 추가로 커다란 뼈와 같은 다른 고대 유물들도 발견되기 시작했어요."'),
(93, '뼈 발굴이 시작되고 얼마 지나지 않아 우린 랩터의 공격을 받고 말았어요. 롱브레이드 연대 소속 병력이 용감히 맞서 싸웠지만 결국 놈들에게 제압당하고 말았죠. 거의 전멸하고 우리 세 명만 살아남았으니까요. 오머 아이언브레이드라는 인부가 저와 발굴조사단장 웰가르님을 안전하게 지켜 줬어요. 얼마나 용감하던지...'),
(94, '"지금은 안전한 동굴에 피신해 있어요. 별다른 위험은 없을 것 같아 보이지만 랩터를 처리할 병력이 투입될 때까지 우린 꼼짝없이 갇히게 됐어요. 웰가르님은 작업을 계속하려고 하시지만 아직도 많이 겁을 먹고 계신 것 같아 보여요. 지금 우리는 이런 상황이에요, 타렐. 즉시 구조 병력을 보내도록 롱브레이드님을 설득해 주세요.\r\n\r\n이런 절박한 상황에서도 당신을 향한 제 사랑은 너무나 강하답니다.\r\n\r\n- 당신의 아내 메린"'),
(95, '가시덤불 골짜기의 푸른 언덕 - 첫째 날은 보통 그렇듯이 순조롭게 지나갔다. 우리는 기지 구축을 위해 필요한 준비를 하는 데 대부분의 시간을 보냈다. 나는 담수가 흘러드는 강어귀 가에서 이상적인 장소를 찾아냈다. 근처에 낡고 버려진 부두가 있는 걸로 보아 이곳은 예전에 어떤 종족이 거주하던 곳인 것 같다. 그러나 원래 누가 살던 땅이었는지는 시간이 흘러야만 알 수 있을 것이다.'),
(98, '그 후 스톰윈드가 석공 길드를 배신한 사건 이후, 얼가딘 경은 왕국 내 귀족들의 역할에 대해 점점 더 씁쓸함을 느끼게 되었습니다. 그는 더 이상 아버지의 혈통이 자신에게 안겨준 귀족 가문의 지위를 유지하고 싶지 않았습니다.$B$B하지만 이야기가 옆길로 샜네요. 이 이야기는 정치 논문이나 전기가 아닙니다. 이것은 제가 가시덤불 골짜기의 푸른 언덕에서 대형 사냥감을 사냥하며 겪은 경험에 대한 이야기입니다.'),
(100, '내가 아제크가 오늘의 사냥 전략에 별 관심이 없는 이유를 묻으려던 찰나, 그녀는 화살통에 손을 뻗어 화살을 뽑아 불쌍한 바르닐을 향해 쏘았다. 하지만 아제크가 쏜 화살은 바르닐을 향한 것이 아니었다. 바르닐이 입을 쩍 벌리고 옆으로 비켜서자, 커다란 강악어가 수면 위로 떠올랐고, 아제크의 화살은 악어의 커다란 두 눈 사이에 정확히 박혔다.'),
(102, '"바닐이 한 발짝 발을 헛디디자 얼가딘 경은 그 큰 손으로 바닐의 어깨를 잡았다. 아제크와 나는 그가 다만 부주의한 바닐에게 꼭 필요한 따끔한 질책을 하는 거라고 생각하며 별생각 없이 쳐다보았다. 하지만 얼가딘 경은 머리로 천천히 근처에 쓰러져 있는 나무를 가리켰다. 거기엔 면도날 같이 날카로운 송곳니 바로 위로 두 개의 검은 눈이 뚫어질 듯 무섭게 우릴 쏘아보고 있었다.\r\n"'),
(104, '놈의 죽음으로 원정대는 축제 분위기에 휩싸였다. 바닐은 모두가 즐길 수 있도록 벌꿀술을 따라 주었으나 축제는 오래가지 못했다. 시체를 다시 기지로 보내기 위해 준비하느라 모두 방심하고 있던 중에 끔찍한 으르렁거리는 소리가 들려 온 것이었다. 내 생애에서 피가 얼어 붙는 것처럼 그렇게 섬뜩한 소리는 다시 들어 보지 못했다.'),
(105, '저 위 바위투성이 절벽 위에서, 석양에 실루엣처럼 드러난 그 맹금류는 내가 여태껏 본 것 중 가장 큰 녀석이었다. 나는 소총으로 서투르게 한 발을 쏘았지만, 그 녀석은 꼼짝도 하지 않았다. 다시 한번, 이번에는 처음보다 더 크게 으르렁거리더니$B$B사라졌다. 우리는 짐을 챙겨 엄숙하게 캠프로 돌아갔다.'),
(108, '"오늘은 새로운 퓨마 흔적을 쫓아 남쪽으로 사냥을 나갔다. 출발한 지 얼마되지 않아 우리는 밧줄로 만들어진 멋진 다리가 놓인 계곡에 이르렀다. 기술이 낳은 이 경이로운 다리를 보는 순간 나는 이 지역을 묘사한 브란의 글을 떠올리지 않을 수 없었다. 종종 트롤 원주민은 원시적이고 교육 받지 못한 종족이라 생각했지만, 뛰어난 기술로 만들어진 다리를 올려다 보면서 나는 이 불가능해 보이는 일을 이뤄낸 트롤 건축가들의 솜씨를 인정하게 되었다."'),
(110, '아제크와 엘르가딘 경은 흔들리는 나무 밑동의 무성한 덤불을 향해 총을 겨누고 자세를 잡았다. 한낮의 태양이 우리에게 강렬하게 내리쬐었다. 엘르가딘이 안전핀을 당기자 그의 관자놀이에서 땀방울이 천천히 흘러내렸다. 딸깍 소리와 함께 빽빽한 덤불이 갈라지더니, 크고 아름다운 검은 표범 한 마리가 평원으로 뛰쳐나왔다.'),
(112, '그의 총이 팔에서 세게 뒤로 튕겨 나갔다. 총구가 옆으로 휘청거리며 아제크의 소총 아래로 들어왔다. 아제크는 바로 그 순간 방아쇠를 당겼다. 조준이 나무숲 쪽으로 어설프게 쏠린 소총은 굉음과 함께 발사되었다. 새 떼가 나뭇가지 사이로 비명을 지르며 사방으로 흩어졌다. 나무에서 연기가 피어올랐다. 우리는 거대한 나뭇가지가 도망치던 표범 위로 떨어져 표범의 등이 부러지는 모습을 경외심을 가지고 지켜보았다.'),
(114, '"우리는 해가 뜨자마자 트카시 폐허를 지나 남쪽을 향해 출발했다. 바닐은 붉은머리부족과 마주치게 되지 않을까 걱정했다. 나는 바닐에게 붉은머리부족은 그들 일족의 숙적인 백골가루부족을 처치하는 데 여념이 없을 거라고 상기시켜 주었다. 물론 바닐은 전혀 안심하지 않았지만, 나는 장전된 총, 화약을 가득 담은 가방, 그리고 세 명의 뛰어난 사냥꾼이 있어 어떤 적이 습격해 온다 해도 걱정이 없었다."'),
(115, '나는 전장에서 수없이 지옥을 드나들었다. 바로 사방에서 공격해 오는 불타는 군단이라는 지옥의 군대를... 그들에 비하면 난폭한 트롤 무리는 던 모로의 언덕을 뛰어다니는 토끼만큼이나 안전하다고 할 수 있다. 우리는 아무 문제 없이 트카시 폐허를 지나왔고 이로써 바닐도 많이 안심하게 되었다. 대해를 향해 서쪽으로 계속 가면서 바로 남쪽에 보이는 줄쿤다의 폐허의 가장자리를 지나쳤다. 높은 해안 절벽을 올라가던 도중에 첫 랩터 사냥감을 발견했다.'),
(118, '우리가 급히 쏜 총탄 덕분에 바닐은 간신히 목숨을 건졌다. 바닐은 언덕 아래로 기어 내려와 일행에 합류했다. 우리는 정글 속으로 황급히 도망쳤다. 사나운 꼬리깃맹금류 무리가 우리의 움직임을 쫓고 있었다. 사냥꾼이 이제 사냥감이 되었다.'),
(119, '"나는 해안가에 랩터로부터 숨을 곳이 있기를 바라면서 동료들을 바다 쪽으로 안내했다. 그런데 서둘러 도망쳐 오는 바람에 북쪽으로 너무 멀리 도망쳐 와 위태로운 고지까지 오고 말았다. 이미 실수는 저질러졌고 그건 모두 내 잘못이었다. 우리는 깎아지른 절벽 끝에 멈춰 섰고, 랩터들은 겨우 몇 발자국 뒤에 있었다."'),
(120, '나는 총을 든 채 천천히 앞으로 나섰다. 내가 이 용감한 사냥꾼들을 죽음으로 몰아넣었다. 나는 그들을 지키다 죽을 각오였다. 꼬리깃맹금류는 특히 사납고, 피에 대한 갈증이 멈추지 않는 것으로 악명이 높다. 그들은 우리보다 훨씬 많았다. 하지만 그들이 나와 내 동료들을 죽이기 전에 그들의 피를 먼저 흘리게 할 수는 없었다.'),
(121, '아제크와 얼가딘 경은 무기를 준비하고 바다를 등지고 서 있는 내 양옆을 에워쌌다. 바르닐은 패배한 듯한 한숨을 내쉬며 도끼를 뽑았다. 래시테일 일당이 거의 우리에게 다가왔다. 그들의 일정한 발걸음 속도가 느려졌다. 이제 그들은 우리를 함정에 빠뜨렸다는 것을 알고 먹잇감을 쫓기 시작했다.'),
(124, '헤멧 네싱와리의 가시덤불$b$b              골짜기의 푸른 언덕'),
(153, '우리 처음 주간은 갔다. 그리고 사람은 처음 주간을 갈 것을 예상 할 수있다. 우리 시대의 대부분은베이스 캠프를 수립하는 데 필요한 준비를하는 데 몰두했습니다. 나는 담수 강 입구에 의해 이상적인 설정을했다. 근처에 버려진 부두가있는 것으로 판단하여이 지역은 언젠가 거주하게되었습니다. 원래의 거주자에 관해서는 시간 만이 그 이야기를 말할 수 있습니다.'),
(154, '이번 원정을 위해 저는 아제크 루악과 S. J. 얼가딘 경, 그리고 제 충실한 하인 바닐 스톤팟을 소집했습니다. 저는 아제크의 아버지와 함께 동맹을 수호하는 수많은 전투에 참전했었죠. 그녀가 이렇게 성장한 모습을 보니 참 감회가 새롭습니다. 그녀의 아버지는 그녀에게 무기 사용법을 훌륭하게 가르쳤습니다. 활 솜씨를 보면 혹시 엘프의 피가 흐르는 건 아닐까 하는 생각이 들 정도입니다.'),
(155, 'S. J. 얼가딘 경은 인간 귀족 출신입니다. 그의 아버지인 얼가딘 백작은 관대함으로 유명했습니다. 제2차 세계 대전 후 스톰윈드 복구 과정에서 석공 조합의 근무 환경 개선을 위해 적극적으로 노력한 사람이 바로 얼가딘 백작이었습니다.'),
(156, '그 후, 스톰윈드가 석공 길드를 배신한 뒤 얼가딘 경은 왕국에서 귀족들이 맡은 역할에 점점 환멸을 느꼈습니다. 그는 더 이상 아버지의 혈통이 귀족원에서 자신에게 안겨 준 지위를 지키고 싶어 하지 않았습니다. 하지만 이야기가 옆길로 샜군요. 이 글의 목적은 정치 논문도, 전기도 아닙니다. 이것은 제가 가시덤불 골짜기의 푸른 언덕에서 거물 사냥을 하며 겪은 이야기입니다\n.'),
(157, '우리는 해가 뜨자마자 일어났다. 바르닐은 아침 식사를 준비하기 시작했다. 아제크의 시선이 어딘가 산만해 보였다. 오늘의 여정은 길고, 사냥은 우리를 위험에 가까이 데려갈 것이다. 집중력이 흐트러지면 쉽게 사고로 이어질 수 있었다. 하지만 아제크는 강가에 서서 식기를 헹구고 있는 바르닐에게서 눈을 떼지 못하는 듯했다.'),
(158, '내가 아제크가 오늘의 사냥 전략에 별 관심이 없는 이유를 묻으려던 찰나, 그녀는 화살통에 손을 뻗어 화살을 뽑아 불쌍한 바르닐을 향해 쏘았다. 하지만 아제크가 쏜 화살은 바르닐을 향한 것이 아니었다. 바르닐이 입을 쩍 벌리고 옆으로 비켜서자, 커다란 강악어가 수면 위로 떠올랐고, 아제크의 화살은 악어의 커다란 두 눈 사이에 정확히 박혔다.'),
(159, '우리는 빽빽하게 우거진 정글을 헤치고 서쪽으로 향했다. 느리고 신중한 발걸음으로 빽빽한 잎사귀 사이를 헤치며 먹잇감을 찾았다. 아침은 답답한 침묵 속에 흘러갔다. 계곡에는 바람 한 점 불지 않고 아무것도 움직이지 않았다. 오후가 되자 탐험대는 초조해졌다. 바르닐은 더 이상 먹잇감을 쫓는 포식자처럼 조심스럽게 걷지 않았다. 오히려 마른 잎이나 떨어진 나뭇가지를 밟으며 투박하게 길을 따라 걸어갔다.'),
(160, '바르닐이 그런 실수를 저지르자, 에를가딘은 그의 어깨에 거칠게 손을 얹었다. 아제크와 나는 그저 에를가딘이 바르닐의 부주의함을 꾸짖는 거라고 생각하며 무심코 쳐다보았다. 그러나 에를가딘은 고개를 천천히 저어 근처에 쓰러진 나무를 가리켰다. 날카로운 송곳니가 가득한 입 위로 날카로운 검은 눈 두 개가 우리를 응시하고 있었다.'),
(161, '그 짐승은 수컷 목가리호랑이였다. 내가 소총을 장전하기도 전에 에를가딘이 석궁을 들어 짐승을 향해 쏘았다. 화살은 빗나가 짐승의 왼쪽 옆구리에 박혔다. 호랑이는 필사적으로 도망치려 했지만 상처가 너무 컸다. 짐승은 몇 초 동안 비틀거리며 고통스러워했고, 그때 바르닐이 던진 도끼로 마무리 일격을 가했다.'),
(162, '그 살해는 탐험대들 사이에서 축제 분위기를 불러 일으켰습니다. 바닐은 모두가 즐길 수있는 미드를 쏟아 부었다. 그러나 우리의 축제는 오래 가지 못했습니다. 우리가 기지 캠프로 돌아가는 수송을 위해 시체를 준비 할 때 우리는 모두 끔찍한 으르렁 거리에 의해 경계를당했습니다. 내 년 동안 나는 피가 흐트러지기 때문에 아무것도 듣지 못했습니다.'),
(163, '저 위 바위투성이 절벽 위에서, 석양에 실루엣처럼 드러난 그 맹금류는 내가 여태껏 본 것 중 가장 큰 녀석이었다. 나는 소총으로 서투르게 한 발을 쏘았지만, 그 녀석은 꼼짝도 하지 않았다. 다시 한번, 이번에는 처음보다 더 크게 으르렁거리더니$B$B사라졌다. 우리는 짐을 챙겨 엄숙하게 캠프로 돌아갔다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(164, '나는 그 모피가 아제로스 전역에 높은 수요가 있기 때문에 다음날 사냥 표범을 보낼 탐험을 약속했다. 동맹의 이름으로 용맹스럽게 목숨을 바칠 수있는 유능한 사냥꾼, 덫 사냥꾼 및 모피 무역상들 모두와 함께 그러한 요구가 존재해야한다는 것은 의미가 있습니다.'),
(165, '아제크와 얼가딘 경은 드워프 소총으로 효과적인 사냥법을 배우고 싶어 안달이 났습니다. 저는 그 두 인간에게 원시적인 원거리 무기를 베이스캠프에 두고 오라고 했습니다. 그리고 바르닐과 저는 아이언포지에서 만든 최고급 화기들을 그들에게 지급했습니다.'),
(166, '이날 우리는 신선한 표범 발자국을 따라 남쪽으로 향했습니다. 곧 거대한 밧줄 다리가 놓인 협곡에 도착했습니다. 그 경이로운 건축물을 보니 브란이 이 지역을 묘사했던 글들이 저절로 떠올랐습니다. 사람들은 흔히 토착 트롤들이 미개하고 교육받지 못한 종족이라고 생각했지만, 이 다리의 정교한 솜씨를 보니 트롤 건축가들이 불가능해 보이는 위업을 얼마나 뛰어난 기술로 이뤄냈는지 알 수 있었습니다.'),
(167, '얼마 지나지 않아 아제크는 남서쪽으로 향하는 표범의 흔적을 발견했다. 우리는 먹잇감을 기다리며 총을 겨누고 조용히 걸었다. 근처 숲에서 나뭇가지가 부러지는 소리가 들려왔다. 무언가가 안에 있는 것이 분명했다. 바닐에게 날카로운 눈빛을 보내자 그의 생각은 분명해졌다. 바닐은 천천히 총을 내렸다. 이번 사냥은 우리를 위한 것이 아니었다. 우리 인간 동료들을 위한 것이었다. 수많은 표범들이 우리 총구 앞에서 목숨을 잃었다. 이번 사냥은 인간들을 위한 것이었다.'),
(168, '아제크와 엘르가딘 경은 흔들리는 나무 밑동의 무성한 덤불을 향해 총을 겨누고 자세를 잡았다. 한낮의 태양이 우리에게 강렬하게 내리쬐었다. 엘르가딘이 안전핀을 당기자 그의 관자놀이에서 땀방울이 천천히 흘러내렸다. 딸깍 소리와 함께 빽빽한 덤불이 갈라지더니, 크고 아름다운 검은 표범 한 마리가 평원으로 뛰쳐나왔다.'),
(169, '인간들은 나무숲 가장자리를 따라 달리는 표범에게 시선을 고정했다. 그들의 총구는 완벽하게 평행을 이루며 동시에 움직였다. 바르닐은 나에게 재촉하는 눈길을 보냈지만, 나는 고개를 저었다. 이 사냥은 인간들을 위한 것이었지, 바르닐이나 나를 위한 것이 아니었다. 에를가딘이 굉음을 내며 총을 쏘았지만, 표범은 빗나갔다. 그는 총격의 강력한 반동에 대비하지 못했던 모양이다.'),
(170, '그의 총이 팔에서 세게 뒤로 튕겨 나갔다. 총구가 옆으로 휘청거리며 아제크의 소총 아래로 들어왔다. 아제크는 바로 그 순간 방아쇠를 당겼다. 조준이 나무숲 쪽으로 어설프게 쏠린 소총은 굉음과 함께 발사되었다. 새 떼가 나뭇가지 사이로 비명을 지르며 사방으로 흩어졌다. 나무에서 연기가 피어올랐다. 우리는 거대한 나뭇가지가 도망치던 표범 위로 떨어져 표범의 등이 부러지는 모습을 경외심을 가지고 지켜보았다.'),
(171, '몇 주가 지나면서 표범과 호랑이 가죽은 엄청나게 쌓여갔습니다. 저는 탐험대의 목표를 새로운 도전, 바로 맹금류 사냥으로 옮겨야 할 때라고 판단했습니다.$B$B인간들은 바르닐과 제가 제공한 훈련에 감사했지만, 총기를 사용한 사냥은 하지 않기로 했습니다. 아제크는 정교하게 장전된 활을 훨씬 더 잘 다루었고, 얼가딘 경은 튼튼한 석궁 없이는 절대 캠프를 나서지 않았습니다.'),
(172, '우리는 동이 트자마자 남쪽으로 향하며 트카시 유적지를 지나 길을 나섰다. 바닐은 블러드스칼프 부족원들을 만날지도 모른다고 걱정했다. 나는 블러드스칼프 부족은 부족의 적수인 스컬스플리터들을 섬멸하는 데 더 관심이 있다는 것을 바닐에게 상기시켰다. 당연히 바닐은 전혀 안심하지 못했다. 하지만 나는 장전된 소총과 화약이 가득 든 가방, 그리고 세 명의 뛰어난 사냥꾼들을 데리고 있었기에 적의 매복 공격에 대한 걱정은 덜 수 있었다.'),
(173, '나는 전장에서 거대한 인페르날 앞에 서 있었고, 불타는 군단의 군대는 사방에서 진격해 오고 있었다. 하지만 제멋대로인 트롤 무리는 던 모로그 언덕의 산토끼처럼 무해해 보였다.$B$B우리는 별다른 사건 없이 트카시 유적을 지나갔고, 바르닐은 안도의 한숨을 내쉬었다. 일행은 남쪽으로 조금 떨어진 줄쿤다 유적을 우회하며 대신해를 향해 서쪽으로 나아갔다. 높은 해안 절벽을 오르던 중 우리는 첫 번째 랩터를 발견했다.'),
(174, '그 짐승은 우리의 존재를 전혀 눈치채지 못했습니다. 사실, 탐험대가 그에게 건넨 유일한 인사는 미간에 박힌 총알뿐이었습니다. 에를가딘 경은 우렁찬 함성을 질렀고, 아제크는 고개를 끄덕이며 나를 칭찬했습니다. 나는 축하의 의미로 담배를 피우려고 배낭을 뒤져 파이프를 찾았습니다. 바르닐은 랩터의 시체를 수습하기 위해 언덕 위로 서둘러 올라갔습니다. 나는 큰 사냥감을 잡았을 때 느끼는 만족감에 젖어 쓰러진 짐승을 바라보았습니다.'),
(175, '하지만 나는 사냥의 영광을 오래 누릴 수 없었다. 시선을 지평선으로 돌리자, 불쌍한 바르닐 바로 위 언덕 너머로 여러 그림자가 나타났다.  $B$B"도망쳐, 바르닐!" 나는 소리쳤다. 아제크, 에를가딘 경, 그리고 나는 바르닐과 그를 추격하는 맹금류들을 향해 총알과 화살, 볼트를 퍼부었다. 혼란 속에서 우리 중 한 명이 명중시켰다.'),
(176, '우리가 급히 쏜 총탄 덕분에 바닐은 간신히 목숨을 건질 수 있었다. 바닐은 언덕 아래로 기어 내려와 일행에 합류했다. 우리는 정글 속으로 황급히 도망쳤다. 사나운 꼬리깃맹금류 무리가 우리의 움직임을 쫓고 있었다.$B$B사냥꾼이 이제 사냥감이 되었다.'),
(177, '나는 해안선이 랩터들로부터 피난처가되기를 희망하면서, 파티를 바다쪽으로 이끌었다. 서두르지도 않고 너무 북쪽으로, 너무 높은 고도로 이동했습니다. 실수가있었습니다. 그 잘못은 내 것이 었습니다. 우리는 깎아 지른듯한 절벽에 그만 두었습니다. 랩터스는 몇 발자국 뒤에 있습니다.'),
(178, '나는 총을 든 채 천천히 앞으로 나섰다. 내가 이 용감한 사냥꾼들을 죽음으로 몰아넣었다. 나는 그들을 지키다 죽을 각오였다. 꼬리깃맹금류는 특히 사납고, 피에 대한 갈증이 멈추지 않는 것으로 악명이 높다. 그들은 우리보다 훨씬 많았다. 하지만 그들이 나와 내 동료들을 죽이기 전에 그들의 피를 먼저 흘리게 할 수는 없었다.'),
(179, '아제크와 얼가딘 경은 무기를 준비하고 바다를 등지고 서 있는 내 양옆을 에워쌌다. 바르닐은 패배한 듯한 한숨을 내쉬며 도끼를 뽑았다. 래시테일 일당이 거의 우리에게 다가왔다. 그들의 일정한 발걸음 속도가 느려졌다. 이제 그들은 우리를 함정에 빠뜨렸다는 것을 알고 먹잇감을 쫓기 시작했다.'),
(180, '그리고 기적적인 일이 일어났습니다. 떨어져서 우리 쪽에서 우리는 굉장히 하얀 타이거의 별개의 그리고 무서운 포효를 들었다. 그들의 수에도 불구하고, 맹금류는 돌고 모든 방향에서 뿌렸다.우리는 호랑이가 우리를 지나서 뛰쳐 나와 랩터 중 한 명을 놀라게하면서 짧은 플래시를 보았습니다. 명령을 줄 필요가 없습니다. 우리 당원 모두 네가 도망 갈 시간임을 알았다.'),
(181, '우리는 베이스캠프까지 전속력으로 달렸고, 속도를 늦추지 않았다. 그날 밤, 우리는 모닥불 주위에 조용히 앉아 기묘한 운명의 장난 덕분에 목숨을 건졌다는 사실을 깨달았다. 이것이 바로 사냥꾼의 위험이다. 우리는 운명을 가지고 놀면서 동시에 운명을 조종한다. 하지만 우리 모두는 언젠가 운명의 날카로운 이빨에 직면하게 될 것이다. 이 드워프는 그 순간이 가시덤불 골짜기의 푸른 언덕에서 오지 않아서 다행이라고 생각할 뿐이다.'),
(182, '"자랑스런 동료와 진실의 탐구자들에게\r\n\r\n현장 발굴 작업은 계속되고 있지만 지난 보고서에서도 언급했던 트로그 놈들 때문에 작업이 지연되고 있소. 이 트로그 중 일부는 보통 때보다 더 공격적이긴 하지만 난 놈들을 처치할 방법이 있으리라 확신하오. 최근 유물이 많이 발굴되고 있지만 한 가지를 제외하고는 그 가치에 있어서 이전 것과 별반 다를 게 없소. 대단한 것은 아니지만 흥미로운 사실이오. 이 건에 관해서는 아래에 자세히 설명하도록 하겠소."'),
(183, '"한 가지 예외가 있었소. 최근 발견된 독특하게 조각된 조각상들이 현장에 있는 트로그들에게 영향을 미치는 것 같소. 놈들은 이 돌 조각상들에 이끌리고 있으며, 일부 트로그들은 돌 조각상의 영향으로 광포해지기까지 하오! 지난 번 보고서에 이 조각상들에 대한 간략한 설명이 포함되어 있소.\r\n\r\n이 조각상들에 대해 어떤 결론을 내리기 위해서는 더 면밀한 조사가 필요하겠지만, 아무튼 난 이 조각상들이 트로그와 티탄 간의 관계를 밝혀 줄 것으로 기대하고 있소."'),
(184, '"끝으로, 다시 한번 강조하지만 우린 화약이 필요하오. 현재 보급품이 거의 바닥나 발굴 작업에 큰 지장을 주고 있소. 곧 다시 화약이 보급될 것이라고 들었지만 아직까지 받지 못했소.\r\n\r\n혹 무슨 일이 있는 것인지, 지연되고 있는 이유가 궁금하오.\r\n\r\n그럼 이만 줄이겠소.\r\n발굴조사단장 다테우스 아이언밴드"'),
(185, '"모든 것은 롤랜드 광산에서 그 저주받은 낫을 발견하면서 시작됐다. 낫을 발견하기 전까지 이곳은 노스샤이어 계곡만큼이나 평온한 곳이었다.\r\n\r\n정말 후회스럽게도 내가 광산의 돌 무더기 사이에서 튀어나와 있던 낫의 자루를 발견하고 그걸 잡아 꺼내면서부터 롤랜드 광산은 비참한 죽음의 장소가 되어 버렸다."'),
(186, '"모든 것은 롤랜드 광산에서 그 저주받은 낫을 발견하면서 시작됐다. 낫을 발견하기 전까지 이곳은 노스샤이어 계곡 만큼이나 평온한 곳이었다.\r\n\r\n정말 후회스럽게도 내가 광산의 돌 무더기 사이에서 튀어나와 있던 낫의 자루를 발견하고 그걸 잡아 꺼내면서부터 롤랜드 광산은 비참한 죽음의 장소가 되어 버렸다."'),
(187, '"무슨 일이 일어날지 진작 알았더라면 룬문자가 새겨진 그 낫 자루를 잡지 못하게 내 손을 잘라 버리기라도 했을 것이다. 이 얼마나 후회스러운 일인가! 후회란 세상을 등지기 전 노인들만 하는 것이라고 생각했었는데... 후회란 노인이 아니라 절망에 빠진 자의 것이란 걸 깨달았다. 후회하는 사람은 외투를 뒤집어쓰고 불행한 운명에 굴복하여 벗을 수도 없고 벗으려는 의지도 없는 자들이다.\r\n\r\n감상적인 시인들이나 할 법한 얘기는 이쯤에서 그쳐야겠다. 내가 겪은 일들을 계속 기록해야 하니까..."'),
(188, '"그 낫이 세상에 모습을 드러낸 이후 광산에 변화의 물결이 일었다. 희미한 횃불에서 나오던 빛이 휘어지고, 우리는 목소리 크기를 스스로 제어할 수 없게 되었다. 어떤 때는 한 사람이 속삭이는 소리가 손으로 귀를 틀어막아야만 할 정도로 굴 속 전체에 크게 울려 퍼지기도 하고, 또 어떤 때는 고함 소리가 채 몇 발자국 거리도 못 가 바람에 묻혀 희미하게 사라져 버리기도 했다.\r\n\r\n물론 우린 당황했지만 이 이상한 현상에 대한 궁금증은 곧 풀렸다. 그것은 우리를 광산에서 내쫓은 늑대인간의 출현을 알리는 전조였을 뿐이었다."'),
(189, '"놈들이 사방에서 공격해 왔다. 우리 발 아래 숨겨진 구덩이에서 튀어나오기도 하고, 머리 위에서 조용히 떨어져 내리기도 했다. 이렇게 끔찍한 상황이 시작되고 몇 분이 지나지 않아 반이 당하고 말았다. 나를 포함한 나머지 생존자는 필사적으로 도망쳤다. 나는 달려가면서 많은 형제들이 놈들의 이빨과 발톱에 당하는 걸 목격했고, 비명 소리가 짧게 사라지거나 헐떡이다 끊어져 버리는 것을 수없이 들었다.\r\n\r\n난 그곳을 탈출한 유일한 인간이었던 것이다."'),
(190, '"내가 그날 밤 어떻게 살아남을 수 있었는지 정확히는 모르겠지만 아마도 경계를 늦추지 않고 공격이나 위험으로부터 재빨리 빠져나왔기 때문일 것이다. 내 별명도 이런 성격 탓에 붙여진 것이니 붙여졌다. 이런 나의 조심스러운 성격이 날 구한 것이 아니었을까...?\r\n\r\n아니면 내가 돌 무더기에서 잡아 꺼낸 낫 때문이었을 수도... 정신없이 도망치는 동안 그 낫을 잃어버렸으니깐 그것도 아닐 것이다. 하지만 어쨌든 나 때문에 늑대인간이 그늘숲에 나타난 것이니 늑대인간 놈들도 내게 일종의 예의를 차린 것 아니었을까? 저주받을 놈들!"'),
(191, '"아니면 내가 그늘숲에 초래한 변화의 목격자가 되는 비참한 운명을 타고난 것인가? 아마도 늑대인간이 이 땅을 짓밟고 그 사악함으로 세상을 끝없이 더럽히는 것을 지켜보는 것이 내 운명일지도...\r\n\r\n진정 그것이 내 운명이라면, 나에게 닥친 시련은 그것뿐만이 아닐 것이다. 그늘숲을 차지하려는 세력은 늑대인간만이 아니다. 죽음의 고개에서 나타난 악귀들도 이 땅을 노리고 있는 것이다.\r\n\r\n그들에 대해서는 다음 장에서 쓰도록 하겠다. 그리고 이 땅을 노리는 자들이 그들이 마지막이 되길 바랄 뿐이다..."'),
(192, '"롤랜드 광산에서 무사히 도망친 후, 나는 스벤이라는 자의 헛간에 숨었다. 그 헛간에서 며칠을 지냈지만 계속 공포에 휩싸여 있었기 때문에 스벤이나 그의 가족이 보지 못하게 숨어있었다. 하지만 숨어서 지켜보니 농부가족인 이들은 매우 좋은 사람들이었다. 그때 내가 헛간에서 나갔다면 그들이 안전하게 나를 숨겨 줬었겠지만, 당시 누군가를 믿는다는 건 내게 너무 어려운 일이었다. 광산에서 그 충격적인 일을 겪은 후로는 더욱 그랬다. 그래서 나는 숨어 있었고 그것이 나를 살렸다."'),
(193, '"내가 헛간에 숨어 지낸 지 며칠이 지난 후, 스벤은 다크샤이어로 떠나기 위해 농장을 나섰다. 그는 아내에게 작별의 입을 맞추고 아이들에게 미소를 지어 보이고는, 곧 장난감과 과자를 사 가지고 돌아오겠다는 약속과 함께 길을 나섰다. 불쌍한 사람, 그것이 가족들의 모습을 본 마지막이었다. 그래도 그들은 마지막 순간에 행복하게 헤어질 수 있지 않았는가. 또 그의 아내가 먼저 죽었으니 아이들의 처참한 죽음을 목격하고 피눈물을 흘리는 일은 피할 수 있지 않았던가. 하지만, 내게는 이런 작은 자비도 허락되지 않았다. 난 모든 걸 목격했고, 그 모습은 악몽으로 나타나 영원히 나를 괴롭힐 것이다."'),
(194, '"스벤이 떠나고 집에 남아 있던 그의 가족이 흑기사의 습격을 당하던 그날 밤의 악몽이 생생히 떠올라 내 손이 떨리면서 또다시 후회가 밀려온다. 내가 뛰쳐나가 죽음의 고개에서 온 저 악귀들과 맞서 싸웠어야 하는데... 이미 되돌릴 수 없는 후회일 뿐이다. 참사에서 살아남은 생존자라면 누구나 이러한 후회에 시달리게 된다. 설령 내가 숨어 있던 곳에서 뛰쳐나갔다 하더라도 나 역시 죽임을 당하고, 내 시체가 조각조각 찢겨 사방으로 흩어져서 형체도 알아볼 수 없게 되었으리란 걸 잘 알고 있다."'),
(195, '하지만 내가 이 극악무도한 살인을 막기 위해 할 수 있는 건 아무것도 없었지만 정말 후회스러운 게 있다. 바로 내가 흑기사들을 스벤의 농장에 불러들였다는 것이다. 내가 낫을 발견했기 때문에 늑대인간들이 그늘숲에 풀려났을 뿐더러 죽음의 고개에서 흑기사를 불러들이기까지 한 것이다. 놈들은 가족을 몰살시키기 전 아이들을 꼭 안고 있던 스벤의 아내에게 한 가지 질문을 했었다. 이 대화를 통해 내가 이 엄청난 파장의 씨앗이라는 사실을 알게 되었다. 그녀는 죽음이 가까이 왔음을 분명히 느끼면서도 최대한 아이들을 안심시키기 위해 애쓰고 있었다.'),
(196, '"""엘룬의 낫."" 흑기사 중 하나가 마치 돌에 도끼를 가는 듯한 거칠고 날카로운 목소리로 소리쳤다. 그리고 말이 끝날 때쯤에는 - 엘룬 - 이라고 목이 멘 듯 쉰 목소리가 났다.\r\n\r\n그 목소리는 공포 그 자체였다. 소리가 무시무시하기도 했었지만... 나는 그들이 얘기하는 낫이 무엇인지 알고 있었기 때문이었다. 그것은 며칠 전 내가 롤랜드 광산의 돌 더미에서 꺼낸 그 저주받은 물건을 말하는 것이 분명했다. 그게 흑기사들이 찾고 있는 물건이었다니! 그리고 그때문에 스벤의 가족이 죽임을 당하다니..."'),
(197, '"항상 남편이나 아이들에게 스벤의 아내의 호칭은 ""여보"", ""내 사랑"", ""엄마"" 등이었기 때문에 난 그녀의 이름을 알지 못했다. 그녀의 이름을 알았더라면 좋았을 텐데... 난 그날 그녀의 마지막 모습을 기억하고 있는 유일한 사람이고, 비록 일개 농부의 아내일 뿐이었지만 지금까지 내가 봐 온 어떤 사람보다도 용감한 사람이었다.\r\n\r\n물론 그녀는 낫에 대해 모르고 있었지만 흑기사가 그걸 찾고 있다는 사실을 눈치채고 곧 작전을 생각해 냈다. 정말 대담하고도 영리한 작전이었다. 성공했더라면 정말 좋았을 것을..."'),
(198, '"""낫이라고요?"" 조용한 목소리로 그녀가 대답했다. ""물론 알고 있죠. 이곳에 사는 사람 중에 그 낫을 모르는 사람이 있겠어요?"" 그녀는 흔들림 없이 흑기사를 쳐다봤다. 만약 내가 진실을 모르고 있었다면 나조차도 그녀가 사실을 말할 것이라고 믿었을 것이다. 그녀가 낫에 대해 알리는 없었던 것이다.\r\n하지만 그녀의 거짓말이 효과를 발휘했다. 조금 전 질문을 했던 흑기사가 그녀를 향해 고개를 약간 숙이고는 외쳤다. ""어디에 있지?"" ""내가 데려다 주겠어요, 당신들 모두."" 그녀가 대답했다. 그녀의 눈 속에 작은 희망이 희미하게 빛나는 것을 볼 수 있었다."'),
(199, '"""하지만 가는 길이 멀고 아이들은 방해만 될 테니까 여기 두고 가요."" 그녀의 속임수는 단순했지만, 원래 단순한 속임수가 가장 잘 먹히는 법이다. 성공했더라면 흑기사들을 농장에서 멀리 데려갈 수 있었을 것이다. 그러면 그녀 자신은 살아남지 못하더라도 아이들만은 살릴 수 있었을 것이다. 그리고 흑기사가 그녀의 지혜로운 거짓말을 믿기만 했더라면 성공했을 것이다. 난 신을 믿은 적이 없었지만, 저 끔찍한 흑기사와 맞서고 있는 스벤의 아내를 위해 열심히 기도했다.\r\n\r\n""제발... 놈들이 믿도록 해 주십시오."""'),
(200, '놈들은 꼼짝도 않고 서 있었고 그녀는 태연하게 그들의 시선을 받고 있었다. 그리고는 놈들 중 하나가 멀리서 부르는 소리라도 들리는 듯이 위를 쳐다보았다. 놈은 자신의 품 속에서 작은 보석을 꺼내 들여다보았다. 그리고는 스벤의 아내에게 그 보석을 내밀었다. 그 흑기사의 손에서 빛이 나와 기분 나쁜 흰색 손 모양으로 변해 그녀를 향했다. 그녀는 똑바로 빛을 응시했지만 나는 그녀의 자신감 넘치는 얼굴 뒤에 감춰진 불안감을 읽을 수 있었다. 그 손은 그녀에게 닿자 손가락을 펴 그녀의 머리를 감싸고는 쥐어짰다.'),
(201, '"스벤의 아내는 판자처럼 굳은 채로 서 있었고 눈동자는 커졌다. 비명을 지르기 위해 입을 벌렸지만 어떤 소리도 들리지 않았다. 이 끔찍한 순간이 몇 분 동안 계속된 후 그 손은 그녀를 놓아 주었고 그녀는 바닥에 쓰러졌다. 그리고는 보석을 가진 흑기사가 말 안장에 올라타더니 커다란 목소리가 뿜어져 나왔다.\r\n\r\n""이 여자는 거짓말을 하고 있다."" 이 목소리는 그 후 내가 꾸는 악몽에 계속 나타나고 있다. ""이 여자는 낫을 본 적도 없어."""'),
(202, '"그러고 나서 그 흑기사는 몸 속의 영혼이 빠져 나가기라도 한 듯 어깨를 약간 굽혔다. 그리고 마지막으로 전과 같이 늙고 날카로운 목소리로 이렇게 외쳤다.\r\n\r\n""주인께서 명하셨다. 모두 죽여라!""\r\n\r\n그 뒤에 일어난 일은 설명할 수가 없다. 기억에 또렷이 남아 있긴 하지만 내 비열한 영혼조차도 차마 그 후의 끔찍했던 몇 분 동안 일어난 일들을 종이 위에 옮기지는 못하겠다."'),
(203, '"그저 스벤의 가족이 모두 죽었다는 것만 말할 수 있다. 그리고 얼마 지나지 않아 스벤이 이 끔찍한 죽음의 현장으로 돌아왔다. 나는 그의 깊은 슬픔 앞에 내 모습을 나타내기가 두려웠다. 그리곤 그가 나를 발견하게 될까 두려운 나머지 숨어 있던 헛간에서 도망쳐 나왔다. 나는 지금 스벤이 어디에 있는지 모르지만 그가 언젠가 평온을 되찾게 되기를 빈다.\r\n\r\n그 후 몇 주 동안 이곳 저곳으로 피해 다녔다. 흑기사에 대한 두려움 때문에 어디에서도 지체할 수가 없었다."'),
(205, '"그 낫이 세상에 모습을 드러낸 이후, 놈들이 사방에서 공격해 왔다. 우리 발 아래 숨겨진 구덩이에서 튀어나오기도 하고, 머리 위에서 조용히 떨어져 내리기도 했다. 이렇게 끔찍한 상황이 시작되고 몇 분이 지나지 않아 반이 당하고 말았다. 나를 포함한 나머지 생존자는 필사적으로 도망쳤다. 나는 달려가면서 많은 형제들이 놈들의 이빨과 발톱에 당하는 걸 목격했고, 비명 소리가 짧게 사라지거나 헐떡이다 끊어져 버리는 것을 수없이 들었다."'),
(206, '"내가 그날 밤 어떻게 살아남을 수 있었는지 정확히는 모르겠지만 아마도 경계를 늦추지 않고 공격이나 위험으로부터 재빨리 빠져나왔기 때문일 것이다. 내 별명도 이런 성격 탓에 붙여졌다. 이런 나의 조심스러운 성격이 날 구한 것이 아니었을까...?\r\n\r\n아니면 내가 돌 무더기에서 잡아 꺼낸 낫 때문이었을 수도... 정신없이 도망치는 동안 그 낫을 잃어버렸으니깐 그것도 아닐 것이다. 하지만 어쨌든 나 때문에 늑대인간이 그늘숲에 나타난 것이니 늑대인간 놈들도 내게 일종의 예의를 차린 것 아니었을까? 저주받을 놈들!"'),
(207, '"롤랜드 광산에서 무사히 도망친 후, 나는 스벤이라는 자의 헛간에 숨었다. 그 헛간에서 며칠을 지냈지만 계속 공포에 휩싸여 있었기 때문에 스벤이나 그의 가족이 보지 못하게 숨어있었다. 하지만 숨어서 지켜보니 농부가족인 이들은 매우 좋은 사람들이었다. 그때 내가 헛간에서 나갔다면 그들이 안전하게 나를 숨겨 줬었겠지만, 당시 누군가를 믿는다는 건 내게 너무 어려운 일이었다. 광산에서 그 충격적인 일을 겪은 후로는 더욱 그랬다.\r\n\r\n그래서 나는 계속 숨어 있었다."'),
(208, '<책의 나머지 부분은 비어 있습니다.>'),
(209, '"보고서: 코볼트\r\n\r\n노스샤이어 계곡 주변 지역에서 코볼트의 활동이 증가하고 있습니다. 노스샤이어 수도원 북쪽에 있는 메아리 광산 안에는 상당한 수의 코볼트가 집결해 있는 것으로 밝혀졌습니다. 이에 코볼트 섬멸을 도울 성기사와 전사, 지역 주민들을 소집 중입니다. 현재까지는 순조롭게 진행되고 있으며 필요하면 인원을 더 충원할 계획입니다."'),
(210, '"보고서: 도적 무리\r\n\r\n노스샤이어 계곡에 코볼트보다 위험한 인간 도적 떼가 나타났습니다. 그들은 붉은 복면을 하고 자신들을 결사단이라 칭하고 있습니다. 이 정도 규모의 조직이라면 노스샤이어를 비롯한 엘윈 숲 전역에 문제를 일으킬 수 있습니다. 놈들의 지휘관 중 한 명인 개릭 패드풋이란 자의 신원을 확인하고 현재 놈을 처치하기 위해 노력하고 있습니다."'),
(211, '"보고서: 늑대\r\n\r\n노스샤이어에서 야생동물들의 습격이 증가하고 있습니다. 이건의 말로는 그늘숲에서 늑대들이 이곳으로 쫓겨왔다고 합니다. 늑대들이 인간을 공격하는 일은 극히 드물지만 놈들의 수가 증가하면서 농부들이 피해를 입고 있으며 가축을 많이 잃고 있습니다."'),
(212, '"추천서:\r\n\r\n이 문서를 지닌 이는 열정과 뛰어난 능력으로 노스샤이어를 위해 봉사한 공로를 인정받아 스톰윈드 군대에서 부관 대리의 지위를 수여받았습니다. 이 사람은 엘윈 숲을 위해서도 필요한 사람이라 확신합니다.\r\n\r\n서명: 노스샤이어 스톰윈드 군대\r\n치안대장 더글라스 맥브라이드"'),
(213, '"서부정통 스튜 조리법\r\n\r\n재료:\r\n식인독수리 고기 3덩이\r\n뿔엄니멧돼지 주둥이 3개\r\n멀록 눈알 3개\r\n오크라 3개\r\n\r\n위의 재료를 함께 넣고 적어도 두 시간 이상 푹 끓인 후 그릇에 담아낸다."'),
(214, '"사랑하는 이베트\r\n\r\n이 편지를 가장 빠른 전령에게 맡기도록 하겠소. 전령이 우리를 포위하고 있는 적진을 뚫고 무사히 빠져나가기를 기원하오. 그리고 내가 전하는 마지막 소식이 될 이 편지를 당신이 읽을 수 있기를 간절히 바라오이다.\r\n\r\n그래도 이 암울한 시기에 당신만은 무사하다는 사실이 내게 유일한 위안이라오."')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(215, '누락된 텍스트'),
(218, '"스톤필드 일가와 맥클루어 일가 간의 전쟁으로 토미 조가 죽임을 당해, 꽃을 피우고 있는 메이벨의 사랑이 슬픈 결말을 맞이하게 되지 않을까 걱정이라네. 난 전쟁으로 어두운 소식과 소문이 끊이지 않고 있는 이런 시기에는 젊음과 사랑이 더욱 활짝 꽃펴야 한다고 생각한다네.\r\n그래서 부탁인데, 자네의 능력을 발휘하여 이 두 젊은이가 사랑을 이룰 수 있도록 물약이나 비약을 만들어 줬으면 하네. 고맙네, 윌리엄. 바쁘지 않으면 한번 들리게나. 옛 이야기나 나누게 말이야.\r\n\r\n밀드레드 스톤필드"'),
(219, '스톰윈드 시 건축가 바루스 알렉스톤이 폐하께, "데피아즈단"의 최근 활동과 왕국 전역에서 벌어지고 있는 일들에 대한 보고서를 작성하여 드려야 할 필요성을 느낀 데에는 여러 가지 이유가 있습니다. 먼저 간략한 역사적 배경부터 말씀드리겠습니다. 아시다시피, 저는 스톰윈드 시의 석공 길드 일원으로서 시정에 첫발을 내딛었습니다. 수년간의 노력 끝에 저희는 스톰윈드 시의 재건 사업을 완료했습니다.'),
(220, '스톰윈드에서는 석공 길드의 청구서, 회비, 급여 등이 미지급 상태로 방치되어 있었습니다. 당시 에드윈 밴클리프가 석공 길드의 길드장으로 선출되었고, 그는 자신들의 작업에 대한 보상을 요구하며 목소리를 높였습니다. 이에 스톰윈드 귀족회는 석공 길드의 해산을 명령했고, 이는 당연히 밴클리프를 격분시켰습니다. 밴클리프는 폭동을 일으켜 석공들을 이끌고 도시 밖으로 나갔습니다. 이야기를 계속하기 전에, 그 시기에 일어난 다른 사건들을 몇 가지 언급하겠습니다.'),
(221, '이번에 여러분께 알려드려야 할 중요한 점이 있습니다. 첫째, 제가 밴클리프 편에 서지 않는다면 도시 건축가 자리를 제안받았던 때입니다. 하지만 이념적인 차이 때문에 스톰윈드에 남기로 했습니다. 폭동 중에 밴클리프의 부관이자 가장 신뢰하는 조수였던 바질 스레드가 체포되어 투옥되었습니다. 재판과 심문을 기다리는 동안 스레드는 감옥에서 거의 잊혀진 존재였습니다. 밴클리프가 잔당을 이끌고 돌아온 후, 스레드는 다시 밴클리프에게 돌아왔습니다.'),
(222, '스톰윈드 출신의 석공이었던 그는 상대적으로 방어가 허술한 서부 몰락지대의 상황을 틈타 막대한 인력을 동원해 많은 농부들을 쫓아내고 얼마 안 되는 금광들을 장악했습니다. 이렇게 확보한 자원을 발판 삼아 밴클리프는 스톰윈드 정부에 대한 복수 계획을 세웠습니다. 이 사실은 최근 이 문서의 소지자의 도움으로 밝혀졌으며, 그는 이 거대한 음모를 드러내는 데 결정적인 역할을 했습니다.'),
(223, '"필요할 경우 이 정보를 전하도록 하라.\r\n\r\n\r\n티리스팔 지역 사령부\r\n\r\n대장 멜로즈\r\n\r\n대장 바콘\r\n\r\n대장 페린\r\n\r\n\r\n대영주 지령 사항\r\n\r\n\r\n대장 페린, 지시에 따라 현재 주둔 중인 남서쪽 감시탑의 경계를 더욱 강화하라. 추가 보급품은 후일 공급될 것이니 그동안 주변 농장에서 구할 수 있는 대로 물품을 조달하도록 하라.\r\n"'),
(224, '"브릴 지역의 언데드 조직에 대해 보다 자세한 정찰 및 정보 수집 활동을 펼치도록 하라.\r\n\r\n\r\n대장 바콘, 북쪽 탑 근처에서 언데드의 움직임이 증가하고 있는 것으로 보인다. 신속히 진압하라.\r\n\r\n\r\n대장 멜로즈, 역병지대 변방에서 활동 중인 언데드 조직의 규모에 대한 우려의 목소리가 있다. 몇 주 내에 증원 병력을 그곳으로 보내도록 하겠다.\r\n\r\n\r\n정의의 편에 영광 있으라.\r\n"'),
(229, '"첫째 날\r\n\r\n전차가 고장 났지만 이 언덕 어딘가에 키론 광석이 있을 것이다. 해머풋에게 전차를 떠나지 말고 잘 지키라고 이르고 나는 혼자 정찰을 계속했다. 전차를 수리하지 못하면 이 일지는 내 마지막 유언이 될 것이다.\r\n\r\n- 조종사 버론 힐델브, 아이언포지 전차 부대"'),
(230, '"둘째 날\r\n\r\n정찰을 계속했지만 광석을 찾지는 못했다. 스톤기어가 농담으로 그 광석에 대한 소문을 지어낸 건 아닌지 모르겠다. 흠, 만약 정말 그랬다면 스틸그릴의 정비소로 돌아가는 대로 그의 머리를 부숴 버릴 것이다!\r\n\r\n오늘 밤 야영을 준비하면서 협곡에 메아리치는 짐승의 울음소리를 들었다.\r\n\r\n늑대는 아니고, 혹시 곰일지도 모르겠다."'),
(231, '"셋째 날\r\n\r\n짐승의 울음소리가 밤새 계속됐고 오늘도 하루 종일 나를 따라다니며 광석 찾는 일을 방해했다. 아무래도 나를 쫓아다니는 곰이 있는 것 같다.\r\n\r\n가까이 오기만 해라. 머리에 정을 박아 줄 테니까!"'),
(232, '"넷째 날\r\n\r\n가지고 온 물품이 다 떨어져 간다. 식량은 아직 충분하지만, 이렇게 오랫동안 전차 밖의 야외에서 지낼 생각은 아니었기 때문에 에일 맥주를 두 통밖에 가져오지 않은 것이다.\r\n\r\n지난 이틀 동안 밤새도록 잠을 이루지 못했다. 바로 그 망할 놈의 울음소리 때문이다. 그리고 맥주가 거의 바닥났다.\r\n\r\n내일 해머풋과 우리의 증기 전차가 있는 곳으로 돌아가야 할 것 같다. 맥주 없이 이곳에서 길을 잃고 싶은 생각은 추호도 없으니까."'),
(233, '"다섯째 날\r\n\r\n그 망할 놈의 곰이 나를 덮쳤다. 한낮에 내 뒤에서 으르렁거리며 달려들어 공격해 왔다.\r\n\r\n놈이 바람을 등지고 공격해 왔더라면 놈이 다가오는 것을 냄새로 알 수 있었을 것이다. 놈의 냄새는 정말 고약했다. 지저분한 털과 썩은 숨결에서 풍기는 악취만으로도 어지러울 지경이었다.\r\n\r\n놈을 물리치긴 했지만 다리를 심하게 물렸다. 지금은 움직일 수도 없고, 에일 맥주도 바닥이 난 데다, 광석은 하나도 찾지 못했다. 제길!"'),
(234, '"여섯째 날\r\n\r\n아직까지 곰은 다시 나타나지 않았다. 내 공격으로 꽤 큰 타격을 입은 모양이다. 하지만 여전히 놈의 울음소리는 들린다. 놈은 내가 죽기를 기다리는 것 같다.\r\n\r\n이 책을 발견하는 이에게. 당신에게 한 가지 부탁이 있습니다. 저 지저분한 곰을 처치해 주십시오. 놈을 처치하고 이 책을 내 친구 해머풋에게 돌려주시기 바랍니다. 그가 무슨 일이 일어난 것인지 궁금해 할 테니까요. 그리고 내 갑옷은 당신이 가지시기 바랍니다. 늙은 썩은발톱을 상대하려면 필요할 겁니다!"'),
(235, '"다크샤이어 시장 엘로 이본로크 보시오. 귀하의 마을에 대해 좋지 않은 소식을 전하게 되어 유감이군. 나는 무에서 유를 창조하는 자요. 이 편지를 전하는 이를 속여 끔찍한 피조물을 만드는 걸 돕도록 했소. 바로 살과 뼈, 그리고 저주받은 금속으로 만들어진 악귀지. 당신이 이 편지를 읽는 지금 이 순간, 그 피조물은 내 초라한 집 밖에서 이를 갈며 내 학살 명령을 기다리고 있을 것이오.\r\n무슨 말인지 곧 알게 될 거요.\r\n\r\n-장의사"'),
(236, '여러 생물의 화석에 대한 연구를 통해 나는 고대에 로다미어 호수에 엄청난 전염이 발생했다는 사실을 추론해 냈다. 그렇다면 원인은 무었이었을까? 그 원인은 영원히 밝혀지지 않을지도 모른다. 하지만 호수 바닥에 널려 있는 수많은 잔해들로 미루어 볼 때 전염 속도는 놀라울 정도로 빨랐던 것 같다.'),
(237, '과거의 일을 밝혀내기 위해 나는 이 수수께끼에 대한 새로운 단서가 발견되기를 바라면서 현존하는 생물들을 조사하기 시작했다. 호수덤불괴물과 호수이끼괴물은 로다미어 호수 한가운데 있는 섬에 사는 고대 짐승이다. 이 짐승들의 몸에는 일부 화석의 흔적이 남아 있는 물질과 유사한 이끼가 자란다. 이러한 연관성이 무엇을 의미하는지 알아내기 위해서는 조사가 더 필요할 것 같다. '),
(238, '이끼 견본을 채집하는 동안 피비린내나는 전투 장면을 목격했다. 썩은지느러미멀록이 약탈을 꾀하는 놀무리에게 포위를 당한 것이었다. 전장에는 놀과 멀록의 시체가 여기저기 흩어져 있었다. 심하게 손상된 멀록의 시체를 지나치다가 상처에서 처음 보는 굳어진 종양이 자라 나오는 것을 발견했다. 종양을 연구하기 시작하면서 이 종양이 내가 수집하던 이끼와 유사한 특성이 있다는 사실이 확실해졌다. 하지만 불행히도, 종양을 하나밖에 발견하지 못했다.'),
(243, '이끼 샘플을 채집하던 중, 나는 피비린내 나는 전투 현장을 목격했다. 사악한 지느러미 멀록 부족이 약탈을 일삼는 놀 무리에게 포위당한 참극이었다. 전장에는 놀과 멀록의 시체가 널려 있었다. 끔찍하게 훼손된 멀록 시체 옆을 지나가다 상처에서 튀어나온 이상한 딱딱한 종양을 발견했다. 종양을 자세히 살펴보니 내가 채집하던 이끼와 비슷한 성질을 가지고 있다는 것이 분명해졌다. 하지만 아쉽게도 그 종양 외에는 다른 종양을 찾을 수 없었다.'),
(244, '"베소르 아이스샤드 경\r\n\r\n\r\n경의 뜻에 따라 요청하신 요원을 보냅니다. 바로 이 명령서를 가져가는 이가 적임자입니다.\r\n\r\n\r\n이 자는 믿을 만하고 충분히 명령을 수행할 능력이 있음을 보여 주었습니다. 스컬지 군대를 상대로 능력을 입증해 보인 자이니만큼 경의 임무에 적격일 거라고 생각합니다.\r\n\r\n\r\n여왕 폐하의 영광이 있기를...\r\n\r\n- 집정관 세브렌 올림\r\n"'),
(245, '"실종된 하사관 키샨을 찾습니다.\r\n\r\n돌망루 요새에서 있었던 혈투에서 마지막으로 목격된 것으로 확인되었으며, 검은바위부족 오크들에 의해 끌려갔다는 보고가 있었습니다.\r\n\r\n레이크샤이어 북쪽, 불타는 평원으로 가는 길 바로 서쪽에 위치한 검은바위부족의 주둔지에 전쟁 포로로 잡혀 있을 것으로 추정됩니다.\r\n\r\n집정관 솔로몬의 명으로, 하사관 키샨을 구출하는 데 도움을 주는 이에게는 치안대장 매리스가 보상할 것입니다."'),
(246, '"지금 나는 언제나 그랬던 것처럼 까마귀 언덕의 버려진 마을에 숨어 있다. 놈들이 스벤의 아내에게 사용했던 그 힘이 무엇이든 나는 그 힘을 감당할 수가 없다. 그리고 놈들이 아직까지도 그 낫을 찾기 위해 그늘숲을 수색하고 있다는 사실을 알고 있다. 그 낫이 지금 내 손에 없다는 것에 대해 신께 감사한다. 만약 내가 지금까지 그걸 가지고 있었더라면 이미 놈들에게 발각됐을 것이다. 지금도 마음 속으로는 언젠가 놈들이 나를 발견할 것이라는 것을 알고 있다.\r\n\r\n난 너무 지쳤다."'),
(248, '주인님, 안녕하십니까.\n\n이 편지를 이런 식으로 보내게 된 점 용서를 구합니다. 알터랙에 있는 제 그림자 마법사들이 자기 임무에 정신이 팔려 있어서, 어쩔 수 없이 새로 동맹을 맺은 나라에서 징집한 전령을 통해 이 보고서를 전하게 되었습니다. 하지만 이 편지는 우리가 가진 가장 난해한 암호 중 하나로 암호화해 두었으니, 그 내용은 시골뜨기들이 절대 해독할 수 없을 겁니다.'),
(249, '발릭, 우리가 돌아올 때까지 노예를 잘 지키고 있도록 하라. `그것`을 이곳에 두는 것은 이제 안전하지 않다. 우리는 아무도 눈치 채지 못하게 북쪽으로 이동할 것이다.   녀석들은 짐승에 지나지 않지만 포악한 짐승들이 무리를 이루면 걱정할 만한 이유가 되지. 그러니 녀석들의 성질을 건드릴 만한 것들은 모조리 숨기는 게 좋아. 녀석들이 무리를 지어 공격해오면 안 되니까 말이야.'),
(250, '"데피아즈단 본부에서 파견된 이들이 징세관과 접촉할 것이다. 그 후 징세관이 수집된 황금을 이송한다.\r\n\r\n이 과정을 수행함에 있어 실패란 있을 수 없으며 신중히 처리되어야 함을 명심하기 바란다. 황금 수송에 대한 책임은 징세관에게 있지만, 질서 있고 주의 깊게 자신의 역할이 수행되도록 하는 것은 궁극적으로 데피아즈단 구성원 각자의 책임이다."'),
(251, '"형제들이여, 우리는 한때 자부심 있는 장인이었다는 사실을 기억하기 바란다. 우리는 예전에 우리가 장인이었을 때와 마찬가지로 지금 우리에게 주어진 임무를 정확하게 수행해 낼 것이다.\r\n\r\n-EVC"'),
(252, '"아버지께서 남아 우리 가족을 지키기로 결정하신 것이 큰 실수가 아니었는지 걱정스럽소. 스컬지 군대가 티리스팔 숲을 통해 무서운 기세로 진격하고 있고, 우리가 만반의 방어 태세를 갖췄다고 해도 내 형제 데블린의 배반 이후에 우리는 놈들의 계속되는 공격에 저항할 힘과 병력이 부족한 실정이오.\r\n\r\n이베트, 이 편지를 받으면 데블린이 배반자라는 사실을 꼭 알아 두기 바라오."'),
(253, '"데블린은 실의에 빠져 불운 속에서 빠져나올 탈출구를 찾고 있었고 그러던 중 스컬지와 계약을 맺게 된 것이오. 어떤 보상을 약속받았기에 배신을 한 것인지는 모르지만, 내 생각엔 그럴듯한 거짓말일 것이 자명하오.\r\n\r\n그를 보게 되면 도망치도록 하시오. 그는 이제 악귀일 뿐이니까 말이오. 며칠 전 밤 그는 우리 경비병 둘을 살해하고 소규모 스컬지 부대를 잠입시켜 다수의 아군이 취침하고 있는 곳으로 데려왔었소."'),
(254, '"놈들의 매복 공격은 잔인했소. 우리는 미처 반격하기도 전에 삼분의 일이 희생됐소. 이제 변경을 지킬 경비병도 부족할 실정이오. 우리의 빈약한 방어선이 무너지고 스컬지가 공격해 오는 건 이제 시간 문제일 뿐이오.\r\n\r\n그 저주받은 밤에 절망적인 얼굴의 사람들과 음산한 얼굴의 스컬지들 사이에서 데블린의 얼굴을 봤지만 그는 내가 붙잡기 전에 사라져 버렸소. 아마 벌써 죽었거나 아니면 아직도 스컬지의 앞잡이로 살고 있겠지.\r\n\r\n어쨌든, 그는 이제 괴물이오."'),
(255, '"데블린은 우리가 스컬지에 대항하려 하면 비참한 최후를 맞게 될 거라고 경고했었소. 그들이 티리스팔 숲에 처음 발을 들여놓았을 때 우리에게 그런 얘길 했었지. 우리를 포위하기 훨씬 전에 말이오. 아마 그는 우리가 떠나기를 간절히 바랬던 것이거나, 아니면 회심의 미소를 짓고 있었던 것일지도 모르지.\r\n\r\n데블린은 언제나 진의를 파악하기 힘든 자였소. 그는 어렸을 때부터 우리에게 수수께끼 같은 존재였지."'),
(256, '"하지만 결국 그가 옳았고 우리는 비참한 최후를 맞았소. 아가만드 가문은 이제 여기서 끝나는가 보오. 아직은 살아 있지만 나도 곧 죽게 되리라는 것을 알고 있소.\r\n\r\n난 두렵지 않고 내 가족과 함께 남아 있었던 것에 대해 일말의 후회도 없소. 하지만 결국 마지막에 떠오르는 건 당신이구려.\r\n\r\n사랑하는 이베트, 당신은 반드시 살아 남아야 하오. 내가 편히 눈감을 수 있도록.\r\n- 투르만"'),
(257, '우리의 계획은 순조롭게 진행되고 있습니다. 앞서 말씀드린 대로, 우리는 비밀결사대라고 자칭하는 인간 집단과 동맹을 맺었습니다. 그들의 지도자들은 한때 알터랙의 귀족이었으며, 이곳을 다시 한번 지배하려 하고 있습니다.\n\n그래서 그들은 우리와 거래를 했습니다. 그들이 후회하게 될 거래 말입니다.'),
(258, '현재 비밀결사대는 이 지역에서 큰 영향력을 행사하지 못하고 있지만, 지형을 잘 알고 있으며 앞으로의 임무에 필요한 충분한 병력을 확보해 놓았습니다. 적절한 지휘만 있다면 비밀결사대가 머지않아 다시 알터랙을 지배하게 될 것이라고 확신합니다.\n\n또한, 우리는 비밀결사대에게 인근 아라시 고원에 있는 스트롬가드 시를 목표로 삼도록 권고했습니다. 스트롬가드는 우리 군대와 오우거, 그리고 스트롬가드 인간들 사이의 전쟁터이지만, 신중한 전술을 펼친다면 한때 위대했던 이 도시를 우리가 차지할 수 있을 것이라고 생각합니다.'),
(259, '이 모든 것이 완료되면, 우리 계획의 다음 단계가 시작될 수 있을 것이다. 우리만의 국가와 이 지역에 기반을 마련하게 되면, 제3군단을 위한 길을 닦을 수 있을 것이다.\n\n머지않아, 군단의 군주들이 다시 한번 하늘에서 불을 쏟아부어 우리의 노고에 보답할 것이다!'),
(260, '이 모든 것이 완료되면, 우리 계획의 다음 단계가 시작될 수 있을 것이다. 우리만의 국가와 이 지역에 기반을 마련하게 되면, 제3군단을 위한 길을 닦을 수 있을 것이다. 머지않아, 군단의 군주들이 다시 한번 하늘에서 불을 쏟아부어 우리의 노고에 보답할 것이다!'),
(261, '힐스브래드 시 등록부 저희 힐스브래드 시민들은 위대한 군주, 아이언포지의 마그니 브론즈비어드 왕과 스톰윈드의 안두인 레인 왕께서 유지하시는 얼라이언스에 대한 충성과 헌신을 엄숙히 맹세합니다. 이곳은 웅장한 알터랙 산맥 기슭에 자리한 아름다운 도시 힐스브래드를 다스리고, 왕과 전능하신 얼라이언스에 세금을 납부한 모든 자들의 기록을 보관하기 위한 시 등록부입니다.'),
(262, '판사 러더퍼드 번사이드 모든 채무 청산 완료. 대장장이 에이버리 베링턴 모든 채무 청산 완료. 서기 호레이스 화이트스티드 모든 채무 청산 완료. 시의원 길리스 모든 채무 청산 완료. 시의원 훅스 모든 채무 청산 완료. 농부 게츠 모든 채무 청산 완료. 농부 레이 미지급 채무 있음. 수확 시 농산물로 지불 약속. 농부 라이온 미지급 채무 있음. 토지에서 퇴거 조치됨.'),
(263, '농부 칼라바 미지급 부채. 수확 시 농산물로 지불 약속. 시민 윌크스 모든 부채 상환 완료. 시민 보노안 모든 부채 상환 완료. 광부 웰티 미지급 부채. 아주렐로드 광석 다음 인도 시 지불 예정. 광부 시드니 미지급 부채. 아주렐로드 광석 다음 인도 시 지불 예정. 광부 해킷 미지급 부채. 아주렐로드 광석 다음 인도 시 지불 예정.'),
(265, '광부 오웰 미지급 부채. 아주렐로드 광석 다음 납품 시 지불 예정. 광부 피츠제럴드 미지급 부채. 아주렐로드 광석 다음 납품 시 지불 예정. 시민 네더랜드 모든 부채 상환 완료. 시민 메이 모든 부채 상환 완료. 반장 본즈 미지급 부채. 아주렐로드 광석 다음 납품 시 지불 예정.'),
(266, '"소규모의 언데드 무리의 우두머리인 케간 다크마르란 자가 우리와 그들의 관계에도 자신들의 동지들로부터 은신할 곳을 찾아 우리에게 왔다. 그의 피부는 썩고 있었고 피가 오랫동안 통하지 않은 것 같았지만, 그의 행동은 매우 위엄 있고 자신보다는 동료의 안전을 더 걱정하는 것 같았다. 사실 그는 내 주위의 인간들에게도 찾아보기 힘든 인간애를 소유하고 있었다."'),
(267, '"그런데 내가 이런 사실을 언급하는 이유는 무엇일까? 바로 지금부터 써 나갈 내용에 신빙성을 부여하기 위함이다. 왜냐하면 이 내용은 케간의 입에서 나온 것이고, 내 동료들이 이 일지를 읽고 내가 그의 말을 믿게 된 이유를 알아주길 바라기 때문이다.\r\n\r\n""고대 신들 중에서 살아남은 자들이 아직 이 세계 깊은 곳에 남아 있다. 새로운 세력이 이 고대의 힘을 이용하기 위해 혈안이 되어 있으며, 성공하는 자는 적에 대항할 강력한 무기를 손에 넣게 될 것이다."""'),
(268, '"이것이 바로 케간이 내게 그의 혈석 펜던트를 주며 한 말이다. 그때 그의 눈은 공포와 함께 경의의 빛이 빛나고 있는 것 같았다. 그리고 내 손에 닿은 그의 손의 느낌으로 볼 때 내게 펜던트를 넘겨주는 것이 썩 내키지 않는 것 같았다. 뭔가 좋지 않은 기분이 날 엄습했는데, 지금까지도 그게 그의 죽은 살갗이 닿았기 때문이었는지, 아니면 펜던트가 내 피부를 스멀거리게 한 것이었는지 모르겠다.\r\n\r\n나는 펜던트에 담겨 있는 어떤 힘을 느꼈다. 깊고, 숨겨져 있는, 뭔가에 굶주려 있는 힘. 그리고 해방을 갈망하는 힘."'),
(269, '"달라란에 있는 내 동료들은 케간과 그의 부하들이 가져온 혈석에 대한 연구를 놓고 망설이며, 대신 이 네 명의 도망자를 격리하고 그들과 함께 혈석을 그대로 놔두었지만, 나는 그의 혈석 펜던트를 연구해 주기를 바라는 케간의 진심을 외면할 수 없었다."'),
(270, '"나는 이런 종류의 돌이 마법 특성을 가질 수 있으며, 언젠가는 우리의 적이 혈석을 이용해 우리를 공격하게 될지도 모르기 때문에, 우리 달라란 마술사들이 혈석의 힘을 이용하고 싶지 않더라도 최소한 그 특성은 알아 두어야 한다는 것을 밝혀 보이고 싶었다.\r\n\r\n그렇게 내 연구가 시작된 것이다."'),
(271, '"나는 혈석이 석영이나 흑요석과 같은 암석의 일종이라는 가정 하에 실험을 시작했다. 따라서 이를 확인할 일련의 처리 과정에 착수했다. 혈석에 포함된 광물의 종류, 혈석의 색과 경도를 만들어낸 힘의 정체, 그리고 암석 및 광석의 공통적인 기타 특성... 하지만 실망스럽게도 혈석 펜던트는 처리 과정에서 일반 광석과는 다른 반응을 보였다."'),
(272, '"사실, 기대했던 것과는 정반대의 반응을 보이는 경우가 많았다. 펜던트가 일부러 내 실험을 망치려 들기라도 하듯 말이다.\r\n\r\n마치 스스로 생각하고 살아 있는 것처럼...\r\n\r\n나는 화가 나긴 했지만 희망을 잃지는 않았다. 그리고 이제 펜던트를 움직이지 않는 암석 조각이 아니라 살아 있는 생명체로 여기기로 했다.\r\n\r\n하지만 나는 또다시 실패하고 말았다."'),
(273, '"내가 실시한 새로운 실험 중 그 어떤 것으로도 혈석의 기원을 밝힐 수 없었다. 그때까지 내가 푼 유일한 수수께끼라고는 혈석이 살아 있는 것도, 그렇다고 죽은 것도 아니라는 사실뿐이었다.\r\n\r\n하지만 바로 그때, 실패 직전에 돌파구가 마련됐다. 가장 최근의 실험에 사용된 유리 비커는 이가 빠져서 가장자리를 따라 작은 홈들이 생겨 있었다. 실험이 다시 아무 소득 없이 끝나자 나는 작업대를 청소하다가 비커에 손을 베었다."'),
(274, '"상처는 깊지 않았지만 피가 많이 났다. 상처 입은 손가락에 붕대를 감기 전에 상당량의 피가 작업대 위에 흘러 있었다.\r\n\r\n피 때문에 다시 엉망이 되어 버린 작업대를 닦다가 나는 참으로 기이한 현상을 목격했다."'),
(275, '"혈석 펜던트 근처에 떨어진 피가 마치 중력에 이끌리기라도 하는 것처럼 그 보석을 향해 서서히 움직이고 있는 것이었다. 펜던트에 닿은 피는 사라져 버린 것처럼 보였고, 더 많은 피를 흡수할수록 혈석의 붉은색은 진해져 갔다."'),
(276, '"이 광경을 본 후, 머리가 가벼워졌다. 아마 방금 입은 상처 탓이거나(그 정도로 많은 피를 흘렸다고 생각하지는 않지만), 아니면 그토록 많은 좌절을 겪은 후 마침내 혈석의 특성 중 하나를 밝혀 냈기 때문이리라. 나는 뒤에 있는 작업용 의자를 끌어다 앉아 생각에 잠겼다. 머릿속에 수많은 생각과 의문들이 빠르게 오가면서 혼란과 압박감으로 쓰러질 것 같았다.\r\n\r\n혈석이 피를 마시는 건가? 피를 원하고 있는 건가? 피를 빨아들이는 건가?"')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(277, '"아니면 혈석 자체가 피로 만들어진 것인가? 만약 그렇다면 누구의 피로 만들어진 것인가? 내 피? 아니면 다른 인간의 피? 동물의 피?\r\n\r\n그것도 아니라면 혈석은 알려지지 않은 어떤 존재의 피란 말인가? 케간이 내게 펜던트를 건네 줄 때 두려워하면서도 경의를 표했던 바로 그 존재.\r\n\r\n그것은 반드시 답을 찾아야 할 중요한 의문이다. 이것이 바로 수수께끼의 열쇠인 것이다."'),
(278, '"내 안에서 다시 뜨거운 열의가 타올랐고 다시 실험에 착수했다. 이번에는 어떠한 가정도 하지 않고 내가 할 수 있는 모든 실험을 꼼꼼하게 실행했다. 때문에 전보다 엄청나게 많은 노력이 필요했지만 그 정도는 기꺼이 감수할 만큼 나는 해답을 발견하기를 원하고 있었다.\r\n\r\n그리고, 비록 나의 연구실은 작고 도와줄 조수도 없지만 나는 혈석의 또 다른 흥미로운 성질을 발견해 냈다."'),
(279, '"피뿐만 아니라 혈석에는 정령의 힘들이 깃들여 있었다. 불, 물, 천둥, 그리고 바위가 피(과연 누구의 피란 말인가?)와 섞여 있으며, 이 혼합물은 겉보기에 움직임이 없어 보이지만 내부적으로는 이 모든 힘들이 서로 격렬히 충돌하고 있는 것 같았다. 이제 이 놀랍고도 불길한 예감이 드는 물질에 대해 더 많은 의문이 생겨났다."'),
(280, '하지만 그 모든 의문에 답하려면 펜던트에 관해 더 많은 연구와 실험이 행해져야 한다. 하지만 로다미어 포로수용소는 그러한 일을 위해 인력이나 장비를 배정할 상황이 아니라는 점이 우려된다. 그래서 나는 실험 초기에 내가 겪었던 시행착오를 반복하지 않도록 실험 방법에 대한 구체적인 지침과 함께 급사를 통해 혈석 펜던트를 달라란으로 보냈다.'),
(281, '"이러한 실험의 결과를 기다리는 동안 나는 케간과 이야기를 나눴다. 혈석에 대해 아는 것을 말해 달라고 끈질기게 부탁했지만 그는 펜던트를 주던 날 했던 말 외에는 절대 입을 열지 않았다. 그리고 자신이 ""포세이큰"" (그는 자신의 언데드 일족을 이렇게 불렀다.)이라는 집단에 몸담고 있을 때의 이야기도 잘 하지 않았다."'),
(282, '"하지만 케간은 다른 주제에 관해서는 이야기하기를 매우 좋아했다. 특히, 자신이 멸망 전의 로데론에서 자라던 시절의 이야기를 자주 했다.\r\n\r\n이미 폐허가 되어 사멸했지만 그는 아직도 그 사라진 왕국에 대해 큰 애정이 있었다.\r\n\r\n난 점점 더 케간을 좋아하게 되었고 덕분에 인내심을 가지고 실험 결과를 기다릴 수 있었다."'),
(283, '"하지만 아무 소식도 없이 몇 주가 지나자 내 인내심도 흔들리기 시작했다. 그래서 달라란에 자세히 문의해 본 결과, 혈석이 내 동료들에게 전달되지 않았다는 사실을 알게 되었다. 내가 보낸 급사가 혈석 펜던트와 함께 도중에 실종돼 버린 것이다!\r\n\r\n이건 심각한 사태다. 케간과 그의 부하들에게 실험에 사용할 수 있는 혈석 견본이 아직 남아 있기는 하지만, 펜던트가 불미스러운 자의 손에 들어가게 될까 봐 걱정이다."'),
(284, '"나는 다른 전령을 달라란으로 보냈고, 아직도 보호 지역 밖의 폐허에서 펜던트를 찾고 있다는 소식을 전해 듣고 있다.\r\n\r\n너무 늦기 전에 되찾게 되기만을 바랄 뿐이다."'),
(285, '"방랑자 그리렉의 이야기\r\n\r\n[...서판의 첫 부분은 닳아 지워졌지만 마지막 부분은 알아볼 수 있습니다...]\r\n\r\n그리렉은 정글을 짓밟아 버렸다. 그의 눈은 분노로 불타고 가슴은 우레와 같이 뛰고 있었다. 허공을 향해 분노로 울부짖은 그는 팔을 쳐들었다.\r\n\r\n오른쪽 팔을 잃고 나머지 한 쪽 팔만으로 이어온 사냥을 통해 그의 왼쪽 팔은 강하고 튼튼하게 단련되어 있었다."'),
(286, '"트롤의 전설, 제 3권 해일의 돌\r\n\r\n저자: 대마법사 앤자이럼 룬위버\r\n\r\n달라란\r\n\r\n서문\r\n\r\n고대 구루바시 제국은 매우 매혹적이고 흥미로운 전설의 근원이다. 이 전설은 그들의 주변 환경에 대한 신념과 사회적 규범에 대한 고찰로 자연을 향한 위대한 숭배 정신에 초점을 맞추고 있다. 본 연구의 이전 부분에서는 그들의 뱀 숭배의 여러 가지 측면에 대해 자세히 살펴봤다.\r\n"'),
(287, '"쿠르트란 와일드해머\r\n\r\n저명한 용기사이자 맹금의 봉우리의 그리핀 조련사. 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대 소속 그리핀 비행사단의 사령관. 사망한 것으로 추정.\r\n\r\n바람 소리에 창공의 리의 울음소리가 들리면 산봉우리에 부딪혀 울리는 그대의 우렁찬 망치 소리가 들릴 겁니다. 형제여, 저 세상에서도 힘차게 나아가십시오. 조상들의 전당에서 편히 쉬시기를...\r\n\r\n- 맹금의 봉우리의 군주, 폴스타드 와일드해머"'),
(288, '"순찰대장 알레리아 윈드러너\r\n\r\n쿠엘탈라스의 저명한 트롤 사냥꾼. 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대에서 정찰대 및 첩보부대를 지휘. 사망한 것으로 추정.\r\n\r\n바람을 가르는 화살만큼이나 곧은 마음의 소유자여. 그대는 우리 순찰대의 가장 빛나는 존재였으며 우리 종족이 가장 사랑했던 이였습니다.\r\n\r\n- 쿠엘탈라스의 순찰대 사령관, 실바나스 윈드러너"'),
(289, '"키린 토의 대마법사 카드가\r\n\r\n메디브의 전 제자이자 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대의 총사령관. 사망한 것으로 추정.\r\n\r\n그 누구도 그대처럼 헌신적인 자세로 마법과 전쟁의 어두운 소용돌이 속을 뛰어든 자는 없었으니... 지혜로운 방랑자여, 당신이 어디에 있든지 평안을 빕니다\r\n\t\t\t\t\r\n- 달라란의 대마법사, 안토니다스"'),
(290, '"투랄리온 장군\r\n\r\n전직 안두인 로서 경의 부관. 은빛 성기사단원. 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대의 장성. 사망한 것으로 추정.\r\n\r\n에사루스 다르 노 `다라도르` - 피와 명예로 기립니다.\r\n친구여, 자네는 정의와 미덕의 오른손이었네. 자네 이름은 우리의 전당에서 영원히 기려질 것일세.\r\n\r\n- 은빛 성기사단, 빛의 수호자 우서 경"'),
(291, '"다나스 트롤베인\r\n\r\n스트롬가드의 민병대 사령관. 장군 투랄리온의 전술 조언가이자 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대의 군단장. 사망한 것으로 추정.\r\n\r\n사랑하는 조카야, 너에 대한 기억을 잊지 않을 것이며 너의 희생에 경의를 표하는 바이다. 우리의 영광스러운 제국을 건설한 이후에도 너와 같은 영웅이 용맹한 전사의 길을 피로 적셔 왔단다.\r\n\r\n- 스트롬가드의 군주, 토라스 트롤베인"'),
(292, '"최초의 성기사이며 은빛 성기사단의 설립자\r\n빛의 수호자 우서 여기 잠들다.\r\n\r\n우서 경은 로데론 왕국 수호를 위해 평생을 바치다 숨을 거두었다. 비록 자신이 가장 아끼던 제자에게 배신을 당했으나 우리는 그의 영혼이 여전히 살아 있다고 믿는다. 우리의 황폐해진 땅 가까이에 어둠이 손을 뻗쳐올 때에도 그는 계속 우리를 지켜보고 있으니... 그의 빛은 전 인류의 빛. 그가 보여준 정신을 따르는 한 그 빛은 절대 꺼지지 않을 것이다.\r\n\t\t\t\t\t\t\t\t\t- 무명"'),
(293, '"지금부터는 트롤과 바다의 흥미롭고 독특한 관계에 대해 알아보고자 한다.\r\n\r\n대해\r\n\r\n구루바시 제국은 삼면이 바다로 둘러싸여 있었기 때문에 그들의 사회에서 물이 중요한 의미가 있었던 것은 너무나 당연한 일이라 할 수 있다. 트롤은 그들의 정글 제국을 누비며 광활한 영토를 지배했지만 바다는 쉽게 그들에게 정복되지 않았다. 바다는 광대하고 무한했으며, 강력한 트롤들조차 쩔쩔매게 하는 이웃이었다.\r\n"'),
(294, '"최근 밝혀진 사실들로 미루어 볼 때 트롤들은 대해 너머의 땅을 탐험하는 데는 거의 관심이 없었던 것 같다. 트롤 종족은 아제로스, 카즈 모단, 그리고 로데론에 이르는 광활한 지역에서 만날 수 있지만, 새롭게 발견된 칼림도어의 땅이나 남쪽 바다의 섬에서는 그들 문명의 흔적이 거의 발견되지 않았다. 이러한 사실이 트롤이 그들의 대륙 영토에만 머물고 더 멀리까지는 진출하려 하지 않았음을 나타내는 것인지,\r\n"'),
(295, '"아니면 대양을 항해하기 위해 필요한 기술을 개발하는 데 실패했음을 의미하는 것인지를 밝히기 위해서는 본 글의 범위를 넘어서는, 더욱 심도 있는 조사와 분석이 이루어져야 할 것이다.\r\n\r\n하지만 누구도 그 거대한 문명의 존재를 부정할 수 없거니와, 가시덤불 골짜기의 광활한 트롤 폐허에서 새로 발견된 자료들은 이전에는 알려지지 않았거나 문헌에 기록되지 않았던 트롤과 바다의 관계를 보여 주고 있다.\r\n"'),
(296, '"해일의 돌\r\n\r\n가시덤불 골짜기의 트롤 폐허에 대한 조사를 통해 최근 새로 발견된 자료들은 ""해일의 돌""이라 알려진 유물에 대해 언급하고 있다. 트롤 전설의 여러 부분들을 조합해 보면 해일의 돌과 이 돌이 고대 구루바시 제국이 갖는 중요성에 대해 좀 더 전체적으로 파악할 수 있을 것이다.\r\n\r\n해일의 돌은 그것을 지니고 있는 자에게 여러 형태의 물, 강, 비, 조류 등을 제어할 수 있는 능력을 부여했던 것으로 보인다. 해일의 돌의 사용과 관련된 여러 이야기들로 미루어\r\n"'),
(297, '"나는 그것이 실제로 강력한 바다 정령인 바다제왕의 힘을 물리적으로 형상화한 것이라고 추측해 왔다. 그런 물건이 어떻게, 그리고 왜 바다제왕의 통제에서 벗어나 트롤의 손에 들어갔느냐 하는 것은 나로서는 알 수 없는 또 다른 의문점이다.\r\n\r\n해일의 운반자\r\n\r\n그 이름의 기원이 된 조류가 넘실대듯 해일의 돌은 트롤과 함께하다가 이들을 떠났으며, 한 번에 한 세대 이상 오랜 기간 동안 꾸준히 트롤이 소유했던 적은 없었다.\r\n"'),
(298, '"트롤 전설에 따르면 해일의 돌은 가시덤불 골짜기 해안을 따라 여행하던 한 트롤 전사에 의해 발견되어 처음으로 구루바시 제국에 들어가게 되었다고 한다. 트롤 전사는 내부에 우유처럼 흰 가닥들이 떠서 흘러 다니는 신비한 푸른 돌을 우연히 발견했다. 돌에 흥미를 느낀 전사는 돌을 가지고 여행을 계속했다.\r\n\r\n몇 주 그리고 몇 달의 시간이 흐르면서 전사는 그 돌이 자신에게 물을 제어할 수 있는 능력을 주었다는 사실을 알게 되었다. 그는 물의 정령과,\r\n"'),
(299, '"완전히 물로만 이루어진 생명체를 불러낼 수 있었다. 그것은 키린 토의 강력한 마법사들만이 행할 수 있는 마법에 해당하는 것이었다.\r\n\r\n전사는 새로 발견한 능력을 황제에게 보이기 위해 제국의 수도인 줄구룹으로 향했다. 그가 제국 수도의 중심부에서 그 힘을 선보이자 쉽게 왕궁의 주목을 받게 되었다. 그 힘에 크게 놀란 구루바시 황제는 즉시 전사에게 왕궁의 명예로운 지위를 주고 ""해일의 운반자""라는 이름을 하사하여 옛 이름 대신 사용하도록 했다.\r\n"'),
(300, '"해일의 운반자는 전투에서 그의 명령에 따르는 물의 정령을 불러내고 가시덤불 골짜기의 물이 제국에 유리한 방향으로 흐르도록 조작하며 여러 해 동안 구루바시 제국을 위해 일했다. 하지만 세월이 흐르면서 해일의 운반자는 점점 더 은둔 생활에 빠져들어 왕궁을 떠나 지내는 시간이 길어졌다.\r\n\r\n해일의 운반자는 왕궁의 감시의 눈길을 피해 한 가지 비밀을 숨기고 있었다. 해일의 돌은 그에게 그러한 능력과 함께 저주를 내렸던 것이다. 몇 해가 지나면서\r\n"'),
(301, '"해일의 운반자는 서서히 모습을 감췄다. 죽음을 맞이할 때까지 밀물과 썰물이 반복될 때마다 해일의 운반자는 그 존재가 사라졌다가 나타나기를 반복하면서 점점 몸의 형태를 잃고 사라져갔다. 결국 마지막에는 그가 맨 처음 해일의 돌을 발견했던 해변으로 돌아가서는 바다로 걸어 들어가 영원히 사라져 버렸다.\r\n\r\n수세대가 지난 후, 해일의 돌은 가시덤불 골짜기 해변으로 휩쓸려왔고 또 다른 해일의 운반자가 선택되어 그 트롤이 해일의 돌을 다시\r\n"'),
(302, '"줄구룹으로 가져왔다. 이런 식으로 수세대 동안 해일의 돌은 조류와 함께 모습을 나타냈다가 다시 해일 속으로 해일의 운반자와 함께 사라지기를 반복했다.\r\n\r\n오늘날 곳곳에서 해일의 돌에 대한 이야기들이 전해지지만, 왜 그런 힘을 가진 물건이 그토록 규칙적으로 나타나며, 과연 누가 그렇게 만든 것인가 하는 것은 여전히 수수께끼로 남아 있다.\r\n"'),
(303, '"붉은해적단의 명령서\r\n\r\n이것이 무법항에서 우리에게 주어진 마지막 기회이므로 동지들은 이 명령서를 주의 깊게 읽도록 하라.\r\n\r\n나는 올 던큰을 북쪽으로 정찰을 보내 신호를 기다리라고 지시했다.\r\n\r\n담셀의 행운호는 보급품을 싣기 위해 남쪽 곶에 닻을 내릴 것이다. 난쟁이 스틸워터 선장은 선원들과 함께 물에 빠진 약탈물을 따라 항해할 준비를 하고 있다. 그 멍청이 브루터스가 모든 것을 손에 넣게 되는 것이다."'),
(306, '"킬하울 선장은 립타이드호를 남동쪽으로부터 해안으로 이동시키도록 하라. 신호가 있으면 그의 선원들이 배에서 내려 육지로 들어가도록 할 것이다.\r\n\r\n거대한 몸집의 살트후프는 사람들을 들고 흔들어 해치울 수 있을 정도의 힘을 가졌다. 레빌가즈와 시혼 앞에 지옥을 선사하도록 하라. 그들을 바다 밑바닥에 가라앉혀도 상관없다.\r\n\r\n함장들은 죽음의 폐광에서 밴클리프와 함께 진행하는 작은 계획에 유용할 것이라고 생각되는 것은 무엇이든 책임지고 회수해 오도록 하라."'),
(307, '"내가 아이언패치에게 사격 명령을 내리겠다. 포격 지원을 통해 어떤 검은바다 해적단의 선박도 항구를 떠나거나 들어오지 못하도록 하라.\r\n\r\n크림슨 베일호에서 포탄을 모두 빼낸 후 립타이드호와 함께 이동시켜 지원과 필요한 만큼의 예비 병력을 제공받도록 하겠다.\r\n\r\n살트후프와 그의 부하들이 마을을 불태우고 모든 선원들이 갑판에 오르고 나면 출항하여 폭풍 해안에서 무법항에 한 번 더 추가 포격을 가할 것이다.\r\n\r\n- 함장 피랠론"'),
(308, '"당시에는 잔질을 피해 그 썩어가는 배에서 도망가는 것이 현명하다고 생각했지만 갑자기 그대로 죽는 편이 더 나을지도 모른다는 생각이 들기 시작했다.\r\n\r\n우리 조상들의 가호로 살아남을 수 있었다고 생각했다. 하지만 지금은 평생 갇혀 살아야 한다면 무엇이 현명한 길인지 의문이 든다.\r\n"'),
(309, '"이 섬을 지배하는 저 괴물은 끔찍하리 만큼 강하다. 다른 모든 생물들은 하늘갈기고릴라와 긴발톱 흑표범 앞에서 무릎을 꿇는다. 지금까지도 놈의 울음소리가 들리는 듯하여 소름이 끼친다.\r\n\r\n놈들은 이 섬에 오는 모든 이를 해칠 것이다. 선조들의 가호를 믿을 수밖에..."'),
(310, '"우리 일족과 집이 그립다. 이 정글의 열기 대신 넓은 평야에 부는 바람을 느끼고 썬더 블러프 너머로 지는 석양을 바라볼 수만 있다면 더할 나위 없을 것이다.\r\n\r\n멀지 않은 곳에 바다가 있지만 내 몸과 화를 식혀 주지는 못한다. 갇혀 있었던 시절만 환기시킬 뿐이다."'),
(311, '1일차:  오전 6시~11시 - 상부  캠프, 오전 11시~11시 30분  - 휴식, 점심, 오전 11시  30분~오후 4시 - 협곡 통과, 오후   4시~7시  30분 - 상부 캠프.    2일차: 1일차와   동일한  일정. 3일차: 동일한 일정. 4일차: 동일한 일정이지만 한 가지 예외가 있었다. 해질녘 직전, 토르센이 협곡 아래로 내려가는 동안 나에게 대신 임무를 맡겼다. 나는 그가 우리 요원들을   만나러 간 줄 알았다. 하지만 그는 한 시간 후에 돌아왔다. 나는 그가 우리 요원들을 만나고 쿠르젠과 합류할 거라고 생각했는데, 뭔가 잘못된 것 같았다.'),
(312, '5일차:  토르센은 오늘 몹시 불안해 보였다. 어제 외출 중에 무엇을 보고 누구를 만났는지 모르겠지만, 분명 겁에 질린 모양이다. 우리   요원들이 그와 이야기를 나눴을 거라고 짐작했지만, 내가 토르센을 대신해 임무를 수행하는 동안 그가 어디에 갔었는지 묻자 그는 아무 말도 하지 않았다. 그는 내가 자신의 친구라고 믿고 있으며, 위험한 비밀로부터 나를 보호하고   있다고 생각하는 것 같다. 그의 충성심은 잘못된 것이지만, 매우 강하다. 그가 우리와 합류하면 쿠르젠의 부대에 큰 도움이 될 것이다.'),
(313, '6일째:  이른 아침, 토르센은 요화 하사와 오랫동안 이야기를 나누었다. 나는 아직 자는 척해야 했기에 그들의 대화가 들리지 않도록 움직일 수 없었다. 하지만 그들은 토르센의 이전 외출에 대해 이야기했을 거라고 짐작한다. 점심 식사   때 나는 토르센을 유심히 지켜보았고, 요화도 마찬가지라는 것을 알아챘다. 나중에 도렌이 토르센을 불렀다. 세 사람은 비밀을 공유하고 있다. 도렌과 요화는 토르센이 당신네 요원들과 만나고 있다는 것을 알고 있을 것이다. 그는 반군을   위해 스파이 활동을 하고 있다.'),
(314, '토르센에게 더 이상 정보를 줘서는 안 되며, 그를 제거해야 합니다. 그는 더 이상 우리 대령에게 쓸모가 없습니다. 기회가 주어진다면 제가 토르센을 처리하겠지만, 이 편지를 받으셨다면 아직 그럴 기회가 없었다는 것을 아실 겁니다. 그렇다면 토르센이 우리 요원들과 다시 만나는 것은 치명적인 일이 될 것입니다. 쿠르젠 만세, -M'),
(315, '의회가 당신을 아르거스 웨이크의 수장이자 인간과 드워프의 땅에서 그들의 전략을 지휘하는 총사령관으로 임명한 것은 현명한 결정이었습니다. 그리고 저는 알터랙에서 당신의 뜻을 따르는 자로서 봉사하게 되어 영광입니다.\n\n살게라스의 이름으로,\n\t\n나가즈, \n아르거스 대제사장'),
(316, '"못난 바보들!\r\n\r\n내 계획은 두 다리를 동시에 파괴하는 것이었다. 그런데 어리석은 네놈들은 어떻게 했느냐? 다리는 하나밖에 파괴하지 못했고 동맹 전체에 우리 계획만 알리는 꼴만 되지 않았느냐. 바보 같은 놈들!\r\n\r\n네 놈들의 실수를 만회할 마지막 기회를 주겠다. 예비 폭탄을 아라시 고원의 다리에서 그리 멀지 않은 곳에 숨겨 두었다.\r\n\r\n네 놈들의 임무를 완수하고 살아 있을 가치가 있다는 걸 증명하라!\r\n\r\n- 캄 딥퓨리"'),
(317, '저습지의 던 모드르에서$B$B사랑하는 사라에게,$B$B수일 안으로 탄돌 교각을 감시하기 위해 이동해야 할 것 같소, 이것이 당신에게 보내는 마지막 편지가 될까 두렵소. 내가 이 세상에 존제하지 않게 되었을 때 당신이 내 소식이나마 알 수 있도록 이렇게 몇 줄 적어야겠다는 생각이 드는구려.'),
(318, '이번 임무는 며칠 걸릴 것으로 보이는데 성공하면 아주 만족스러운 작전이 될 것 같소. 그리고 격전과 죽음이 도사리고 있을 거요. 하지만 내 기꺼이 얼라이언스를 위해 전장에서 쓰러질 각오가 되어 있소.$B$B우리가 추구하고 있는 대의에 대해 나는 한치의 의심도 없고 불안하지도 않을 만큼 내 용기와 믿음은 확고하다오.'),
(319, '아이언포지 왕국이 얼라이언스의 승리에 거는 기대가 얼마나 큰지 알고 있소. 또 우리가 대전쟁에서 피를 흘리며 고통 속에 사라져 간 이들에게 얼마나 큰 빚을 지고 있는지도 잘 알고 있소. 나는 얼라이언스를 수호하고 그 빚을 갚기 위해 이생에서의 내 모든 기쁨을 기꺼이, 아주 기꺼이 희생할 각오가 되어 있소.'),
(320, '사라, 당신을 향한 내 사랑은 영원할 것이오. 나를 감싸고 있는 강한 사랑의 끈은 오직 전능하신 신만이 끊을 수 있을 것이며, 왕국에 대한 내 충절은 강한 바람처럼 일어나 그 강한 사랑의 끈과 함께 전장에서 나를 굳건히 지탱시켜 주고 있소.'),
(321, '당신과 함께 한 행복했던 모든 순간들의 기억이 내 머릿속을 스쳐 지나가는구려. 신과 당신, 오랫동안 나의 기쁨이었던 이 두 존재에 대해 너무나 깊이 감사하고 있소. 당신과 함께 살면서 서로 사랑을 나누고 우리 자식들 곁에서 훌륭한 드워프로 성장해 가는 모습을 지켜보게 될 미래에 대한 희망을 포기하고 불살라 버리는 것이 내게 얼마나 힘든 일인지 모를 거요.'),
(322, '내가 감히 신의 섭리에 도전할 자격이 없다는 건 알지만, 누군가 내가 사랑하는 가족들에게 무사히 돌아가게 될 거라고 속삭이는 소리가 들리오. 어쩌면 공중에 떠다니는 우리 꼬마 애드거의 기도가 내게 전해진 것인지도 모르겠소. 사랑하는 사라, 내가 돌아가지 못하더라도 내가 당신을 얼마나 사랑하는지, 그리고 내가 전장에서 마지막 숨을 거두게 될 때 당신의 이름을 부를 것이라는 사실을 부디 잊지 말기 바라오.$B내가 저지른 많은 잘못과 당신에게 준 수많은 고통, 그리고 잦은 경솔함과 어리석음을 용서해 주시오.'),
(323, '내 눈물로 당신의 행복을 막는 더러운 것들을 모두 씻어 내고 이 세상의 모든 악과 싸워 사랑하는 당신과 우리 자식들을 위험으로부터 지킬 수가 있다면 얼마나 기쁘겠소.$B하지만 그럴 수가 없구려,$B황천에 가서라도 반드시 당신을 지켜볼 거요. 그리고 당신이 이승에서 세파를 이겨내는 동안 그 곁을 지키며 기다리겠소. 우리가 다시 만나 영원히 함께하게 될 그 날까지...'),
(324, '바다에서 솟아오른 거대한 물기둥, 넵툴론은 멸망할 운명에 처한 일랄라이를 향해 거대한 크라켄들을 보냈다. 그 몸집은 너무나 거대해서 해초 숲이 팔다리 사이로 흔들렸고, 레비아탄들이 몸속을 헤엄쳐$B$B다녔다. 가장 큰 크라켄은 팔을 높이 들어 바다에 내리쳐 파도를 일으켰다. 그리고 그 파도는 일랄라이를 향해 맹렬하게 돌진했다.'),
(325, '크라켄들이 포효하며 마치 바다 폭풍처럼 우렁찬 목소리를 냈다.$B$B"우리가 간다!$B$B" 민로스는 굳건히 서서 마법을 시전했다. 일랄리아로 향하던 파도가 갈라져 양쪽으로 흘러가더니 그 너머 정글을 가득 채웠다. 민로스는 부하들에게 속박 주문을 외우라고 명했고, 수십 명의 트롤들이 목소리를 높여 외치자 굉음이 울려 퍼졌다. 그리고 그중$B$B한 목소리가 우렁차게 울려 퍼졌다.'),
(326, '민로스는 포효했고, 그의 마법은 하수인들의 주문력을 모아 다가오는 크라켄에게 시전했습니다. 바다가 갈라지고 민로스의$B$B주문은 넵툴론의 하수인들을 향해 빠르게 날아갔습니다. 번개가 하늘을 가르고 주문이 그들을 강타하자 수천 개의 번개가 쏟아져 내리며 물을 끓이고 땅에 불타는 분화구를 만들었습니다. 민로스는$B$B자신의 주문이 거대한 짐승들을 쓰러뜨릴 것을 알고 승리의 함성을 질렀습니다.'),
(327, '하지만 크라켄은 아주 오래되었지, 정말 오래되었어. 그들은 땅이 처음 바다에서 솟아나던 때를$B$B기억했지. 그들은 고대 존재들이 지배하던 때와 여행자들이 와서 그들을 몰아내던 때를 기억했어. 그들은 마법이 새롭게 생겨나던$B$B때를 기억했지. 그들은 오래되었고 많은 비밀을 간직하고 있어. 민로스의 주문은 강력했지만, 트롤처럼 필멸의 존재였지.$B$B그래서 실패했어.'),
(328, '민로스는 크라켄을 속박하는 데 실패했지만, 오히려 그들을 격노시켰다. 오랜 세월 동안 필멸자가 그들에게 고통을 준 적이 없었기에, 트롤의$B$B주문은 고통스러웠다. 그래서 그들은 민로스의 주문 속박에서 벗어났지만, 곧 포효하며 분노에$B$B휩싸였다. 깊은 바다에서 거대한 파도가 솟아올라 육지를 향해 돌진하는 굉음이 들렸다. 파도가 일랄라이에 이르자 도시에 그림자를 드리웠다. 하지만$B$B도시를 파괴하기 직전, 크라켄은 멈춰 서서 자세를 잡았다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(329, '트롤 주술사들은 떨며 주인에게 부르짖었다. 민로스는 바다의 산들을 바라보며 운명에 맞서면서도 저항하는 듯한 모습을 보였다. 그는 추종자들에게 몸을 돌려 속삭였고, 트롤들은 그의 마지막 말을 돌에 새겼다. 그리고 민로스는 거대한 크라켄을 마주했다. 그는 얼굴을$B$B찡그리며 지팡이를 던졌다. 그것이 그의 마지막 용감한$B$B행동이었다. 크라켄은 민로스에게 분노를 쏟아부었고, 바다가 일랄라이를 덮쳤다. 그리고$B$B모든 것이 끝났다.'),
(330, '그러자 물이 정글 위로 쏟아져 내려 ​​모든 것을 휩쓸어 버렸습니다. 트롤과 짐승들은 물이 덮쳐 그들을 삼키자 비명을 질렀습니다.$B$B많은 구루바시들은 왜 바다가 자신들을 삼켰는지 궁금해했지만, 결국 그들은 죽어 아무것도$B$B알지 못했습니다. 마침내 물이 산에 이르렀을 때, 멈췄습니다. 잠잠해진 ​​물은 해안 너머로 물러났고, 죽음의 흔적을 남겼습니다. 물은$B$B물러났지만, 일랄라이 주변을 에워싸고 남아서 영원히 일랄라이를 물에 잠기게 했습니다.'),
(331, '그리고 줄구룹의 산맥 뒤에 안전하게 숨어 있던 족장 바르가줄은 정글로 나가 보니 그의 백성들이 흔적도 없이 사라진 것을 발견했습니다.$B$B그는 정복의 꿈이 좌절되자 절망에 빠졌습니다.$B$B그리고 뱀 민로스는 끝내 발견되지 않았습니다.'),
(332, '하지만 사라, 죽은 자들이 아제로스로 다시 돌아와 그들이 사랑했던 이들 주변을 몰래 맴돌 수 있다면, 나는 기쁜 날이나 슬픈 날이나, 칠흑 같이 깜깜한 밤이나 낮이나 언제나 당신 곁에 머무를 것이오. 당신의 볼에 부드러운 미풍이 분다면 그건 내 숨결일 것이며, 당신의 고동 치는 관자놀이에 서늘한 공기가 느껴진다면 그건 내 영혼이 당신 곁에 있기 때문일 거요.$B$B사라, 내 죽음을 슬퍼하지 마시오. 나는 잠시 당신곁을 떠나 당신을 기다리고 있다고 생각하시오. 우리는 반드시 다시 만날 테니까.$B$B--설리'),
(333, '친애하는 국왕 폐하께$B$B폐하와 같은 위대한 지도자의 뜻에 이의를 제기하는 것은 일개 병사의 부인이 할 일은 아닙니다만, 우리 땅에서 일어나고 있는 전쟁의 궁극적인 목적은 차가운 모단 호수의 수역에서부터 던 모로의 험춘하고 눈 덮인 산맥에 이르기까지 우리가 사랑하는 위대한 자연을 지키기 위한 것이라고 믿어 의심치 않습니다.'),
(334, '하지만 우리가 생명 수호의 이름 아래 치르고 있는 이 전쟁이 지금 어떤 대가를 요구하고 있습니까? 쓰러진 병사들을 보면서도 그토록 지키려고 애쓰는 생명들이 전장의 이슬로 사라져 가고 있다는 사실을 우리는 깨닫지 못하고 있습니다.$B$B얼마나 많은 검과 도끼 아래 우리의 미래를 내던져야 할까요? 얼마나 깊은 땅속에서 우리의 과거를 묻어야 할까요?'),
(335, '일개 병사의 아내된 몸으로 이런 질문을 하는 것이 불경하다는 것은 압니다. 하지만 지금 저는 비천한 병사의 미망인으로서 이 글을 적고 있습니다. 제남편 설리 발루가 폐하께는 수천 명의 병사들 중 하나일 뿐이겠지만, 제겐 아이들의 아버지이자 평생 하나뿐인 동반자였습니다.$B$B위대한 지도자시여, 제 요청이 불경하게 들리신다면 용서하십시오. 하지만 죽은 자가 이런 말을 드릴 수는 없기에...$B$B폐하의 충성스런 백성, 사라 발로 올림'),
(336, '"슈나이더 일가 귀중,\r\n\r\n안녕하시오. 운하 지역에서의 사업은 잘 되고 있으리라 믿소. 이곳 상업 지구는 급속히 번창하여 지금 편물 옷감 재고가 바닥난 상태라오. 그러니 가능한 한 빨리 통상적인 양의 옷감을 보내 주기 바라오.\r\n\r\n행운을 비오. 그리고 당신네 아들 투르만의 공부도 잘 진척되길 바라오.\r\n\r\n- 할란 바글리"'),
(337, '"쿨 티라스 함대 공식 명령서\r\n\r\n나 프라우드무어 함장은 칼림도어 해안의 최초 상륙 작전을 직접 지휘하겠다.\r\n\r\n내가 부재 중일 경우에는 부대장 베네딕트가 지휘권을 일임 받는다. 타이라가드 요새에서 12개월 동안 내 소식을 듣지 못할 경우 부대장 베네딕트가 해당 지역을 확보하기 위한 두 번째 작전을 지휘한다."'),
(338, '"그 동안 부관 알베롤드를 보내 칼림도어 대륙의 탐험 임무를 수행하도록 하겠다. 그의 부대는 임무를 완수한 다음 타이라가드 요새의 아군과 합류한다.\r\n\r\n부관 알베롤드의 임무는 상당한 시간이 소요될 것으로 예상된다. 새로운 땅은 광활하고 위험할 것이다. 그러나 나와 부대장 베네딕트에게 불운이 닥칠 경우 알베롤드의 부대가 요새를 맡도록 한다.\r\n\r\n저 요새가 우리 수중에 들어올 때까지 우리는 멈추지 않을 것이다.\r\n\r\n- 함장 프라우드무어"'),
(340, '<HTML>\n<BODY>\n<H1>호드 징병 추천서</H1>\n<BR></BR>\n<P>이 자는 호드의 이름으로 뛰어난 용기와 능력을 보여 주었습니다.그 용기와 능력을 크로스로드에서도 발휘할 수 있도록 즉시 임무를 맡기는 것이 좋을 것 같습니다.</P>\n<BR></BR>\n<BR></BR>\n<P>정중히 부탁드립니다.</P>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<P>촉망되는 인재로 판단됩니다.<BR></BR>\n- 타크린 패스시커</P>\n</BODY>\n</HTML>'),
(341, '<HTML>\n<BODY>\n<H1>호드 징집 등록</H1>\n<BR></BR>\n<P>이 사람은 호드의 이름으로 놀라운 힘과 기량을 보여주었습니다. 즉시 크로스로드 근무에 배치해야 합니다.</P>\n<BR></BR>\n<BR></BR>\n<P>삼가,\n<BR></BR>- 카르갈 배틀스카</P>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<P>좋아 보이는군.<BR></BR>\n- 타크린 패스시커</P>\n</BODY>\n</HTML>'),
(342, '"바엘 모단 발굴\r\n\r\n애초에 탐험가 연맹에서 파견한 조사단이 발견했던 내용이 옳았다. 이곳 땅에는 우리 종족에게 무한한 가치를 갖는 유물들이 묻혀 있다. 바엘 모단의 모래와 바위 아래에서 지식을 구한다면 틀림없이 많은 해답을 얻게 될 것이다.\r\n\r\n하지만 이 지역의 지질학적 특성 때문에 극단적인 수단을 사용해야 한다. 혹독한 조건과 변화하는 기후로 인해 많은 모래 더미가 단단하게 굳어 버린 것이다."'),
(343, '"그러나 해결 방법은 매우 간단하다. 나무 펄프를 흡수제로 사용하면 미량의 니트로글리세린을 질산나트륨과 섞어 강력한 폭발물을 만들 수 있는데, 이렇게 하면 아무리 밀도 높은 덩어리라도 뚫을 수 있다.\r\n\r\n시끄럽고 파괴적인 작업이 되겠지만 인근 주민들의 안락함보다는 우리의 조사가 훨씬 더 중요하다. 사실, 벌써 이 주변에서 알짱대며 성가시게 굴던 황소 인간 무리를 몰아낼 수밖에 없었다."'),
(344, '"이곳에는 다양한 악당들이 돌아다니고 있어 이에 대처하려면 왕국 군대의 지원이 필요할 것 같다. 발굴 작업에만 군사 지원이 필요한 것이 아니라 이곳에 온 지 얼마 안 된 내가 보기에 현재 폭발 직전인 세계 정치 상황을 감안할 때 바엘 모단은 위치상 얼라이언스에 전략적 가치가 있을 것으로 보인다.\r\n\r\n이런, 주제에서 벗어난 이야기를 하고 말았다. 바위 밑에서 해야 할 일이 잔뜩 있는데도 글 쓰는 데 너무 많은 시간을 보내느라 발굴을 충분히 하지 못했다..."'),
(345, '누락된 텍스트'),
(349, '이곳에는 여러 불량배들이 활동하고 있는 것으로 보아 왕실군의 지원이 필요할 것 같습니다. 발굴 작업 자체에도 군사적 지원이 필요할 뿐 아니라, 제 초보적인 시각으로 볼 때 벨 모단의 위치는 현재 세계 정세의 불안정성을 감안하면 동맹군에게 전략적으로 중요한 곳일 가능성이 높습니다. 아, 이야기가 딴 데로 샜네요. 바위 아래에는 아직 할 일이 산더미 같습니다. 글 쓰는 데 너무 많은 시간을 쓰고 발굴 작업은 충분히 하지 못했네요…'),
(350, '"사모플랜지 제어장치는 연료, 가스 및 액체의 흐름과 관련 기계를 자동으로 제어합니다. 초기 설정을 완료한 다음에는 특별한 유지관리 없이도 문제 없이 작동합니다.\r\n\r\n제어장치 구성요소의 개요(왼쪽에서 오른쪽으로)\r\n\r\nI. 주동력 레버가 사용 위치에 있으면 사모플랜지가 활성화됩니다. 레버를 꺼짐 위치에 두어도 제어 과정이 자동으로 해제되지 않습니다."'),
(351, '사모플랜지 제어장치는 연료, 가스 및 액체의 흐름과 관련 기계를 자동으로 제아합니다. 초기 설정을 완료한 다음에는 특별한 유지관리 없이도 문제 없이 작동합니다.   \n\n제어장치 구성요소의 개요(왼쪽에서 오른쪽으로)\n\n   Ⅰ. 주동력 레버가 사용 위치에 있으면 사모플랜지가 활성화됩니다. 레버를 꺼짐 위치에 두어도 제어 과정이 자동으로 해제되지 않습니다 '),
(352, '"감독관 피즈스프로켓 귀하. 사장 라즈덩크의 승인 하에 귀하가 요청한 설비 목록을 동봉합니다.\r\n\r\n사장님께서는 칼림도어 전역으로 사업을 확장하는 일에 투자개발회사가 큰 관심을 보인다는 점을 귀하께 반드시 상기시켜 드리라고 하셨습니다. 불모의 땅에 있는 우리 굴착 현장 역시 수익이 높고 효율적이라는 사실이 입증되긴 했지만 여전히 귀하의 관할인 멀고어에서 충분한 물건들을 제공받길 기다리고 있습니다."'),
(353, '"자문 위원회는 타우렌 본거지와 그렇게 가까운 곳에서 대규모 설비를 운영하는 데 수반되는 어려움은 이해하고 있지만, 자신들이 지역 내에서 우리의 전체적인 사업 계획에 큰 장애가 되고 있다는 사실은 자각하지 못하고 있습니다.\r\n\r\n광물이 풍부한 멀고어의 평원에서 채굴 작업이 시작되었다는 소식을 듣게 되어 기쁩니다. 그 덕분에 위원회가 귀하의 설비 요청을 승인해 준 것입니다."'),
(354, '멀고어는 채굴뿐만 아니라 벌목에도 적합한 지역이므로 우리의 최신 모델 절단기 몇 대와 제재소 건설에 사용할 원자재도 함께 보내 드리겠습니다.'),
(355, '"이는 냉각 프로세스를 시작할 뿐이며 장치를 끄는 데는 상황에 따라 약 1~2분이 걸립니다.\r\n\r\n주의: 주동력 레버는 실제 기계에 있는 제어 밸브 3개를 해제한 경우에만 조작이 가능합니다. 이 밸브들은 순서에 관계 없이 잠글 수 있습니다.\r\n\r\n첫 번째는 대형 수직 연통의 하부에 있는 주 제어 밸브입니다. 다음은 연료 제어 밸브로, 연료 탱크(3개가 있음)에서 연통으로 이어져 있는"'),
(356, '"대형 파이프에 설치되어 있습니다. 마지막은 연통으로 이어지는 2개의 대형 원통형 탱크 하부에 설치된 압력 조절 밸브입니다.\r\n\r\nII. 연료 계기\r\n\r\n첫 번째, 두 번째 및 세 번째 연료 탱크 내부의 현재 압력을 표시합니다.\r\n\r\nIll. 유속 계기\r\n\r\n시스템 내부의 현재 유속을 표시합니다."'),
(357, '"IV. 유속 제어장치\r\n\r\n유속을 높이거나 낮춥니다. 사모플랜지 컨트롤 메커니즘에 의해 자동으로 제어됩니다.\r\n\r\nV. 온도 계기\r\n\r\n일반적인 시스템 작동 온도를 표시합니다."'),
(358, '별의 후예들은 영원의 샘이 있는 반짝이는 물가에서 오랫동안 살아왔다. 영원한 황혼의 빛이며 달의 성위이자 여신인 엘룬께서 격무에서 잠시 휴식하실 때에 그 물 속에 거했다는 이야기는 모두에게 잘 알려져 있다. 엘룬께서 사랑하던 별의 후예들은 항상 시선이 하늘을 향하도록 훈련을 받았음에도 달빛 밝은 밤에는 샘 연안에 자신들의 보금자리를 틀었다.'),
(359, '"땅이 흔들리며 마법에 걸린 숲의 오래된 나무들이 송두리째 뽑히고 쓰러져 갔다. 세나리우스의 후예들이 돌보던 숲과, 별들의 후예들의 돌탑이 흔들리는 땅 위로 쓰러졌다. 전투의 혼란 속에서도, 절망적인 상황 속에서도 밝게 빛나는 우리의 여왕님이 계셨다. 마법이 풀리면서 마법에 걸렸던 하늘의 색이 바뀌었고, 폭발로 인해 온 세상이 갈가리 찢어질 것만 같았다.\r\n\r\n형제가... 형제와 싸웠다. 선택받은 자가 축복받은 자와 싸웠다."'),
(360, '마법에 걸린 숲의 고대 나무들이 뿌리째 뽑히고 쓰러지자 땅이 흔들렸다. 세나리우스의 아들딸들이 가꾸던 숲과 숲속 공터, 그리고 별의 자식들이 세운 돌탑들이 요동치는 땅으로 무너져 내렸다. 절망과 혼란 속에서도 찬란하게 빛나는 우리의 여왕이 그곳에 있었다. 마법의 폭발과 세상을 산산이 조각낼 듯한 함성으로 마법에 걸린 하늘은 색깔을 바꾸어 갔다. 형제가 형제처럼 싸웠다. 선택받은 자들이 싸웠다.'),
(361, '"존경하는 스승이신 델그렌님,\r\n걱정하시던 대로였습니다. 알살락스의 탑에 대한 스승님의 이론이 사실로 증명되었습니다. 한 이교도 집단이 탑에 모여 있었는데, 그 중에는 많은 마법사들이 포함되어 있고 심지어 사악한 사티로스까지 있었습니다. 그들은 스스로를 암흑이교도라 칭하고 있습니다. 그들이 어떤 사악한 목적을 위해 모였는지는 알 수 없지만 우려가 됩니다.\r\n편지를 이렇게 짧게 줄이는 것을 부디 용서해 주십시오. 하지만 지금 제 주위의 숲에는 위험이 도사리고 있으며 상황 설명을 위해 길게 말씀 드릴 수가 없습니다."'),
(364, '"호숫가에는 이미 많은 마을과 집이 지어져 있었지만 태고적부터 칼도레이의 사랑받는 여왕인 아즈샤라의 축복을 받은 아메스아란과 바샬아란이 가장 훌륭했다. 여왕은 총애하는 신하인 귀족들을 이 쌍둥이 마을에서 살게 하였고, 그 마을들을 통치하기 위해 여왕이 애스리쿠스 나라신을 보내었다. 하지만 그는 하루의 대부분을 마을에서 꽤 떨어진 알살락스의 탑에서 보냈다."'),
(365, '"그의 보좌관이자, 육체적인 능력만큼 뛰어난 마법 솜씨를 발휘하던 아스테리온은 바샬아란의 주민들과 함께 살며 아메스아란으로 여러 번 건너가 그곳의 주민들에게 필요한 것을 살폈다.\r\n\r\n그리하여 별 아래의 세계가 천천히 광란에 접어드는 동안 이 쌍둥이 마을은 영원의 샘 연안에서 날로 번창해 갔다."'),
(366, '"싸운 자들 모두가 귀족은 아니었다. 일부는 이 광란이 자신들을 집어삼킬 때까지 그냥 서 있기만 했다. 강대한 도시나 초라한 마을 할 것 없이 모두 쓰러져 갔다.\r\n\r\n아메스아란에서는 모든 것이 폐허로 변해 버렸고, 주민들은 마치 그것만 붙잡으면 이 모든 파괴 속에서 살아남을 수 있기라도 한 것처럼 땅을 붙들고 놓지 않았다. 바로 그때 아즈샤라의 총애를 받는 애스리쿠스 나라신이 나타나 그들을 안전한 곳으로 인도했다.\r\n\r\n그는 단 하나의 마법 주문으로도 그들을 보호할 수 있다고 말했지만 주변에서는 형제, 자매, 아버지와 어머니가 쓰러져 갔다."'),
(367, '그들은 영생을 누릴 것이고 앞으로 다가올 격랑의 소용돌이에서 두려워할 것이 없다...'),
(371, 'L. F.가 얼라이언스의 멍청이들을 상대로 공세를 강화하라고 명령했다. 아래는 사우스쇼어를 겨냥한 중요한 임무에 필요한 물자 목록이다:$B$B20명분 일주일치 여행 식량$B검은 야간복 20벌$B새 신발 20켤레$B새 검 25자루$B투척용 단검 30자루$B검은 복면 20개$B발화성 기름 10병$B마비 독 50회분$B가능하다면 훔친 사우스쇼어 경비병 제복 5벌$B은화 100개$B$B--남작 V.$B병참장교'),
(372, '"실예의 별\r\n\r\n욕심쟁이 그렐볼그가 실예의 별을 가지고 있습니다. 그는 알터랙 산의 알터랙 폐허에서 싸구려 물건을 찾아 헤매고 있는 탐욕스러운 오우거입니다. 그의 수집품 대부분은 쓸모없는 것이지만 실예의 별 하나만은 가치가 대단합니다."'),
(373, '"다군의 손\r\n\r\n고대 문서에 의하면 다군의 발톱은 먹잇감을 죽이는 데 사용하는 것이 아니라 고대 종족 중 하나로 변형시키는 독을 분비한다고 합니다. 그 가치가 굉장하다는 사실은 의심의 여지가 없습니다.\r\n\r\n다군은 깊은 바다에 살지만 주기적으로 먼지진흙 습지대의 진흙아가미멀록 일족이 수면으로 유인해냅니다. 이들 멀록 점쟁이들은 마법의 해조를 사용하여 다군을 불러냅니다. 점쟁이들을 처치하다 보면 그 해조를 손에 넣을 수 있을 것입니다. 그 해조를 멀록 제단에 놓으면 다군이 나타날 것입니다."'),
(374, '"고대의 심장\r\n\r\n불사신 모그는 가시덤불 골짜기에 살고 있는 트롤 의술사입니다. 그리고 그는 갖고 있는 고대의 심장의 비밀을 풀면 죽음을 피하는 능력을 얻을 수 있다고 합니다. 줄맘웨의 폐허에서 모그를 찾을 수 있으니 그를 물리치고 고대의 심장을 가져오십시오."'),
(375, '"내게 실예의 별, 다군의 손, 그리고 고대의 심장, 이 세 가지를 가져오십시오. 그러면 야그인의 법전을 주겠습니다.\r\n\r\n- 게릭 본그립"'),
(376, '"실예의 별.\r\n\r\n알터랙의 오우거, 욕심쟁이 그렐볼그가 이 보석을 마지막으로 가지고 있었다고 하오. 그는 이 보석을 소유한 자에게는 다른 세계와 교신할 수 있는 능력이 주어진다는 것에 현혹되어 있소. 정보에 따르면 그렐볼그는 더 많은 유물을 찾기 위해 알터랙 산의 알터랙 폐허에서 잡석과 파편들을 뒤지고 다니고 있다고 하오."'),
(377, '"다군의 손.\r\n\r\n다군은 먼지진흙 습지대의 멀록들이 숭배하는, 깊은 물속에 사는 생물이오. 멀록은 주술사의 마법이 걸린 특수한 해조를 사용하여 다군을 수면으로 유인하시오. 멀록을 처치하고 그들의 마법 해조를 모아 멀록 제단에 가져다 놓도록 하시오. 기다리고 있으면 다군이 나타날 것이오.\r\n\r\n그 손을 내게 가져오면 되오."'),
(378, '"고대의 심장.\r\n\r\n고대 문서에 따르면 고대의 심장을 소유한 자는 죽음의 공포에서 벗어날 수 있다고 하오. 고대의 심장을 가지고 있는 트롤 모그가 `불사신 모그`라고 알려진 것을 보면 이 말이 사실일지도 모르오. 백골가루부족 의술사인 모그는 가시덤불 골짜기의 줄맘웨의 폐허에 살고 있소."'),
(379, '"내게 실예의 별, 다군의 손, 그리고 고대의 심장, 이 세 가지를 가져오시오. 그러면 야그인의 법전을 주겠소.\r\n\r\n- 관리인 벨두거"'),
(380, '죽음의추적자 임무 보고$B$B   대원: 레인 요릭, 쿠인 요릭, 엘런드 맥크리$B$B   주요 임무: 은빛소나무 숲 북부 지역 조사 및 야생 동물과 스컬지의 위협 수준 파악. '),
(381, '대원들이 정찰을 개시하여 상당수의 늑대가 존재함을 확인했습니다. 사냥 부대를 파견하여 이 위협을 누그러뜨리는 것이 좋겠습니다.   $B$B죽음의 농장이라고 부르는 지역에서 언데드 놀들이 발견되었습니다. 그들이 농장에 나타난 목적이 무엇인지는 알아내지 못했지만, 그들의 움직임과 준비 상황으로 보아 군사 행동이 임박했음을 알 수 있었습니다. 놀들이 목격된 당시 그들 중 중요한 지도자는 눈에 띄지 않았습니다. 지휘부 또는 증원군이 도착하기를 기다리고 있는 것 같습니다. '),
(382, '정찰을 계속하던 우리 대원들은 이바르의 호박밭에 고립돼 있습니다. 이바르와 그의 가족 및 일꾼들 중 대부분은 스컬지에 굴복하여 그들의 앞잡이가 되었습니다.   $B$B우리 대원들은 공격을 받았지만 그들의 매복 부대를 물리치는 데 성공했습니다. 그러나 큰 타격을 받았으며, 특히 쿠인 대원의 부상이 심각합니다. '),
(383, '이바르의 낡은 집에 방어선을 마련하고 레인이 적의 추가 공격에 대비해 망을 보는 동안 엘런드가 정찰 임무를 계속 수행했습니다.   $B$B그러다 엘런드가 북쪽 과수원에서 검은늑대들에게 포위를 당했고 다른 포세이큰 대원의 도움으로 겨우 탈출할 수 있었습니다. 이 보고서를 전하는 전령이 바로 그 대원입니다.'),
(386, '이 보고서를 전달하는 이는 우리의 임무 완수에 도움이 되었을 뿐만 아니라 포악한 이바르를 물리치고, 엘런드를 구조하며, 이 보고서를 무사히 전달하는 등의 공훈이 있음을 인지해 주시기 바랍니다.   $B$B우리는 그에게 감사를 전하며, 이 자에게 전장에서 보여 준 영웅적 행위에 합당한 보상을 지급할 것을 건의합니다.$B$B   - 죽음의추적자 레인 요릭$B 작전 대장'),
(387, '"그는 팔을 찾아 헤맸지만 잃어버린 팔을 찾을 수는 없었다. 그는 그렇게 저주를 퍼붓고 울부짖으며 돌아다녔다.\r\n\r\n하지만 그리렉은 오래전부터 정령들에게 귀를 기울이지 않았고 화가 난 정령들은 그의 저주를 아랑곳하지 않았다.\r\n\r\n비참한 운명의 그리렉. 그는 팔 없이 헤매야 할 운명을 맞은 것이었다."'),
(394, '사악한 세력이 이 모든 것을 만들어냈네,$B그는 드레드미스트 봉우리에 편안히 앉아 있네,$B너와 네 친구를 비웃고 있네,$B그의 정령들은 끝이 없네,$B$B머지않아 너는 이 마법사와 맞서 싸워야 하네,$B오직 죽음만이 그의 분노를 끝낼 수 있을 것이네.'),
(395, '멜탄드리스의 제단$B$B"엘룬의 빛이 이 여원의 골짜기를 비추고 태고적부터 그래왔듯이 숲의 길을 비추기를." ')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(396, '엘룬께서 내 소원을 들어주셨다. 쓰러진 전우들의 목숨은 헛되지 않을 것이며, 나는 엘룬의 낫으로 그들의 죽음을 복수할 것이다. 그것은 아주 오래된 물건이다. 뒤틀리고 옹이진 나뭇가지로 만들어졌으며, 어쩌면 칼도레이보다도 오래되었을지 모른다.$B$B여신께서 내게 내린 이 도구를 몇 시간이고 살펴보았다. 분명 평범한 무기는 아니며, 단순한 마법 도구도 아니다. 이것을 들고 있으면... 시간과 공간의 장벽이 약해지는 듯하다.$B$B낫을 쥐자'),
(397, '내 손안에서 혼돈의 환영이 펼쳐졌다. 늑대 인간들... 워겐들이... 엄청난 적과 싸우고 있었다. 워겐은 그 원시적인 본성에 걸맞게 사납게 싸웠지만, 적은 조금도 흔들리지 않았다. 에메랄드 불꽃의 군주들이었다.$B$B그때 나는 낫의 진정한 힘을 깨달았다. 낫에 정신을 집중하자 워겐과 교감할 수 있었다. 말을 건 것은 아니었다. 뭔가 다른 방식이었다... 어떻게 설명해야 할지 모르겠다.$B$B중요한 것은 워겐들이 내 뜻을 듣고'),
(398, '이해했다는 것이다. 낫에 더 많은 힘을 흘려 넣자 장벽은 더욱 약해졌고, 워겐을 우리 세계로 끌어올 수 있었다. 첫 시도에서 서른 마리나 소환했다. 놈들은 나를 따라 전투에 나섰고, 그 야만적인 힘을 내 지휘 아래 두자 우리는 지옥숲의 악마들을 무참히 찢어 버렸다.$B$B엘룬께서 내 소원을 들어주셨다. 숲은 정화될 것이다.$B$B$B내 일이 끝날 때까지 엘룬의 축복이 함께하기를.'),
(399, '모든 일이 순조롭다. 더 많은 워겐을 소환해 내 곁에서 싸우게 했다. 생각은 단순하지만, 공격을 맞추고 무리로 움직이는 능력은 놀라울 정도다.$B$B각 무리의 우두머리도 가려냈다. 그들에게 소규모 전사 집단의 지휘를 맡겼다. 우리는 숲 곳곳을 동시에 습격하고 있으며, 악마를 상대로 벌이는 전쟁은 큰 성과를 거두고 있다.$B$B$B내 일이 끝날 때까지 엘룬의 축복이 함께하기를.'),
(400, '무리 하나가 사라졌다. 워겐을 숲으로 보내 악마가 들끓는 곳을 찾아보게 했지만 돌아오지 않았다. 지휘권을 맡긴 우두머리들이 걱정되기 시작한다. 놈들은 생각이 단순한데, 내가 조금 내어 준 권한마저 한껏 휘두르고 있다. 내가 통제력을 잃고 있는 것일까? 당분간은 워겐을 더 소환하지 않는 편이 좋겠다.$B$B$B내 일이 끝날 때까지 엘룬의 축복이 함께하기를.'),
(401, '내가 더는 워겐을 소환하지 않았는데도 그 수가 계속 늘어나고 있다. 이제 낫은 소환에 내 개입조차 필요로 하지 않는 듯하다. 불길하다. 찾을 수 있는 무리들을 최대한 모아 멜탄드리스의 제단에 머물라고 명령했다.$B$B그동안 다르나서스의 도서관을 뒤지고 어둠해안의 고대정령회에도 자문을 구했다. 하지만 이 워겐에 관한 기록은 한 조각도 찾지 못했다. 다만 소문을 들었다,'),
(402, '키린 토의 아루갈이라는 마법사에 대한 소문이다. 내가 들은 바에 따르면 그 역시 워겐을 소환했을 가능성이 있다. 내키지는 않지만 그 마법사를 찾아가 무엇을 알고 있는지 물어봐야겠다.$B$B워겐은 위험하다. 이 흐름을 막아야 한다. 내일 불모의 땅 항구로 가서 신대륙으로 향하는 배편을 알아볼 것이다.$B$B$B내 일이 끝날 때까지 엘룬의 축복이 함께하기를.'),
(403, '"잿빛 골짜기를 위한 내 임무 수행을 기록하기 위해 이 일지를 쓰기 시작했다. 최근 발생한 사건들 중 일부에 대해 의혹이 제기되고 있다. 내가 이 사건들을 해결하여 다른 이들을 도울 수 있기를 바란다.\r\n\r\n후에 잊지 않도록 있었던 사실들을 기록하도록 하겠다.\r\n\r\n최근 나는 마법사 다르톨의 계획에 대한 소문의 진상을 알아냈다."'),
(404, '"인간이 우리 땅에 와서 우리의 지식을 배운다는 것은 있을 수도 없는 일이라 생각했건만, 이 사악한 인간 마법사는 이곳에 와서 살아남았을 뿐 아니라 우리의 지식도 어느 정도 습득했다. 어떻게 그럴 수 있었는지 아직도 이해가 되지 않는다. 내가 실시하고 있는 조사를 통해 그의 목표가 무엇인지는 밝히지 못했지만 그의 계획은 간단해 보였다. 드루이드의 마법을 사용하여 펄볼그를 자기 편으로 끌어들여 조종하려는 것이었다. 만약 우리 종족을 해치려고 하는 것이거나 다른 악의적인 의도가 있는 것이라면 나의 조사가 끝나기 전에 알아내게 되기를 바란다."'),
(405, '"어쨌든, 그는 외견상 자신의 계획을 실행에 옮기는 데 어느 정도 성공한 것 같았다. 그의 음모를 우리 주민에게 실행하기 전에 먼저 펄볼그에게 시험해 보려 한 것일까? 아니면 펄볼그들이 그가 탐내는 무언가를 지니고 있는 건가? 알 수가 없다. 그는 그가 만든 물건, 일종의 마법봉 또는 마법 지팡이를 이용해서 잿빛 골짜기의 펄볼그 종족에게 숨어 들어가려고 했었다. 어느 시점에서 그는 펄볼그들이 서로 적대시하도록 조종하려 하다가 그들에게 발각되고 말았다. 이 당시에 대해서는 지금도 다수의 상세한 내용이 명확히 알려져 있지 않다."'),
(406, '"아마 엘프들이라도 그랬겠지만, 펄볼그들은 분노했고 훨씬 더 거센 반응을 보이며 결국 다르톨을 처치했다.\r\n\r\n적어도 이 당시의 펄볼그는 그 이후처럼 타락한 짐승이 아니었다. 그들은 아직 이성적이며 지적이었다. 그리고 우리 종족과의 관계도 우호적이었다.\r\n\r\n내가 셸드린이라는 드리아드의 도움을 받아 그 마법봉을 다시 만들 수만 있다면 그 힘을 이용해 우리 종족과... 펄볼그들까지도 구할 수 있을 텐데..."'),
(407, '"모든 펄볼그들이 타락한 것은 아니었다. 일부는 아직 살아 남아 숲을 보호하려 하고 있다. 그들이 타락할 당시, 일부 펄볼그는 달아났고, 많은 수가 희생당했으며, 나머지는 그들 일족으로부터 쫓겨났다.\r\n\r\n나는 미스트랄 호수 위쪽에 살고 있는 크롤그라는 훌륭한 썩은나무일족 펄볼그를 만나게 되었다.\r\n\r\n며칠 동안 그를 지켜본 결과, 내가 펄볼그로 위장해 그에게 접근한다면 그를 도와 두 종족간의 우호적인 관계를 회복할 수 있을 것이라는 생각이 들었다."'),
(408, '"다르톨을 처치하면서, 펄볼그는 다시는 마법봉이 자신들에게 사용되지 못하도록 이를 세 조각으로 나눠 버렸다. 어려운 일이긴 했지만, 나는 그 세 조각이 모두 어디에 있는지 알아냈다.\r\n\r\n보석\r\n마법봉의 첫 번째 조각인 빛나는 보석은 잿빛 골짜기 북서쪽의 제단에 숨겨져 있었다. 현재 팔라딤 호수 중앙에 있는 폐허가 바로 이 제단이라 생각된다. 센티널에서는 지금 그곳에 멀록들이 살고 있다고 내게 일러 주었다."'),
(409, '"내가 제단에 숨겨진 보석을 찾을 수 없다면 분명 멀록의 손에 들어간 것이다.\r\n\r\n자루 부분\r\n이 마법봉 조각은 현재 악령의 숲이라 불리는 곳 가까이에 있는 나무정령들의 손에 들어갔다. 펄볼그나 우리 종족은 이 위대한 종족이 이 땅을 덮친 타락의 나락에 떨어졌으리라고는 상상도 하지 못했다. 조사를 통해 이 수호정령들이 이 마법봉 조각을 상자 안에 넣고 잠궈 작은 습지에 보관하고 있다는 사실을 밝혀냈다. 더 자세한 내용을 알아내기 위해서는 셸드린과 얘기해 봐야 할 것이다."'),
(410, '1. 한 명 또는 여덟 명을 잡아라$B2. 사람을 세게 때려라$B3. 사람을 더 때려라$B4. 사람을 불 속에 넣어라$B5. 사람을 먹어라'),
(411, '"셸드린은 아이리스 호수 북동쪽의 달샘을 보호하는 드리아드이다. 그녀는 숲을 떠나거나 숲이 오염되도록 내버려 두려고 하지 않는다. 나는 그녀가 마법봉을 고칠 수 있는 힘과 지식을 지니고 있거나, 적어도 내가 직접 고칠 수 있는 방법을 알려 줄 수 있다는 것을 알고 있다.\r\n\r\n자루 끝\r\n마법봉의 자루 끝 부분은 도르다닐의 드루이드들의 손에 들어갔다. 하지만 여기에는 한 가지 큰 문제가 있다. 그 드루이드들이 이미 죽었다는 것이다. 그들의 영혼은 지금도 그 지역에 남아 있지만 더 이상 우호적이지는 않다."'),
(412, '"여기에 대해서는 조사가 더 필요할 것 같다. 내게 도르다닐의 깊은 곳까지 철저히 조사하여 자루 끝을 찾아내는 것은 고사하고... 죽은 일족의 영혼과 싸울 힘이라도 있을지 자신이 없다.\r\n\r\n참고: 아스트라나르에서 채비를 하는 동안, 최근에 잿빛 골짜기에서 오랫동안 우리 종족을 도와 온 드워프 종족 사냥꾼을 만났다. 그는 스톰윈드라는 곳에서 온 자이다.\r\n\r\n어느 날 밤, 우리는 에일 맥주를 몇 잔 하며 이야기를 나눴는데, 그의 이야기는 내게 자루 끝 부분을 찾을 수 있으리라는 새로운 희망을 안겨 주었다."'),
(413, '"그는 도르다닐 전역을 여행했지만 자루 끝 부분이 보관되어 있을 만한 상자나 다른 용기는 보지 못했다고 했다.\r\n\r\n그리고 그 지역엔 썩어가는 진흙괴물이 사는 곳으로 그들은 자신들보다 작은 건 뭐든 먹어 치운다고 했다. 그는 그들이 탁자, 조각품, 곰, 심지어는 노움까지 ""먹어 치우는"" 걸 봤다고 한다!\r\n\r\n진흙괴물들은 마법의 힘이 있는 사물에서 많은 양의 양분을 얻는 것 같다. 만약 자루 끝 부분이 보관된 상자에 마법이 걸려 있다면 진흙괴물들이 먹어 버렸을지도 모른다."'),
(414, '"도박이긴 하지만 지금으로서는 다른 단서가 없으니...\r\n\r\n무언가 더 찾아내게 되면 여기에 상세히 적을 것이다. 하지만 그때까지 마법봉 조각들을 찾아 잿빛 골짜기를 돕는 데 전력을 다해야 한다."'),
(415, '"진질에게\r\n이미 오랜 시간이 흘렀지만 붉은깃털일족의 마지막 생존자가 죽었다는 사실을 알고 싶어할 것 같군. 이 편지를 자네에게 전하는 사람이 한 일이니 내게 감사할 필요는 없네. 자네가 원한다면 불모의 땅에서 짐마차의 순회가 끝나는 대로 그녀의 머리를 자네에게 보내 주겠네. 자네의 부두 마법을 사용하기 위해서는 그게 필요하다는 사실을 알고 있으니 말이야.\r\n잘 지내게, 내 오랜 벗이여\r\n\r\n-달소크 스위프트대거"'),
(416, '진질, 오랜만이야. 블러드페더 일족이 모두 처치됐다는 소식을 전하고 싶었어. 고맙다는 말은 하지 마. 편지를 전해준 사람이 바로 그 블러드페더를 처치한 사람이니까. 원하신다면, 캐러밴이 황무지를 한 바퀴 돈 후에 그녀의 머리를 가져다 드릴 수도 있어. 네가 부두 마법에 그런 걸 좋아하는 걸 알고 있거든. 잘 가, 오랜 친구. -다르소크 스위프트대거'),
(417, '좋아, NG-5 폭약과 기폭 장치를 준비해야 해. 내가 표시해 놨어... 파란색은 제재소용이고, 빨간색은 윈드셰어 광산용이야.   내가 정찰을 좀 해봤는데, 윈드셰어 절벽 곳곳에 폭발물이 충분히 있어서 잠입해서 폭발물을 설치하고 폭발시키기 전에 빠져나오는 건 전혀 문제없을 거야. 명심해, 이건 주의를   분산시키는 작전이야. 고블린들이 무슨 일이 있었는지 확인하러 오기 전에 마차에서 멀리 떨어져 있다가, 그들 뒤로 몰래 잠입해.'),
(418, '참고로 조심해서 다루세요. 니트로미르글리세로늄만으로도 사람을 먼지로 만들 수 있습니다. 액체의 일부를 구리 튜브에 넣어 안정적이고 안전하게   보관했습니다. 콜린에게서 받은 두루마리는 기폭 장치에 사용했습니다. 이제 기폭 장치를 설치하면 NG-5 폭약에 무음 신호가 전송됩니다. 전선의 전도성을 최적화하고 차동 유체 사이의 니트로미르글리세로늄 흐름이 평균 이상이 되도록 간단한 스탈트워건 메커니즘을 사용했습니다.'),
(419, '제 설계에 대한 자세한 설명을 드리기 전에, 폭발물을 어디에 설치해야 하는지 먼저   설명드리겠습니다.플랜 알파  - 제재소:제재소 앞에 마차가 한 대 있습니다(벌목 및 목재 수집 시설의 북동쪽에 있습니다). 설계 도면은 제재소 안에 있을 것으로 예상됩니다.  폭발물을 설치하려면 마차 뒤쪽으로 가십시오. 설치가 완료되면 서둘러 거리를 두십시오.'),
(420, '준비되면 기폭 장치를 작동시키세요.   상자 케이스 안에 멜투시안 안테나 배열과 함께 구리선과 은선을 연결해서 강력한 신호를 확보해 뒀습니다. 사정거리가 꽤 넓을 겁니다. 다만 근처 고블린들을 조심하세요. 그들이 당신을 발견하면 제 발명품을 좋아하지 않을 겁니다. 아, 그리고   혹시 몰라서 말인데, 폭발할 때 마차 근처에 있지 마세요... 엄청 아플 겁니다.'),
(421, '베타 계획 - 윈드셰어   광산: I가 광산 입구 북쪽에서 고블린들이 폭발물을 실은 또 다른 수레를 사용하는 것을 봤습니다. 그곳이 NG-5 폭약(빨간색)을 설치하기에 적당한 장소일 것 같습니다. 수레 뒤쪽에 폭약을 설치한 후, 거리를 두고   버튼을 누르세요. 만약 고블린들이 소란을 확인하러 달려오지 않는다면, 아마 산이 그들의 머리 위로 무너져 내렸을 겁니다.'),
(422, '투자개발회사의 편지들은 광산 밖에 있어요... 아마 맨 아래층에 있는 상자들 위에 있을   거예요. 행운을 빌어요,   그리고 기억하세요...  파란색 폭탄:   제재소, 빨간색 폭탄: 광산. 아, 그리고 임무를 완수하면 이 편지를 없애버리세요. 음, 읽고 나면 편지가 저절로 사라지게 하는 방법을 알아봐야겠네요. 나쁘지 않은 생각인데...'),
(424, '--1일차--\n\n아이언포지에서 출발한 여정이 드디어 칼림도르에 도착했습니다!\n\n벨 모단의 탐사원 카즈고름은 순조롭게 탐사를 진행하고 있습니다. 오늘 그는 고대 신의 뼈 조각으로 추정되는 화석을 발굴했습니다. 카즈고름은 이 화석이 더 큰 미스터리의 일부라고 확신하고 있습니다. 그가 발굴 현장을 관리하는 동안, 저는 이 미스터리를 풀기 위해 더 많은 화석을 찾는 임무를 맡았습니다. \n\n제 임무는 남쪽으로 향하여 더 많은 단서를 찾는 것입니다.'),
(425, '--둘째 날--\n\n황무지는 광활하고 드넓습니다. 길고 험난한 여정이었지만, 탐험가 연맹 기록 보관소에 남길 만한 흥미로운 것은 아직 아무것도 찾지 못했습니다. \n\n유일하게 주목할 만한 사건은 금광 도로 근처에서 일어났습니다. 멀리서 이상한 생명체들이 눈에 띄었습니다. 반은 돼지, 반은 사람처럼 보였습니다. 저는 재빨리 숨어 그 끔찍한 짐승들이 지나가도록 했습니다. 그런데 그들이 남긴 악취는 정말 지독했습니다!'),
(426, '--셋째 날--\n\n오, 놀랍고도 멋진 발견이로군!\n\n오늘 탐사를 하다가 엄청난 것을 발견했습니다. 멧돼지처럼 생긴 거대한 생물의 유해였는데, 두개골은 제 키보다 훨씬 컸습니다. 이빨 하나하나도 난쟁이보다 훨씬 거대했고요. 이 거대한 유해를 보니, 소문으로만 듣던 고대 신의 유해일지도 모른다는 생각이 듭니다.'),
(427, '얼마 전 아이언포지에 있는 탐험가 연맹 본부에서 수석 고고학자 그레이위스커가 했던 강연이 생각나네요. 그 노련한 분이 다르나서스의 기묘한 엘프들이 숭배하는 신에 대해 이야기했었죠. 그 신은 이타적인 성품으로 유명하다고 전해지는데…\n\n흥! 잠깐만. 텐트 밖에서 콧김 소리가 들리네. 분명 엉겅퀴 멧돼지들이 내 사과 저장고를 노리고 있는 거겠지…'),
(428, '--4일차--\n\n붙잡혔다!\n\n빨리... 써야 해. \n\n레이저펜 부족의 멧돼지 인간들에게 공격당했어. 쓰러진 신의 거대한 멧돼지 유해가 있는 곳으로 데려가는 줄 알았지. 그런데 그들은 거대한 화석들을 피해 황금길을 건너 거대한 두개골 바로 서쪽으로 향했어.'),
(429, '악취가 진동하고 가시덤불이 뒤엉킨 가시덩굴 우리 안으로 거칠게 끌려왔다. 조잡하게 지은 오두막 안에 내던져졌고, 죽어가는 나이트 엘프 한 명과 함께 갇혔다.\n\n내게 남은 물건이라곤 이 일기장과 깃펜, 회중시계뿐이다...\n\n누군가 오고 있다...'),
(430, '--5일째--\n\n내 나이트 엘프 감방 동료는 심각한 부상을 입었다. 멧돼지 인간들이 그를 여러 차례 채찍질했고, 기적적으로 구조대가 이 위험한 곳에 도착하지 않는 한 곧 죽을 것 같다. 그는 의식을 잃었다가 다시 돌아오기를 반복한다. 그가 깨어날 때마다 내가 가진 얼마 안 되는 물을 주려고 애쓴다.'),
(431, '어젯밤 그는 처음으로 말을 할 수 있었습니다. 그는 헤랄라스라는 이름의 드루이드인데, 쓰러진 멧돼지 신에 대한 소문을 조사하기 위해 이곳에 파견되었다고 합니다. \n\n그는 떨리는 목소리로 거대한 멧돼지 해골이 약 1만 년 전 고대 전쟁 당시 불타는 군단과 싸우다 위대한 멧돼지 신 아가마간이 쓰러진 장소라고 믿는다고 말했습니다. 그의 거대한 몸은 땅을 짓눌렀고 그의 피는 땅속으로 스며들었습니다. 그의 피가 떨어진 자리에는 뒤틀린 가시 덤불이 자라났습니다…'),
(432, '헤랄라스와 그의 백성들은 이 땅의 타락의 근원을 밝히려 애쓰고 있습니다. 아가마간은 순수한 신으로 여겨졌다고 그는 내게 말했습니다. 왜 이 추악한 생물들과 악성 가시들이 땅을 뒤덮었는지는 참으로 불가사의한 일입니다.\n\n더 자세한 정보를 캐묻기도 전에 헤랄라스는 다시금 불안한 잠에 빠져들었습니다…'),
(433, '--6일째--\n\n헤랄라스의 상태가 악화되고 있다.\n\n오늘 그는 단 한 번만 눈을 떴다. 고통에 찬 목소리로 말했지만, 그의 메시지는 분명했다. "내가 가시덩굴 우리에서 이 파멸을 피하려면, 탈라나르에 있는 팔핀델 웨이워더에게 찰가 레이저플랭크가 남부 황무지에서 하수인들을 규합하고 있다는 소식을 전해야 한다. 그녀의 힘은 날이 갈수록 강해지고 있다. 타락의 역병이 크롤에서 퍼지기 전에 저 마녀를 막아야 한다."'),
(434, '불쌍한 헤랄라스는 뼈만 남을 정도로 창백해 보인다. 열은 점점 더 심해지고 있다. 그 사이 멧돼지 인간들은 뭔가 큰 군사 작전을 준비하고 있다. 내가 곧 탈출을 시도하지 않으면, 내 엘프 감방 동료와 같은 운명을 맞게 될까 두렵다. \n\n내 계획은 멧돼지 인간들이 다음 사냥을 나갈 때 몰래 빠져나가는 것이다. 경비병들은 게으르고 교대 시간에 잠을 자는 경우가 많다.'),
(435, '가시덩굴 우리에서 빠져나가면 버섯구름 봉우리로 향한 뒤, 신비로운 페랄라스 숲의 경계에 있는 탈라나르까지 서쪽으로 가겠다. 그곳에서 팔핀델 웨이워더라는 드루이드를 찾을 것이다.\n\n내 종족의 과거를 조사하려 시작한 일이 이제 훨씬 큰 문제로 번졌다. 얼라이언스의 안위가 내 손에 달렸다....'),
(436, '"주문 번호: 45TK-3\r\n구매자: 크레이블 콜비어드\r\n\r\n구매서:\r\n\r\n수력래칫 (3)\r\n연발볼트 (50)\r\n30"" 20눈금 구리관 (12)\r\n딥퓨리제 코담배 (1)\r\n최상급 삼각결정(3)"'),
(437, '"이 전갈을 제가 직접 전해드리고 싶지만 중요한 사건을 놓치게 될 것 같아 이곳을 떠날 수가 없습니다.\r\n\r\n알살락스의 탑에 대한 제 조사 내용을 더 자세히 알고 싶어하실지 몰라, 이 편지를 전하는 이가 제게 큰 도움을 주었으며 믿을 만한 자임을 말씀 드립니다.\r\n\r\n긴급히,\r\n발툴 섀도스트라이크"'),
(438, '나즈 스팀보일이라는 고블린은 실제로 고블린 거상의 아들이다. 어느 거상인지를 밝혀내기 위해서는 큰 대가를 치러야 할 것이다.$B$B그는 직접 돈을 벌기보다는 자신의 가족이 번 돈을 쓰는 데 훨씬 더 관심이 많은 것 같다. 그래서 그는 가족이 저축해 둔 재산을 조금 훔쳐 지금은 소금 평원에 숨어 있다.$B$B그가 숨어 있는 곳을 그의 아버지가 알게 된다면 그를 찾아내 집으로 다시 끌고 갈 것이 분명하다. 오만한 행동에 대한 대가로 발가락 하나를 자른 채로 말이다.'),
(439, '피즐버브 씨.$B$B이 편지를 전하는 이와 내가 구상하고 있는 사업 기회에 당신의 참여를 바라는 바이오.  $B$B아시다시피, 나는 소금 평원에서 많은 시간을 보냈소. 앞에서 말한 사업 기회는 이 소금 평원에서 열리는 경주와 관련된 것이오.$B$B만일 경주에, 아니 좀 더 구체적으로 말해서 경주에 걸린 내기에 관심 있다면 이 편지를 계속 읽어 보시오. 가시덤불 골짜기에 관한 당신의 지식이 우리 계획에 도움이 되리라 생각하오.'),
(440, '피즐버브씨, $B$B당신이 우리 동료에게 준 음료는 대단히 성공적이었소. 아주 강하고 정신을 몹시 흐리게 해줄 뿐만 아니라 중독성까지 있는 듯하군. 한 번 맛본 사람은 반드시 더 원하게 될 거요. $B$B당신에게 빚을 졌소이다, 크랭크. $B$B당신을 소금 평원에 초대하오. 아니면 믿을 만한 친구를 보내 이곳의 새로운 도박 기회를 놓치지 않기를 바라오  $B$B - 크레이블 '),
(441, '"친애하는 마르텍,\r\n\r\n나는 지금 곤경에 빠져 자네 도움이 필요하다네. 우리 형제가 경주용 자동차를 제작하고 있는데 튼튼한 피스톤이 필요하네. 여러 가지를 시도해 봤지만 그 어느 것도 강도가 충분치 못하더군. 우리가 만든 새 자동차의 속도를 견뎌 낼 수 있는 게 하나도 없어. 그래서 계속 엔진 고장을 일으키고 있네!\r\n\r\n자네가 금속 가공에는 전문가이니 꼭 도와주기 바라네. 자네만이 할 수 있는 일일세."'),
(442, '"서리갈기 설인을 상대하려면 먼저 녀석이 가장 좋아하는 먹이의 고기로 유인해야 하오.\r\n아제로스에 있는 알터랙 산맥으로 가서 덩치큰 산사자를 한 마리 잡아 죽인 후, 그 시체를 서리갈기 설인이 성스럽게 여기는 우젤 동굴로 가져가시오.\r\n우젤의 불꽃에 그 시체를 올려 놓으면 동굴에서 불에 타는 고기 냄새가 흘러나가게 될 거요.\r\n그러면 서리갈기 설인이 나타날 것이오."'),
(443, '"사람들을 자신의 의지 앞에 굴복시키는 데는 증오만큼 쉬운 수단이 없다는 사실에 항상 놀라곤 한다. 그 중에서도 오크와 트롤이 가장 쉬운 대상이다. 얼라이언스에 대한 증오로 그들은 암흑이교도의 말에 기꺼이 귀 기울이는 충성스러운 백성이 되었다. 자신들이 섬기는 더 큰 힘에 대해 조금이라도 알고 있을까? 격분한 성기사 수호자 델그렌이 잿빛 골짜기 숲에서의 우리 일을 캐고 다니고 있고, 그의 부하 발툴은 내가 그의 존재를 모른다고 생각하며 우리 탑을 염탐하고 있다. 델그렌은 우리를 대수롭지 않게 생각하고 있다."'),
(444, '"아마 또 다른 죽음의 이교도 집단쯤으로 여기고 있을 것이다. 그는 우리가... 어둠의 의회의 이교도 중 하나에 불과하다는 사실을 거의 모르고 있다.\r\n\r\n내가 어린 아이였을 때, 겨우 알아볼 정도의 작은 점 크기의 파리처럼 보이지만 물리면 바로 죽을 수도 있는 곤충에 대한 이야기를 들은 적이 있다. 하지만 그 곤충은 물리면 살이 썩어 들어가며 매우 치명적인 해를 입힐 수 있으므로 박멸해야 한다."'),
(445, '소금 평원에서 경주를 벌이는 로켓 자동차는 높은 성능을 발휘하도록 조정되어 있으며 매우 주의 깊게 관리해 줘야 하오. 따라서 정비반이 항상 대기하고 있는 것은 당연한 일이오. $B$B그들은 지속적으로 자동차를 테스트하고 필요에 따라 자동차를 수리하거나 개조하기도 한다오. 그래야만 자동차의 성능을 최고로 유지할 수 있으니 말이오.$B$B그래서... 우리는 정비반 중 한 명이 자신이 맡은 임무에 소홀해지도록 할 방법을 찾고 있소. 그러한 과실은 곧바로 자동차의 파손이라는 결과로 이어질 수 있으니까.'),
(446, '자동차를 조절해 최고 성능을 발휘할 자동차와 그렇지 않은 차를 우리가 정할 수 있게 될 경우, 도박에서 얼마나 유리해질지는 굳이 설명할 필요도 없을거요.$B$B그러니, 친애하는 피즐버브씨, 우리에게 정비반의 과실을 유도해 낼 수 있는 수단을 제공해 주시오.$B$B가시덤불 골짜기에 노움과 고블린들의 정신을 혼미하게 하는 데 쓸만한 식물이나 약초, 아니면 술 같은 건 없소?$B$B- 크레이블 콜비어드')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(447, '"나는 그동안 위상과 그들의 창조자 티탄에 대해 많은 조사를 해 왔다. 한 인간이 전 생애에 걸쳐 할 수 있는 최대한의 노력을 한 것이라고 생각한다. 티탄들은 이 세상을 떠나면서 이 세상에 5개의 위상을 남겼는데, 이들은 아제로스 세계를 수호하는 임무를 맡은 강력한 용이었다. 그 꼬리는 거대하고 다양한 모양을 하고 있으며, 충분히 많은 정보를 수집하고 난 지금도 이 엄청난 생물에 대해 알아내야 할 것이 훨씬 더 많다고 느끼고 있다."'),
(448, '"연금술사 라이던,\r\n\r\n이 편지가 빨리 당신에게 전해지기를, 또한 이 편지를 전하는 이가 무사하기를 바라오. 멀리 칼림도어에서 당신의 능력을 필요로 하게 될 것 같은 일이 발생했소. 간단히 설명하도록 하겠소이다.\r\n우리의 동맹 타우렌의 고향인 멀고어에서 멀지 않은 돌발톱 산맥에 위기가 닥쳤소. 고블린이 운영하는 투자개발회사가 이 산맥에서 마구잡이로 채굴과 벌목을 강행해 산의 정령들이 격노하고 있소이다."'),
(449, '"이 정령들이 타우렌 주술사와 드루이드의 비호 아래서 여러 방법으로 일으킨 소란이 놈들을 혼란케 하는 것 같소. 타우렌들은 돌발톱 산맥의 투자개발회사를 심각한 위협으로 간주하고 있소. 그들이 위협 요소이든 그렇지 않든, 우린 우리의 동맹을 도와야 하오.\r\n라이던, 당신은 독약에 대해 너무나 잘 알고 있지 않소? 돌발톱 산맥의 고블린들을 전염시킬 수 있는 독약을 만들어 줄 수 있겠지?\r\n\r\n당신의 학식을 존경하는 P. 자마"'),
(450, '"지금 내가 가진 지식 중 상당량은 나 혼자의 힘으로는 결코 알아낼 수 없었을 것이며, 이 점에 대해 나이트 엘프들에게 크게 감사한다. 그들의 도움이 있었기에 이토록 자세한 정보를 확보할 수 있었던 것이다. 그들과 교류하면서 그들의 시초가 내가 처음 생각했던 것보다 훨씬 더 깊이 위상과 관련되어 있는 것 같다는 느낌이 들었다. 하지만 그들은 나조차도 확실히 알 수 없도록 비밀을 철저히 숨기고 있다."'),
(451, '나중에 다른 이들이 참고할 수 있도록 위상에 대해 내가 알아낸 정보를 여기에 기록해 둔다. 이 용들은 시간이 지날수록 이 세상에 더 큰 영향을 미치게 될 것이며 여기에 기록된 정보들은 분명히 유용하게 사용될 것으로 믿는다.'),
(452, '"알렉스트라자:\r\n알렉스트라자는 고룡의 강력한 여왕으로 티탄들은 그녀를 생명의 어머니라고 불렀다. 티탄들이 떠나면서 이 세상을 지키게 할 목적으로 만든 첫 번째 피조물이 바로 그녀였다. 알렉스트라자는 아제로스 대륙에서 모든 종족의 탄생을 목격했다고 전해진다. 훌륭한 품행으로 널리 알려진 그녀의 붉은용 군단은 한때 다른 모든 용족을 지배했다."'),
(453, '"나이트 엘프들 사이에 떠도는 소문에 의하면 알렉스트라자와 반신 세나리우스는 절친한 친구였다고 하며, 불타는 군단이 처음으로 침략했을 때 그녀를 부른 것도 세나리우스였다고 한다."'),
(454, '"이세라:\r\n꿈의 여왕 이세라는 모든 종족들의 잠재 의식을 관장하며 에메랄드의 꿈을 수호한다. 그녀는 종족들의 상상력과 창조의 진정한 가치를 이해하고 그들의 야심을 인정하지만, 그녀와 그녀의 용군단은 현실이 한낱 환상일 뿐이라고 여긴다. 이세라는 모든 종족들이 가장 고귀하고 강하다고 여기는 존재 중 하나이다."'),
(455, '"말리고스:\r\n말리고스는 마법의 청지기 또는 마법의 지배자라고 알려져 있다. 그의 타고난 외모는 여느 용과는 다르며 자신의 의지에 따라 모습을 바꿀 수 있다고 전해진다. 북쪽으로 멀리 달아난 후 거의 모습을 드러내지 않으며, 보통 때는 곤충과 같은 모습을 하고 있지만, 용의 모습을 드러냈을 때 그와 그의 용군단은 여러 가지 푸른 빛을 띤다."'),
(456, '"노즈도르무:\r\n노즈도르무는 시간의 지배자 또는 시간을 초월한 자로 알려져 있다. 그와 그의 용군단은 청동색을 띠고 있으며 다방면에서 뛰어난 솜씨를 보여 준다. 노즈도르무의 관심은 언제나 과거의 유물을 수집하는 데 집중돼 있으며 종족간 분쟁이나 동료 위상들의 현안들에는 별로 관심이 없다. 하지만 정치에 무관심하다고 해서 세상 일에 전혀 관심을 두지 않는 것은 아니다."'),
(457, '수호자로 여겨지는 청동용군단은 문명에 지대한 관심을 보인다. 노즈도르무와 그의 용군단은 천성적으로 인내심이 강하고 언제나 눈으로 확인된 사실만을 믿으며 상황이 급박해지기 전에 계획에 따라 움직인다. 노즈도르무는 강력한 적들이 위협할 경우 언제나 종족들과 시간의 흐름을 보호하려 할 것이다.'),
(458, '"넬타리온:\r\n창조되었을 당시 대지의 수호자로 불렸던 넬타리온은 다른 어떤 위상보다도 강한 충성심으로 아제로스를 수호하려 애썼다. 그의 검은용군단은 산맥들과, 대륙 안에서 종족들간 경계지역을 비롯한 기타 지형의 형성을 담당했다. 그가 타락하게 된 원인은 아직 밝혀지지 않고 있다. 외부에서 영향을 받았는지 아니면 내적으로 부패한 것인지 알 수 없다. 고대 신들이 이 거대한 검은용의 타락과 관련이 있는 것은 아닐지 의문스럽다."'),
(459, '"검은용 넬타리온은 완전한 변형을 거쳤고 결국 이전과는 전혀 다른 존재가 되었다. 그는 악의와 증오의 창조자 데스윙이 되었다. 하이 엘프와 같은 종족에게 더 이상 대지의 수호자는 없게 되었다. 그는 타이탄이 붙여 주었던 이름 대신 죽음의 위상, 그리고 삭사스라는 새로운 이름으로 불렸다. 데스윙은 혼돈과 악의 화신이며, 항상 파괴에 굶주려 있다. 아마도 그는 고대 신들의 추방 이후 아제로스에 나타난 첫 번째 악일 것이다."'),
(467, '"축하 드립니다!\r\n\r\n이제 당신은 땅다람쥐의 자랑스러운 새 주인이 되셨습니다! 땅다람쥐는 다소 낯을 가리기는 하지만 보송보송한 털과 귀여운 용모에다 후각 기관이 매우 발달해 있어 분명히 마음에 드실 것입니다.\r\n\r\n다음 페이지에는 땅다람쥐에 대한 정보가 수록되어 있습니다.\r\n1. 먹이 및 관리법\r\n2. 엉뚱하면서도 귀여운 행동\r\n3. 특허를 받은 땅다람쥐 지휘봉의 사용법\r\n\r\n땅다람쥐의 주인이 되신 것을 다시 한번 축하 드리며, 결코 후회 없는 선택이 되리라고 확신합니다.\r\n-땅다람쥐 회사 사장, 마르위그 러스트볼트"'),
(507, '--13일차\n테라모어 근처에서 병력 이동이 증가했습니다. 많은 사람들이 도시를 떠나 서쪽으로 급히 이동하고 있습니다.\n\n-14일차\n더 많은 병력이 도시를 떠나고 있습니다. 저는 소규모 무리를 따라가 테라모어에서 활시위 거리까지 벗어난 후 그들이 군복을 벗는 것을 목격했습니다. 탈영병일까요?\n\n-15일차\n오늘 테라모어 병사들이 경비병들이 초소를 이탈했다는 이야기를 하는 것을 우연히 들었습니다. 탈영병에 대한 제 의심이 맞는 것 같습니다.'),
(527, '--13일차\r\n테라모어 근처에서 병력 이동이 증가했습니다. 많은 사람들이 도시를 떠나 서쪽으로 급히 이동하고 있습니다.\r\n\r\n-14일차\r\n더 많은 병력이 도시를 떠나고 있습니다. 저는 소규모 무리를 따라가 테라모어에서 활시위 거리까지 벗어난 후 그들이 군복을 벗는 것을 목격했습니다. 탈영병일까요?\r\n\r\n-15일차\r\n오늘 테라모어 병사들이 경비병들이 초소를 이탈했다는 이야기를 하는 것을 우연히 들었습니다. 탈영병에 대한 제 의심이 맞는 것 같습니다.'),
(528, '"요르겐,\r\n내가 두려워하던 일이 현실로 드러났네. 그것도 내가 전혀 생각지도 못했던 방식으로 말일세. 놈들이 이렇게 가까이 다가올 줄은 생각도 못했었네.\r\n이 편지를 전하는 이를 도와주도록 하고 그를 `그`에게 보내게. 솔직히 말해, 내 생각에는 이번 일이 워낙 심각한 만큼 그가 우릴 도와줄 것 같네. 만약 다른 위협이었다면 그가 우리와 우리 도시의 문제를 계속 무시해 버리겠지만 말이야. 고맙네, 이 어부 친구야. 언제나 자네에게 신세만 지는구먼.\r\n자네의 친구, 드라베이"'),
(547, '요르겐, 내 두려움이 현실이 되었군. 그들은 내가 상상도 못 했던 방식으로 행동했어. 이렇게 가까이까지 올 줄은 꿈에도 생각 못 했는데 말이야. 부디 이 편지를 전하는 사람을 도와서 그에게 전해 줘. 솔직히 말해서, 이 문제가 심각하기 때문에 그가 우리를 도와줄 거라고 생각해. 만약 다른 위협이었다면, 그는 아마 우리와 우리 도시의 문제들을 계속 외면했을 거야. 고맙네, 노련한 어부. 언제나처럼 네게 큰 빚을 졌어. 네 친구, 델라베이'),
(548, '--16일차\n울레그와 타르길은 임무를 마치고 테라모어 항구로 돌아왔습니다. 항구에 새로운 배 한 척이 정박해 있는 것을 보았는데, 바로 피의 참새호였습니다. 이 배는 아제로스의 메네틸 항구에서 온 것이었습니다.\n\n내일 울레그와 타르길은 다시 항구로 돌아가 배에 몰래 잠입할 계획입니다. 그들은 테라모어와 얼라이언스 간의 관계를 밝혀줄 정치적 문서를 찾기를 기대하고 있습니다.'),
(571, '--16일차\r\n울레그와 타르길은 임무를 마치고 테라모어 항구로 돌아왔습니다. 항구에 새로운 배 한 척이 정박해 있는 것을 보았는데, 바로 피의 참새호였습니다. 이 배는 아제로스의 메네틸 항구에서 온 것이었습니다.\r\n\r\n내일 울레그와 타르길은 다시 항구로 돌아가 배에 몰래 잠입할 계획입니다. 그들은 테라모어와 얼라이언스 간의 관계를 밝혀줄 정치적 문서를 찾기를 기대하고 있습니다.'),
(572, '켈투자드가 로데론에서 성공을 거두자, 리치 왕은 인간 문명에 대한 공격을 위한 최종 준비를 마쳤습니다. 네르줄은 역병의 에너지를 여러 개의 휴대용 유물인 역병 가마솥에 담아 켈투자드에게 로데론으로 운반하여 여러 이단 집단이 장악한 마을에 숨기도록 명령했습니다.'),
(573, '충성스러운 추종자들이 지키는 가마솥은 역병 발생기 역할을 하여, 아무것도 모르는 로데론 북부의 농경지와 도시 곳곳에 역병을 퍼뜨렸다. 리치 왕의 계획은 완벽하게 성공했다. 로데론 북부의 많은 마을들이 순식간에 오염되었다. 노스렌드에서와 마찬가지로, 역병에 걸린 주민들은 죽었다가 리치 왕의 자발적인 노예로 되살아났다.'),
(574, '켈투자드 휘하의 광신도들은 죽었다가 다시 살아나 암흑 군주를 섬기는 삶을 간절히 원했다. 그들은 언데드가 되어 불멸을 누릴 수 있다는 전망에 환희에 휩싸였다. 역병이 확산되면서 북부 지역에는 점점 더 많은 흉포한 좀비들이 생겨났다. 켈투자드는 리치 왕의 점점 커지는 군대를 바라보며 \'재앙\'이라는 이름을 붙였다. 머지않아 그 군대는 로데론의 성문을 향해 진격해 올 것이며, 인류를 세상에서 완전히 쓸어버릴 것이다.'),
(575, '"아무도 우주의 기원에 대해 정확히 알지 못한다. 어떤 이들은 엄청난 대폭발이 거대한 암흑 속으로 무한한 공간들을 방출시켜서 현재와 같이 되었고, 그 안에 형성된 세계들이 놀랍게도 다양한 생명을 잉태하게 되었다는 가설을 내세운다. 또 다른 이들은 무한한 힘을 가지고 있는 전능한 존재에 의해 지금의 우주가 창조되었다고 믿는다.\r\n"'),
(576, '"비록 이 무질서한 우주의 정확한 기원은 불명확하지만, 어떤 강력한 종족이 혼돈 상태였던 세계를 체계화하고 후손들이 안전하게 그들의 발자취를 따를 수 있도록 미래를 확보해 놓았다는 것은 확실하다.\r\n\r\n우주 먼 곳으로부터 온, 금속의 피부를 가진 거대한 신, 티탄들이 나타나 세계에 힘을 불어 넣었다. 그들은 거대한 산맥을 일으키고 광활한 바다를 만들어 세계의 형태를 다듬었다.\r\n"'),
(577, '"티탄들은 숨을 불어넣어 하늘을 만들고 대기를 채웠다. 먼 미래를 내다본 그들의 헤아릴 수 없는 계획에 따라 혼돈에서 질서가 창조되었다. 그들은 원시 종족들에게 힘을 부여하여 자신들의 일을 돕고 각각의 세계를 완전한 상태로 유지하도록 했다.\r\n\r\n티탄들의 세계의 정권은 최상위 집단 판테온이 잡고 있었으며, 첫 번째 창조 시대 동안 끝없는 어둠 너머 곳곳에 흩어져 있는 수억 개의 세계에 질서를 확립시켰다.\r\n"'),
(578, '"자비로운 판테온은 뒤틀린 황천이라는 다른 차원에서 온 사악한 존재들의 공격으로부터 그들이 창조한 세계를 안전하게 지키기 위해 경계를 늦추지 않았다. 혼란스러운 마법으로 가득한 천상계인 황천은 우주의 무수한 세계와 연결되어 있으며, 생명을 파괴하고 우주의 생명 에너지를 삼켜 버리는 데만 혈안이 되어 있는 악의 무리들에게 고향과 같은 곳이다.\r\n"'),
(579, '--17일째\n울레그가 임무를 마치고 돌아왔습니다. 임무는 실패했고, 타르길은 포로로 잡혔습니다. 울레그를 보내 나지르에게 이 보고서를 전달하도록 했습니다.\n\n저는 여기에 남아 있겠습니다. 테라모어 해안에서 선박 활동이 증가한 것을 목격했습니다. 계속 감시를 하면서 특이사항이 있으면 직접 보고하겠습니다.'),
(580, '우리의 첫 번째 계획은 이미 실패했다!  피스트는 그날 저녁 터널 경비 근무표를 바꾸는 데 성공했지만, 스톰윈드 시민들의 예상치 못한 개입으로 목표물이 우리가 붙잡기 전에 현장을 빠져나갔다. 하지만 이런 사태도 예상해 두었다. 두 번째 계획은 이미 실행에 들어갔으며, 스톰윈드의 매복이 발동하기 전부터 순조롭게 진행되고 있었다.'),
(581, '두 번째 계획도 마찬가지로 간단하지만, 우리에게는 좀 더 인내심이 필요할 겁니다. 메네틸에 있는 우리 정보원은 이미 수고에 대한 대가를 받았고, 임무를 훌륭하게 완수했습니다. 출항만 한다면 목표물을 포착하고 생포하는 데는 아무런 문제가 없을 겁니다.'),
(582, '공격은 목적지에서 몇 마일 떨어진 곳에서 일어날 겁니다. 바로 그곳에 우리 동맹군이 매복해 있을 테니까요. 우리가 왜 저런 괴물들과 동맹을 맺어야 했는지 모르겠지만, 어쩔 수 없이 강요당하는 기분이 듭니다. 하지만 결국엔 상관없겠죠. 목표물을 손에 넣으면, 우리에게서 스톰윈드를 빼앗아간 자들에게서 도시를 되찾을 수 있을 테니까요!'),
(607, '"존경하는 롱비어드씨\r\n\r\n아시는 바와 같이, 우리 스톰파이크 일가는 명품을 볼 줄 아는 눈이 있습니다. 그래서 당신이 만드는 방패가 얼마나 품질이 좋은지도 잘 알고 있습니다.\r\n그래서 그런 방패를 좀 주문했으면 합니다. 주문 내역은 다음 페이지에 나와 있습니다."'),
(627, '"오크 호드와 끔찍한 2차 대전쟁으로 인해 로데론의 얼라이언스는 충격과 혼란에 빠지게 되었다. 강력한 대족장 오그림 둠해머가 이끄는 피에 굶주린 오크족은 드워프들이 점령하고 있는 카즈 모단으로 공격하여 쳐 부셨을 뿐 아니라 로데론의 중심 지역도 다수 손에 넣었다.\r\n냉혹한 오크들은 심지어 머나먼 엘프의 왕국 쿠엘탈라스까지 진격한 후에야 그 난폭한 공격을 멈추게 되었다."'),
(628, '"안두인 로서 경과 빛의 수호자 우서 경과 댈린 프라우드무어 제독이 이끄는 얼라이언스 부대는 오크족을 남쪽으로 황폐해져 버린 아제로스까지 밀고 나아갔다. 오크족의 잔혹한 살육에 처음으로 쓰러진 왕국은 아제로스였다.\r\n\r\n로서 경이 이끄는 얼라이언스 부대는 가까스로 둠해머의 부족을 로데론에서 오크가 점령한 아제로스로 다시 밀어냈다. 로서의 군대는 오크족의 화산 요새인 검은바위 첨탑을 포위하고 공성전을 벌였다."'),
(629, '최후의 발악으로 둠해머와 그의 부관들은 검은바위 첨탑에서 돌격해 불타는 평원에서 로서의 성기사들과 결전을 벌였다. 둠해머와 로서는 일대일로 맞닥뜨려 서로 상처입고 지치게 되었다. 아슬아슬하게 둠해머가 로서에게 이겼지만 그 위대한 영웅의 죽음도 자신이 원한 결과를 가져오지는 못했다.'),
(630, '"로서가 가장 신뢰하는 부관 투랄리온이 로서의 피 묻은 방패를 다시 집어 들고 슬픔에 잠긴 동료들을 규합하여 맹렬한 반격을 가했다. 짓밟힌 로데론과 아제로스 양국의 깃발 아래, 투랄리온의 부대는 둠해머의 마지막 잔병들을 해치우고 영광스럽지만 끔찍한 승리를 거두었다."'),
(631, '"겨우 살아남은 오크 생존자들은 오크족의 최후의 보루, 어둠의 문으로 도망칠 수밖에 없었다.\r\n\r\n투랄리온과 그의 전사들이 오염된 슬픔의 늪을 지나 어둠의 문이 우뚝 서 있는 타락한 저주받은 땅으로 오크족의 잔병들을 추격했고, 그 거대한 문 아래에서 호드의 잔병들과 만신창이가 된 얼라이언스 부대가 2차 대전쟁의 마지막 대혈전을 벌였다."'),
(632, '"수적으로 열세인데다가 피를 향한 욕망의 저주에 미쳐 버린 오크들은 얼라이언스 부대의 분노 앞에 결국 쓰러져 버렸다. 둠해머는 체포되어 로데론으로 이송되었고 나머지 부족들도 얼라이언스 부대가 모아 북쪽, 로데론으로 이송했다."'),
(633, '"네더가드가 완성된 지 얼마 되지 않아 어둠의 문의 힘이 형상화되어 드레노어로 연결되는 새로운 문이 열렸고, 장로 주술사인 넬쥴이 이끄는 나머지 오크 부족들은 다시 한번 아제로스로 진격했다. 오크들은 넬쥴의 힘을 배가할 마법 유물들을 훔쳐 드레노어에서 새로운 문을 열어 이 멸망해 가는 붉은 세계에서 영원히 탈출하고자 했다."'),
(634, '"넬쥴이 얼라이언스에게 공격을 감행할 작정이라고 생각한 로데론의 국왕 테레나스는 드레노어로 군대를 파견해 오크의 위협을 완전히 제거하게 했다. 카드가와 장군 투랄리온이 이끄는 이 얼라이언스 부대는 불타는 평원을 가로지르며 오크족과 싸우게 되었다. 순찰대장 알레리아, 드워프 쿠르트란, 그리고 노병 다나스의 도움까지 받았지만 결국 카드가는 넬쥴이 다른 세계로 연결되는 문을 여는 것을 막아내지 못했다."'),
(635, '"두 문이 하나로 합쳐지면서 생긴 격렬한 마법력의 태풍이 황폐한 세계를 뒤흔들기 시작했다. 넬쥴은 자신이 가장 신뢰하는 신하들만 데리고 두 문 중 하나로 빠져나갔고, 카드가는 아제로스에 있는 동료들에게 되돌아 가기 위해 혼신의 힘을 다해 싸웠다. 곧 파멸할 세계에 갇혀 버릴 것이라는 것을 깨달은 카드가와 그의 동지들은 아제로스가 드레노어의 격렬한 파괴로 인해 피해를 입지 않도록 헌신적으로 어둠의 문을 파괴하기로 결정했다."'),
(636, '전해진 바로 이 영웅들은 어둠의 문을 성공적으로 파괴해 아제로스를 구해냈다. 하지만 그들이 드레노어의 생지옥을 빠져나왔는지는 아직 알 수 없다.'),
(637, '"오크족과 인간이 1차 대전쟁에서 맞붙기 1만 년 전에 아제로스의 세계는 하나의 거대한 대륙으로, 끝없고 거친 바다에 둘러싸여 있었다. 칼림도어라 불리는 이 땅덩어리는 막 태어나고 있던 세계의 거친 자연 속에서 살아남기 위해 서로 다투는 절박한 종족과 짐승들의 고향이었다. 이 어두운 대륙의 중심부에는 하얗게 빛나는 힘을 내뿜는 신비한 호수가 있었다."'),
(638, '"훗날에 영원의 샘이라고 불린 이 호수는 이 세계의 마법과 자연력의 태고의 근원이었다. 이 호수는 이 세계 너머의 끝없는 대 암흑으로부터 힘을 빨아들여 전 세계로 보내 다양한 생명을 놀라운 형태로 무럭무럭 자라나도록 하는 신비한 샘이었다.\r\n\r\n시간이 흘러 인간의 모습을 한 원시적인 야행성 부족이 조심스레 이 매혹적인 마법의 호숫가로 모여들었다."'),
(639, '야성적이고 유목민적인 성격의 이들은 샘의 신비로운 힘에 이끌려 잔잔한 호숫가에 천연 재료 그대로 집을 지었다. 시간이 흐르면서 샘의 무한한 힘이 이 이상한 종족을 강하고 지혜롭고 불멸에 가깝게 변화시켰다. 이 종족은 스스로를 그들의 언어로 별의 후예란 뜻을 가진 칼도레이라 칭하였다. 막 피어나고 있는 자신들의 사회를 기리며 그들은 호수 주위에 거대한 구조물과 사원들을 세웠다.'),
(640, '후에 나이트엘프라고도 불리는 칼도레이는 달의 여신 엘룬을 숭배했고 해가 떠 있는 동안에는 엘룬이 샘의 바닥에서 잔다고 믿었다. 초창기의 나이트엘프 사제들과 예언자들은 끝없는 호기심으로 그 비밀과 힘을 캐내고자 샘을 연구했다. 사회가 커져 감에 따라 나이트엘프들은 칼림도어를 두루 탐험했고 수많은 동식물을 접하게 되었다.'),
(641, '"이들 중 그들이 가장 흥미롭게 여긴 것은 아주 오래되고 강력한 용들이었다.\r\n뱀 모양을 한 이 짐승들은 종종 은둔을 하지만 알려진 대륙을 잠재적인 위협으로부터 보호하기 위해 많은 활동을 했고, 나이트 엘프들은 용들이 이 세계의 수호자일 것이니 그들의 비밀을 캐내지 않는 것이 좋다고 믿었다."'),
(642, '"나이트 엘프의 끝없는 호기심은 결국 여러 강한 존재들을 만나 친분을 쌓게 하였는데, 이 중에서도 주목할 만한 존재는 원시 삼림지의 강대한 반신인 세나리우스였다. 마음이 넓은 세나리우스는 호기심이 강한 나이트 엘프에게 정이 들었고 많은 시간을 할애하여 그들에게 자연의 세계에 대해 가르쳐 주었다. 차분한 종족인 칼도레이는 칼림도어의 살아 있는 숲에 강한 유대를 만들어 나갔고 조화로운 자연의 균형을 즐기며 살았다."'),
(643, '"하지만 끝이 없을 것 같은 긴 시간이 흐르면서 나이트 엘프의 도시는 점차 커져나갔고, 문명도 번창하였으며 그들의 사원, 길, 그리고 주거지가 대륙의 양쪽 끝으로 뻗어나갔다. 나이트 엘프의 아름답고 축복받은 아즈샤라 여왕은 샘 근처에 거대하고 호화로운 궁전을 지어 자신이 가장 신뢰하는 신하들에게 나눠 주고 온갖 금은보석으로 수놓은 전당에서 살도록 했다."'),
(644, '"그녀가 귀족이라는 뜻으로 쿠엘도레이라 부르던 이 신하들은 그녀의 모든 명령에 맹목적으로 복종하며 자신들이 다른 모든 나이트 엘프들보다 더 위대하다고 믿었다. 모두 주민이 똑같이 아즈샤라 여왕을 사랑했지만 질투심을 느낀 다수의 군중들은 은밀히 귀족들을 미워했다.\r\n\r\n영원의 샘에 대한 호기심으로 가득했던 사제들처럼 아즈샤라 여왕은 지식이 풍부한 귀족에게 샘의 비밀을 캐내어 세계의 진정한 목적을 찾아내도록 지시를 내렸다."')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(645, '귀족들은 일에 몰두하여 샘에 대해 쉬지 않고 연구했다. 시간이 흘러 그들은 샘의 무한한 힘을 조작하는 방법을 발전시켰고 무모한 실험을 계속하면서 이 새로운 힘으로 창조와 파괴를 마음대로 할 수 있다는 것을 알게 되었다. 이 불운한 귀족들은 원시 마법을 발견하여 이를 완전히 익히는 데 전념하기로 마음먹었다.'),
(646, '"마법은 무책임하게 다룰 경우 본질적으로 위험한 것이라는 데에는 모두 동의했음에도 불구하고 아즈샤라 여왕과 귀족들은 마법을 남용했다. 세나리우스와 여러 나이트 엘프 학자들이 명백하게 위험의 여지가 남아있는 마법을 남용하면 대재난이 일어나게 될 것이라고 경고했지만, 아즈샤라와 그녀의 신하들은 자신들의 고집대로 점점 커져 가고 있는 그들의 힘을 더욱 확장해 나갔다."'),
(647, '마법의 힘이 더해갈수록 아즈샤라와 귀족에게 변화가 일어나기 시작했다. 도도하고 초연한 계급이던 이들은 다른 나이트 엘프 동료들에게 냉담하고 잔인하게 변해갔다. 한때 매혹적인 아름다움을 지녔던 아즈샤라 여왕에게는 어둡고 스산한 기운이 감돌았고 자신을 사랑하는 백성들에게서 등을 돌리고 오직 자신이 신뢰하는 귀족 사제들과만 어울리려고 했다.'),
(648, '많은 시간을 샘의 영향에 대한 연구에 보낸 퓨리온 스톰레이지라는 이름의 한 젊은 학자는 이 끔찍한 힘이 귀족들과 그가 사랑하는 여왕이 타락하는 원인이 아닌가 의심하기 시작했다. 다가오고 있는 악이 무엇인지는 잘 알 수 없었지만 곧 나이트 엘프의 삶이 영원히 달라질 것이라는 것은 알 수 있었다.'),
(649, '"완전 원형으로 주먹과 팔꿈치 사이에 장착할 수 있어 함.\r\n가장자리에 은으로 만든 징이 박혀 있어야 함.\r\n중앙에 손가락 세 개 정도 길이의 큰 징이 하나 박혀 있어야 함.\r\n재질은 참나무로 만들어지고 철로 보강해야 함.\r\n맨 위쪽 테두리에 그링거 스톰파이크라는 이름이 새겨져야 함."'),
(650, '"대금은 통상적인 경로를 통해 지급해 드리도록 하겠습니다. 그리고 이 주문서를 전달하는 이에게 관례적인 배달료를 지불해 주시기 바랍니다. 그 비용은 방패 대금에 포함시켜 주시면 됩니다.\r\n\r\n\r\n감사합니다.\r\n- 그링거 스톰파이크"'),
(669, '아제로스에 대한 언데드의 위협은 실제로는 아서스 왕자의 타락으로 시작된 것이 아니다. 그 사건이 있기 훨씬 전부터 이미 시작되고 있었다. 오래전부터 로데론의 멸망을 부르게 될 사건들이 곳곳에서 벌어지고 있었다. 그것은 오크 부족들과 불타는 군단이 나타나면서 시작되었다고 할 수 있다.'),
(670, '드레노어에서 오크들은 고귀하고 신비한 존재였다. 그들은 강력한 전사 집단이었으며 강인한 신체와 의지를 지니고 있었다. 불다는 군단이 그들을 제거하려 했던 것도 바로 이런 이유 때문이었다. 군단에서 가장 큰 힘을 가진 악마 킬제덴은 오크 부족들을 노예로 삼아 아직 불타는 군단이 정복하지 못한 세계에 보낼 군대로 이용하고자 했다.'),
(671, '킬제덴은 오크 부족들을 이끄는 지도자인 넬쥴이라는 강력한 주술사에게로 갔다. 그는 넬쥴에게 오크 부족들이 불타는 군단의 노예가 되겠다는 계약을 맺으면 알려지지 않은 신비한 힘과 지식을 주겠다고 약속했다. 이 계약은 그들의 운명뿐 아니라 그들이 살고 있는 세계의 운명을 영원히 결정지어 버렸다.'),
(672, '시간이 지나면서 넬쥴은 오크 부족의 운명이 불타는 군단의 손에 달려 있다는 사실을 깨닫게 되었고, 이에 이 오크 주술사는 킬제덴에게 반항하기 시작했다. 킬제덴은 넬쥴에게 분노하여 쉽게 매수할 수 있는 그의 수습생 굴단에게 접근했다.'),
(673, '부족 전체의 주술신앙이 쇠퇴하게 된 것은 바로 이 굴단의 짓이었다. 적을 능가하는 힘과 권력에 대한 약속은 그의 욕심을 더욱 부추겼다. 킬제덴의 도움으로 굴단은 그의 앞잡이가 되어 부족을 이끌기 시작했다. 이전의 고귀했던 오크들은 타락하여 어리석고 야만적인 존재가 되어 버렸다. 그들의 몸에 악마의 피가 들어오자 오크들은 더욱 더 잔인하고 포악해졌다.'),
(674, '넬쥴을 매수하는 데 실패한 킬제덴은 굴단을 매수하는 데 성공하긴 했지만, 킬제덴은 넬쥴을 증오했고 원래 계약의 내용을 그대로 이행하겠다고 단언했다. 킬제덴은 넬쥴을 잡아서 믿을 수 없을 만큼 고통스러운 고문을 서서히 가하기 시작했다. 넬쥴은 죽음을 애걸했지만 킬제덴은 넬쥴에게 그들의 계약이 아직 유효하다는 사실만을 상기시켰다. 킬제덴은 이 오크를 죽였다. 하지만, 그를 육체적으로만 죽였을 뿐, 킬제덴은 넬쥴의 뒤틀린 영혼이 황천으로 가 버리기 전에 이 오크 주술사의 영혼을 단단히 붙잡았던 것이다.'),
(675, '킬제덴은 뒤틀린 황천에서 가져온 얼음 덩어리 안에 넬쥴의 영혼을 가둬 놓았다. 그의 영혼이 얼음 속에 갇혀 있는 동안 킬제덴은 그의 영혼에 보다 더 강력한 힘을 불어넣었다. 육신을 잃고 그토록 놀라운 힘을 얻게 되었다는 것이 넬쥴에게 일어난 변화의 핵심이었다.'),
(676, '킬제덴은 얼음 덩어리를 여러 차원 너머에 있는 아제로스로 다시 던져 버렸다. 얼음 덩어리는 노스렌드 대륙에 떨어졌고, 그렇게 해서 이 엄청난 악마가 우리 세계에 들어오게 된 것이었다. 넬쥴은 영원히 사라져 버렸고, 그 대신 얼음과 증오로 가득 찬 왕좌가 생겨 났다. 한때 존경 받던 주술사 지도자는 이제 놀랄 만큼 강력한 힘을 가진 리치 왕이 되었던 것이다.'),
(677, '킬제덴은 리치 왕을 신뢰하지 않았기 때문에 무시무시한 지배자들을 보내 그 영혼을 주시하고 리치 왕이 그의 명령을 잘 따르는지 감시하도록 했다. 흡혈귀 부하들이 자진해서 아제로스로 모여들었고, 리치 왕의 힘을 조종하여 전 세계 종족 전체의 파괴와 말살한다는 목표에 몸을 내던지게 되었다.'),
(678, '그로부터 십여 년이 흘렀다. 그 동안 리치 왕은 그의 막대한 힘으로 노스렌드에 살고 있는 생명체들의 정신을 조종해 그의 얼어붙은 왕좌 주위에 거대한 요새를 건설하도록 명했다. 이제 노스렌드 전체가 그의 지배 하에 놓이게 되자, 리치 왕은 로데론 침략을 시작해야 할 필요성을 느꼇다. 얼음 속에 갇혀있던 옛 오크 주술사는 더 많은 노예를 조종하고 지배하고 싶었던 것이다.그의 각지에서 자신의 종을 소환하려고 했다.'),
(679, '리치 왕의 소환 사실은 모두에게 알려졌고, 특히 강한 힘을 가진 소수에게 알려졌다. 그중에는 달라란을 지배하던 조직 키린 토의 영향력 있는 구성원이던 대마법사 켈투자드도 포함되어 있었다. 그는 흑마법의 습득을 금하는 키린 토의 정책을 어기면서 모든 종류의 마법을 추구했다. 켈투자드는 키린 토와 그 진부한 사고의 틀을 모두 깨버리고 리치 왕으로부터 최대한 많은 것을 배우기로 맹세했다.'),
(680, '그 둘 사이에 계약이 맺어졌고 켈투자드는 리치 왕의 노예가 되는 대신 영생과 막대한 힘을 손에 넣게 되었다. 켈투자드의 첫 번째 임무는 로데론에서 그의 재산과 영향력을 이용하여 저주받은 자들의 교단이라는 이교집단을 세우는 것이었다. 이 집단은 그들의 "신"인 넬쥴에 충성을 맹세하는 모든 구성원에게 평등과 영원한 생명을 약속했다.'),
(681, '이후 넬쥴은 로데론의 인간 문명에 역병을 퍼뜨리도록 설계된 장치를 만들었다. 그는 그 장치를 켈투자드의 손에 넘기고 이를 로데론 전역에 퍼뜨리도록 했다. 그의 추종자들은 어떤 희생을 치르더라도 그 장치를 지켜야 하는 임무를 맡게 되었다.'),
(682, '역병은 온 세상에 퍼지기 시작하면서 주민들을 감염시켰다. 켈투자드의 감독 하에, 리치 왕의 군대는 빠르게 성장했고 곧 넓은 지역을 점령하게 되었다. 이 군대의 유일한 목표는 아제로스 전역에서 인류를 말살한다는 것이었고 스컬지라는 이름으로 불리게 되었다.'),
(690, '"`배신자`라고 조악하게 긁어 써 놓은 아래에 다음과 같은 비문이 정교하게 새겨져 있습니다.\r\n\r\n가족에게 자상한 아버지이자,\r\n자상한 남편이며,\r\n강인한 성기사였던,\r\n유리브 여기 잠들다.\r\n그의 아이들이 빛에 대한 그의 헌신을 증언하리라.\r\n그는 스스로 하지 않을 일은 결코 다른 이에게 부탁하는 일이 없었다."'),
(691, '누락된 텍스트'),
(692, '당신은 사랑과 선행으로 가득한 조용한 삶을 살았습니다. 가난한 자들을 돕고, 병든 자들을 치유하고, 죽어가는 자들을 위로했습니다. 영원한 평화가 가득한 내세를 누릴 것이라는 확신에 차 기쁨으로 기다렸습니다. $B$B하지만 당신은 $B$B배신당했습니다. 저는 당신을 위로할 수 없습니다. 하지만 복수는 제 손안에 있습니다. 데스넬의 옛 교회로 오십시오. 당신이 배웠던 바로 그 신앙을 통해 치명적인 피해를 입히는 법을 가르쳐 드리겠습니다. - $B$B어둠의 성직자 듀에스텐, 사제 훈련관.'),
(693, '새로운 불멸의 존재가 된 기쁨을 만끽하고, 우리의 멸망을 꾀하는 자들을 세상에서 몰아내기 위해 네 힘을 사용하라. 적은 무수하지만, 우리는 불과 그림자로 $B$B그들을 섬멸할 것이다. 어둠과 소환술을 배우고 싶을 때, 옛 데스넬 교회에서 나를 찾아라. - $B$B막시밀리언, 흑마법사 훈련관.'),
(694, '어서 그 무덤에서 나와라! 할 일이 있다! 스칼렛 크루세이드는 우리 종족을 향해 빠르게 진격해 오고 있고, 다른 인간들은 기회만 되면 우리를 죽이려 든다. 네 검이 필요하다.$B$B 무기에 대해 더 배우고 싶다면 데스넬의 폐허가 된 선술집으로 찾아와라. 내가 가르쳐주겠다. $B$B- 대널 스턴, 전사 훈련 교관.'),
(695, '정교하게 새겨진 비문 위에 \'배신자\'라는 단어가 거칠게 휘갈겨져 있다. 비문에는 다음과 같이 적혀 있다. 유리브가 여기에 잠들어 있다. 아버지, 남편, 성기사. 그의 자녀들이 그의 빛에 대한 헌신이 얼마나 확고했는지 증언하게 하라. 그는 자신이 하지 않을 일은 결코 자녀들에게 요구하지 않았다.'),
(696, '일기 -   4일째 섬에 고립된 지 벌써 4일이 되었네. 생각에 잠겨 홀로 남겨졌지. 바나나는 정말 맛있지만, 거기까지 가려면 얼마나 멀리 올라가야 하는 거야. 음식을 구하거나 간간이 내리는 비를 피하는 시간을 제외하고는 온통 구조 생각뿐이야.   만약 나와 함께 해변으로 떠밀려온 종이 상자와 병들이 없었다면 이렇게 희망을 품지 못했을 거야. 연금술사와 서기관들로 가득 찬 배에 갇혀서 얼마나 많은 시간을 투덜거렸는지 생각하면 지금 생각하면 웃음이 나.'),
(697, '일기 - 일 512 바나나가 나에게 말하기 시작했고 나는 그들의 문화에 대해 많은 것을 배웠다. 나는 그들의 무의미한 가정 파괴와 젊은 세대의 소비를 중단했다. 내가 파괴하고있는 위대한 문명을 얼마나 알지 못했습니다. 다른 주제에 관해서 나는 병과 종이 위에서 낮게 달리고있는 것처럼 보인다. 내가 처음 해변에 닿았 던 거대한 종이 뭉치를 보았을 때 그들은 무진장 할 것이라고 생각했습니다. 내 일기는 곧 끝나야합니다.'),
(698, '아제로스 대륙은 한없이 경이로운 땅이다. 그 대지 위에는 동식물과 문명, 그리고 마법이 충만하다. 사실, 호기심이 강한 이라면 누구나 이 대륙의 무한한 다양성을 깨닫게 될 것이다. 그냥 둘러보기만 해도 알 수 있으니 말이다.$B$B하지만 깊이 관찰하게 되면 완전히 새로운 세계로의 창을 발견하게 될 것이며, 각각의 세계에는 저마다 경이로움이 기다리고 있다.$B$B각각의 세계에 저마다 공포가 숨어 있는 것처럼...$B'),
(699, '이 책을 쓰는 목적은 우리 땅을 파괴하려고 하는 존재, 다른 세계의 악마들을 체계적으로 정리하여 그들과 마주치게 되는 모험가들에게 정보를 주기 위함이다.$B$B따라서 스스로 아제로스의 수호자라 여기는 이라면 이 책을 계속 읽기 바라며 적에 대해서 알게 되기를 바란다.$B$B- 우르$B달라란 마술사'),
(700, '늑대인간에 대해서$B$B시골에는 이 생물에 대한 오랜 전설이 전해져 오기 때문에 농부의 자손이라면 누구나 마을밖의 숲과 늪을 어슬렁거리는 잔인한 늑대인간에 대해 들어 본 적이 있을 것이다.$B$B그리고 그런 전설에 진실이 숨어 있을지도 모른다. 우리를 겁주기 위해 신화처럼 베일에 가려진 채 전해오는 늑대인간에 대한 경고는 아닐까?'),
(701, '하지만 그런 전설을 제쳐놓기 전에 독자들에게 한 가지 확실히 해 두어야겠다. 늑대인간은 실제로 존재한다. 우리 세계의 존재는 아닐지 몰라도 그들의 세계와 우리 세계를 연결하는 통로가 존재하며 강력한 마법을 사용해 그들을 이곳으로 불러올 수 있다.$B$B늑대인간은 지나는 곳마다 공포와 살육을 가져오기 때문에 그러한 주문은 언급하지 않는 것이 최선이다.'),
(702, '늑대인간은 우리 세계의 늑대와 비슷한 외모로 알아볼 수 있다. 늑대인간의 외향을 살펴보면 일정한 방향으로 난 털, 뾰족한 귀, 그리고 긴주둥이에서 우리가 아는 늑대와 유사하다는 사실을 쉽게 알 수 있다.$B$B하지만 차이점 역시 금방 눈에 뛴다. 일정한 방향으로 난 털은 두 다리로 서 있는 강인한 몸을 뒤덮고 있으며, 긴 송곳니와 칼처럼 날카로운 발톱이 두드러져 보인다. 그리고 그 울음 소리 뒤에는 자연의 짐승에게서는 찾아볼 수 없는 증오가 숨어 있다.'),
(703, '늑대인간의 고향은 악몽이 가득한 장소인 어둠의 땅이다. 만약 그 세계에 저주받은 늑대인간으로부터 안전한 곳이 있다면 내 연구를 통해서는 아직 그런 요새를 알아 내지 못했다. 그리고 늑대인간의 잔인함과 사악한 면으로 미루어 볼 때 그런 곳은 존재하지 않을 가능성이 크다.$B$B일부 늑대인간은 강력한 마법을 지니고 있으면서도 스스로 아제로스에 들어오려는 시도를 하지 않는 것으로 보아 자신들의 세계에 머무르는 데 만족하는 것 같다. 그리고 그 점이 우리로서는 다행이 아닐 수 없다.'),
(704, '위에서 언급했듯이, 일부 늑대인간들은 신비로운 기술을 사용하는 데 능숙하며 그들이 사용하는 마법은 어둠과 타락의 마법이다.$B$B보통 저주와 초자연적인 독약을 사용하므로 주의해야 한다. 즉, 늑대인간 마법사를 상대하는 이들은 어둠을 상대할 수 있는 방어 태세를 갖추어야 한다.'),
(705, '정의로운 마음을 가진 자의 양심에 의해서라도 달라란 마술사가 늑대인간을 찾는 일이 일어나지 않기를 바란다. 이 짐승과는 어떠한 계약도 맺을 수 없으며, 어떠한 비밀도 알아낼 수 없고, 아무런 이득도 얻을 수 없기 때문이다.$B$B늑대인간은 그들의 세계에 있도록 두는 것이 가장 좋다. 그들이 우리 세계에 나타나고 누구도 그들을 처치하지 못한다면 우리에게 끔찍한 위험이 닥치게 될 것이기 때문이다.'),
(711, '헬그럼,$B$B황무지에 카르가스 기지를 건설하라는 명령을 내린 분께 경의를 표합니다. 그곳은 우리 병력을 훈련시키기에 이상적인 장소입니다. 혹독한 날씨, 사나운 야생 동물, 호전적인 원주민, 그리고 외부 지원의 완전한 부재는 이곳을 최고의 전사와 정찰병만이 배출될 수 있는 용광로로 만들어 줍니다.$B$B훌륭한 계획입니다. 잘하셨습니다.'),
(731, '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align="center">\n엘리자\n</H1>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="center">\n사랑하는 아내여, 대지가 그대의 굶주림을 달래 주기를.\n</P>\n</BODY>\n</HTML>'),
(750, '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align="center">\n엘리자\n</H1>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="center">\n사랑하는 아내여, 대지가 그대의 굶주림을 달래 주기를.\n</P>\n</BODY>\n</HTML>'),
(751, '"다음은 피스톤의 사양입니다.\r\n\r\n길이: 32 WW\r\n너비: 12WW\r\n무게: 23.5 IBG~25.5 IBG\r\n전도율: 70 TC\r\n전단력: 98 이상\r\n결합 강도: `엄청 튼튼` 이상\r\n노움의 측정 단위를 잊으셨다면 다음을 참고하세요.\r\nWW = `수염 너비`\r\nIBG = `아주 조금` 그램\r\nTC = `발가락 털 길이`"'),
(752, '그래, 친구. 이 편지를 시련의 계곡에 있는 프랑에게 전해다오. 그는 보통 동굴 밖에서 어린 전사들을 훈련시켜 호드를 위해 싸우게 하고 있을 거야. 그는$B$B너처럼 교활한 전사들이 필요해. 오크들에게 근육 말고 다른 걸로 싸우는 법을 가르쳐 줄 사람이 필요하거든. 넌 대부분의 오크보다 빠르고 똑똑하지만, 그걸 자랑하지는 마. 오크들은 모욕을 좋아하지 않으니까. 그들은 좋은 동맹이 될 거고, 어쩌면 너에게도 한두 가지 가르쳐 줄 게 있을지도 몰라.$B$B- 타르세르'),
(753, '누락된 텍스트'),
(754, '누락된 텍스트'),
(755, '누락된 텍스트'),
