INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(762, '누락된 텍스트'),
(763, '누락된 텍스트'),
(764, '누락된 텍스트'),
(765, '누락된 텍스트'),
(766, '누락된 텍스트'),
(771, '"먹이 및 관리법:\r\n\r\n저희 땅다람쥐 회사에서는 귀하의 다람쥐를 위한 모든 것을 제공하기 위해 최선의 노력을 다하고 있습니다. 저희 고객은 땅다람쥐 회사에 수준 높은 서비스를 기대하고 있으며 이 점은 저희도 환영하는 바입니다!\r\n\r\n저희는 작은 구멍이 뚫린 땅다람쥐 상자를 설계하여 빛이 잘 비치지 않는 곳에서도 땅다람쥐를 안전하게 보호할 수 있도록 하고 있습니다.\r\n\r\n상자 안에는 땅다람쥐가 제일 좋아하는 간식인 청엽수 줄기 냄새가 나는 그릇도 달려 있습니다!"'),
(791, '카르가스의 정찰병들이 조사한 주변 지형을 다음과 같이 묘사하겠습니다. - 붉은 바위투성이 언덕과 메마른 평야는 생명체가 살기에 적합하지 않습니다. - 작열하는 태양과 거센 바람. - 호수나 시냇물은 물론이고, 드문드문 웅덩이조차 없습니다. 물을 찾으려면 주민들은 깊고 진흙탕인 우물을 파거나, 보기 드문 선인장이나 가시 돋친 잡초에서 얼마 안 되는 수분을 빨아먹어야 합니다. 요컨대, 덥고 고된 삶입니다.'),
(792, '황무지는 적들로 가득 차 있다. 오우거들은 작열하는 사막을 배회하며 방심한 자들을 매복 공격한다. 검은무쇠 드워프들은 카르가스 동쪽의 병영에 거주하며 북쪽의 로크 모단에서는 피부색이 더 밝은 동족들과 전투를 벌인다. 트로그라고 불리는 잔혹하고 원시적인 짐승들은 그늘진 곳이면 어디든 숨어들어 맹렬하게 방어한다. 그리고 황무지 동쪽, 레슬로르 협곡에는 용들이 살고 있다. 정찰병들이 너무 가까이 접근했다가 돌아오지 못했기에 그 수가 얼마나 되는지, 크기가 얼마나 되는지는 알 수 없다.'),
(793, '굳이 말할 필요도 없이, 카르가스에 주둔한 우리는 이 임무에 아주 만족하고 있습니다. 우리는 여기서 강인함을 유지해야 합니다. 조금이라도 약해지면 죽기 때문입니다. 그리고 저는 다른 어떤 것도 바라지 않습니다. 니카 블러드스카 카르가스 정찰대장'),
(794, '우리 세계는 역사로 가득 차 있습니다. 신구 종족의 역사, 오래전에 끝난 전쟁과 아직도 꺼지지 않은 전쟁의 역사.  \n\n하늘에서 내려온 신들의 역사, 그리고 땅속에 잠들어 있는 고대 신들의 역사.\n\n지금 내가 말하려는 것은 바로 그 존재들, 고대 신들입니다. 세상이 새롭게 태동하던 시절, 아제로스 전역에 거하며 격렬하게 날뛰었던 그들 말입니다.'),
(795, '고대 신은 우리 세계의 의지다. 폭풍이 몰아칠 때마다 고대 신의 웃음소리가 울려 퍼진다. 들불의 화염은 그들의 시선이 내뿜는 열기다. 고대 신이 걸음을 옮기면 대지는 떨고 갈라지며, 하찮은 존재들은 절망에 빠져 비명을 지르고 제 살을 찢는다.\n\n절망해야 마땅하다. 불길이 호기심 많은 아이의 손을 봐주지 않듯, 고대 신도 자신보다 아래에 있는 자들을 조금도 신경 쓰지 않는다. 잘해야 우리는 장기판의 말이고, 최악에는 그저 장난감일 뿐이다.'),
(796, '그들은 세상의 첫 번째 지배자였으며, 막강한 힘과 공포로 세상을 다스렸습니다. 비록 지금은 사슬에 묶여 잠들어 있지만, 그들의 하수인들은 여전히 ​​활보하고 있으며, 우리처럼 나약한 필멸자들은 그들의 힘에 감히 맞설 수 없습니다.\n\n도전하는 자는 잡아먹힐 뿐입니다. 그러나 자신의 위치를 ​​알고, 고대 신들의 하수인들에게 무릎 꿇고 간청하며, 기꺼이 정신과 영혼을 바치는 자들만이 은총을 얻을 것입니다.'),
(797, '심연의 공주 아쿠마이는 고대 신들을 섬긴다. 그녀는 블랙패덤 심연에 거주하며 고대의 지혜로 동굴들을 축복한다. 나이 든 필멸자들에 의해 심연으로 인도된 아쿠마이는 신성의 상징이다. 그녀는 고대 신들의 힘과 잔혹함의 극히 일부분만을 지니고 있지만, 그럼에도 불구하고 그 위력은 헤아릴 수 없을 정도다.\n\n그래서 그녀는 숭배받고, 두려움의 대상이 되며, 동시에 사랑받는 존재이다.\n\n\n-로르갈리스'),
(811, '계획은 이미 실행에 옮겨졌습니다. 한때 위대한 신앙의 요새였던 영웅의 감시탑을 우리의 기지로 삼으십시오. 준비가 완료되었다는 연락을 보내주시면 서부 몰락지대에서 증원군을 파견하겠습니다. 스톰윈드의 시민과 병사들에게 거의 잊혀진 이 지역은 우리 공격을 위한 완벽한 전초 기지가 될 것입니다. 데피아즈 가문이 스톰윈드를 되찾을 것입니다! 답변을 기다리겠습니다.'),
(812, '더러운 트로그들은 속이기 너무 쉬워. 우리 동족에 대한 그들의 증오심 덕분에 그들을 조종하고 꼭두각시로 이용하기가 훨씬 수월하지. 어떻게든 동맹이 맺어졌다는 게 놀랍지만, 우리 동족이 그들의 존재에 훨씬 더 큰 위협이 돼... 적어도 지금은$B$B말이야. 하지만 공격이 시작되면 양측 모두 약해져서 우리 공격에 취약해질 거야. 헬름스 베드 호수 남쪽의 정착지를 점령하고 다음 지시를 기다려. 아이언포지는$B$B우리 것이 될 거야.'),
(831, '다음 페이지에는 화염으로 단련된 갑옷을 만드는 데 필요한 재료 목록이 나와 있습니다. 행운을 빕니다, 전사여.\n\n\n-푸렌 롱비어드'),
(832, '그을린 거미 송곳니:$B$B텔겐 바위 근처 동굴에서 발견되는 인화석 광석이 그곳에 서식하는 거미들을 그을리게 했습니다.$B$B거미 송곳니의 독이 끓어오르면서 송곳니 자체와 반응하여 매우 단단한 물질을 생성합니다.'),
(833, '그을린 뿔:$B$B칼림도르의 돌발톱 산맥에 있는 그을린 계곡에 서식하는 키메라의 그을린 뿔은 마치 불에 탄 거미의 송곳니처럼 매우 귀중한 특성을 지니고 있습니다. $B$B납작하게 두드리고 적절히 처리하면 물리적 스트레스에 매우 강해집니다.'),
(834, '아연 도금 뿔:$B$B희귀한 아연 도금 뿔의 뛰어난 내구성은 제가 만들 갑옷 전체의 핵심 요소이므로 반드시 구해야 합니다.이것은$B$B그을린 계곡에 있는 희귀한 키메라 암컷에게서 얻을 수 있습니다.'),
(835, '플로지스톤 약병:$B$B갑옷 제작의 마지막 단계에는 극도로 뜨거운 용광로가 필요합니다. 필요한 열을 발생시키려면 플로지스톤 약병이 필수적입니다. 이 물질을$B$B만들 수 있는 유일한 인물은 전설적인 가시멧돼지, 루구그이며, 그는 쉽게 약병을 내놓지 않을 것입니다. 루구그는 남부 황무지의 가시덩굴 우리 깊숙한 곳에 살고 있습니다.'),
(850, '다음 페이지에는 화염으로 단련된 갑옷을 만드는 데 필요한 재료 목록이 나와 있습니다. 행운을 빕니다, 전사여. -푸렌 롱비어드'),
(851, '그을린 거미 송곳니:\n\n텔겐 바위 근처 동굴에서 발견되는 인화석 광석이 그곳에 서식하는 거미들을 그을리게 만들었습니다.\n\n거미 송곳니 속의 독은 끓어오르면서 송곳니 자체와 반응하여 매우 단단한 물질을 생성합니다.'),
(852, '그을린 뿔:\n\n칼림도르의 돌발톱 산맥에 있는 그을린 계곡에 서식하는 키메라의 그을린 뿔은 마치 불에 탄 거미의 송곳니처럼 매우 귀중한 특성을 지니고 있습니다.  \n\n납작하게 두드리고 적절히 처리하면 물리적 충격에 매우 강해집니다.'),
(853, '아연 도금 뿔:\n\n희귀한 아연 도금 뿔의 뛰어난 내구성은 제가 제작할 갑옷 전체의 핵심 요소이므로 반드시 구해야 합니다.\n\n이 재료는 그을린 계곡에 서식하는 희귀한 키메라 암컷에게서 얻을 수 있습니다.'),
(854, '플로지스톤 약병:\n\n갑옷 제작의 마지막 단계에는 극도로 뜨거운 용광로가 필요합니다. 필요한 열을 발생시키려면 플로지스톤 약병이 필수적입니다.\n\n이 물질을 만들 수 있는 유일한 존재는 전설적인 가시멧돼지, 루구그뿐이며, 그는 쉽게 약병을 내놓지 않을 것입니다. 루구그는 남부 황무지의 가시덩굴 우리 깊숙한 곳에 살고 있습니다.'),
(855, '"아래에 위대한 사이클로니안을 소환하는 마법 주문에 필요한 것들을 적어 놓았네. 행운이 함께하길 빌겠네.\r\n\r\n- 바람의감시자 바스라"'),
(856, '"생명의 뿌리:\r\n\r\n이것은 황무지에서 구할 수도 있고 먼지진흙 습지대에 사는 시든덩굴괴물들에게서 얻을 수도 있네. 이 생명의 뿌리는 사이클로니안의 생명의 정수를 이 세계로 가져오는 데 필요할 걸세."'),
(857, '"붉은머리부족의 어금니:\r\n\r\n가시덤불 골짜기에 사는 붉은머리부족은 아주 희귀한 성질을 지니고 있지. 붉은머리부족의 사악한 힘은 어금니에 집중되어 있기 때문에 어금니를 가루로 빻으면 사악한 힘이 풀려 나올 걸세."'),
(858, '"떠도는 정령의 정수:\r\n\r\n이 정수는 아라시 고원에 사는 떠도는 정령들의 세 가지 부적을 한데 합쳐서 만들어진 것이네. 이 정령들에게서 천둥 부적, 불타는 부적, 용마루장식 부적을 모아서 각각 여덟 개씩 내 가마솥에 넣게. \r\n\r\n그러면 떠도는 정령의 정수가 만들어질 걸세."'),
(871, '"친애하는 $N,\r\n먼저 제 아내와 저를 위해 베풀어 주신 모든 일에 대해 다시 한번 감사 드립니다. 아내의 생명을 구해 주신 은혜는 제가 백 번을 다시 산다고 해도 다 갚지 못할 것입니다. 아내는 제 인생의 전부입니다. 아내가 죽었더라면... 글쎄요, 제가 무슨 짓을 저질렀을지 모르겠군요.\r\n\r\n보답으로 여기에 적어놓은 재료를 찾아오시면 당신께 성스러운 무기를 만들어 드리겠습니다. 제가 생각하기에 가장 찾기 쉬운 것부터 어려운 것 순으로 적어 놓았습니다. 도움이 되었으면 좋겠군요."'),
(872, '"쓸만한 흰돌참나무 약간 - 서부몰락지대가 정복 당하기 전만 해도 문브룩 지하 폐광에는 목재가 아주 많았습니다. 열과 압력에도 잘 견디기 때문에 단단한 격자나 도구를 제작하는 데 쓰였죠.\r\n\r\n목재는 바다 건너 어딘가에서 가져와 그곳으로 운반되었습니다. 당신의 무기를 제조하는 데 쓸 수 있을 정도로 아주 튼튼하지만 매우 희귀한 목재죠. 폐광에 아직 남아 있다면 아마 고블린 나무꾼들이 갖고 있을 겁니다."'),
(873, '"제련된 광석 - 텔사마에 베일러 스톤핸드라는 드워프 대장장이가 있는데, 한동안 제게 기술을 가르쳐 주셨던 분입니다. 그분은 아주 특수한 합금을 만드는 데 당신의 새 무기에 딱 맞을 것 같군요. 제가 아이언포지에 있는 동안 합금이 도착할 줄 알았는데 아직 아무 소식이 없습니다.\r\n\r\n그분을 찾아서 합금을 보냈는지 확인해 주세요. 만약 모단 호수에서 계시지 않는다면... 옛 스승에게 무슨 일이 일어난 것이 분명합니다."'),
(875, '"그 중 한 가지가 아버지께서 물려주신 대장장이 망치입니다. 어렸을 때는 그 망치에 마법이 깃들었다는 아버지의 말씀을 믿지 않았었는데... 그 망치는 스컬지에게 당해 돌아가시기 전 아버지의 손때가 묻은 유일한 물건입니다.\r\n\r\n제 열정을 되돌릴 수 있도록 그 망치를 가져다 주세요. 정말로 마법이 깃든 망치라면 우리 모두에게 도움이 될 거예요.\r\n\r\n망치는 성채의 넓은 안마당에 있는 마구간에 두었습니다. 괴물들이 직접 망치질을 하지 않는다면 아직 그곳에 있을 겁니다."'),
(876, '"코르석 - 제가 들은 이야기에 의하면 마법을 사용하는 이들은 이 보석에 마법의 힘을 모아서 훨씬 강하게 만들었다고 합니다. 한때 제가 도움을 줬던 툰드리스 윈드위버라는 나이트엘프에게 제 얘기를 하면 자세히 얘기해 줄 겁니다. 당신의 무기를 만드는 데 그 보석에 담긴 힘을 쓸 수 있는 게 있을 겁니다.\r\n\r\n저와 마지막으로 얘기를 나눴을 때 툰드리스는 어둠의 해안 깊은 곳에 있는 아우버다인이라는 마을에 있었습니다. 그 타락한 숲은 이제는 음산한 그늘이 져 버린 나이트엘프들의 고향으로, 해안에 점점이 흩어져 있죠."'),
(877, '코르 보석 - 제가 들은 이야기로는, 일부 마법사들이 마법 에너지를 저장하는 데 이 보석을 사용한다고 합니다. 그렇게 하면 마법이 더욱 강력해지죠. 제가 예전에 도와줬던 나이트 엘프 썬드리스 윈드위버가 더 자세한 내용을 알려줄 수 있을 겁니다. 당신이 제 대신 이야기해 줄 테니까요. 제 생각에는 이 보석에 저장된 에너지 중 하나가 당신의 무기 제작에 사용될$B$B수 있을 것 같습니다.우리가 마지막으로 이야기했을 때, 썬드리스는 나이트 엘프 고향의 그림자 아래 해안을 따라 펼쳐진 타락한 숲, 다크쇼어 깊숙한 곳에 있는 마을 오버딘에 있었습니다.'),
(891, '이 설명서의 페이지를 채우는 소용돌이 치는 기호와 그림은 이해할 수 없을 정도로 난해합니다.'),
(911, '비취를 구하세요. 비취는 다양한 여러 장소에 숨겨져 있을 겁니다. 비취는 매우 희귀해서 구하기 어렵지만 대장 기술이나 기계 공학을 익힌 자들에게 물어보면 한두 개 얻을 수도 있을 겁니다.'),
(931, '"아래의 물건들이 갑옷 제작에 필요한 재료들이오.\r\n\r\n돌발톱 산맥의 칼바람 광산에 있는 칼바람 코볼트에게서 연기나는 철제 주괴.\r\n\r\n힐스브래드에 있는 힐스브래드 광부에게서 아주라이트 가루.\r\n\r\n채광을 익힌 자나 당신이 채광을 익혔다면 철 광맥에서 철 주괴.\r\n\r\n가시덩굴 우리에 있는 루구그라는 가시멧돼지에게서 연소 약병."'),
(951, '"(얼룩에 가려 일지의 일부만을 읽을 수 있습니다.)\r\n울다만, 셋째 날\r\n\r\n내가 그렇게 바보스러웠다는 게 믿기지 않는다. 그 역겨운 검은무쇠 드워프들에게 약점을 찔리다니 초보자나 하는 실수였다. 상처가 아무는 속도를 보면 중독된 것이 분명하다. 기운이 점점 빠져나가는 것 같다. 그렇지만 정찰은 해야 한다...\r\n\r\n...엎친 데 덮친 격으로 노움이 만들어 준 목걸이가 산산조각 나 버렸다! 박혀 있던 보석 중 가장 큰 세 개가 없어졌다. 반드시 찾아야 한다. 그게 없으면 목걸이는 아무 힘도 발휘하지 못한다..."'),
(953, '아메스아란의 노래\n\n\n오랜 세월 별의 자손들은 영원의 샘에서 반짝이는 물가에 터전을 잡고 살았다. 영원한 황혼의 빛이자 달의 여신인 엘룬이 자신의 일을 마치고 쉴 때면 그 물속에 머문다는 사실은 모두가 알고 있었다. 엘룬의 총애를 받은 별의 자손들은 샘가에 집을 세웠고, 그들의 시선은 언제나 달빛 어린 밤하늘을 향했다.'),
(954, '아메스아란의 몰락\n\n\n마력 깃든 숲의 고대 나무들이 뿌리째 뽑혀 쓰러지자 대지가 진동했다. 세나리우스의 아들딸들이 돌보던 숲과 공터, 별의 자손들이 세운 돌탑도 흔들리는 땅 위로 무너져 내렸다. 절망과 혼돈으로 뒤엉킨 전투 속에서도 우리의 여왕은 찬란하게 빛났다. 마법이 뿜어져 나오고 세계를 산산이 찢을 듯한 폭발이 이어질 때마다 마력으로 물든 하늘은 시시각각 빛깔을 바꾸었다.'),
(971, '"울다만, 넷째 날...\r\n\r\n...첫 번째 단서가 울다만의 깊은 곳에서 그 모습을 드러냈다. 지금까지 본 것 중 가장 포악한 트로그가 커다란 사파이어 하나를 휘둘러대고 있었다. 틀림없이 내 목걸이에 딱 맞는 크기일 것이다. 난 우연히 검은무쇠 드워프가 그 괴물같은 놈을 그림로크라고 부르는 것을 들었다. 하지만 놈이 데리고 있는 경비병들은..."'),
(972, '"울다만, 다섯째 날\r\n\r\n트로그를... 그리고 죽음을 당한 `형제들`의 토파즈를 빼앗아 전당 앞쪽에 있는 옆 동굴로 들어간 다음...\r\n\r\n...방 뒷편의 크고 눈에 띄인 항아리에 재빨리 집어넣고...\r\n\r\n...하필이면 드워프라니! 그것도 세 놈씩이나 되는데 지금 트로그에게 막혀 있다. 힘이 약해진 상태에서는 역겨운 트로그 녀석들에게 당할지도 모르니 녀석들을 부르는 것은 자살행위나 마찬가지였다. 하지만 세 번째 보석을 알게 되면 나는..."'),
(973, '"울다만, 여섯째 날\r\n\r\n...너무 배고프다. 식량이 다 떨어져 이제는 곰팡이 핀 빵이라도 진수성찬으로 보일 정도다... 내 눈 바로 앞에 있는 트로그의 머리가 맛있는 스테이크로 보일 지경이다..."'),
(974, '"울다만, 일곱째 날\r\n\r\n...내 실수를 만회할 마지막 기회다. 루비는 드워프가 트로그를 막기 위해 쳐 놓은 최후의 방어진 내에 있는 것으로 보인다. 그들의 전투는 유적지의 유물이나 보석을 차지하기 위해 벌어지고 있는 것이 확실해 보였고 날이 갈수록 치열해지고 있다. 그런 곳에 보석을 숨겨놓다니 사악한 드워프답다. 사정이야 어쨌든 나도 움직여야 한다. 어쩌면 이곳을 미친 듯이 뛰쳐나가는 것이 최선일지도..."'),
(991, '벼락 맞은 나뭇가지를 가져오세요. 나뭇가지를 얻으려면 아라시 고원의 마른나무껍질 트롤에게서 마른나무껍질 토템 막대를 10개 모아야해요. 막대를 가지고 아라시 고원에 외부 봉인의 마법진에 있는 원형의 돌로 가져가서 원형의 중앙에 있는 돌에 막대를 놓고 벼락을 맞을 때까지 기다리세요. 나뭇가지가 벼락을 맞으면 나뭇가지가 변하게 될 겁니다.'),
(992, '이 자격증을 소지한 자는 모든 일급 도둑 및 도적이 받아야 할 존경을 받을 권리가 있음을 증명함.'),
(1011, '"내가 카즈뮬의 방으로 들어가는 방법을 알아냈다!\r\n\r\n나의 궤짝에서 그니키브의 메달을 습득한다.\r\n\r\n지도실 앞방에 있는 레벨로쉬라는 트로그를 처치하고 티솔의 자루를 회수한다.\r\n\r\n메달과 자루를 합쳐 잃어버린 역사의 지팡이를 만든다.\r\n\r\n지도실에서 지팡이를 사용해 카즈뮬의 방으로 통하는 문을 연다.\r\n\r\n그러면 그 방 안에 있는 것은 모두 당신의 것이다!\r\n\r\n-밸로그"'),
(1031, '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\n의학 박사이자 교사이자 친구였던 친애하는 스승 호레이쇼 M. 몽고메리를 기리며...\n</P>\n<BR/>\n<H1 align="center">\n50 BTFT - 25 ATFT\n</H1>\n<BR/>\n<P>\n"이 세계는 병들고 지친 자들로 가득하니 우리는 의사로서, 아니, 의학을 배운 남녀로서 모든 `질병`을 치료할 의무가 있다."\n</P>\n<BR/>\n<P>\n- 의학박사, 철학박사, 법학박사, 일류 농부, 비범한 무용수, 동물의 친구였던 호레이쇼 몽고메리\n</P>\n<BR/>\n</BODY>\n</HTML>\n'),
(1051, '"이 탑의 경비병들은 내 공격에 유독 약한 듯하다. 내가 탑의 뒤편을 조사하던 중, 정찰병 하나가 나를 보고 공격을 했는데 때를 맞춰 후려치고 목을 졸라 아주 손쉽게 처치할 수 있었다.\r\n\r\n나는 이 정찰병의 동료가 소동이 나는 소리를 듣고 조사하러 오기를 숨어서 기다렸다. 그는 내가 시체를 끌고 간 덤불로 가서 조사하기 시작했다. 내가 매복하고 있는 것이 발각되지 않도록 나는 천천히, 조심스럽게 그의 뒤로 다가갔다."')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(1052, '"적절한 기회가 포착되자 나는 녀석의 등에 내 단검을 찔러넣었다! 내 공격에 그는 허파가 터져 쿵하고 둔탁한 소리를 내며 쓰러졌다.\r\n\r\n워낙 빠르고 맹렬한 기습이어서 녀석은 고통으로 비명을 지를 틈조차 없었다. 이상하게도 내가 그의 등에서 칼을 뽑자 그 정찰병에게서 악취가 나기 시작했다."'),
(1053, '"클레븐이 궤짝에 숨겨 놓은 것이 탑의 주민들에게 나쁜 영향을 끼치고 있는 것 같았다. 다른 경비병들도 비슷한 약점들을 가지고 있을 듯하고, 어쩌면 클레븐 자신도 그 폐기물로 인해 피해를 입었을지 모른다.\r\n\r\n첩보원 앰버 켈넌\r\nSI:7 지상 행동 요원, R8"'),
(1071, '사령관님,\n\n오그리마로 복귀하십시오. 병력이 부족합니다. 새로운 정보에 따라 상황을 재검토해야 합니다.\n\n수많은 섀도우스원과 오우거가 있습니다. 악마들이 어둠의 문을 지키고 있습니다.\n\n-스랄, 호드 대족장'),
(1090, '클레이븐이 상자 안에 가둬둔 무언가가 탑 거주자들에게 악영향을 미치고 있는 것 같습니다. 다른 경비병들도 비슷한 약점을 가지고 있을지도 모르고, 어쩌면 클레이븐 자신도 그 여파에 희생되었을지도 모릅니다. 앰버 커넌 요원, SI:7 지상 작전 요원, R8'),
(1091, '"줄파락의 나무망치\r\n\r\n1. 줄파락의 나무망치를 만들려면 우선 동부 내륙지에 있는 줄의 제단으로 가서 트롤 문지기를 처치하여 신성한 나무망치를 얻는다.\r\n\r\n2. 이 신성한 망치를 진타알로라는 트롤 도시 꼭대기에 있는 제단으로 가지고 간다.\r\n\r\n3. 제단에서 신성한 나무망치를 사용하면 마력이 부여되면서 줄파락의 나무망치로 변한다."'),
(1131, '"일급 기밀 3중 암호화 데이터 카드\r\n\r\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111"'),
(1151, '투자개발회사 <읽을 수 없는 글씨> 혼합물을 안정시키려다 그 바보들이 작업 전체를 거의 날려 버릴 뻔한 모양이다.\n\n<여러 장의 페이지가 뜯겨 나간 흔적이 보인다>\n\n'),
(1152, '내가 알아낸 바로는 그 낙진이 엄청나게 치명적이다. 만약 <읽을 수 없는 글씨>라면 어떨지 상상해 봐! 하하하!'),
(1153, '내가 미쳐가는 걸까? 오늘 나는 가장 신뢰하는 순찰대원 중 한 명의 목을 베어 영혼을 들여다보려 했다. 잘린 숨구멍을 들여다보니 문득 깨달았다. 내가 며칠 동안 아무것도 먹지 못했다는 사실을!'),
(1154, '마티아스 쇼가 심부름꾼을 보내 날 죽이려고 했어.\n\n지금 그 <illegible text>녀석이 밖에서 순찰을 돌고 있어. 생각 없고 생명력 없는 꼭두각시 같으니.\n\n하하하!'),
(1155, '밴클리프..<illegible text>.\n\n날 불렀다고?? 자기가 누군데?? 난 클레이븐 모트웨이크다! 벌레 같은 놈한테 명령받을 순 없어!\n\n<the rest of the pages in the book are missing>'),
(1156, '커글 씨, $B$B당신의 최신 발명품을 애타게 기다리고 있었습니다. 제 연구 과정을 기록하는 데 어서 사용해 보고 싶습니다.$B$B제 전령에게 전달해 주십시오.$B$B$B진심으로 감사드립니다.$B$B다린 라이트윈드'),
(1191, '"일급 데이터! 보안 등급 5122!\r\n\r\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101"'),
(1192, '"절대 이 정보가 적의 손에 들어가는 일이 없도록 하십시오!\r\n\r\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010"'),
(1193, '"보안 등급 10^10000 일급 기밀 데이터!\r\n\r\n01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001"'),
(1194, '"이 정보의 보안 등급이 매우 높아 이를 표현하기 위한 새로운 숫자 개발을 보류 중입니다!\r\n"'),
(1211, '"땅다람쥐 수색\r\n\r\n땅다람쥐는 구석지고 어두운 곳을 좋아하며 낯을 매우 가리는 편입니다.\r\n\r\n땅다람쥐에게 수색을 시키려면 땅다람쥐가 집처럼 편안하게 생각할 수 있는 곳을 찾아야 합니다. 그리고 반드시 땅다람쥐가 가장 좋아하는 음식인 청엽수 줄기가 있는 곳으로 데리고 가야 합니다.\r\n\r\n이러한 장소 중 가장 가까운 곳은 가시덩굴 우리입니다. 그곳에서 구멍 난 상자를 열면 땅다람쥐가 근처에 있는 청엽수 줄기의 냄새를 맡고 상자 밖으로 나와 당신을 따를 것입니다."'),
(1212, '"땅다람쥐 지휘봉\r\n\r\n땅다람쥐는 놀라운 동물입니다. 성질이 아주 고약한 초원타조에게서도 사랑과 보살핌을 받을 수 있을 뿐만 아니라, 최대 50미터 정도 떨어진 곳에 묻혀 있는 청엽수 줄기의 냄새를 맡을 수도 있습니다!\r\n\r\n땅다람쥐를 시켜 청엽수 줄기를 찾으려면 별도 판매되는 저희 회사의 특허 제품인 땅다람쥐 지휘봉을 사용하시기 바랍니다.\r\n\r\n사용법은 다음 장에 이어집니다."'),
(1213, '"고도의 훈련을 받은 땅다람쥐는 지휘봉을 흔들기만 해도 수색 태세를 취할 것입니다. 이때 청엽수 줄기의 냄새를 맡기 시작하며, 발견 즉시 달려가서 땅을 파기 시작합니다.\r\n\r\n만약 땅다람쥐가 청엽수 줄기를 찾는 동안 지휘봉을 다시 흔들면 땅다람쥐는 수색을 즉시 중단하고 주인의 곁으로 돌아옵니다.\r\n\r\n땅다람쥐는 손에 쥐었을 때 아주 부드러울 뿐 아니라 훈련이 잘되어 있고, 쓸모가 많기 때문에 여러분의 파티에 큰 도움이 될 것이라 자부합니다!"'),
(1214, '"저희 코담배 회사에서는 일부 욕심 많은 청엽수 줄기 채집꾼들이 우리의 사랑스러운 땅다람쥐들을 어둡고 위험한 곳으로 보내 노역을 시켰다는 보고를 받았습니다. 무척 가슴 아픈 사실이 아닐 수 없습니다.\r\n\r\n저희는 그러한 무책임한 행동을 묵과하지는 않을 것입니다. 그러나 고객 만족 정책의 하나로 저희가 판매하는 모든 땅다람쥐에는 품질보증서를 붙여서 땅다람쥐가 죽는 불상사가 발생해도 고객은 돌아가서 땅다람쥐를 새로 얻을 수 있습니다.\r\n\r\n그럼, 즐거운 채집되십시오!"'),
(1231, '이 증서는 이 불타는 협곡의 재앙,$n 마골 더 레이저를 처치했음을 증명합니다.$B$B아이언포지 박물관은 이 업적을 인정하며, 증서 소지자의 아낌없는 공헌에 감사드립니다. -$B$B수석 큐레이터 토리우스 스톤텐더'),
(1251, '지난 몇 달 동안 곰곰이 생각하고, 오래된 믿음과 편견을 떨쳐낼 시간이 생겼습니다. 얼라이언스? 호드? 선? 악? 한때 너무나 명확했던 이 단어들의 의미는 이제 끝없이 펼쳐진 바다를 바라보며 흐릿해집니다. 이제 무엇이$B$B중요한지 압니다. 바나나들이 저를 쫓고 있습니다. 나무$B$B꼭대기에 앉아 차가운 악의로 저를 노려봅니다. 마지막으로 먹으려 했던 바나나는 거의 토할 뻔했습니다! 반쯤 베어 무는 바나나를 바위에 내리쳐 부수자 비명 소리가 들리는 듯했습니다. 전쟁입니다.$B$B그리고 저는 승리할 것입니다.'),
(1270, '저희 스너프 주식회사는 일부 욕심 많은 땅다람쥐 사냥꾼들이 사랑스러운 애완동물의 안전을 전혀 고려하지 않고 어둡고 위험한 구석진 곳으로 내몰아 땅다람쥐를 사냥하게 한다는 보고를 받아 유감스럽게 생각합니다. 저희는 이러한 무책임한 행동을 결코 용납하지 않지만, 고객 만족을 위해 판매하는 모든 땅다람쥐에 보증을 제공하여 새 주인이 구매처로 돌아와 잃어버린 애완동물을 교체받을 수 있도록 하고 있습니다. 즐거운 사냥 되세요!'),
(1271, '기계공학 학문$B$B아제로스에서 누가 기계공학이란 학문을 먼저 만들어 낸 것인지는 분명치 않으나, 현대에 와서는 기계공학 학문에 있어서 노움과 고블린이 가장 유력한 제창자인 것에 반론의 여지가 없다. 기계공학에 대한 그들 종족 전체의 헌신은 가히 발명의 시대라고 칭할 만한 이 시대에 매우 훌륭한 발명품을 만들어 내도록 했을 뿐만 아니라 종족 간의 치열한 경쟁도 빚어내었다. 이러한 경쟁은 분기된 기계공학 분야에서 가장 두드러진다.'),
(1272, '노움 기계공학$B$B노움은 전체적으로 주변의 세계를 조작 및 제어하는 장치의 설계에서 탁월한 기술을 선보인다. 폭발물과 무기의 개념에 대한 이해는 피상적인 수준에 그치고 있지만, 대신 노움 기계공학은 말 그대로 삶을 보다 편리하고 쉽게 만드는 장치에 중점을 두고 있다. 이 학문은 이론적인 가능성이 노움의 전문적 지식을 통해 현실화되는 것을 다루는 것이다. 그러나 일부 가능성은 결코 완전하게 현실화되지 못한다.'),
(1273, '고블린 기계공학$B$B스스로 거의 모든 분쟁에서 중립적이라고 생각하는 고블린 종족은 과학을 이익으로 전환하기 위해 아주 대단한 조치를 취했다. 기계공학의 실질적인 응용 노선을 채택한 이들의 관점은 폭발물, 화기, 기계 장치 등의 급진적인 설계에서 분명하게 드러난다. 고블린 기계공학은 기계공학의 이론을 크게 중요시하지 않는다. 일반적으로, 그들의 발명품이 제대로 작동하지 않는 일은 없고 오히려 작동을 너무 잘해서 문제가 된다. 심장이 약한 사람은 절대 손을 대서는 안 될 학문이다.'),
(1274, '불과 학문 연구$B$B노움과 고블린은 서로에게 자신들의 지식을 공개하지 않기 때문에 두 가지 학문을 동시에 배우는 것은 불가능하다. 각 종족은 정치적 소속에 상관없이 상대 종족의 학문 추구를 포기하는 것에 동의하는 자들에게만 자신들의 학문을 가르친다. 예를 들어, 어떤 학생이 노움 기계공학을 추구하기로 결정하면 이 학생은 고블린 기계공학을 배울 수 없게 된다.'),
(1275, '영구적 결정$B$B두 가지 기계공학 분야에 대해 앞에서 지적한 중요한 사항은 교육을 위해 다시 한번 짚고 넘어가야 한다. 이 두 학문 중 하나를 선택하는 것은 다른 학문을 결코 공부할 수 없게 되는 것을 뜻하며, 이러한 최종성은 비전문 기술자의 기를 꺾을지도 모르나 노련한 기술자는 노움과 고블린이 자신들의 비밀을 철저하게 보호하는 것을 이해하게 된다. 아무것도 배우지 않는 것보다는 일부라도 배우는 것이 낫다. '),
(1276, '인용문$B$B"고블린 기계공학에 대해서 알고 싶은가? 고블린 기계공학의 일인자 중 하나인 \'누비 스텀핑거즈\'에게 물어 보라. 왜 그런 이름이 붙었는지 궁금한가? 그것이 바로 고블린 기계공학이다."$B--노움 기술자, 링고 트래지딕션$B$B"우리 고블린들에 대해 뭐라고 말하든 상관없다. 단, 한 가지만 분명히 말해 주겠다. 우리는 폭탄을 지니고 있다고!"$--고블린 포병, 야즈 니트로스포크'),
(1277, '추가 인용문!$B$B"무언가를 다 만든 다음 처음으로 작동시켜 자신이 만든 장치가 작동하기 시작하는 걸 바라보며 발명의 힘과 기쁨을 느낄 때의 기분을 아는가? 노움들은 그런 기분을 절대 알지 못한다."$B--기술자 조합장, 닉스 스프로켓스프링$B$B"기계공학이란 환상을 환상적으로 만들어 내는 것이다!"$B--노움 발명가, 로비스 맥크랭큰스팽크'),
(1291, '야수 소환:지옥사냥개$B$B추적자를 소환하려면 제공된 지옥 구슬를 사용해야 합니다.$B$B참고:$B$B소환된 지옥사냥개 추적자는 이 세계에 30분 동안만 존재합니다.소환된$B$B지옥사냥개 추적자는 아즈샤라이트 진형을 찾는 데만 도움을 줍니다.소환된$B$B지옥사냥개 추적자는 다음을 하지 않습니다: 속임수, 공격, 도움, 춤, 마법 생물 파괴.다음 페이지로$B$B넘어가세요...'),
(1292, '야수 조종하기:지옥사냥개$B$B추적자는 야수의 포효에만 반응합니다. 지옥사냥개 추적자가 아즈샤라이트 진형을 추적하게 하려면, 힘차게 포효해야 합니다! (지옥사냥개 추적자를 대상으로 지정하고$B$B/roar 명령어를 입력하세요.)지옥사냥개 추적자는 진형을 발견하면 주변의 존재들을 거의 신경 쓰지 않고 진형으로 질주합니다. 지옥사냥개를 보호할 필요는 없지만, 잃어버리지 않도록 가까이 머무르는 것이 좋습니다.'),
(1293, '야수의 처치:30분 후,$B$B야수는 뒤틀린 황천에 있는 자신의 거처로 돌아갑니다.참고:$B$B야수는$B$B흥분 상태에서 절벽이나 산에서 떨어질 수 있습니다. 지옥사냥개 추적자의 죽음을 슬퍼하지 말고, 대신 다른 지옥사냥개를 소환하세요.'),
(1311, '"쪽지를 주은 자에게\r\n\r\n이 쪽지를 읽고 있다면 당신은 다음 두 장소 중 하나에 있는 것이다.\r\n\r\n1. 아즈샤라의 남부 반도.\r\n\r\n2. 절벽거인의 뱃속\r\n\r\n둘 다 편히 쉴만한 곳은 못 된다.\r\n\r\n나도 한때 남부 반도에도 있어 보았고 지금은 뱃속에 앉아 이 쪽지를 쓰고 있다."'),
(1312, '"거인의 뱃속에 있으면 생각할 시간이 생기게 된다.\r\n\r\n내 몸이 결정화되어 가면서 나도 어쩌면 아직도 이 세상에 많은 영웅 중 하나가 나를 구할 수 있을지도 모른다는 희망을 품게 되었다. 내 어떻게든 이 곤경을 벗어나게 되면 그 유령 같은 오크 녀석의 목을 졸라 버리고 싶다!\r\n\r\n- 윈던 셰이"'),
(1313, '"내가 지금 무슨 생각을 하고 있는 것일까?\r\n\r\n좀 더 나은 질문이 되려면 이렇게 물어야 할 것이다. 거인의 뱃속에 들어앉아서 쪽지나 쓰고 있다니 이게 무슨 짓일까?\r\n\r\n둘 다 내가 지금 당장 답할 수 없는 질문들이다...\r\n\r\n사실, 내가 여기로 오게 된 이유 자체부터 어리석었다. 아즈샤라 남부에서만 나는 수정, 아즈샤리트를 찾아 온 것이다. 아, 그것만 손에 넣었다면 엄청난 부자가 되었을 것을!\r\n\r\n나, 참! 지금 내 꼴을 보라고..."'),
(1314, '"이성적인 존재가 이 쪽지를 발견한다면 스스로에게 질문을 던져 봐야 할 것이다. ""키가 10미터나 되는 난폭한 거인들이 마구 돌아다니는 곳에서 대체 지금 뭘 하고 있는 거지?""라고.\r\n\r\n- 무크"'),
(1392, '"닐스 수사님,\r\n\r\n제 포도는 무사합니다! 이 포도 수확 목록을 지니고 있는 $n씨가 용감하게도 악당들이 득실거리는 제 포도밭에 들어가 제가 가져오지 못한 포도를 가져와주었답니다. 강 건너편에서는 아직도 데피아즈단이 어슬렁거리고 있지만 제 포도는 거의 다 구했습니다. 수사님의 저장고에 포도를 한 부대 더 두셔도 좋습니다.\r\n\r\n성스러운 빛의 가호가 함께 하길.\r\n\r\n-밀리 오스워드 올림"'),
(1431, '베테크 스톰브로$B$B베테크는 정처 없이 헤매다 검은바위 산의 깊은 곳에 이르게 된다. 산의 비밀이 그를 부르고 있다.$B$B그의 영혼이 흔들리지 않기를.'),
(1432, '베테크 스톰브로$B$B베테크는 정처 없이 헤매다 검은바위 산의 깊은 곳에 이르게 된다. 산의 비밀이 그를 부르고 있다.$B$B그의 영혼이 흔들리지 않기를.'),
(1433, '"우그젤 해머핸드\r\n\r\n우그젤은 솜씨 좋고 진지한 조각가로, 암흑의 열쇠라는 짐을 지고 있지 않을 때에는 그의 손에서 장인의 전당에 있는 걸작들이 만들어진다."'),
(1434, '짐렐 다크투스어둠의$B$B열쇠가 짐렐을 사로잡을 때, 죽어가는 자들의 비명만이 그를 달랠 수 있다.그의 희생을 위해,$B$B그는 언제나 경기장 위 벤치에 앉게 될 것이다. 우리의 잔혹한 스포츠가 그의 마음속 분노를 누그러뜨리기를.'),
(1435, '"오프구트 스톤피스트\r\n\r\n암흑의 문지기 오프구트의 망치 아래 쓰러진 자들의 수는 헤아릴 수 없을 정도다.\r\n\r\n서부 주둔지 병사들은 그가 지날 때 허리 굽혀 인사하며 경의를 표한다. 오프구트의 눈 속에서 암흑의 열쇠가 속삭이는 비밀을 볼 수 있는 자가 그 중 누구란 말인가?"'),
(1436, '"펠베르 딥스톰프\r\n\r\n암흑의 문지기 펠베르는 가장 영광된 제자이다. 그 누구보다도 암흑의 열쇠를 오래 지니고 있었으며 그로 인해 엄청난 대가를 치렀다. 그가 암흑의 열쇠를 위해 부름을 받으면 거주지에서 그는 보호를 받는다.\r\n\r\n암흑이 그를 지배하게 되더라도... 그의 희생은 언제까지나 우리의 마음 속에 소중하게 기억될 것이다."'),
(1471, '"솔로몬,$B$B이 명령서를 지닌 자는 스톰윈드의 부관 대리로 공식 임명되었노라. 그러니 이 자를 보내 검은용군단이 검은바위부족 오크와 연루되어 있다는 증거를 찾도록 하라. 증거를 찾거든 이 부관이 스톰윈드에 있는 내게 그 증거를 보낼 것이다. 그 증거를 받으면 레이크샤이어에 지원 병력을 투입하는 명령을 허가하겠노라.$B$B대영주 볼바르 폴드라곤"'),
(1491, '<HTML>\n<BODY>\n<H1 align="center">\n수정탑 사용자 설명서\n</H1>\n<BR/>\n<P align="center">\n"운고로 분화구의 수정 동력 수집 및 사용 안내"\n</P>\n<BR/>\n<BR/>\n<P align="left">\n제1장: 북쪽 수정탑\n</P>\n<BR/>\n<P align="left">\n제2장: 동쪽 수정탑\n</P>\n<BR/>\n<P align="left">\n제3장: 서쪽 수정탑\n</P>\n<BR/>\n</BODY>\n</HTML>'),
(1510, '<HTML>\n<BODY>\n<H1 align="center">\n수정탑 사용자 설명서\n</H1>\n<BR/>\n<P align="center">\n"운고로 분화구의 수정 동력 수집 및 사용 안내"\n</P>\n<BR/>\n<BR/>\n<P align="left">\n제1장: 북쪽 수정탑\n</P>\n<BR/>\n<P align="left">\n제2장: 동쪽 수정탑\n</P>\n<BR/>\n<P align="left">\n제3장: 서쪽 수정탑\n</P>\n<BR/>\n</BODY>\n</HTML>'),
(1511, '<HTML>\n<BODY>\n<H1 align="center">\n제1장: 북쪽 수정탑\n</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_mini_north" align="left"/>\n<P align="right">\n북쪽\n<BR/>\n수정탑 사용 가능:\n<BR/>\n노란색, 빨간색,\n<BR/>\n초록색\n<BR/>\n수정\n</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="left">\n더 수정탑은 노란색 수정을 주요 에너지원으로 사용하여 생성할 수 있는 에너지에 초점을 맞추고 있습니다.\n</P>\n</BODY>\n</HTML>'),
(1512, '<HTML>\n<BODY>\n<H1 align="center">\n북쪽 수정 조합\n</H1>\n<BR/>\n<P align="left">\n가능한 효과는 두 가지입니다. 하나는 피해를 발생시키는 것이고, 다른 하나는 피해를 무효화하는 것입니다.\n</P>\n<BR/>\n<P align="left">\n수정 충전: 빨간색과 노란색 수정이 필요합니다.\n<BR/>\n이것은 큰 폭발을 일으킬 것입니다.\n</P>\n<BR/>\n<P align="left">\n수정 복원: 노란색과 녹색 수정이 필요합니다.\n<BR/>\n이것은 당신에게 치유의 기운을 제공할 것입니다.\n</P>\n</BODY>\n</HTML>'),
(1513, '<HTML>\n<BODY>\n<H1 align="center">\n북쪽 수정탑 도표\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_north"/>\n</BODY>\n</HTML>')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(1514, '<HTML>\n<BODY>\n<H1 align="center">\n제2장: 동쪽 수정탑\n</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_mini_east" align="left"/>\n<P align="right">\n동쪽\n<BR/>\n수정탑 사용 가능:\n<BR/>\n파란색, 노란색,\n<BR/>\n초록색\n<BR/>\n수정\n</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="left">\n더 수정탑은 청색 수정을 주요 에너지원으로 사용하여 생성할 수 있는 에너지에 초점을 맞추고 있습니다.\n</P>\n</BODY>\n</HTML>'),
(1515, '<HTML>\n<BODY>\n<H1 align="center">\n동쪽 수정 조합\n</H1>\n<BR/>\n<P align="left">\n가능한 효과는 두 가지입니다. 하나는 정신력에 보너스를 제공하는 것이고, 다른 하나는 피해를 주는 보호막을 생성하는 것입니다.\n</P>\n<BR/>\n<P align="left">\n수정 포스: 파란색과 녹색 수정이 필요합니다.\n<BR/>\n이것은 당신의 정신력을 증진시켜 줄 것입니다.\n</P>\n<BR/>\n<P align="left">\n수정 스파이어: 파란색과 노란색 수정이 필요합니다.\n<BR/>\n이렇게 하면 공격자에게 피해를 주는 보호막이 생성됩니다.\n</P>\n</BODY>\n</HTML>'),
(1516, '<HTML>\n<BODY>\n<H1 align="center">\n동쪽 수정탑 도표\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_east"/>\n</BODY>\n</HTML>'),
(1530, '<HTML>\n<BODY>\n<H1 align="center">\n동쪽 수정탑 도표\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_east"/>\n</BODY>\n</HTML>'),
(1531, '<HTML>\n<BODY>\n<H1 align="center">\n제3장: 서쪽 수정탑\n</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_mini_west" align="left"/>\n<P align="right">\n서쪽\n<BR/>\n수정탑 사용 가능:\n<BR/>\n빨간색, 초록색,\n<BR/>\n파란색\n<BR/>\n수정\n</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="left">\n더 수정탑은 붉은색 수정을 주요 에너지원으로 사용하여 생성할 수 있는 에너지에 초점을 맞추고 있습니다.\n</P>\n</BODY>\n</HTML>'),
(1532, '<HTML>\n<BODY>\n<H1 align="center">\n서쪽 수정 조합\n</H1>\n<BR/>\n<P align="left">\n두 가지 효과가 있을 수 있습니다. 하나는 피해로부터 자신을 보호하는 능력을 증가시키는 것이고, 다른 하나는 적의 방어력을 약화시키는 것입니다.\n</P>\n<BR/>\n<P align="left">\n수정 워드: 빨간색과 초록색 수정이 필요합니다.\n<BR/>\n이렇게 하면 방어력이 증가합니다.\n</P>\n<BR/>\n<P align="left">\n결정 수율: 파란색과 빨간색 결정이 필요합니다.\n<BR/>\n이는 특정 대상의 방어력을 낮출 수 있습니다.\n</P>\n</BODY>\n</HTML>'),
(1533, '<HTML>\n<BODY>\n<H1 align="center">\n서쪽 수정탑 도표\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\n</BODY>\n</HTML>'),
(1550, '<HTML>\n<BODY>\n<H1 align="center">\n서쪽 수정탑 도표\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\n</BODY>\n</HTML>'),
(1551, '"안녕하세요. 모험가 여러분!\r\n\r\n저, 크린클 굿스틸은 험난한 임무를 수행하기 위해 기꺼이 위험을 무릅쓸 뜻이 있는 분들을 찾고 있습니다. 제가 책임지고 있는 임무와 작업량이 너무 많은 이유로 이 목록에 적힌 물건들을 제게 무사히 가지고 오시는 분에게는 후한 사례를 하겠습니다.\r\n\r\n물건 목록은 다음 페이지에 있습니다..."'),
(1552, '"단단한 수정 다리 마디 -\r\n\r\n믿을 수 없겠지만 불타는 골짜기에 서식하는 유리그물거미는 수정 같은 물질로 이루어져 있습니다. 이 거미들을 처치할 때 다리가 손상되지 않게 해서 가지고 오시면 제 동료들의 기계 공학 실험에 아주 우수한 도체로 사용할 수 있을 겁니다.\r\n\r\n실험해 볼 다리가 좀 필요한데 거미에게는 다리가 8개나 있으니까 강인한 전사나 솜씨 좋은 마법사에게는 문제가 되지 않을 것입니다."'),
(1553, '"부쳐지지 않은 소포 -\r\n\r\n믿을 만하다고 생각한 조종사 하나를 고용해 테라모어에서 소포 하나를 가져오게 했었는데 생각보다 실력이 아주 형편없었습니다. 그 조종사가 살아서 자초지종을 듣긴 했지만 자기 목숨 건지려고 비행선과 화물을 몽땅 버려두고 와버렸지 뭡니까.\r\n\r\n그 소포가 필요합니다. 비질 말로는 그 자가 먼지진흙 습지대 만의 바로 서쪽에 추락했다고 해요. 물가에 있는 언덕을 넘자마자 바로 추락했다더군요.\r\n\r\n음... 그런데 추락한 원인은 말해주지 않았습니다."'),
(1554, '"균형 잡힌 굿스틸의 플랑베르주 -\r\n\r\n마지막으로 찾아야 할 물건은 제가 지금까지 대장장이로 살면서 만든 물건 중 가장 우수한 것입니다. 이 플랑베르주는 믿을 수 없을 만큼 훌륭한 검이었는데, 저는 이 검을 명예롭고 위대한 전사라고 생각된 자에게 주었습니다. 그런데 그만 그 전사가 자르콰이인가 하는 멀록에게 당하고 말았지요.\r\n\r\n그 전사는 슬픔의 늪 해안을 따라가던 중 멀록을 공격했었습니다. 하지만 멀록에게 당한 전사는 도망을 치다 그 검을 버렸고 결국 멀록이 가져가 버렸습니다."'),
(1556, '물건들을 찾거든 이 장부와 함께 가젯잔으로 가지고 와주세요. 그러면 사례를 하겠습니다.'),
(1591, '이 모루는 조던 스틸웰의 소유물입니다. 절대로 사용하지 마십시오!$B$B- 조던'),
(1611, '"<페이지마다 고대 엘프의 룬문자가 가득합니다.>\r\n\r\n본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 경험을 담고 있다.\r\n\r\n부디 이 책이 적들의 손에 들어가지 않기를.\r\n\r\n부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.\r\n\r\n부디 캘타스님의 은총 속에서 숨을 거두기를.\r\n\r\n부디 일리단님의 영광을 위해 살생을 하기를.\r\n\r\n-카리엘 윈탈루스"'),
(1631, '"<페이지마다 고대 엘프의 룬문자가 가득합니다.>\r\n\r\n본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.\r\n\r\n부디 이 책이 적들의 손에 들어가지 않기를.\r\n\r\n부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.\r\n\r\n부디 캘타스님의 은총 속에서 숨을 거두기를.\r\n\r\n부디 일리단님의 영광을 위해 살생도 불사하기를.\r\n\r\n-카리엘 윈탈루스"'),
(1632, '<The pages are covered in ancient elven runes.>\n\n이 책에는 하급 마법약을 제작하는 데 필요한 재료들을 모으고 만들어내는 과정에서 일어난 사건들의 기록이 담겨 있다.\n\n우리의 적들이 이 책에 결코 접근하지 못하게 하소서. \n\n쿠엘탈라스에 다시 한번 창백한 달빛이 비치는 것을 볼 수 있게 하소서.\n\n켈타스의 은총이 아니었다면 죽음을 맞이했을 것입니다.\n\n일리단의 영광을 위해 적을 처치할 수 있게 하소서.\n\n-카리엘 윈탈루스 님'),
(1633, '"<페이지마다 고대 엘프의 룬문자가 가득합니다.>\r\n\r\n본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.\r\n\r\n부디 이 책이 적들의 손에 들어가지 않기를.\r\n\r\n부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.\r\n\r\n부디 캘타스님의 은총 속에서 숨을 거두기를.\r\n\r\n부디 일리단님의 영광을 위해 살생도 불사하기를.\r\n\r\n-카리엘 윈탈루스"'),
(1634, '<The pages are covered in ancient elven runes.>$B$B이 책에는 하급 마법약을 제작하는 데 필요한 재료들을 모으고 만들어내는 과정에서 일어난 사건들의 기록이 담겨 있다.$B$B우리의 적들이 이 책에 결코 접근하지 못하게 하소서. $B$B쿠엘탈라스에 다시 한번 창백한 달빛이 비치는 것을 볼 수 있게 하소서.$B$B켈타스의 은총이 아니었다면 저는 죽었을 것입니다.$B$B일리단의 영광을 위해 저는 적을 처치할 것입니다.$B$B-카리엘 윈탈루스 님'),
(1691, '안녕, 펠녹!$B$B불타는 초원에서의 내 연구는 아주 순조롭게 진행되고 있어. 그리고 $N의 도움 덕분에 $ghis:her;정말 큰 은혜를 입었지! 연구를 계속하려면 다음 재료들이 필요해:$B$B스틸코일 범퍼비첼$B17게이지 아이스 스패너$B오리 깃털 12파운드$B네가 만든 접착제 한 병$B$B정말 고마워, 펠녹. 다음에 또 만나면 네 부츠에 석탄을 넣지 말라고 꼭 말해줘!$B$B-팅키'),
(1711, '"절벽파수꾼 롱혼에게 보내는 긴급 전갈$B$B에톡 야영지의 켄타우로스 군대가 대규모로 공격하여 보급품 짐마차 중 한 대를 습격. 짐마차에 타고 있던 자들과 보급품 실종 및 분실. 지금까지의 켄타우로스 공격과는 달리 매우 과감한 공격으로, 앞으로 추가 공격이 우려됨."'),
(1731, '"로데론 최후의 진정한 국왕 테레나스 메네실 2세, 여기 잠들다.\r\n\r\n그의 업적은 위대했고, 그의 통치는 오랜 세월 이어졌으나, 그의 죽음은 상상도 하지 못한 것이로다.\r\n\r\n         ""부디 그 아버지가 아들의 행동으로 비난받지 않기를.\r\n         부디 그 피 묻은 왕관이 영원히 돌아오지 않고 잊혀지기를."""'),
(1751, '그림 바톨 전투가 끝난 직후 저습지에서는 거대한 붉은 용의 시체가 발견되었다. 티란니스트라즈는 용의 여왕인 알렉스트라자의 손위 배우자였다고 한다.'),
(1752, '이 굳어버린 발톱은 가시덤불 골짜기의 남쪽 해안에서 발견되었다. 생태학자들은 이 발톱이 고대의 태양 로크의 것이라고 추정하고 있다. 이 생물은 타우렌의 고대 신화에 자주 등장하나 발톱의 발견은 그 생물이 실제로 존재했었다는 것을 증명한다.'),
(1753, '초원타조 중 가장 덩치가 큰 게루 타조는 그 수가 워낙 적어 눈에 띄는 일이 매우 드물다.'),
(1754, '이 조형물은 이갈이산양의 골격을 복제한 것이다. 이 전설의 산양은 카즈 모단의 불가사의기도 하지만 드워프 민속담에서 주인공으로 자주 등장한다. 오늘날까지도 생태학자들은 이 산양의 비정상적인 크기나 체력을 설명하지 못하고 있다.'),
(1755, '운고로 분화구의 외딴 우림에서 발견한 이 알에는 한때 데빌사우루스의 태아가 들어있었다. 상대를 약화시키는 효력을 지닌 데빌사우루스 독의 해독제를 만드는 데 그 어느 때보다 열중하고 있던 생태학자 연맹에게 이 태아의 유전적 형질은 아주 값진 자료가 되었다.'),
(1756, '"이 프테라돈 뼈는 운고로 분화구 외딴곳에서 회수한 것으로, 골격 구조가 온전한 걸 보아 아무도 이 뼈를 발견하지 못했던 게 분명하다. 이 뼈는 발견되지 않았더라도 운고로 분화구의 비옥한 토양 아래 몇 세기든 온전하게 보존될 수 있었을 것이다."'),
(1757, '"수사마르의 해저 유적에서 찾은 이 아스트롤라베는 거의 2만년 전 귀족의 나이트 엘프들이 제작한 것으로 아직도 작동이 가능하다. 마법, 비술, 천문학에 유난히 집착이 강했던 명가의 엘프들은 갖가지 훌륭한 도구들을 개발했다. 이 장치는 고대 나이트 엘프들의 과학적 수준을 엿볼 수 있는 아주 중요한 물건이다."'),
(1758, '이 고대 토석인 도구들은 울다만 발굴현장에서 회수한 것들이다. 암시적인 룬문자나 상형문자는 거의 없지만 고대 드워프 종족의 장인 정신과 일상적인 도구에 대해서는 알 수 있다.'),
(1759, '이 글이 새겨진 유물은 아마도 울다만의 첫 번째 방 안에서 발견한 것들 중 가장 중요한 물건일 것이다. 새겨진 글에 의하면 골렘과 유사한 토석인과 드워프 종족간의 관계를 암시하고 있다. 더 많은 증거가 확보되면 전설의 티탄이 창조했다는 가설이 사실로 확인될 수도 있을 것이다.'),
(1760, '타나리스 사막의 무더운 황야에서 발견한 이 특이한 알은 아직도 현대 생태학자들에게 수수께끼로 남아 있다. 연대를 연구해 본 결과 이 알은 최고 일천 년 전의 것으로 추정된다. 곤충류 조직임을 나타내는 몇 가지 요소가 있기는 하나 실제 근원은 알아내지 못했다. 이러한 알을 낳는 종이 무엇인지 아직 밝혀내지 못했기 때문이다.'),
(1761, '이 2차 대전쟁의 유물을 보면 호드가 아이언포지 산맥을 거의 점령할 뻔했던 기억이 소용돌이 치듯 떠오른다.'),
(1762, '이 악마 판금 갑옷은 처음으로 우리 민족을 피의 욕망에 빠지게 했던 생물이 입었던 것이다. 하지만 한 용감한 오크의 영웅적인 행동으로 인해 그는 쓰러졌다. 파괴자 만노로스는 이제 없다. 항상 이 판금 갑옷을 보면서 우리 민족이 명예를 되찾기 위해 얼마나 먼 길을 걸어왔고 또 얼마나 많은 노력을 했는지 기억해야만 한다.\r\n$B$B-호드 대족장, 스랄'),
(1771, '이 2 차 대전에서 남은 자들은 호드가 아이언 포지 마운틴을 정복하기 위해 얼마나 위험스럽게 닫혔는지에 대한 자극적 인 알림으로 작용합니다.'),
(1772, '웜탈락, 네 주인 네파리안으로부터 직접 명령을 받았다. 만약 외부인이 더 이상 성채 안으로 들어오지 않는다면 내가 적절하다고 판단하는 방식으로 너를 처벌하라는 명령이다. 누가 네게 명령을 내리는지 잊지 마라, 파충류 같은 놈아. 블랙핸드의 아들, 검과 전투의 달인, 진정한 전쟁 지도자가 바로 나다. -렌드'),
(1773, '시간이 흐르면서 뒤틀린 황천의 악마적인 존재들이 티탄의 세계로 침입하기 시작했고 판테온은 최전 방어선의 역할을 할 최고의 전사로 살게라스를 선발했다. 고귀한 청동 거인 살게라스는 이 악마들을 찾아내 처단하며 수천 년 동안 자신의 임무를 수행했다. 오랜 세월이 흘러 살게라스는 물질계를 힘으로 지배하려는 강력한 두 악마 종족을 만나게 되었다.'),
(1774, '사악한 흑마술사 종족인 에레다르는 흑마법을 이용해 수많은 세계를 침략해 노예로 삼았다. 침략당한 세계에 살던 종족들은 에레다르의 사악한 마력으로 인해 악마의 모습으로 변해 버렸다.'),
(1775, '무한에 가까운 살게라스의 힘은 사악한 에레다르를 물리치기에 충분했지만 이들의 타락과 모든 것을 소모시켜버리는 사악함은 살게라스를 매우 힘들게 만들었다. 그러한 타락을 이해할 수 없었던 이 숭고한 티탄은 깊은 생각에 빠지기 시작했다. 하지만 점점 커져 가는 불안에도 불구하고 살게라스는 흑마법사들을 뒤틀린 황천의 구석에 가두어버림으로써 우주에서 흑마법사들을 모두 소탕했다.'),
(1776, '혼란과 불안이 깊어지는 동안 살게라스는 티탄의 질서를 무너뜨리려는 나스레짐이라는 또 다른 무리와 싸워야 했다. (공포의 군주라고도 알려진) 흡혈 악마로 이루어진 이 암흑의 종족은 생명체를 사로잡아 어둠의 길로 이끄는 방법으로 그들이 거주하던 수많은 세계를 정복했다.'),
(1777, '극악무도하고 교활한 공포의 군주는 세상의 모든 종족들에 맹목적인 증오와 불신을 심어 서로에게 등을 돌리게 만들었다. 살게라스는 손쉽게 나스레짐을 물리쳤지만 그들의 타락은 살게라스의 정신 세계에 깊은 영향을 주었다.'),
(1778, '살게라스는 이성을 압도하는 의심과 절망을 감당하지 못하고 자신의 임무에 대한 모든 신념과 티탄이 추구하는 질서 있는 우주에 대한 믿음까지도 잃게 되었다. 결국 살게라스는 질서라는 개념 자체가 의미 없는 것이며 혼돈과 타락이 이 어둡고 외로운 우주에서 절대적인 유일한 것이라고 믿기 시작했다.'),
(1779, '티탄 동료들은 살게라스의 잘못된 생각을 되돌리고 격심한 감정을 달래보려 했지만 살게라스는 그들의 낙관적인 믿음이 이기적인 착각일 뿐이라 생각했다. 그는 마침내 동료들의 대열에서 영원히 벗어나 이 우주에서 자신만의 자리를 찾아 나서게 되었다. 판테온은 살게라스가 떠나는 것을 슬퍼했지만 자신들의 곁을 떠난 형제가 얼마나 심각한 일을 저지르게 될 것인지는 예감하지 못했다.'),
(1780, '한때 용맹스러웠던 영혼의 마지막 자취마저 살게라스의 광기로 인해 모두 사라졌을 때 살게라스는 창조의 실패가 티탄들 스스로의 잘못이라고 믿었다. 우주 전체에서 티탄들이 이루어온 일들을 모두 원상태로 되돌리기로 결정한 그는 천하무적의 군대를 편성해 물질계를 불태우기로 했다.'),
(1781, '"한때 숭고했던 가슴이 타락으로 찌들면서 살게라스가 지닌 티탄의 모습도 변형되기 시작했다. 눈과 머리카락, 수염에서는 불길이 치솟고 청동 피부는 갈라져 끝없이 타오르는 증오를 드러냈다."'),
(1782, '분노로 가득찬 살게라스는 에레다르와 나스레짐이 갇혀 있던 감옥을 부수고 이 사악한 악마들을 풀어 주었다. 이 교활한 짐승들은 어둠의 티탄이 내뿜는 광폭한 분노 앞에 허리를 굽히고 그가 원하는 일이라면 어떠한 수단도 가리지 않고 해내겠다고 맹세했다. 살게라스는 강력한 에레다르의 용사 중 둘을 골라 파괴의 악마 군단을 이끌도록 했다.'),
(1783, '"그 중 하나인 책략가 킬제덴은 우주에서 가장 사악한 종족들을 찾아내 살게라스의 수하로 데려오는 일을 맡았고, 다른 하나인 파멸자 아키몬드는 살게라스의 강대한 군대를 이끌고 어둠의 티탄에게 거역하는 자들을 가차없이 처단하는 임무를 맡았다."'),
(1784, '킬제덴이 한 첫 번째 일은 자신의 무시무시한 무력 아래 공포의 군주들을 굴복시키는 것이었다. 공포의 군주들은 우주 전체에서 살게라스의 대리인으로 활동하면서 노예로 삼을 원시 종족들을 찾아내 자신들의 종족으로 만드는 일에 큰 기쁨을 느꼈다. 그러한 공포의 군주 중 부패자 티콘드리우스가 으뜸이었다. 티콘드리우스는 완벽한 병사로 킬제덴을 섬기며 살게라스의 불타는 의지를 우주 구석구석에 퍼뜨리는 데 동의했다.'),
(1785, '강대한 아키몬드 역시 자신의 대리인을 내세웠다. 아키몬드는 지옥의 군주들과 그들의 야만적인 우두머리인 파괴자 만노로스를 불러내 모든 피조물을 소탕할 정예 군단을 만들고자 했다.'),
(1786, '살게라스는 군대가 편성되고 자신의 모든 명령에 복종할 준비가 된 것을 보고 그 포악한 군대를 끝없는 어둠으로 보냈다. 그는 점점 커져 가는 자신의 군단을 불타는 군단이라 불렀다. 이 사악한 불타는 전사들이 우주 곳곳을 돌아다니면서 오늘날까지도 얼마나 많은 세계를 침략하고 불태워 버렸는지는 정확히 알 수 없다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(1787, '"피조물을 다시 무로 돌리려는 살게라스의 사명을 알지 못한 채, 티탄들은 계속해서 이 세계에서 저 세계로 옮겨가며 자신들이 적합하다고 생각하는 대로 세계를 꾸미고 질서를 세워 갔다. 후에 거주자들이 아제로스라고 부르게 되는 작은 세계에 도달하게 된 티탄들은"'),
(1788, '"이 세계의 혼돈스럽고 원시적인 땅을 지나다가 몇몇 사나운 정령들을 만나게 되었다. 고대 신들이라고만 알려진, 알 수 없는 악의 존재들을 섬기는 이 정령들은 티탄들을 몰아내고 이 침입자들의 철의 손길로부터 자신들의 세계를 지킬 것을 맹세했다."'),
(1789, '"악행을 취미로 삼는 고대 신들을 염려한 판테온은 정령들과 그들의 사악한 지배자에 맞서 전쟁을 치렀다. 고대 신들의 군대는 가장 뛰어난 정령 부관들이라고 할 수 있는 불의 군주 라그나로스, 돌의 어머니 테라제인, 바람의 군주 알아키르, 바다의 사냥꾼 넵튤론이 이끌었다."'),
(1790, '이 혼돈의 군단은 아제로스를 휩쓸고 다니며 거대한 티탄과 충돌했다. 정령들은 평범한 생명체에 비하면 상상을 초월하는 힘을 지니고 있었지만 그들의 군대의 힘을 모두 합쳐도 강대한 티탄을 저지할 수는 없었다. 정령의 지도자들은 하나씩 쓰러지고 결국 군대는 와해되어 버렸다.'),
(1791, '판테온은 고대 신들의 보루를 쳐부수고 다섯 명의 사악한 고대 신들을 세계의 지하 깊은 곳에 속박해 두었다. 정령들은 자신들의 사나운 영혼을 물질계와 결속시켜주던 고대 신들의 힘이 없어지자 이계로 추방되어 그곳에서 영원히 서로 싸우게 되었다. 정령들이 사라지자 자연은 고요해졌고 세계는 평화로운 조화를 이루게 되었다. 티탄은 위협적인 존재들이 제압된 것을 보고 일을 시작했다.'),
(1792, '"티탄은 세계를 가꾸는 일을 도울 종족을 창조했다. 땅 아래 끝없이 깊은 동굴을 파내기 위해 생명이 깃든 마법의 돌로 난쟁이처럼 생긴 토석인을 창조했고, 바다를 고르고 해양 바닥에서 땅을 들어올리기 위해 거대하지만 온순한 바다 거인을 창조했다. 오랜 세월 동안 티탄은 열심히 땅을 가꾸었고 마침내 하나의 완벽한 대륙만이 남게 되었다."'),
(1793, '"티탄은 이 대륙의 중심에 반짝이는 에너지가 깃든 호수를 만들어 영원의 샘이라 불렀고 이 세계의 생명의 원천으로 삼았다. 이 호수의 강렬한 에너지는 세계의 뼈대에 영양분을 공급했으며 생명체를 창조해 이 세계의 비옥한 땅에 정착하도록 했다. 시간이 흘러 각종 식물과 나무, 괴물, 생명체들이 이 원시 대륙에서 번성하기 시작했다."'),
(1794, '"일을 끝낸 마지막 날 해질 무렵, 티탄들은 이 대륙에 `영원한 별빛의 땅`이란 뜻의 칼림도어라는 이름을 지어 주었다."'),
(1795, '작은 세계에 질서가 찾아오고 자신들의 일이 끝이 났다는 사실에 만족한 티탄은 아제로스를 떠날 준비를 했다. 하지만 떠나기 전 새로 태어난 종족 중 가장 훌륭한 종족을 골라 이 완벽한 고요를 깨뜨리려는 세력으로부터 칼림도어를 보호하도록 했다. 이 시대에는 여러 용군단이 있었다.'),
(1796, '그 중에서도 다섯 용군단이 각자의 동족들을 지배하고 있었다. 티탄은 이 다섯 용군단에게 새로 태어나는 세계를 보호하는 임무를 맡기기로 했다. 판테온의 가장 위대한 지도자는 자신이 가진 힘의 일부를 용군단의 지도자에게 각각 나누어 주었다. 이 다섯 용 지도자는 5대 위상 또는 용의 위상이라 불리게 되었다.'),
(1797, '판테온의 대부인 아만툴은 자신이 가진 무한한 힘의 일부를 거대한 청동용인 노즈도르무에게 주었다. 아만툴은 노즈도르무에게 시간 자체를 지배할 권한을 주어 끊임 없이 돌고 도는 운명의 길들을 지키도록 했다. 그리하여 냉철하면서도 위엄 있는 노즈도르무는 시간의 지배자로 알려지게 되었다.'),
(1798, '"모든 생명의 수호자인 티탄, 이오나는 자신이 가진 힘의 일부를 거대한 붉은용인 알렉스트라자에게 주었다. 그 후 알렉스트라자는 생명의 어머니로 불리며 아제로스 세계의 모든 생명체를 보호하는 데 힘썼다. 알렉스트라자는 탁월한 지혜와 모든 생명체에 대한 끝없는 연민으로 용의 여왕이 되어 붉은용혈족을 다스리게 되었다."'),
(1799, '이오나는 알렉스트라자의 여동생인 녹색용 이세라에게도 자연의 신비한 힘을 주었다. 이세라는 창조의 꿈에 결속되어 영원한 무아지경에 빠져들었다. 꿈의 여왕이라 불린 이세라는 자신의 초록빛 왕국인 에메랄드의 꿈 속에서 세계의 자라나는 야생 생물들을 지켜보았다.'),
(1800, '티탄의 현자이자 대마법사인 노르간논은 자신의 광대한 힘의 일부를 푸른용 말리고스에게 주었다. 그때부터 말리고스는 마법과 숨겨진 비밀의 수호자인 마법의 지배자로 불리게 되었다.'),
(1801, '"만물을 빚어내고 창조한 조물주 티탄중 하나인 카즈고로스는 자신의 광활한 힘의 일부를 강대한 검은용 넬타리온에게 주었다. 후에 대지의 수호자로 불린 넓은 마음의 소유자, 넬타리온은 세계의 대지와 지하 세계를 지배하게 되었다. 세계의 힘을 부여 받은 넬타리온은 알렉스트라자의 가장 든든한 힘이 돼 주었다."'),
(1802, '이렇게 힘을 부여 받은 5대 위상은 티탄이 없는 동안 세계를 보호하는 임무를 맡았다. 용들이 자신들이 만들어 놓은 세계를 보호할 준비가 되자 티탄은 영원히 아제로스를 떠났다. 하지만 안타깝게도 티탄이 공들여 가꾼 이 작은 신세계의 존재를 살게라스가 발견하는 것은 시간 문제일 뿐이었다.'),
(1803, '귀족들이 무분별하게 마법을 사용하면서 영원의 샘에서 솟아나오는 힘은 끝없는 어둠 너머로 흘러 들어 갔다. 그런데 이 힘을 끔찍한 외계의 존재들이 느끼게 되었다. 모든 생명체의 적이자 만물의 파괴자인 살게라스는 이 힘을 느끼고 그 근원지를 찾아 먼 길을 나서게 되었다.'),
(1804, '영원의 샘에서 나오는 무한한 힘을 느끼고 그 근원인 아제로스의 세계를 찾아나선 살게라스는 탐욕스러운 욕망에 휩싸였다. 표현할 수 없는 공허의 거대한 어둠의 신은 갓 태어난 이 세계를 파괴하고 그 힘을 차지하기로 마음먹었던 것이다.'),
(1805, '살게라스는 자신의 거대한 불타는 군단을 모아 아무것도 모르고 있는 아제로스의 세계로 진격했다. 일백만의 포악한 악마들로 구성된 불타는 군단은 먼 우주에서 나타나 모든 것을 정복하고자 했다. 살게라스의 심복인 파멸자 아키몬드와 파괴자 만노로스는 지옥의 병사들에게 공격 준비를 명령했다.'),
(1806, '끔찍한 마법의 힘에 빠져 있던 아즈샤라 여왕은 부인할 수 없는 살게라스의 힘 앞에 굴복했고 아제로스로 들어올 수 있도록 해주었다. 귀족들까지도 피할 수 없는 마법의 타락에 굴복하여 살게라스를 자신들의 신으로 숭배하기 시작했다. 귀족들은 불타는 군단에 대한 충성을 보이기 위해 아즈샤라 여왕을 도와 영원의 샘 깊은 곳에서 소용돌이 치고 있는 거대한 문을 열었다.'),
(1807, '준비를 모두 마친 살게라스는 아제로스를 무자비하게 침략하기 시작했다. 불타는 군단의 악마와 같은 전사들은 영원의 샘을 통해 아제로스로 들어와 잠들어 있던 나이트 엘프의 도시에 공격을 가했다. 아키몬드와 만노로스가 이끄는 불타는 군단은 칼림도어의 땅을 휩쓸고 다녔으며 그들이 지나간 자리에는 잿더미와 슬픔만이 남게 되었다.'),
(1808, '"극악무도한 흑마법사들은 칼림도어의 우아한 사원에 마치 지옥의 운석이 떨어지듯 불타는 지옥불정령을 불러냈으며, 피를 뿌리며 다니는 불타는 살인마 집단인 파멸의수호병은 칼림도어의 평원을 지나면서 눈에 보이는 자들을 닥치는 대로 살해했다. 거칠고 흉포한 지옥사냥개 무리조차 도시 주변을 휘젓고 다니며 모든 것을 파괴했다. 칼도레이의 용감한 전사들이 유서 깊은 고향을 지키기 위해 돌격했지만 불타는 군단의 맹공격 앞에서 점차 무릎을 꿇을 수밖에 없었다."'),
(1809, '"이제 위기에 처한 동족을 구해내는 것은 말퓨리온 스톰레이지의 손에 달려 있었다. 마법을 사용하는 귀족인 일리단의 친형, 말퓨리온은 귀족 계급의 부패가 심각해져 가는 데 몹시 화가 나 있었다. 일리단에게 위험한 집착을 버리도록 설득한 말퓨리온은 세나리우스를 찾아 저항 세력을 모으기 위해 길을 나섰다."'),
(1810, '젊고 아름다운 여사제 티란데도 엘룬의 이름으로 두 형제와 동행하기로 했다. 말퓨리온과 일리단은 둘 다 이 이상주의적인 여사제를 비밀리에 사랑하게 되었지만 티란데의 마음은 말퓨리온에게만 가 있었다. 일리단은 형인 말퓨리온과 티란데의 사랑이 싹트는 것을 시기했지만 그 가슴앓이는 마법에 중독되었던 고통에 비하면 아무것도 아닌 것을 알고 있었다.'),
(1811, '한때 마법의 강력한 힘에 의존했던 일리단은 자신을 통제하면서 다시 한번 샘의 힘을 사용하고픈 욕구를 억누르려고 안간힘을 썼다. 티란데의 끈기 있는 도움으로 샘의 힘에 대한 욕구를 극복할 수 있었던 일리단은 형을 도와 세상을 등지고 숨어버린 반신 세나리우스를 찾게 되었다.'),
(1812, '"머나먼 하이잘 산맥의 성스러운 달의 숲에서 살고 있었던 세나리우스는 말퓨리온과 일리단, 티란데가 고대의 용을 찾아 도움을 받을 수 있도록 힘을 써주기로 했다. 그리하여 거대한 붉은용 알렉스트라자가 이끄는 붉은용족은 강대한 용군단을 보내 나이트 엘프의 땅을 침략한 악마와 그 군주에 대항하기로 했다."'),
(1813, '세나리우스는 마법의 숲에 사는 정령들을 불러내 고대 거목인 부대를 모으고 대담한 지상전을 펼치며 불타는 군단에 대항했다. 나이트 엘프의 동맹군이 아즈샤라의 사원과 영원의 샘에 다다를 무렵에는 전면전이 벌어졌다. 하지만 새로운 동맹군과 합세했음에도 불구하고 말퓨리온과 그의 동료들은 군대의 힘만으로는 불타는 군단을 무찌를 수 없다는 것을 깨닫게 되었다.'),
(1814, '"아즈샤라의 수도에서 대접전이 벌어지는 동안, 살게라스의 힘에 현혹된 아즈샤라 여왕은 살게라스가 도착하기만을 기다리고 있었다. 한편 불타는 군단의 군주는 영원의 샘을 지나서 이 파괴의 세계로 들어오려 하고 있었다. 믿을 수 없을 정도로 거대한 살게라스의 그림자가 소용돌이 치는 샘의 표면에 가까워지자 아즈샤라는 귀족 추종자 중 가장 강한 자들을 모았다. 그들의 마법을 연결해 하나의 집중된 주문을 사용해야만 살게라스가 들어올 수 있을 만큼 커다란 문을 만들 수 있었기 때문이었다."'),
(1815, '불타는 칼림도어 평원에서 전쟁이 한창일 때 상황을 뒤엎는 끔찍한 사건이 발생했다. 이 전쟁의 자세한 내막은 시간이 흐르면서 잊혀졌지만 알려진 바에 의하면 대지의 위상인 넬타리온이 불타는 군단과 중대한 접전을 벌이다 이성을 잃었다고 한다. 넬타리온의 검은 가죽에서 화염과 분노가 뿜어져 나오면서 몸이 갈라지기 시작했다. 이 불타는 용은 자신의 이름을 데스윙이라 바꾸고 동족을 공격하며 다섯 용군단을 전장에서 몰아냈다.'),
(1816, '데스윙의 갑작스러운 배반은 워낙 파괴적이어서 다섯 용군단은 결코 완전하게 회복되지 못했다. 상처입고 충격 받은 알렉스트라자와 다른 숭고한 용들은 어쩔 수 없이 죽을 운명에 놓인 그들의 동족을 포기해야 했다. 용군단의 퇴각으로 수적인 열세에 놓인 말퓨리온과 그의 동료들은 계속되는 대학살에서 겨우 목숨만을 건질 수 있었다.'),
(1817, '"말퓨리온은 영원의 샘이 악마와 이 세계를 밀접하게 연결해주는 고리 역할을 한다고 확신하여 샘을 파괴해야 한다고 주장했다. 그의 동료들은 영원의 샘이 나이트 엘프에게 불멸성과 힘을 주는 근원이라는 것을 알고 있었기에 그 무모한 주장에 충격을 감추지 못했다. 하지만, 티란데는 그의 생각이 현명하다고 판단하여 아즈샤라의 사원에 쳐들어가 영원의 샘을 완전히 봉쇄해야 한다고 세나리우스와 동료들을 설득했다."'),
(1828, '"끔찍한 폭발 속에서 살아남은 나이트 엘프들은 함께 뗏목을 타고 눈에 보이는 유일한 땅덩어리로 천천히 나아갔다. 말퓨리온과 티란데, 세나리우스는 엘룬의 은총으로 대재앙에서 살아남을 수 있었다. 지칠 대로 지친 영웅들은 살아남은 동료들을 이끌고 새로운 터전을 일구기로 했다."'),
(1829, '침묵 속에서 여행을 하면서 그들은 폐허가 된 세상을 보게 되었고 이 모든 파괴가 자신들의 욕망에서 나온 것임을 깨닫게 되었다. 비록 영원의 샘이 파괴되면서 살게라스와 그의 불타는 군단이 이 세계에서 사라졌지만 말퓨리온과 그의 동료들은 승리의 끔찍한 대가를 마음 속 깊이 새겼다.'),
(1830, '많은 귀족들도 이 대재앙에서 무사히 살아 남았다. 그들은 다른 나이트 엘프들과 함께 바다를 건너 새로운 땅으로 갔다. 귀족들의 마음을 믿을 수는 없었지만 영원의 샘의 마력 없이는 큰 재난을 일으키진 않을 것이라는 생각에 말퓨리온은 안심하였다.'),
(1831, '지친 몸을 이끌고 새 대륙의 해안에 다다른 나이트 엘프들은 성스러운 하이잘 산이 대참사의 여파 속에 무사한 것을 알게 되었다. 새로운 삶의 터전을 찾던 말퓨리온과 나이트 엘프들은 하이잘 산에 올라 거센 바람이 몰아치는 정상에 이르렀다. 그들은 거대한 산봉우리 사이에 자리잡은 나지막한 숲 지대로 내려가다가 작고 고요한 호수를 발견했다. 그들이 두려워했던 대로 호수의 물은 마법으로 오염되어 있었다.'),
(1832, '"한편, 일리단도 대재앙에서 살아 남아 말퓨리온과 나이트 엘프들이 도착하기 훨씬 전에 하이잘 산의 정상에 다다랐다. 일리단은 이 세상에 마법의 힘을 계속 유지시켜야 한다는 잘못된 생각으로 물병에 담아온 영원의 샘의 고귀한 물을 산의 호수에 부었다."'),
(1833, '그러자 영원의 샘이 지녔던 강렬한 힘이 빠르게 타오르며 새로운 영원의 샘이 생겨났다. 새로운 영원의 샘이 미래의 자손들에게 큰 선물이 될 것이라 믿고 기쁨에 차 있던 일리단은 자신을 찾아온 말퓨리온을 보고 놀라움을 금치 못했다. 말퓨리온은 마법에는 혼돈의 힘이 깃들어 있어 마법을 사용하면 타락과 갈등을 불러오게 된다고 설명했으나 일리단은 자신의 마력을 포기하지 않으려 했다.'),
(1834, '일리단의 무모한 계략이 어떤 결과를 가져올지 잘 알고 있었던 말퓨리온은 결국 마법의 노예가 된 동생에게 무슨 수를 써야겠다고 결정했다. 말퓨리온은 세나리우스의 도움을 받아 일리단을 거대한 지하 감옥에 봉인해 세계가 끝날 때까지 힘을 쓰지 못하도록 가두어 버렸다. 마이에브 섀도송을 개인 교도관으로 선발해 동생을 철저히 감시하도록 했다.'),
(1835, '나이트 엘프들은 새로운 영원의 샘을 파괴하면 더 큰 참사가 일어날지 모른다고 우려해 샘을 그대로 두기로 했다. 대신 말퓨리온은 다시는 마법을 사용하지 않을 것이라고 선언했다. 나이트 엘프들은 세나리우스의 보살핌 아래 폐허가 된 땅을 치유하고 하이잘 산 기슭에 사랑하는 숲을 다시 키우기 위해 고대 드루이드의 지식을 배우기 시작했다.'),
(1836, '오랜 세월 동안 나이트 엘프들은 과거의 고향을 재건하기 위해 쉬지 않고 일했다. 부서진 사원과 도로에는 풀이 덮이도록 두고 하이잘 산 기슭의 울창한 숲과 그림자가 드리워진 언덕 한가운데 새로운 터전을 마련했다. 시간이 지나자 대재앙에서 살아남은 용들도 은둔지에서 나와 모습을 드러냈다.'),
(1837, '"붉은용 알렉스트라스자와 녹색용 이세라, 청동용 노즈도르무는 드루이드의 고요한 숲으로 내려와 나이트 엘프들의 노력이 맺은 결실을 살펴보았다. 강력한 힘을 지닌 대드루이드가 된 말퓨리온은 강대한 용들을 맞이하며 새로운 영원의 샘이 만들어진 배경에 대해 얘기해 주었다."'),
(1838, '영원의 샘에 대한 얘기를 듣고 놀란 용들은 영원의 샘이 존재하는 한 불타는 군단이 언젠가 다시 쳐들어올 것이라고 생각했다. 말퓨리온과 세 용은 영원의 샘을 보호하고 불타는 군단이 다시는 이 세계로 들어오지 못하도록 힘을 모으자고 약속했다.'),
(1839, '생명의 어머니 알렉스트라스자는 영원의 샘 심장부에 마법 도토리 하나를 넣어두었다. 강력한 마법의 물을 흡수한 이 도토리는 거대한 나무로 자라났다. 뿌리는 샘의 물을 먹고 자라났으며 울창한 가지들은 하늘을 찌를 듯 했다.'),
(1840, '"이 거대한 나무는 나이트 엘프와 자연의 결속을 나타내는 영원한 상징물로, 생명을 불어넣는 나무의 힘은 곳곳으로 뻗어나가 점차 세계를 치유하게 될 것이었다. 나이트 엘프들은 이 세계수의 이름을 그들의 언어로 ""천상의 왕관""이라는 뜻인 놀드랏실로 정했다."'),
(1841, '시간의 지배자 노즈도르무는 세계수에 마법을 걸어 이 거목이 서 있는 한 나이트 엘프들은 절대 나이가 들거나 질병에 걸리지 않도록 했다.'),
(1842, '꿈의 여왕 이세라 역시 세계수에 마법을 걸어 에메랄드의 꿈이라고 알려진 천상의 세계와 세계수를 연결했다. 광활하고 끊임없이 변화하는 정신의 세계인 에메랄드의 꿈은 물질계의 경계 밖에 존재했다. 에메랄드의 꿈에서 이세라는 자연의 흥망과 세계의 진화 자체를 통제할 수 있었다.'),
(1843, '말퓨리온 자신을 포함한 나이트 엘프 드루이드는 세계수를 통해 에메랄드의 꿈에 결속되었다. 드루이드는 신비로운 약속의 일부로서 한번에 몇 백 년 동안 잠을 자면서 자신들의 영혼이 이세라의 끝 없는 꿈의 길을 거닐도록 하는 데 동의했다. 드루이드는 그들의 삶에 있어 그렇게 많은 시간을 잠으로 잃는 것에 슬퍼하면서도 헌신적으로 이세라와의 약속에 동의했다.'),
(1844, '"수 세기가 지나면서 나이트 엘프의 새로운 사회는 점점 강해서 그들이 잿빛 골짜기라고 부르게 된 숲 전체로 확대되었다. 펄볼그나 가시멧돼지처럼 대재앙 이전에 많았던 생물과 종족이 다시 나타나 번성하기 시작했고 드루이드의 인자한 통치 아래 나이트 엘프는 별빛 아래서 전례 없는 평화와 고요를 누리게 되었다.\r\n"'),
(1845, '"하지만 원래 귀족이었던 생존자들은 불안해하기 시작했다. 그들은 일리단과 마찬가지로 아끼던 마법을 잃어 고통스러워 하던 터라 영원의 샘의 힘을 끌어내 마법을 사용하는 기쁨을 맛보고 싶어했다. 성급하고 솔직했던 귀족 지도자 다트리마는 마법의 주인은 원래 자신들이었다고 주장했고 마법을 사용하지 못하게 하는 드루이드에게 불만을 품어 그들을 겁장이라며 비난하기 시작했다.\r\n"'),
(1846, '"말퓨리온과 드루이드들은 다트리마의 비난을 넘겨 듣고 귀족들에게 마법을 사용하게 되면 사형에 처할 것이라 경고했다. 하지만 다트리마와 그의 추종자들은 드루이드에게 법을 폐지할 것을 납득시키려는 거만하고도 불행한 의도로 잿빛 골짜기에 끔찍한 마법 폭풍을 일으켰다.\r\n"')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(1847, '"그 많은 동족을 모두 사형에 처할 수 없었던 드루이드들은 이 무모한 귀족들을 자신들의 땅에서 추방하기로 결정했다. 다트리마와 그의 추종자들은 마침내 보수적인 동족들과 떨어지게 된 것을 기뻐하며 특별히 제작한 배에 올라 항해를 시작했다. 격돌하는 혼돈의 소용돌이 너머에 무엇이 있는지 아무도 몰랐지만 그들은 아무런 처벌도 받지 않고 마법을 자유롭게 사용할 수 있는 자신들만의 터전을 만들기를 간절히 바랬다.\r\n"'),
(1848, '"과거에 아즈샤라가 ""쿠엘도레이""라 이름을 지어주었던 이 귀족들은 마침내 인간이 로데론이라고 부르게 될 동쪽 땅의 해안에 다다랐다. 그들은 자신들만의 마법 왕국인 쿠엘탈라스를 세우기로 하고 달을 숭배하고 밤에만 활동하는 나이트 엘프의 규율을 저버렸다. 그 후 이들은 태양을 받아들이고 ""하이 엘프""라고만 불리게 되었다.\r\n"'),
(1849, '고집불통의 동족들이 떠난 후 나이트 엘프들은 다시 고향을 지키는 데 주력했다. 동면의 시기가 가까워진 것을 느낀 드루이드들은 사랑하는 이와 가족을 남겨두고 동면에 들어갈 준비를 했다.'),
(1850, '엘룬의 대여사제가 된 티란데는 연인인 말퓨리온에게 자기를 두고 이세라의 에메랄드의 꿈 속으로 떠나지 말라고 부탁했다. 하지만 변화하는 꿈의 길에 들어서기로 서약했던 말퓨리온은 티란데에게 작별을 고하면서 자신들의 사랑이 진실하다면 결코 떨어지지 않을 것이라고 맹세했다.'),
(1851, '새로운 세계의 위협으로부터 칼림도어를 홀로 지키게 된 티란데는 나이트 엘프 자매들을 모아 강력한 부대를 결성했다. 칼림도어 방어를 맹세한 고도로 훈련 받은 이 강력한 여전사들은 파수꾼이라 불리게 되었다. 파수꾼들은 홀로 잿빛 골짜기의 그늘진 숲을 정찰하는 것을 좋아했지만 위급한 시기에 부를 수 있는 동맹자들도 많이 있었다.'),
(1852, '반신 세나리우스는 근처 하이잘 산의 달의 숲에 남았고 숲의 수호자라 알려진 세나리우스의 아들들은 나이트 엘프들을 지켜보면서 정기적으로 파수꾼을 도와 평화를 지켰다. 수줍음을 많이 타는 세나리우스의 딸인 드리아드들도 더 자주 모습을 드러내기 시작했다.'),
(1853, '티란데는 잿빛 골짜기의 평화를 지키는 일에 바빴지만 말퓨리온과 함께하지 못해 기쁘지 않았다. 드루이드들이 잠든 동안 수세기가 흘렀고 악마들의 2차 공격에 대한 그녀의 두려움은 점점 커져 갔다. 티란데는 불타는 군단이 아직도 끝없는 어둠 너머에서 나이트 엘프와 아제로스의 세계에 대한 복수를 꾀하고 있을지도 모른다는 생각을 떨쳐버릴 수가 없었다.'),
(1854, '다트리마가 이끄는 하이 엘프는 칼림도어를 뒤로 하고 혼돈의 소용돌이에서 몰아치는 폭풍에 맞서 앞으로 나아갔다. 이들은 오랜 시간 동안 세계를 두루 돌아다니며 그들이 머문 곳마다 신비로운 유적들과 잃어버린 왕국을 보았다. 선스트라이더(\'대낮에 활보하는자\')로 이름을 바꾼 다트리마는 자신의 동족을 위한 새로운 국가를 건설하고자 목초가 무성한 곳을 찾아 다녔다.'),
(1855, '다트리마와 그의 동족은 마침내 훗날 인간이 로데론이라고 부른 왕국의 해안에 이르렀다. 내륙으로 들어간 하이 엘프들은 고요한 티리스팔 숲에 새로운 정착지를 건설했다. 하지만 몇 년 후 많은 하이 엘프들이 미쳐가기 시작했다. 그 지역의 지하에 사악한 무엇인가 잠들어 있기 때문이라는 소문이 있었지만 그 소문이 사실인지는 끝내 확인되지 않았다. 결국 하이 엘프들은 야영지를 철수하고 초목이 무성한 북쪽 땅으로 옮겨갔다.'),
(1856, '로데론의 바위투성이 산악 지대를 넘어가면서 하이 엘프들의 여행은 더욱 위험해졌다. 하이 엘프들은 영원의 샘에서 흘러나오는 생명 에너지와 사실상 단절되었기 때문에 상당수가 추운 날씨로 병에 걸리거나 굶어 죽어갔다. 하지만 그 중에서도 가장 혼란스러운 변화는 그들이 더 이상 불로불사하거나 자연에 대한 면역력을 갖지 않게 되었다는 사실이었다. 하이 엘프들은 키도 약간씩 줄고 그들만이 지녔던 보랏빛 피부도 점점 빛을 잃어갔다.'),
(1857, '이 많은 고난에도 불구하고 이들은 칼림도어에서 볼 수 없었던 수많은 희귀 생물과 접하게 되었고 이 고대의 숲 전역에서 사냥을 하는 원시 인간 부족들도 만나게 되었다. 하지만 그들이 만난 가장 위협적인 존재는 탐욕스럽고 교활한 줄아만의 숲 트롤이었다.'),
(1858, '피부가 이끼로 덮인 이 트롤들은 잘려나간 사지를 다시 자라게 하고 심각한 신체의 부상을 치유하는 능력을 지녔으나 야만적이고 사악한 종족이었다. 아마니 제국은 로데론 북부의 대부분을 차지했고 트롤들은 외부인이 자신들의 영토에 들어오는것을 막기 위해 열심히 싸웠다. '),
(1859, '엘프들은 포악한 트롤에게 깊은 혐오감을 느끼게 되어 트롤이 눈에 뛸 때마다 처치해 버렸다.  여러 해가 흘러 하이 엘프들은 마침내 칼림도어를 연상시키는 땅을 찾게 되었다. 이들은 로데론 북부의 깊숙한 숲에 쿠엘탈라스 왕국을 세우고 이를 칼도레이 동족의 제국보다 훨씬 강력한 제국으로 만들 것을 맹세했다. 하지만 안타깝게도 엘프들은 트롤이 아직도 성지로 여기고 있는 고대 트롤 도시 위에 쿠엘탈라스를 세운 것을 알게 되었고 곧 트롤들은 엘프의 정착지를 집단으로 공격하기 시작했다.'),
(1860, ' 엘프들은 새로운 터전을 포기하지 않은 채 완강하게 버티며 영원의 샘에서 조금씩 모아두었던 마법을 사용해 야만적인 트롤들이 더 이상 접근하지 못하도록 막았다. 다트리마의 지휘 아래 엘프들은 10대 1의 수적인 열세를 극복하고 아마니 전투부대를 물리칠 수 있었다. 칼도레이의 오랜 경고를 기억하는 일부 엘프들은 마법의 사용이 추방 당한 불타는 군단의 주목을 끌지도 모른다고 생각하고, '),
(1861, '계속해서 마법을 사용할 수 있도록 자신들의 땅에 보호 장벽을 세우기로 결정했다. 그들은 쿠엘탈라스를 둘러싼 위치에 마법 장벽의 경계를 표시하는 일련의 거대하고 튼튼한 마법석을 세웠다. 이 마법석은 엘프의 마법이 외부의 위협에 노출되지 않도록 숨겨주었을 뿐 아니라 미신을 믿는 트롤 전투부대에게 겁을 주어 접근하지 못하게하는 역할도 했다. '),
(1862, '시간이 흘러 하이 엘프의 노력과 탁월한 마법 능력 덕분에 쿠엘탈라스는 완성된 제국의 모습을 갖추게 되었다. 그들의 아름다운 성은 칼림도어의 고대 전당과 동일한 건축 양식으로 지어졌으나 주변의 자연 환경과 훨씬 잘 어우러졌다. 쿠엘탈라스는 엘프들이 그토록 만들고 싶어했던 화려한 보배가 된 것이다. 쿠엘탈라스의 지배층으로 실버문 의회가 구성되었지만, '),
(1863, '정치력의 상당 부분은 선스트라이더 왕조가 쥐고 있었다. 일곱 명의 최고위급 하이 엘프 군주로 구성된 이 의회는 엘프의 영토와 동족의 안전을 지키기 위해 일했다. 보호 장벽에 둘러싸인 하이 엘프들은 칼도레이의 오랜 경고에도 흔들리지 않고 거의 모든 생활 속에서 마법을 마음껏 사용했다. '),
(1864, '하이 엘프들은 완전히 격리된 왕국 안에서 거의 4처년을 평화롭게 지냈다. 하지만 앙심을 품은 트롤들은 그리 쉽게 좌절하지 않았다. 그들은 숲 속에서 음모를 꾸미고 전투부대의 수가 늘어나길 기다리고 있었다. 마침내 강력한 트롤 군대가 어둠의 숲으로부터 돌격해 와 쿠엘탈라스의 빛나는 첨탑에 다시금 공격을 가하기 시작했다. '),
(1865, '하이 엘프가 그칠 줄 모르는 트롤의 맹공격에 살아남기 위해 싸우고 있을 때 여기저기 흩어져 있던 로데론의 인간 유목민 부족들도 자기들만의 영토를 얻기 위해 싸우고 있었다. 초기 인간 부족들은 종족 단결이나 명예는 아랑곳하지 않고 서로 거주지를 공격하고 있었다.'),
(1866, '하지만 아라시라는 이름의 한 인간 부족은 트롤의 세력이 무시할 수 없을 만큼 큰 위협이 되고 있다는 것을 느끼고 모든 부족을 자신의 지배 아래 하나로 모아 트롤 전투부대에 대비해 통일된 전선을 확보하고자 했다.'),
(1867, '6년이라는 시간이 흐르면서 약삭빠른 아라시 부족은 경쟁 부족을 제압하게 되었고 매번 승리할 때마다 정복당한 부족에게 평화와 평등을 보장해 주고 그들의 충성을 받게 되었다. 마침내 아라시 부족은 수많은 다른 부족민을 받아들이면서 성장해갔고 군대의 규모도 거대해졌다.'),
(1868, '"트롤 전투부대는 물론이고 필요한 경우 은둔해 있는 엘프와도 싸워 이길 자신이 있었던 아라시 족장들은 로데론의 남부 지역에 강력한 요새 도시를 건설하기로 결정했다. 스트롬이라는 이름의 이 도시국가는 아라시인들의 국가, 아라소르의 수도가 되었다. 아라소르가 번성하자 대륙 각지에서 인간들이 스트롬의 보호와 안전을 찾아 남쪽으로 몰려들었다."'),
(1869, '한 깃발 아래 단결된 인간 부족은 강하면서도 낙관적인 문화를 발전시켜 나갔다. 아라소르의 소라딘 왕은 잘 알려지지 않은 북방의 엘프들이 끊임 없이 트롤의 공격을 받고 있다는 것을 알았지만 은둔해 사는 외부인을 보호하기 위해 자기 백성의 안전을 걸 생각은 없었다. 그로부터 여러 달이 지나 엘프들이 패배한 것 같다는 소문이 북쪽에서 흘러 들어오기 시작했다. 쿠엘탈라스로부터 녹초가 된 사절단이 스트롬에 도착하고 나서야 소라딘은 트롤의 위협이 얼마나 큰 지 실감하게 되었다.'),
(1870, '엘프들은 소라딘에게 트롤 군대의 규모가 엄청나다는 것과 트롤이 쿠엘탈라스를 파괴한 후에는 남부 지역까지 공격해 올 것이라는 정보를 알려주었다. 엘프들은 군사적 원조가 절박했던 탓에 급히 트롤 전투부대와의 싸움을 도와주는 대가로 선별된 특정 인간에게 마법을 사용하는 법을 가르쳐 주기로 했다.'),
(1871, '소라딘은 마법의 힘은 믿지 않았지만 어쩔 수 없이 엘프들을 도와주는 데 동의했다. 그 직후 엘프 마술사들이 아라소르에 도착해 일부 인간들에게 마법의 도를 가르치기 시작했다.'),
(1872, '엘프는 인간이 선천적으로 마법을 다루는 데 서툴기는 하지만 마법에 대한 친화력이 매우 높다는 것을 알았다. 백 명의 인간들은 가장 기본적인 엘프 마법만 익혔다. 트롤과의 전투에 그 이상은 필요하지 않았기 때문이다. 마법을 배운 인간들이 전투를 지원할 준비가 되었다고 판단한 엘프들은 스트롬을 떠나 소라딘 왕의 강력한 군대를 따라 북으로 향했다.'),
(1873, '엘프와 인간이 합세한 군대는 알터랙 산맥 아래에서 엄청난 수의 트롤 전투부대와 맞닥뜨렸다. 여러 날 동안 전투가 계속되었지만 지칠 줄 모르는 아라소르의 군대는 트롤의 맹공격 앞에서도 지치거나 물러서지 않았다. 엘프의 군주들은 마침내 적에게 마법의 힘을 보여줄 때가 되었다고 여겼다.'),
(1874, '이에 백 명의 인간 마법사와 수많은 엘프 마술사들은 천상의 분노를 불러내려 트롤 군대를 불태우기 시작했다. 자연의 힘으로 발생한 이 불은 저절로 상처를 치유하는 트롤의 능력을 없애고 불길에 휩싸여 고통 받는 트롤의 몸을 완전히 불태워버렸다.'),
(1875, '소라딘의 군대는 뿔뿔이 흩어져 도망치는 트롤을 끝까지 쫓아가 하나도 남김없이 처치해버렸다. 트롤은 이 패배에서 영원히 헤어나지 못했으며 역사상 하나의 단일 국가로 일어서는 일도 더 이상 없었다. 쿠엘탈라스를 파멸로부터 구했다고 확신한 엘프는 아라소르 국가와 소라딘 왕의 혈통에 충성과 우정을 맹세했다. 그 이후 오랫동안 인간과 엘프는 평화로운 관계를 키워나갔다.'),
(1876, '북쪽 대륙에서 트롤이 사라지자 쿠엘탈라스의 엘프들은 자신들의 영광스러운 고향을 재건하는 데 주력했다. 승리를 거둔 아라소르 군대는 고향 땅 스트롬으로 돌아갔다.'),
(1877, '아라소르의 인간 사회는 점점 번창해갔지만 지나친 확장은 왕국의 분열을 초래할 수도 있다고 염려한 소라딘은 스트롬을 아라소르 제국의 중심으로 유지해갔다. 오랜 세월 평화롭게 계속되어 온 성장과 교류의 시간이 지나고 위대한 소라딘이 나이가 들어 세상을 떠나자 아라소르의 젊은 세대는 스트롬의 영토 너머로 아라소르 제국을 확장할 수 있게 되었다.'),
(1878, '엘프에게서 마법의 도를 배운 최초의 인간 마법사 백 명은 자신들의 힘을 키워나가면서 마법 사용의 신비로운 비법에 대해 더욱 세부적으로 연구했다. 이 마법사들은 강한 의지력과 숭고한 정신을 인정받아 선택되었기 때문에 신중하고 책임감 있게 마법을 사용해 왔으나 이들의 마력과 비법을 전수받은 새로운 세대는 전쟁의 혹독함이나 자제력의 필요성에 대해 알지 못했다.'),
(1879, '이 젊은 마법사들은 동족을 위한 책임보다는 개인의 욕심을 채우기 위해 마법을 사용하기 시작했다.'),
(1880, '아라소르 제국이 성장하고 새로운 땅으로 세력을 확장하면서 이 젊은 마법사들도 남쪽으로 퍼져나갔다. 마법사들은 신비로운 힘을 휘두르며 야생의 위험한 동식물로부터 동족을 보호하고 황무지에서 새로운 도시국가를 건설할 수 있도록 했다. 하지만 마법사들은 힘이 점점 커지자 더욱 자만하며 사회에서 고립되어 갔다.'),
(1881, '스트롬의 북쪽 지방에는 아라소르의 두 번째 도시국가인 달라란이 세워졌다. 많은 신출내기 마법사들은 답답한 스트롬을 벗어나 달라란으로 가서 자신들의 새로운 힘을 더 자유롭게 사용하길 원했다. 이 마법사들은 자신들의 기술로 달라란의 첨탑들을 쌓아 올리며 마법을 연구하는 데 빠져 지냈다.'),
(1882, '달라란의 주민들은 이 마법사들의 행동을 너그러이 봐주며 마법을 사용하는 수호자들의 보호 아래 풍족한 삶을 누리게 되었다. 하지만 점점 더 많은 마법사들이 마법을 사용하게 되면서 달라란 주변의 현실 구조가 힘을 잃고 붕괴되기 시작했다.'),
(1883, '영원의 샘이 무너지면서 추방되었던 불타는 군단의 사악한 첩자들은 달라란 마법사들의 무분별한 마법 사용으로 인해 다시 이 세계로 발을 들여놓게 되었다. 비교적 약한 이 악마들은 아직까지 대규모로 나타나지 않았지만 달라란의 거리에 상당한 혼란과 혼돈을 불러왔다.'),
(1884, '악마와 마주치는 대부분의 사건은 산발적으로 발생했고 마법 지배층은 이러한 사건이 대중에게 알려지지 않도록 안간힘을 썼다. 가장 강한 마법사들을 보내 교묘히 피해 다니는 악마들을 잡아들이려 했지만 그들의 힘은 불타는 군단의 첩자 하나와도 상대가 안 된다는 것을 알게 되었다.'),
(1885, '몇 달 후 미신을 믿는 농민층은 이 마법 지도자들이 무엇인가를 숨기고 있는 게 아닌가 의심하기 시작했고 과대 망상에 걸린 시민들은 한때 존경했던 마법사들의 동기와 음모에 대해 문제를 제기하면서 달라란의 거리에는 혁명의 소문이 나돌기 시작했다. 농민의 혁명과 스트롬의 처벌을 두려워한 마법지배층은 자신들의 문제를 이해해줄 유일한 자들을 찾아갔으니 그것은 바로 엘프족이었다.'),
(1886, '마법지배층으로부터 달라란에서 악마들이 활동한다는 것을 알게 된 엘프족은 즉시 가장 강력한 마법사들을 인간의 땅으로 보냈다. 이 엘프 마법사들은 달라란의 에너지 흐름을 조사하며 자신들이 목격한 모든 악마의 활동에 대해 상세히 보고했다. 엘프족은 비록 아직까지는 이 세계에 들어온 악마의 수가 소수에 불과하나 인간들이 계속해서 마력을 사용한다면 불타는 군단의 위협은 더욱 커질 것이라고 결론내렸다.'),
(1887, '쿠엘탈라스의 엘프들을 지배하는 실버문 의회는 달라란의 마법지배층 지도자들과 비밀 조약을 맺었다. 엘프들은 마법지배층에 고대 칼림도어의 역사와 아직도 이 세계를 위협하는 불타는 군단에 대해 들려주며 마법을 계속 사용하는 한 불타는 군단의 잔악한 첩자들로부터 시민들을 보호해야 할 것이라고 전했다.'),
(1888, '마법지배층은 불타는 군단과의 끝없는 비밀 전쟁에 맞서기 위해 자신들의 마력을 한 몸에 받아 사용할 인간 투사 한 명을 선발할 것을 제안했다. 그리고 공포심이나 망상증으로 인해 폭동을 일으키는 일이 없도록 수호자나 불타는 군단의 위협에 대해서는 대다수의 인간들에게 비밀로 할 것을 강조했다. 엘프족은 이 제안에 동의하여 수호자의 선발을 관리하고 이 세계에 혼란이 발생하는 것을 막을 비밀 단체를 창단했다.'),
(1889, '이 단체는 하이 엘프들이 처음 정착했던 로데론의 그늘진 티리스팔 숲에서 비밀 모임을 가졌다. 이리하여 이 비밀 단체에는 티리스팔의 수호자라는 이름이 붙게 되었다. 수호자가 되기 위해 선발된 투사들은 엘프의 마법과 인간의 마법을 모두 받아 엄청난 힘을 지니게 되었다. 수호자는 한 번에 한 명만 선발되었으나 그 힘이 워낙 막강해 불타는 군단의 첩자가 발견될 때마다 이들을 손쉽게 물리쳤다.'),
(1890, '수호자의 힘은 너무나 강력했기 때문에 오직 티리스팔 의회만이 수호자의 뒤를 이을 후임자를 선발할 권한이 있었다. 수호자가 너무 늙거나 혼돈과의 비밀 전쟁에서 지칠 때마다 티리스팔 의회는 새로운 투사를 선발해 통제된 환경에서 정식으로 수호자의 힘을 부여해주었다.'),
(1891, '오랜 세월 동안 수호자는 아라소르와 쿠엘탈라스의 전역에서 불타는 군단의 보이지 않는 위협으로부터 인류를 보호했다. 제국 곳곳에서 마법이 폭넓게 사용되면서 아라소르는 성장하고 번성해 갔다. 그러는 동안 수호자는 악마의 활동을 신중히 살폈다.'),
(1892, '아주 오래전 티탄이 아제로스를 떠난 후 토석인이라 알려진 티탄의 자손들이 계속해서 세계를 보호하며 구석구석을 일구어 나갔다. 토석인은 지상에 사는 종족들의 일에는 관여하지 않은 채 어두운 땅 속 깊은 곳으로만 파고들었다.'),
(1893, '"세계가 영원의 샘의 내파로 인해 갈라지면서 토석인은 깊은 영향을 받게 되었다. 토석인은 대지 자체의 고통과 함께 휘청거리다 정체성의 대부분을 상실하고 자신들이 처음 창조되었던 석실에 스스로를 봉인해버렸다. 울다만, 울둠, 울두아, 이는 토석인이 처음으로 태어난 고대 티탄 도시의 이름들이다. 토석인은 땅 속 깊은 곳에 묻힌 채 거의 8천년간을 평화롭게 쉬고 있었다."'),
(1894, '토석인을 깨운 것이 무엇인지는 확실하지 않지만 울다만에 봉인되었던 토석인은 마침내 스스로의 봉인을 풀고 긴 잠에서 깨어나게 되었다. 토석인들은 기나긴 잠에 빠져 있는 동안 자신들이 많이 변했다는 것을 깨달았다. 돌처럼 딱딱했던 피부는 부드러워졌고 돌과 흙을 다루던 힘도 많이 약해졌다. 그들은 평범한 생명체로 변한 것이었다.'),
(1895, '스스로를 드워프라 칭한 마지막 토석인들은 울다만의 전당을 떠나 이제 막 깨어나고 있는 위험한 세계로 나아갔다. 여전히 땅 속 세계의 안전과 경이로움에 마음이 편안해지는 것을 느끼는 드워프들은 높디 높은 산 아래 거대한 왕국을 세웠다.'),
(1896, '그들의 조상이자 티탄 창조주인 카즈고로스의 이름을 따 이 땅을 `카즈의 산`이라는 뜻의 카즈 모단이라 불렀다. 티탄 아버지를 위해 제단을 세운 드워프들은 산의 중심에 거대한 용광로를 지었다. 이리하여 이 용광로를 중심으로 생겨난 도시가 후에 아이언포지라 불리게 된다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(1897, '선천적으로 보석과 돌을 다듬는 일을 좋아하는 드워프들은 주변의 산을 돌아다니며 보석과 광석을 캤다. 이들은 땅 속에서 일하는 것에 만족하며 땅 위에 살고 있는 이웃들의 일에는 무관심한 채로 지냈다.'),
(1898, '"스트롬은 계속해서 아라소르의 중심지로 남아 있었지만 달라란처럼 로데론 대륙의 각지에서 많은 도시국가들이 생겨났다. 새로 생긴 첫 도시국가들로는 길니아스, 알터랙, 그리고 쿨 티라스가 있었다. 이 도시들은 각각 고유한 관습과 상업 정책에 따라 운영되었지만 스트롬의 통일된 권한에 속해 있었다."'),
(1899, '"달라란은 티리스팔 의회의 철저한 감독 하에 세계 각지에서 온 마법사들의 배움의 장으로 자리잡았다. 달라란을 지배하는 마법지배층은 키린 토라는 전문 분파를 결성하고 당시 인류에게 알려진 모든 주문과 유물, 마법 물품을 수록하고 조사하는 일을 담당하게 되었다."'),
(1900, '길니아스와 알터랙은 스트롬의 강력한 지원자가 되어 막강한 군대를 편성하고 남쪽 산악 지대인 카즈 모단을 탐험하게 되었다. 이 탐험 기간 동안 인간들은 처음으로 고대 드워프족을 접하고 그들의 지하 동굴 도시인 아이언포지에 발을 들여놓게 되었다. 인간과 드워프족은 금속 세공술과 기계 공학 기술을 서로 주고받으며 전투와 무용담에 대한 공통된 열정을 나누었다.'),
(1901, '로데론 남부 지방의 큰 섬 위에 세워진 쿨 티라스는 어업과 무역을 기반으로 풍요로운 경제 활동을 영위해 갔다. 시간이 흘러 쿨 티라스는 거대한 상업 선단을 이끌고 이색적인 거래 상품들을 찾아 세계 각지를 돌아다녔다. 하지만 아라소르의 경제가 번성했음에도 불구하고 아라소르를 이루고 있던 가장 강력한 요소들은 붕괴되기 시작했다.'),
(1902, '시간이 지나 스트롬의 군주들은 건조하고 메마른 남부 땅을 떠나 로데론의 청청한 북부 지방으로 터전을 옮기고 싶어했다. 하지만 소라딘 왕의 후계자이자 아라시 혈통의 마지막 자손들은 스트롬을 버려서는 안 된다고 주장했고 그곳을 떠나고 싶어하던 시민들의 불만을 사게 되었다. 결국 스트롬의 군주들은 길들여지지 않은 북부 지방에서 순수함과 깨우침을 얻고자 이 고대 도시를 떠나기로 결정했다.'),
(1903, '스트롬의 군주들은 달라란에서 북쪽으로 멀리 떨어진 곳에 새로운 도시국가를 짓고 이를 로데론이라 불렀다. 후에 전 대륙이 이 도시국가에서 이름을 가져오게 된다. 로데론은 종교적 순례자와 내면의 평화와 안전을 갈구하는 모든 이들이 모이는 동경의 땅이 되었다.'),
(1904, '고대 스트롬의 부서져가는 성벽 안에 남겨진 아라시의 자손들은 남부에 있는 카즈 모단의 바위투성이 산맥을 지나 남쪽으로 떠나가기로 결정했다. 오랜 여행 끝에 그들은 마침내 후에 아제로스라 불리게 된 대륙의 북부 지역에 정착했다. 이들은 비옥한 계곡에 스톰윈드 왕국을 건설하고 매우 짧은 시간에 자급자족할 수 있는 능력을 갖춘 국가가 되었다.'),
(1905, '스트롬에 남겨진 몇몇 전사들은 스트롬에 계속 남아 고대 도시의 성벽을 지키기로 결심했다. 더 이상 아라소르 제국의 중심지가 아니게 된 스트롬은 스트롬가드라는 새로운 국가로 발달했다. 다른 도시국가들은 저마다 번성하고 있었지만 아라소르 제국은 사실상 붕괴된 것이었다. 각 국가는 자신들만의 관습과 신앙을 발달시키면서 점차 서로에게서 분리되어갔다. 단결된 인류를 꿈꾸던 소라딘 왕의 비전은 마침내 사라져버렸다.'),
(1906, '일곱 개 인간 왕국의 정치 세력과 경쟁자들이 흥망을 거듭하는 동안에도 수호자들은 혼돈에 대비해 경계를 늦추지 않았다. 기나긴 세월 동안 여러 수호자가 있었지만 한번에 단 한 명만이 티리스팔의 마력을 사용할 수 있었다. 이 시대의 최후 수호자 중 하나는 암흑에 맞선 강력한 여전사였다.'),
(1907, '젊고 불 같은 성격을 지닌 인간 여자 아이 에이그윈이 티리스팔 교단의 승인을 받고 수호자의 자격을 받은 것이다. 에이그윈은 악마들이 눈에 띌 때마다 모조리 소탕하며 열심히 활동했지만 가끔 티리스팔 의회의 남성 중심적 권한에 대해 불만을 드러냈다.'),
(1908, '그녀는 의회를 통솔하는 고대 엘프와 나이든 노인들의 사고 방식이 너무 경직되어 있고 혼돈과의 투쟁을 확실하게 끝낼 수 있는 선견지명이 부족하다고 믿었다. 기나긴 토론과 논쟁을 견디지 못한 그녀는 동료와 윗사람에게 자신의 가치를 증명해 보이려고 노력했고 그 결과 중대한 상황에서 지혜보다는 용맹을 택하는 일이 잦았다.'),
(1909, '티리스팔의 무한한 힘을 다스리는 능력이 점점 커져가면서 에이그윈은 북쪽 노스렌드 대륙의 얼어붙은 땅에 강력한 악마의 무리가 나타나고 있음을 느끼게 되었다. 에이그윈은 북쪽 멀리 산속까지 악마들을 추적했다. 그곳에서 그녀는 악마들이 용군단의 마지막 생존자 중 하나를 사냥해 용이 가지고 있던 마력을 빼내고 있는 것을 발견하였다.'),
(1910, '필멸의 종족들의 계속되는 세력 확장을 피해 은둔해 있던 이 강대한 용들은 불타는 군단의 흑마법과 자신들의 마법이 우열을 가릴 수 없을 정도로 비슷하다는 것을 깨달았다. 악마에게 맞선 에이그윈은 고귀한 용들의 도움으로 그들을 모조리 제거해 버렸다. 그러나 마지막 악마가 이 세상에서 추방되자 북쪽 전역에 거대한 폭풍이 일어났다.'),
(1911, '노스렌드의 하늘에 거대한 그림자가 나타났다. 불타는 군단의 군주이자 악마의 제왕인 살게라스가 지옥의 에너지를 내뿜으며 에이그윈 앞에 나타난 것이다. 살게라스는 젊은 수호자에게 티리스팔의 종말이 다가왔노라며 곧 불타는 군단의 대학살 앞에 전 세계가 굴복하게 될 것이라고 말했다.'),
(1912, '용감한 에이그윈은 자신이 이 암흑의 신을 상대할 수 있으리라 믿고 마력을 풀어 살게라스의 화신을 공격했다. 에이그윈은 믿을 수 없을 정도로 손쉽게 악마의 제왕을 공격하여 그의 껍데기를 죽이는 데 성공했다. 살게라스의 영혼이 남아있을 것을 걱정한 순진한 에이그윈은 영원의 샘이 붕괴되면서 바다 밑으로 가라앉아버린 칼림도어 고대 전당 중 하나에 살게라스의 파괴된 껍질을 봉인했다.'),
(1913, '하지만 에이그윈은 자신의 행동이 모두 살게라스의 계략이었음을 결코 알아채지 못했다. 그녀는 그녀도 모르는 사이에 필멸의 생명체들이 살고 있는 세계를 운명짓게 된 것이다. 사실 살게라스의 육체가 죽음을 맞이한 순간 그 영혼이 에이그윈의 지친 몸 속으로 들어갔고 살게라스는 이 젊은 수호자의 영혼 속에서 그녀가 알아채지 못하도록 오랜 세월 숨어서 지내게 된다.'),
(1914, '아이언포지 산맥의 드워프족은 수 세기 동안 평화로운 삶을 누렸다. 그러나 산악 도시의 좁은 공간 속에서 사회는 너무나 커져 버렸다. 모디무스 앤빌마 대왕이 정의와 지혜로 모든 드워프를 다스렸음에도 불구하고 드워프 사회에서는 세 개의 강력한 당파가 생겨났다.'),
(1915, '"마도란 브론즈비어드 호족이 이끄는 브론즈비어드 일족은 대왕과 긴밀한 관계를 유지하며 아이언포지 산맥의 전통적인 수호자로 일어섰고, 카드로스 와일드해머가 이끄는 와일드해머 일족은 산기슭 주변의 바위산과 구릉지대에 살며 도시 내에서 세력을 확장하려고 노력했다."'),
(1916, '"세 번째 당파인 검은무쇠단은 타우릿산이라는 마법사 족장을 지도자로 두었는데, 이 부족은 산 아래 깊은 그늘 속에서 브론즈비어드 부족과 와일드해머 부족을 몰아내기 위한 음모를 꾸미고 있었다."'),
(1917, '이 세 당파들 사이에 불안하게 유지되어 온 평화는 앤빌마 대왕이 세상을 뜨면서 폭발하게 되었다. 세 지도층 부족이 아이언포지를 서로 차지하기 위해 전쟁을 시작한 것이다. 땅속에서는 오랫동안 드워프의 내전이 계속되었다. 결국 가장 큰 군대를 보유하고 있던 브론즈비어드 부족이 검은무쇠단과 와일드해머 부족을 추방하고 산을 차지했다.'),
(1918, '카드로스와 와일드해머 전사들은 북쪽으로 던 알가즈의 성문을 지나 머나먼 그림 바톨의 봉우리로 이동하여 그들만의 왕국을 건립했다. 그곳에서 와일드해머 부족은 번영을 누리며 자신들의 보물 창고를 다시 채워나갔다. 타우릿산과 검은무쇠단 부족 역시 어려움을 겪기는 마찬가지였다. 패배로 치욕을 당한 검은 무쇠단 부족은 아이언포지를 파괴할 음모를 꾸몄다. 타우릿산은 부족을 이끌고 남쪽으로 내려가 아름다운 붉은마루 산맥에 자신의 이름을 딴 도시를 세웠다.'),
(1919, '"시간이 흐르면서 도시는 번창했지만 검은무쇠단 부족의 증오는 사라지지 않았다. 타우릿산과 그의 아내, 여마법사 모드구드는 아이언포지와 그림 바톨 양쪽 모두에 각각 공격을 감행했다. 검은무쇠단은 카즈 모단 전역을 손에 넣기 위해 혈안이 되어 있었다."'),
(1920, '검은무쇠단 군대는 동족의 요새를 거세게 공격하며 두 왕국을 거의 손에 넣기에 이르렀다. 그러나 결국은 마도란 브론즈비어드가 부족을 이끌고 타우릿산의 마법 군대를 물리쳐 승리를 쟁취했다. 타우릿산과 그의 부하들은 모드구드의 부대가 그림 바톨에서 카드로스와 와일드해머 부족 전사들과 힘든 전투를 벌이고 있다는 사실을 인식하지 못한 채 다시 자신들의 도시로 후퇴하였다.'),
(1921, '적의 전사들과 맞닥뜨린 모드구드는 마법을 사용해 적에게 공포심을 불어넣으려 했다. 그녀의 명령에 그림자들이 움직이고 마물들이 땅속 깊은 곳에서 기어 나와 와일드해머의 전당을 돌아다녔다. 모드구드는 마침내 성문을 뚫고 요새를 공격했다. 와일드해머 부족은 필사적으로 싸웠다. 카드로스는 직접 싸움에 뛰어들어 적의 마법사 여왕인 모드구드를 처치했다.'),
(1922, '여왕이 쓰러지자 검은무쇠단 부족은 와일드해머 부족의 분노를 피해 달아났다. 그들은 남쪽에 있는 왕의 요새로 도망치다 그림 바톨을 지원하러 온 아이언포지 군대와 맞닥뜨리게 되었다. 두 군대 사이에 꼼짝없이 갇힌 검은무쇠단 패잔병들은 철저하게 패배하고 말았다.'),
(1923, '아이언포지의 군대와 그림 바톨의 군대는 서로 합세해 남쪽으로 향했다. 타우릿산과 검은무쇠단 부족을 완전히 말살하기 위해서였다. 하지만 출발한지 얼마 되지 않아 타우릿산의 광기와 분노가 엄청난 규모의 마력을 불러일으켰다. 타우릿산이 자신에게 승리를 가져다 줄 초자연적인 생물을 소환하기 위해 지하 세계에 잠들어 있는 고대의 마력을 불러낸 것이다. 하지만 소환해낸 생물은 타우릿산조차도 상상하지 못했을 만큼 끔찍한 것이었고 결국 그것이 타우릿산 자신의 파멸을 불러왔다.'),
(1924, '"이 세계가 태어난 지 얼마 되지 않던 시절 티탄에게 추방당한 불의 군주, 불의 정령들의 영원한 군주인 라그나로스가 다시 깨어났다. 그가 이제 타우릿산의 소환으로 다시 깨어나게 된 것이다. 아제로스에서 일어난 대재앙, 라그나로스의 환생으로 붉은마루 산맥이 파괴되고 그 파괴의 중심에 격렬한 화산이 만들어졌다."'),
(1925, '"검은바위 첨탑이라고 하는 이 화산은 북쪽으로 이글거리는 협곡, 남쪽으로 불타는 평원과 닿아 있다. 타우릿산은 자신이 푼 마력에 죽고 말았지만 살아남은 그의 동족들은 결국 라그나로스와 그의 정령들에게 노예로 잡히고 말았다. 그들은 오늘날까지도 검은바위 첨탑 속에 남아있다."'),
(1926, '참혹한 파괴의 현장과 남부 산맥으로 퍼져가는 불길을 본 마도란 왕과 카드로스 왕은 군대를 멈추고 자신들의 왕국으로 되돌아가는 바람에 라그나로스의 무시무시한 분노와 마주치지 않을 수 있었다.'),
(1927, '브론즈비어드 부족은 아이언포지로 되돌아가 영광스러운 도시를 재건하였다. 와일드해머 부족도 고향인 그림 바톨로 되돌아갔다. 하지만 모드구드의 죽음으로 산악 요새가 사악한 기운으로 오염돼 더 이상 거주할만한 곳이 못 되었다.'),
(1928, '"사랑하는 고향 땅을 잃게 된 와일드해머 부족은 가슴이 아팠다. 이에 브론즈비어드 왕이 와일드해머 부족에게 아이언포지에서 살 곳을 마련해주려 했지만 와일드해머 부족은 단호히 거절했다. 카드로스는 부족을 이끌고 북쪽의 로데론으로 향했다. 동부 내륙지의 푸른 숲에 정착한 와일드해머 부족은 맹금의 봉우리라는 도시를 세우고, 그곳에서 자연과 더욱 가까워지며 그 지역의 강대한 그리핀과도 유대 관계를 갖게 되었다."'),
(1929, '아이언포지의 드워프들은 동족과의 관계를 유지하고 교역을 활성화하기 위해 탄돌 교각이라는 두 개의 거대한 다리를 만들어 카즈 모단과 로데론을 연결했다. 상호 교역으로 인해 두 왕국은 번창해갔다. 마도란과 카드로스가 사망하자 그 아들들은 함께 손을 잡고 아버지를 기리는 뜻에서 두 개의 거대한 석상을 만들도록 지시했다.'),
(1930, '이 두 개의 석상은 라그나로스가 깨어나면서 화산 지대로 변해 버린 남부 지방으로 통하는 길목을 지키고 서 있게 된다. 이는 드워프 왕국을 침략하려는 자에 대한 경고의 역할뿐 아니라 검은무쇠단 드워프들이 치른 죄의 대가를 상기시키는 역할을 했다'),
(1931, '두 왕국은 몇 년 동안 밀접한 관계를 유지했으나 와일드해머 부족은 그림 바톨에서 목격했던 공포로 인해 많이 변해있었다. 그들은 산중의 땅속에 거대한 왕국을 짓기보다는 땅 위의 맹금의 봉우리에 사는 것을 택했다. 결국 이러한 이상의 차이로 두 드워프 부족은 각자의 길을 가게 되었다.'),
(1932, '수호자 에이그윈은 시간이 흐르면서 더욱 강해져 티리스팔의 에너지를 이용해 생명을 상당히 연장시켰다. 어리석게도 그녀는 살게라스를 영원히 해치 웠다고 착각하며 900년 가까이 악마의 제왕의 하수인들로부터 세계를 보호해 왔다. 그러나 티리스팔 의회는 이제 에이그윈의 수호자 역할이 끝날 때가 되었다고 선언했다.  '),
(1933, '의회는 에이그윈에게 수호자의 힘을 부여할 새로운 후임자를 선발할 수 있도록 달라란으로 돌아올 것을 명령했다. 하지만 항상 의회를 불신해오던 에이그윈은 자신이 직접 후임자를 선택하기로 결정했다.'),
(1934, '에이그윈은 자신의 마력을 물려줄 아들을 낳기로 마음 먹었다. 티리스팔 교단이 자신에게 그랬듯이 후임자를 마음대로 조종하도록 내버려두지 않을 생각이었다. 아제로스의 남쪽 나라로 내려간 에이그윈은 아들의 아버지가 되어줄 완벽한 남자를 만났으니 바로 니엘라스 아란이라는 능력 있는 인간 마법사였다. '),
(1935, '아란은 궁중 마법사이자 아제로스 왕의 고문이었다. 에이그윈은 이 마법사를 유혹해 아들을 갖게 되었다. 하지만 니엘라스의 선천적인 마법 친화력이 아직 태어나지 않은 아이의 내면깊숙이 파고들면서 훗날 이 아이가 밟게 될 비극을 만들어내고 있었다. 티리스팔의 마력도 아이에게 주입되었으나 이 마력은 아이가 신체적으로 성숙할 때까지 깨어나지 않도록 되어 있었다.'),
(1936, '시간이 흘러 에이그윈은 멀리 떨어진 조그만 외딴 숲에서 아들을 낳았다. 에이그윈은 아이에게 하이 엘프 언어로 "비밀의 수호자"라는 뜻의 메디브라는 이름을 지어주고 아이가 자라나 다음 수호자가 될 것이라 믿었다. 하지만 불행히도 그녀의 몸안에 숨어있던 살게라스의 사악한 어둠의 영혼이 아이가 뱃속에 있는 동안 아이를 점령해 버렸다. 하지만 에이그윈은 이제 막 세상에 태어난 새로운 세계의 수호자가 세계 최대의 적에게 점령당한 줄은 꿈에도 몰랐다.'),
(1937, '에이그윈은 틀림없이 아기가 건강하고 튼튼하다고 생각하여 어린 메디브를 아제로스의 궁전으로 데리고 가서 인간 아버지와 그 동족들의 손에 길러지도록 남겨두었다. 그리고는 황야로 가서 자신에게 다가올 죽음의 그림자를 기다렸다. 메디브는 강한 아이로 자라났지만 자신이 태어나면서부터 지니고 있는 티리스팔의 잠재적인 힘에 대해서는 전혀 알지 못했다.'),
(1938, '살게라스는 어린 메디브의 몸 속에서 메디브의 힘이 나타나길 기다리고 있었다. 나이가 십대에 접어들 즈음 메디브는 마법을 다루는 솜씨 덕분에 아제로스에서 아주 인기가 좋았다. 그리고 친구인 아제로스 왕자 레인과 아라티 혈통의 마지막 후손 중 하나인 안두인 로서와 모험을 떠나기도 했다. 이 세 소년들은 왕국을 돌아다니며 언제나 말썽을 부렸지만 백성들은 모두 이들을 좋아했다.'),
(1939, '메디브가 14살이 되자 내면에 깃들어 있던 광대무변한 힘이 깨어나면서 그의 영혼 속에 숨어 있던 살게라스의 영혼과 충돌을 일으켰다. 메디브는 혼수 상태에 빠져 여러 해를 보냈다. '),
(1940, '혼수 상태에서 깨어난 메디브는 자신이 성인이 되었으며 친구인 레인과 안두인이 아제로스의 고위 인물이 되었다는 것을 알게 되었다. 메디브는 놀라울 정도로 강한 자신의 새로운 힘을 자신이 고향이라 부르는 땅을 보호하는 데 사용하고 싶었지만 살게라스의 사악한 영혼이 그의 사상과 감정을 음흉한 쪽으로 몰고 갔다.'),
(1941, '어둠으로 물들어 가는 메디브의 마음 속에 숨어 있던 살게라스는 2차 세계 침략 계획이 거의 완성 단계에 이르렀고 이 세계의 마지막 수호자가 그 계획을 실현시켜 줄 것이라는 사실을 알고 몹시 기뻐했다.'),
(1942, '"아제로스에서 메디브가 태어날 즈음, 책략가 킬제덴은 뒤틀린 황천에서 자신의 추종자들에 둘러싸여 골똘히 생각에 잠겨 있었다. 그가 주인으로 섬기는 살게라스로부터 명령을 받은 이 교활한 악마 군주는 아제로스에 대한 불타는 군단의 2차 공격을 계획하고 있었다."'),
(1943, '이번에는 어떠한 실수도 용납되지 않을 것이었다. 킬제덴은 불타는 군단이 세계에 발을 내딛기 전에 아제로스의 방어력을 약화시킬 새로운 세력이 필요하리라고 생각했다. 나이트 엘프나 용과 같은 종족들이 새로운 위협에 맞서 싸우도록 만든다면 정작 불타는 군단이 침략했을 때는 제대로 저항할 수 없을 정도로 약해져 있을 것이라는 계산이었다.'),
(1944, '킬제덴이 끝없는 어둠 너머를 평화로이 떠다니는 푸른 드레노어 세계를 발견한 것은 바로 이때였다. 주술 문화를 가진 부족 중심의 오크와 평화로운 드레노어족이 사는 이 세계는 아름답기도 했지만 무엇보다 규모가 거대했다.'),
(1945, '고귀한 오크족은 넓은 초원을 누비며 사냥을 즐겼고 호기심이 강한 드레노어족은 세계의 높은 절벽과 봉우리 안에 천연 도시를 세웠다. 킬제덴은 드레노어에 사는 종족들을 잘 키우면 불타는 군단에게 큰 도움이 될 것이라고 생각했다.'),
(1946, '두 종족 중 오크 전사들이 불타는 군단의 타락에 더 쉽게 영향을 받는다는 것을 안 킬제덴은 오래전 살게라스가 아즈샤라 여왕을 지배했던 것처럼 오크의 주술사 장로인 넬쥴을 노예로 만들었다. 킬제덴은 이 교활한 주술사를 앞세워 오크 부족 전체에 전투에 대한 욕망과 만행을 퍼뜨렸다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(1947, '머지 않아 이 영적인 종족은 피에 굶주린 종족으로 변하고 말았다. 킬제덴은 넬쥴에게 마지막 단계로 그의 종족이 전적으로 죽음과 전쟁만을 추구할 것을 맹세하라고 부추겼다. 하지만 자신의 종족이 영원히 증오의 노예로 전락할 것을 느낀 넬쥴은 킬제덴의 명령에 불복종하게 되었다.'),
(1948, '넬쥴의 나약함 때문에 계획에 차질이 생기자 킬제덴은 동족을 불타는 군단에게 넘길 만한 다른 오크를 찾기 시작했다. 교활한 악마의 군주가 마침내 자신이 바라던 순종적인 제자를 찾게 되었으니 그가 바로 넬쥴의 야심 많은 수습생 굴단이었다. 킬제덴은 절대적인 복종의 대가로 굴단에게 거대한 힘을 주기로 약속했다.'),
(1949, '이 젊은 오크는 악마의 마법을 열심히 배우며 역사상 가장 강력한 흑마법사가 되었다. 굴단은 다른 젊은 오크들에게 악마의 마법을 가르치며 오크의 주술 전통을 폐지하려고 했다. 굴단은 지독한 멸망의 악취를 풍기는 끔찍한 새 마력을 자신의 동족에게 선보였다.'),
(1950, '킬제덴은 오크족에 대한 지배를 더욱 강화하고자 굴단이 부족을 조종하고 드레노어 전체에 흑마법을 퍼뜨릴 어둠의 의회라는 비밀 종파를 결성하도록 도와주었다. 어둠의 의회의 결성으로 더 많은 오크들이 흑마법을 사용하기 시작하면서 드레노어의 아름답던 들판과 시내가 빛을 잃으며 검게 변해갔다. 시간이 지나면서 오크족이 오랜 세월 고향이라 부르던 광활한 평원은 시들어 사라지고 황량한 붉은 땅만 남게 되었다. 악마의 힘이 이 세계를 서서히 파괴하고 있었던 것이다.'),
(1951, '오크족은 굴단과 어둠의 의회의 비밀스러운 조종 아래 점점 더 흉포해져 갔다. 그들은 거대한 격투장을 만들어 전투와 죽음을 경험하면서 전사의 실력을 갈고 닦았다. 이 기간 중 몇몇 부족장은 오크족이 점점 타락해 가는 데 대해 우려를 표하기도 했다.'),
(1952, '"서리늑대부족의 듀로탄 족장이 그 중 하나로, 그는 오크족이 증오와 분노에 굴복하는 것에 대해 경고했다. 하지만 전쟁노래부족의 그롬 헬스크림과 같이 전쟁과 정복의 새로운 시대를 주도하고자 하는 더욱 강력한 족장들이 등장하면서 듀로탄의 경고는 무시되고 말았다."'),
(1953, '킬제덴은 오크 부족의 준비가 거의 끝났다는 것을 알았지만 그들이 절대적인 충성을 바칠 것인지를 확실히 해야 했다. 그는 비밀리에 어둠의 의회를 시켜 파괴와 분노의 화신인 파괴자 만노로스를 소환했다. 굴단은 족장들을 한자리에 모아놓고 만노로스의 분노의 피를 마시면 천하무적이 될 수 있다고 설득했다.'),
(1954, '그롬 헬스크림을 시작으로 듀로탄을 제외한 모든 족장은 만노로스의 피를 마시고는 불타는 군단의 노예로 전락하고 말았다. 만노로스의 분노로 힘을 얻은 족장들은 운명을 예감하지 못한 채 아무것도 모르는 동족에게도 그 저주를 나누어주었다.'),
(1955, '"새로운 피의 욕망에 사로잡힌 오크족은 자신들의 길을 가로막는 자에게 그 분노를 폭발했다. 굴단은 때가 된 것을 느끼고 전쟁을 벌이고 있는 부족들을 통일해 단 하나의 멈출 수 없는 군단, 호드를 만들었다."'),
(1956, '그러나 굴단은 헬스크림이나 오그림 둠해머와 같은 여러 족장들이 서로 지배권을 차지하기 위해 싸우게 될 것을 알고 꼭두각시 대족장을 내세워 이 새로운 호드를 지배하기로 했다. 그 어떤 오크 족장보다 타락하고 사악한 파괴자 블랙핸드가 굴단의 꼭두각시로 선택되었다. 이 블랙핸드의 지휘 아래 호드는 단순한 드레노어족을 상대로 자신의 힘을 실험했다.'),
(1957, '불과 몇 달 만에 호드는 드레노어에 살고 있던 거의 모든 드레노어족을 완전히 해치워버렸다. 몇 안 되는 생존자만이 가까스로 오크의 두려운 분노를 피해 목숨을 건졌을 뿐이었다. 승리에 취해 흥분한 굴단은 호드의 힘을 확인하고 매우 기뻐했다. 하지만 싸울 적이 없는 호드는 대학살에 대한 멈추지 않는 욕망으로 끝없는 내전에 휩싸여 자멸해버릴 것 또한 그는 알고 있었다.'),
(1958, '킬제덴은 호드가 마침내 모든 준비를 마쳤다는 것을 알았다. 오크족이 마침내 불타는 군단의 가장 강력한 무기로 변한 것이다. 이 교활한 악마는 때를 기다리고 있는 자신의 군주에게 이 사실을 알렸고 살게라스도 마침내 복수의 시간이 왔다는 데 동의했다.'),
(1959, '"킬제덴이 호드의 아제로스 침공을 준비하는 동안 메디브는 살게라스로부터 자신의 영혼을 지키기 위해 힘겨운 싸움을 계속하고 있었다. 스톰윈드의 고귀한 군주, 레인 국왕은 자신의 옛 친구의 영혼을 타락시키는 듯한 어둠을 점점 더 경계하게 되었다."'),
(1960, '"레인 국왕은 전투 부관으로 임명된, 아라시 혈통의 마지막 자손인 안두인 로서와 근심을 나누었다. 하지만 서서히 광기에 빠져들고 있는 메디브가 가져오게 될 재앙에 대해서는 어느 누구도 예상하지 못했다."'),
(1961, '살게라스는 마지막 유인책으로 굴단이 아제로스로 호드를 이끌고 가는 데 동의할 경우 엄청난 힘을 주겠노라 약속했다. 살게라스는 메디브의 몸으로 나타나 거의 천년 전에 수호자 에이그윈이 살게라스의 손상된 몸을 안치한 해저 무덤을 찾으면 흑마법사 굴단에게 살아 있는 신이 될 수 있다고 말했다.'),
(1962, '굴단은 이에 응하여 아제로스에 살고 있는 자들을 모두 물리친 후 그 전설의 무덤을 찾아 보상을 받기로 결정했다. 호드가 자신의 뜻한 바를 이뤄 줄 것이라 확신한 살게라스는 침공 개시를 명했다.'),
(1963, '"메디브와 어둠의 의회 흑마법사들은 힘을 모아 어둠의 문이라고 하는, 차원을 넘나들 수 있는 통로를 열었다. 아제로스와 드레노어 사이의 먼 차원을 연결해 주는 이 문은 군대가 지날 수 있을 정도로 큰 크기였다. 굴단은 오크 정찰병을 어둠의 문 반대편으로 보내 자신들이 정복할 땅에 대해 조사하도록 했다. 돌아온 정찰병들은 아제로스 세계를 정복할 적당한 때가 되었다고 어둠의 의회에 자신 있게 보고했다."'),
(1964, '여전히 굴단의 타락이 자신의 동족을 파멸시킬 것이라 믿고 있던 듀로탄은 다시 한번 흑마법사들에게 이의를 제기했다. 이 용감한 전사는 흑마법사들이 오크 영혼의 순결함을 파괴하고 있으며 이 무모한 침공이 멸망을 가져오게 될 것이라 주장했다. 굴단은 차마 많은 이들의 호감을 사고 있는 영웅을 처치하는 위험을 감수할 수 없었기에 듀로탄과 서리늑대부족을 이 새로운 세계의 먼 구석으로 추방해 버릴 수밖에 없었다.'),
(1965, '서리늑대 부족을 어둠의 문 너머로 추방한 이후 매우 소수의 오크 부족만이 그 뒤를 따랐다. 이 오크족들은 스톰윈드 왕국 동쪽 먼 곳에 위치한 검은늪 안에 재빨리 작전 본부를 세웠다. 오크들이 여럿으로 갈라져 새로운 땅을 탐험하기 시작하면서 스톰윈드의 인간 수호병들과 즉각적인 충돌이 일어났다.'),
(1966, '이러한 작은 충돌은 빨리 마무리되는 것이 보통이었지만 이로 인해 양 종족의 강점과 약점이 많이 노출되었다. 레인과 로서는 오크족의 숫자에 대해 정확한 자료를 입수하지 못해 자신들이 얼마나 강한 군대를 상대해야 하는 것인지 추측만 할 수 있을 뿐이었다.'),
(1967, '"몇 년 후, 대다수의 오크 호드가 아제로스로 건너왔고 굴단은 인간에게 첫 공격을 감행할 때가 왔다고 판단했다. 호드는 아무 것도 눈치 채지 못하고 있는 스톰윈드 왕국을 전력을 다해 공격하기 시작했다."'),
(1968, '왕국 도처에서 아제로스 군대와 호드 군대가 충돌하면서 양 군대에서 내부적인 갈등이 빚어지기 시작했다. 레인 국왕은 야만적인 오크족에겐 아제로스를 정복할 만한 힘이 없다고 생각하여 얕잡아보며 수도인 스톰윈드에 머무르며 방어전을 벌이려 했다. 적진에 직접 쳐들어가야 한다고 판단한 로서 경은 국왕에 대한 충성과 자신의 신념 사이에서 어느 하나를 택해야만 했다.'),
(1969, '"자신의 본능을 따르기로 한 로서는 메디브의 젊은 수습생, 카드가의 도움으로 메디브의 탑 요새 카라잔을 급습했다. 카드가와 로서는 이번 충돌의 근본 원인으로 확인된 악마에 홀린 수호자 메디브를 처치하는 데 성공했다."'),
(1970, '메디브의 육체를 처치함으로써 로서와 카드가는 의도한 바는 아니었지만 살게라스의 영혼을 심연의 나락으로 추방해 버리게 되었다. 그 결과 메디브의 순수하고 고결한 영혼 역시 계속 살아남아 이후 오랜 세월 동안 천상계를 배회하게 되었다.'),
(1971, '메디브를 물리쳤음에도 불구하고 호드는 계속해서 스톰윈드의 방어 세력을 압도해 나갔다. 호드의 승리가 가까워 옴에 따라 가장 강대한 오크 족장들 중 하나인 오그림 둠해머는 드레노어에 있을 당시부터 부족들 전체에 퍼져 온 타락과 부패를 목격하기 시작했다.'),
(1972, '"그의 오랜 동지인 듀로탄은 유배에서 돌아와 굴단의 배반에 대해 다시 한번 경고해 주었다. 그러나 굴단은 즉시 자객들을 보내어 듀로탄과 그의 가족을 모두 살해하여 보복을 했고 오직 듀로탄의 젖먹이 아들만이 살아남게 되었다. 둠해머는 애델라스 블랙무어라는 인간 장교가 듀로탄의 젖먹이 아들을 발견하여 노예로 삼은 사실을 알지 못했다.\r\n\r\n바로 그 젖먹이 오크가 훗날 오크족 역사상 가장 위대한 지도자로 등장하게 된다."'),
(1973, '"듀로탄의 죽음에 분개한 오그림은 악마의 타락으로부터 호드를 구하기 위해 나섰고 마침내 굴단의 타락한 꼭두각시, 블랙핸드를 처치하고 호드 대족장의 자리에 올랐다. 그의 과감한 지도력 아래, 냉혹한 호드는 마침내 스톰윈드 요새를 포위 공격했다."'),
(1974, '"호드의 힘을 지나치게 과소평가했던 레인 국왕은 자신의 왕국이 녹색 피부를 가진 침략자들의 발 아래 무너지는 것을 가만히 지켜봐야만 했다. 결국 레인 국왕은 어둠의 의회 최고의 암살자 중 하나인 반오크, 가로나의 손에 암살되고 말았다."'),
(1975, '로서와 그의 전사들은 카라잔에서 고향으로 돌아오며 인명의 손실을 막고 한때 영광스러웠던 고향 땅을 구해 낼 수 있기를 소망했다. 하지만 너무 늦어버린 이 용사들을 맞이한 것은 자욱한 연기 속에서 폐허로 변해 버린 사랑하는 고향의 모습이었다. 오크 호드는 계속해서 지방 거주지들을 파괴하며 주변의 땅을 차지해 나갔고 일단 몸을 피할 수밖에 없었던 로서와 그의 동료들은 어떠한 대가를 치르더라도 반드시 고향 땅을 되찾겠다고 굳게 맹세했다.'),
(1976, '로서 경은 스톰윈드 요새에서의 패배 이후 아제로스 군대의 패잔병들을 규합하여 바다 건너 북쪽 로데론 왕국으로 대규모 탈출을 시작했다. 호드를 그대로 방치해 둘 경우 인간 종족 전체를 말살하고 말 것이라 확신한 일곱 인간 국가의 지도자들은 한자리에 모여 훗날 로데론의 얼라이언스라 알려지게 될 연합을 결성하는 데 합의했다.'),
(1977, '거의 3천 년 만에 처음으로 서로 흩어져 있던 아라소르 국가가 다시 하나의 공동 깃발 아래 모이게 된 것이었다. 얼라이언스군의 총사령관으로 지명된 로서 경은 그의 군대를 호드의 침공에 대비시켰다.'),
(1978, '"또한 로서는 빛의 수호자 우서와 댈린 프라우드무어 제독, 투랄리온과 같은 부관들의 도움으로 눈 앞에 닥친 위협에 대해 로데론의 반인 종족을 설득할 수 있었다. 얼라이언스는 아이언포지의 무뚝뚝한 드워프족과 쿠엘탈라스의 소수의 하이 엘프들의 지원을 얻는 데 성공했다."'),
(1979, '당시 아나스테리안 선스트라이더가 이끌던 엘프들은 다가오는 충돌에 대해서는 별로 관심이 없었지만 로서가 오래 전에 엘프들을 도와줬던 아라시 혈통의 마지막 자손이었기에 그에게 도움을 줄 의무가 있었다.'),
(1980, '이제 대족장 둠해머가 이끄는 호드는 고향 세계인 드레노어로부터 오우거들을 불러들였고 엘프들에게 자신의 땅을 빼앗긴 아마니 숲 트롤들까지 징집해 끌어들이고 있었다. 호드는 드워프 왕국 카즈 모단과 로데론의 남부 지방을 침략하기 위한 대규모 전쟁을 시작하면서 모든 저항 세력을 힘들이지 않고 괴멸시켰다.'),
(1981, '"2차 대전쟁의 장대한 전투는 대규모 해전에서 대규모 공중 혼전까지 그 범위가 실로 넓었다. 우여곡절 끝에 호드는 악마의 영혼이라 불리는 강력한 유물을 발굴했고 그것을 이용해 고대의 용, 여왕 알렉스트라스자를 노예로 만들었다. 호드는 그녀의 소중한 알을 파괴해 버리겠다고 위협하며 알렉스트라스자에게 그녀의 자식들인 성체가 된 용들을 전쟁에 내보낼 것을 강요했고 숭고한 붉은용들은 어쩔 수 없이 호드를 위해 싸워야만 했다. 아주 치열하게..."'),
(1982, '"이 전쟁은 카즈 모단과 로데론, 아제로스 대륙 전체를 휩쓸었다. 호드는 북방 전쟁의 일환으로 경계지인 쿠엘탈라스를 불질러 파괴하는 데 성공했으며 이로 인해 엘프들은 결정적으로 얼라이언스의 대의에 대한 헌신을 다짐하게 되었다. 이 전투로 로데론의 보다 큰 도시와 마을들이 남김 없이 파괴되었다. 증원군도 없이 압도적인 수적 열세 상황에서 싸웠음에도 불구하고 로서와 그의 동맹군은 적을 더 이상 접근하지 못하도록 하는 데 성공했다."'),
(1983, '"하지만, 2차 대전쟁 말, 얼라이언스에 대한 호드의 승리가 거의 확실시 되었을 무렵 아제로스에서는 가장 강력한 두 오크 부족 간에 격렬한 싸움이 일어났다. 둠해머가 얼라이언스의 나머지 병사들을 쳐부수기 위해 수도인 로데론에 대한 마지막 공격을 준비하고 있을 때, 굴단과 그의 추종자들은 각자의 임무를 뒤로 한 채 바다로 향했다."'),
(1984, '당황한 둠해머는 굴단의 배반에 병사의 절반을 잃고 얼라이언스를 물리칠 수 있는 최대의 기회를 포기한 채 후퇴해야 했다.'),
(1985, '힘에 굶주린 굴단은 스스로 신의 권위를 얻어야겠다는 집착에 사로잡혀 엄청난 힘의 비밀을 간직하고 있다고 생각한 바다 밑 살게라스의 무덤을 찾아 나섰다. 이미 오크 동지들에게 불타는 군단의 노예가 될 운명임을 선고한 굴단은 둠해머에 대한 충성의 의무는 전혀 생각하지 않았다.'),
(1986, '굴단은 폭풍의 약탈자와 황혼의 망치단의 지원을 받아 바다 밑 살게라스의 무덤을 끌어올리는 데 성공했다. 하지만 물이 가득 찬 그 고대의 무덤 안에서 그를 기다리고 있던 것은 미쳐버린 악마들뿐이었다.'),
(1987, '굴단의 배반으로 너무나 큰 희생을 치러야 했던 둠해머는 제멋대로인 오크들을 처벌하기 위해 군대에게 굴단을 죽이고 변절자들을 데려오라고 지시했다. 한편 굴단은 자신의 무모한 행동으로 풀려난 미친 악마들의 손에 찢겨 죽고 말았다. 한순간에 지도자를 잃어버린 변절 부족들은 얼마 가지 못해 둠해머의 성난 군대 앞에 무릎을 꿇어야 했다.'),
(1988, '변절자들의 반란은 진압됐지만 그로 인해 입게 된 엄청난 손실은 되찾을 길이 없었다. 굴단의 배반으로 얼라이언스는 희망을 찾았을 뿐 아니라 다시 모여 복수할 시간까지 벌게 되었다.'),
(1989, '호드의 내부 분열을 지켜본 로서 경은 나머지 병사들을 모아 남쪽으로 폐허가 된 스톰윈드의 중심부까지 둠해머의 군대를 몰아갔다. 그곳에서 얼라이언스 군대는 후퇴하는 호드를 검은바위 첨탑이라는 화산 요새에 가두어 버렸다. 로서 경은 첨탑 아래서 전투를 벌이다 쓰러졌지만 부관인 투랄리온은 가까스로 얼라이언스 군대를 재집결해 슬픔의 늪으로 호드를 다시 몰아넣었다.'),
(1990, '투랄리온의 군대는 오크의 고향인 드레노어로 통하는 신비한 어둠의 문을 파괴하는 데 성공했다. 지원이 끊기고 계속되는 내분에 지친 호드는 결국 얼라이언스 군대 앞에 무릎을 꿇고 굴복할 수 밖에 없었다.'),
(1991, '흩어진 오크 부족들은 즉시 얼라이언스 군대에 붙잡혀 수용소에 갇히게 되었다. 겉으로 보기에는 호드를 완전히 물리친 듯했지만 평화가 계속되리라는 생각에 여전히 회의적인 반응을 보이는 자들도 있었다. 이제 꽤나 이름을 떨친 대마법사 카드가는 네더가드 요새를 건설하고 어둠의 문을 철저하게 감시하여 더 이상 드레노어의 침략을 받는 일이 없도록 해야 한다고 얼라이언스 지휘관들을 설득했다.'),
(1992, '2차 대전쟁의 불길이 사그라들자 얼라이언스는 오크의 위협을 억압하기 위해 공격적인 조치를 취했다. 붙잡힌 오크를 수용하기 위한 대규모 수용소가 로데론 남부에 대거 건설되었다. 얼라이언스의 성기사와 노련한 병사들이 감시하는 이 수용소는 매우 성공적인 조치였다. '),
(1993, '붙잡힌 오크들은 다시 한번 전쟁을 치를 기회를 엿보며 긴장을 늦추지 않았지만 오랜 감옥 요새인 던홀드에서 근무하는 여러 수용소 감시자들은 평화와 질서를 굳게 유지하고 있었다.'),
(1994, '그러나 지옥 같은 드레노어 세계에서는 새로운 오크 군대가 방심하고 있는 얼라이언스를 공격할 준비를 하고 있었다. 한때 굴단의 스승이었던 넬쥴은 남아있던 오크 부족을 어둠의 깃발 아래 모았다. 넬쥴은 어둠의 달 부족의 도움으로 드레노어에서 몇 개의 문을 열어 손상되지 않은 새로운 세계를 호드를 이끌려 했다. '),
(1995, '새로운 문에 힘을 불어넣기 위해서는 아제로스에서 몇 가지 유물을 가져와야 했다. 그 유물들을 손에 넣기 위해 넬쥴은 어둠의 문을 다시 열어 탐욕스러운 수하들을 내보냈다.'),
(1996, '그롬 헬스크림과 피투성이굴 부족의 킬로그 데드아이와 같은 노력한 족장들을 앞세운 새로운 호드는 시골을 통해 얼라이언스 방어군을 기습하면서 사납게 돌진해 갔다. 넬쥴의 뛰어난 지휘 아래 오크들은 재빨리 필요한 물건을 모아 드레노어로 무사히 되돌아갔다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(1997, '로데론의 테레나스 국왕은 오크들이 또 다시 아제로스를 침략할 준비를 하고 있다고 판단하고 가장 믿음직한 부관들을 소집했다. 그는 투랄리온 장군과 카드가 대마법사에게 원정대를 이끌고 어둠의 문을 지나 오크의 위협을 완전히 제가할 것을 명령했다. 투랄리온과 카드가의 군대는 드레노어로 진격해 가다 폐허가 된 지옥불 반도에서 넬쥴의 부족과 충돌해 전투를 벌였다. '),
(1998, '하이 엘프 알레리아 윈드러너와 드워프 쿠르트란 와일드해머, 노병 다나스 트롤베인의 도움까지 받았지만 결국 카드가는 넬쥴이 다른 세계로 연결되는 문을 여는 것을 막아내지 못했다.'),
(1999, '넬쥴은 마침내 다른 세계로 통하는 문을 열었으나 그것으로 치르게 될 끔찍한 대가에 대해서는 예상하지 못했다. 문에서 나오는 엄청난 힘에 드레노어의 구조가 무너지기 시작한 것이다. 투랄리온의 군대가 고향인 아제로스로 돌아가기 위해 필사적으로 싸우는 동안에도 드레노어 세계는 붕괴되고 있었다. 그롬 헬스크림과 킬로그 데드아이는 넬쥴의 무모한 계획이 오크족 모두를 말살시키게 될 것이라 깨닫고는 나머지 오크들을 모아 비교적 안전한 아제로스로 피했다.'),
(2000, '드레노어에서는 투랄리온과 카드가가 자신들의 위치에서 어둠의 문을 파괴해 끝까지 희생할 것에 동의했다. 비록 자신과 동료의 목숨을 잃게 될지언정 그것만이 아제로스를 구하는 길임을 알고 있었던 것이었다. 헬스크림과 데드아이가 자유를 찾기위해 필사적으로 인간과 맞서 싸우고 있을 때조차 그들 뒤에서 어둠의 문이 폭발했다. 이제 그들과 아제로스의 나머지 오크들은 다시는 되돌아갈 수 없게 된 것이다.'),
(2001, '넬쥴과 그의 충성스러운 어둠의 달 부족이 새로 만들어진 문 중 가장 큰 문을 지나가는 순간 엄청난 화산 폭발이 일어나면서 드레노어의 대륙이 갈라지기 시작했다. 불타는 바다가 일어나 갈라진 땅덩어리를 삼키면서 고통 받던 이 세계는 마침내 종말을 맞이하게 되었다.'),
(2002, '넬쥴과 그의 추종자들은 끝없는 암흑 너머 전역에 흩어져 있는 모든 세계들을 연결하는 천상계인 뒤틀린 황천으로 들어서게 되었다. 하지만 유감스럽게도 그들을 기다리고 있던 것은 킬제덴과 그의 악마 부하들이었다. 건방지게 반항했던 넬쥴에게 복수할 것을 맹세했던 킬제덴은 그 늙은 주술사의 몸을 천천히 갈기갈기 찢어놓았다.'),
(2003, '그러면서 넬쥴의 영혼은 죽이지 않고 살려 두어 자신의 몸이 갈갈이 찢기는 고통을 느끼도록 했다. 넬쥴은 악마 같은 킬제덴에게 자신의 영혼이 잠들 수 있게 풀어달라고 애원했지만 킬제덴은 오래 전에 맺은 피의 서약이 아직도 유효하며 아직도 자기를 섬길 의무가 있다고 단호하게 못박았다.'),
(2004, '불타는 군단이 의도했던 오크족의 세계 정복에 실패하자 킬제덴은 새로운 군대를 만들어 아제로스 왕국 전체에 혼돈의 씨앗을 뿌려야 했다. 이 새로운 군대는 호드처럼 사소한 경쟁이나 내분에 빠져들어선 안 되고 주어진 임무에만 전념해 이를 무자비하게 이행해야 했다. 킬제덴으로서는 이번에야말로 실패해서는 안 되는 것이었다.'),
(2005, '"넬쥴의 무력한 영혼을 사로 잡고 있던 킬제덴은 그에게 불타는 군단을 섬길 것인가 아니면 영원한 고통에 시달릴 것인가에 대한 마지막 선택권을 주었다. 무모하게도, 넬쥴은 다시 한번 이 악마의 서약에 동의했다. 넬쥴의 영혼은 뒤틀린 황천의 깊숙한 곳에서 가져온, 특별히 만들어진 다이아몬드처럼 단단한 얼음 덩어리 속에 안치되었다."'),
(2006, '"넬쥴은 이 얼음 속에 갇힌 채 자신의 의식이 만 배나 확장되는 것을 느꼈다. 악마의 혼돈 마력으로 뒤틀린 넬쥴은 헤아릴 수 없는 힘을 가진 유령과 같은 존재로 변했다. 바로 그 순간, 넬쥴이라는 이름의 오크는 영원히 사라지고 리치 왕이 탄생한 것이다."'),
(2007, '넬쥴에게 충성을 바치던 죽음의 기사와 어둠의 달 부하들도 악마의 혼돈 에너지에 의해 변형되었다. 사악한 마술사들은 갈가리 찢어져 해골 리치로 다시 태어났고 악마들은 넬쥴의 부하들이 죽은 뒤에라도 넬쥴에게 절대 복종하도록 조치하였다.'),
(2008, '"때가 됐을 때, 킬제덴은 리치 왕이 어떤 임무를 수행하기 위해 창조되었는지를 설명해주었다. 넬쥴의 임무는 아제로스 전역에 죽음과 공포의 역병을 퍼뜨려 인간 문명을 영원히 말살시키는 것이었다. 이 끔찍한 역병으로 죽은 이들은 언데드로 환생하게 되었고 그들의 영혼은 넬쥴의 철통 같은 의지에 영원히 묶이게 될 것이었다."'),
(2009, '킬제덴은 이 세상에서 인간들을 말끔히 없애 버리는 이 사악한 임무를 완수하면 지금의 저주에서 해방시키고 건강한 육체를 새로 주겠다고 넬쥴에게 약속했다.'),
(2010, '비록 넬쥴은 이에 유쾌하게 응하고 서둘러 자신의 역할을 수행하고 싶어했지만 킬제덴은 여전히 자신의 앞잡이로서 넬쥴의 충성을 의심하고 있었다. 육체 없이 수정 속에 담겨 있는 리치 왕은 잠시 동안은 착실히 임무를 수행하게 되겠지만 킬제덴은 그를 철저히 감시해야 한다는 것을 알고 있었다. 이를 위해 그는 자신의 정예 악마 경비병인 흡혈 종족 공포의 군주들을 소환해 넬쥴이 사악한 임무를 제대로 완수하는지 잘 감시하도록 했다.'),
(2011, '공포의 군주들 중에서 가장 강하고 교활한 티콘드리우스는 역병의 가혹함과 리치 왕에게 내재된 대량 학살의 난폭한 잠재력에 매혹되어 이 감시 임무를 맡았다.'),
(2012, '"킬제덴은 넬쥴이 든 얼음 수정을 아제로스의 세계로 내던졌다. 단단한 수정은 밤하늘을 가르며 날아가 북극의 황량한 대륙, 노스렌드에 떨어져 얼음왕관 빙하 속 깊숙이 묻혔다. 떨어질 때의 심한 충격으로 모양이 일그러지고 손상된 이 얼어붙은 수정은 왕좌의 모양을 띠게 되었고 곧 그 속에서 복수심에 불타는 넬쥴의 영혼이 움직이고 있었다."'),
(2013, '넬쥴은 얼음 왕좌에 갇힌 채로 자신의 광활한 의식을 펼쳐 노스렌드 토착 주민의 의식에 다다랐다. 거의 힘도 들이지 않고 그는 얼음 트롤이나 사나운 웬디고와 같은 수많은 토착 생물들의 의식을 사로잡을 수 있었고 이들의 사악한 동족들을 점점 커져 가는 자신의 어둠 속으로 끌고 들어왔다. 넬줄의 정신 에너지는 거의 한계가 없었으며 그는 이를 사용해 작은 군대를 만들어 얼음왕관 빙하의 비틀어진 미궁 안에 배치해 두었다.'),
(2014, '공포의 군주들의 끊임없는 감시 아래 리치 왕은 커져 가는 자신의 능력을 제어하는 방법을 통달해 가면서 넓디넓은 용의 황폐지 끝에 있는 외딴 인간 거주지를 발견했다. 넬쥴은 무방비 상태의 인간들에게 자신의 힘을 시험해 보기로 했다.'),
(2015, '넬쥴은 얼음 왕좌의 깊숙한 곳에서 나온 불사의 역병을 이 북극 황무지에 퍼뜨렸다. 그는 자신의 뜻대로 역병을 조절해 이를 인간 마을에 곧장 퍼뜨렸고 사흘 안에 그 마을에 살던 모든 사람이 죽어 곧 좀비로 환생하기 시작했다. 넬쥴은 이들 각각의 영혼과 생각을 마치 자신의 것처럼 생생하게 느낄 수 있었다.'),
(2016, '그의 의식 속에서 격동하는 영혼의 불협화음은 마치 넬쥴에게 꼭 필요한 영양분을 공급하기라도 하듯이 그를 더욱 강하게 만들어 주었고 넬쥴은 좀비들의 행동을 조종하며 마음대로 부리는 것이 어린애 장난처럼 쉬운 일이라는 것을 알게 되었다.'),
(2017, '"그 후 몇 달 동안 넬쥴은 계속해서 불사의 역병을 시험하며 노스렌드에 거주하는 모든 인간들을 정복했고, 날마다 늘어나는 언데드 군단을 보며 진정한 시험의 때가 다가오고 있다는 것을 알았다."'),
(2018, '한편 전쟁으로 폐허가 되어버린 남쪽 땅에서는 흩어진 호드 패잔병들이 생존을 위해 싸우고 있었다. 그롬 헬스크림과 전쟁노래 부족은 겨우 붙잡히지 않고 피할 수 있었지만 데드아이와 피투성이굴 부족은 붙잡혀서 로데론의 수용소에 갇히게 되었다. 많은 희생을 치른 반란이었음에도 불구하고 수용소의 감시자들은 곧 그들을 다시 통제할 수 있었다.'),
(2019, '하지만 아직도 얼라이언스에게 알려지지 않은 거대한 오크 군대 하나가 카즈 모단의 북부 황무지를 돌아다니고 있었다. 악명 높은 흑마법사 네크로스가 이끄는 붉은용부족이 악마의 영혼으로 알려진 고대 유물을 사용해 용의 여왕 알렉스트라자와 그녀의 용군단을 조종하고 있었다. 용의 여왕을 인질로 삼은 네크로스는 일부 사람들이 저주 받았다고도 하는 그림 바톨의 버려진 와일드해머 요새에서 비밀리에 군단을 모집했다.'),
(2020, '그는 자신의 군대와 힘센 붉은용들을 얼라이언스에 풀어놓을 계획을 세우고 호드를 다시 통일해 계속해서 아제로스를 정복하고자 했다. 그러나 인간 마법사 로닌이 이끄는 소규모 저항 세력이 악마의 영혼을 파괴하고 용의 여왕을 네크로스에게서 구하는 데 성공함으로써 네크로스의 비전은 실현되지 못했다.'),
(2021, '"분노한 알렉스트라자의 용들은 그림 바톨을 파괴하고 붉은용부족의 절반 이상을 태워 없애버렸다. 네크로스가 계획한 오크의 재통일이라는 원대한 꿈은 얼라이언스 군대가 나머지 오크 생존자들을 붙잡아 수용소에 가둬버림으로써 물거품으로 사라졌다. 붉은용부족의 패배는 호드의 종말, 그칠 줄 모르는 오크의 피를 향한 열망에 대한 종말을 알린 것이었다."'),
(2022, '여러 달이 지나면서 수용소에 붙잡혀와 갇히는 오크의 수도 늘어갔다. 오크의 수가 계속해서 늘어나자 얼라이언스는 알터랙 산맥의 남쪽 평원에 새로운 수용소를 지어야만 했다. 테레나스 국왕은 늘어가는 수용소를 제대로 관리하고 필요한 물자를 공급하기 위해 얼라이언스 국가들에 새로운 세금을 부과했다.'),
(2023, '이 세금은 국경 문제를 둘러싸고 고조되어 있던 정치적 긴장 상태와 함께 사회적인 불안을 확산시켰다. 어두운 시기에 인간 국가들을 단결시켰던 불안한 조약이 곧 깨어질 듯했다.'),
(2024, '이러한 정치적 혼란 속에서 수용소의 감시자들은 오크 포로에게 불안한 변화가 찾아온 것을 느끼기 시작했다. 시간이 흐르면서 탈출을 시도하는 횟수나 서로 주먹질하며 싸우는 횟수가 크게 줄어든 것이다. 오크들은 갈수록 냉담하고 무기력해져 갔다.'),
(2025, '믿을 수 없게도 한때 아제로스에서 가장 공격적인 종족으로 알려졌던 오크들이 전투 의지를 완전히 상실해 버렸다. 이 이상한 무기력증 현상은 얼라이언스 지도자들을 당황케 했으며 오크들은 하루가 다르게 나약해져만 갔다.'),
(2026, '일부는 오크에게만 걸리는 어떤 이상한 질병 때문에 무기력증이 발생한 것이라고 추측했다. 하지만 달라란의 대마법사 안토니다스는 다른 가설을 내세웠다. 안토니다스는 오크 역사를 연구해본 결과 오크들이 오랜 세월 동안 악마의 힘에 의해 치명적인 영향을 받고 있다는 사실을 알게 되었다.'),
(2027, '"그는 오크들이 아제로스에 처음 침입하기 전부터 이미 이 힘에 타락되어 있었을 것이라고 주장했다. 그러면서 악마들이 오크의 피에 마력을 불어넣어 야만적인 오크의 힘과 체력, 공격성이 비정상적으로 향상된 것이라고 추측했다."'),
(2028, '안토니다스는 오크에게 나타난 무기력증은 실제로 질병이 아니라 그들을 피에 굶주린 무시무시한 전사들로 변화시킨 흑마법이 시간이 지나면서 사라져 발생한 종족적인 부작용이라는 이론을 세웠다.'),
(2029, '"증세가 분명했지만 안토니다스는 오크의 무기력증을 치유할 방법을 찾지 못했다. 그때도 마찬가지로, 많은 동료 마법사들을 비롯하여 몇몇 이름 있는 얼라이언스 지도자들도 오크를 위해 치료법을 찾는다는 것은 신중하지 못한 행동이라고 비난했다. 수수께끼 같은 오크의 상태를 두고 고심하던 안토니다스는 영적인 방법으로만 오크를 치유할 수 있다는 결론을 내렸다."'),
(2030, '"수용소 최고 교도소장인 애델라스 블랙무어는 그의 감옥 요새 던홀드에서 오크 포로들을 감시하고 있었다. 그 중 한 오크가 항상 그의 주의를 끌었는데, 그는 바로 자신이 약 18년 전에 주워 기른 고아 젖먹이였다. 블랙무어는 이 어린 오크 아이를 자신이 가장 총애하는 노예로 키우며 `스랄`이라는 이름을 지어 주었다. 블랙무어는 이 오크에게 전술과 철학, 전투에 대해 가르쳤고 투사로서의 훈련도 시켰다. 여기에는 이 오크를 하나의 무기로 만들어 내려는 타락한 교도소장의 속셈이 있었다."'),
(2031, '그러나 혹독한 훈련과 교육에도 불구하고 튼튼하고 기민한 오크로 성장한 스랄은 노예의 삶이 자신에게 어울리지 않는다는 것을 알았다. 성년으로 자라면서 스랄은 전쟁에 패배한 후 수용소에 갇혀 한번도 직접 만나본 적이 없는 자신의 민족에 대해서 알게 되었다. 자기 민족의 지도자인 둠해머가 로데론에서 탈출해 숨어 지낸다는 소문도 있었다. 하나의 부족만이 남아 얼라이언스의 눈을 피해 비밀리에 황야를 떠돌아 다니고 있다는 것도 알게 되었다.'),
(2032, '능력은 있었지만 아직 경험이 부족한 스랄은 블랙무어의 요새를 탈출해 자신의 동족을 찾아 나서기로 마음먹었다. 여행 중 수용소에 들린 스랄은 한때 강대했던 종족이 이상하게도 위축되고 무기력해져 있는 모습을 보게 되었다. 자신이 기대했던 자랑스러운 전사들을 찾지 못한 스랄은 아직 패하지 않은 마지막 오크 족장인 그롬 헬스크림을 찾아 나섰다.'),
(2033, '끊임없이 인간에게 쫓기고 있던 헬스크림은 여전히 꺼질 줄 모르는 호드만의 전투 의지를 지니고 있었다. 헬스크림은 자신에게 헌신적으로 충성하는 전쟁노래 부족의 도움만으로 쫓기는 동료들을 위해 비밀리에 전쟁을 계속했다. 안타깝게 헬스크림도 붙잡힌 오크들을 무기력증에서 깨어나게 할 방법을 알지 못했다. 감수성이 예민한 스랄은 헬스크림의 이상주의에 감명을 받아 호드와 그 전사의 전통에 크게 공감하게 되었다.'),
(2034, '스랄은 자신의 출생에 대한 진실을 찾아 북쪽으로 전설의 서리늑대 부족을 찾아 나섰다. 스랄은 서리늑대 부족이 1차 대전쟁 초기에 굴단에 의해 추방당했다는 사실을 알았다. 그리고 자신이 거의 20년 전 황야에서 살해당한 서리늑대 부족의 진실한 족장이자 오크의 영웅인 듀로탄의 아들이며 후계자인 것도 알게 되었다.'),
(2035, '스랄은 드렉타르라는 훌륭한 주술사 아래서 굴단의 사악한 통치로 잊혀져버린 자기 민족의 고대 주술 문화를 배웠다. 시간이 흘러 스랄은 강력한 주술사로 성장해 추방된 서리늑대 부족장의 자리에 당당히 올랐다. 자연으로부터 힘을 부여 받은 스랄은 자신의 운명을 찾겠다는 의지를 품은 채 사로잡힌 부족을 해방하고 악마의 힘에 타락한 동족을 치유하기 위해 길을 떠났다.'),
(2036, '여행 중에 스랄은 오랜 세월을 은둔자로 살아온 늙은 족장 오그림 둠해머를 찾게 되었다. 스랄의 아버지와 절친한 친구 사이였던 둠해머는 이 젊고 통찰력 있는 오크를 따라 붙잡힌 부족을 해방시키는 일을 돕기로 했다. 스랄은 수많은 노병 족장들의 도움을 받아 마침내 호드에게 활력을 되찾아주고 동족에게 새로운 영적 정체성을 일깨워주는 데 성공했다.'),
(2037, '"동족의 부활을 상징하기 위해 스랄은 던홀드 요새로 되돌아가 수용소를 공격함으로써 한 때 주인이었던 블랙무어의 계획을 과감히 무산시켜 버렸다. 하지만 대가 없는 승리란 없는 법, 수용소의 동족들을 구하던 중 둠해머가 전장에서 죽음을 맞이하였다."'),
(2038, '스랄은 둠해머가 지니고 있던 전설의 전투해머와 검은 갑옷을 손에 넣고 호드의 새로운 대족장이 되었다. 그 후 몇 개월 동안 스랄이 이끄는 작지만 생기 넘치는 호드는 수용소를 폐허로 만들며 호드의 뛰어난 전략에 대항하려는 얼라이언스의 노력을 수포로 만들었다. 스랄은 절친한 친구이자 스승인 그롬 헬스크림의 격려를 받으며 어떤 오크도 다시는 노예로 전락하지 않도록 최선을 다했다.'),
(2039, '스랄이 로데론에서 동포들을 해방시키는 동안 넬쥴은 계속해서 노스렌드에 자신의 세력 거점을 마련했다. 거대한 요새가 얼음왕관 빙하 위에 세워지고 죽은 자들의 군단이 배치되었다. 하지만 리치 왕이 이 땅에 대한 영향력을 키워 가는 동안에도 그의 힘에 맞서는 어둠의 제국이 있었다.'),
(2040, '"극악한 인간 거미 종족이 건설한 고대 지하 왕국, 아즈졸네룹이 정예 경비병을 보내 얼음왕관을 공격하고 권세를 거머쥐려는 리치 왕의 미친 시도를 끝장내려 한 것이었다. 넬쥴은 이 사악한 네룹인들이 역병뿐만 아니라 자신의 정신적 지배에도 면역성이 있는 것을 알고는 좌절했다."'),
(2041, '네룹 거미 군주들은 거대한 군대를 지휘했으며 그들의 지하 세계는 노스렌드 너비의 거의 절반이나 되는 크기였다. 그들은 리치 왕의 요새를 치고 빠지는 전략으로 공격해 이들을 근절하려는 리치 왕의 시도는 번번이 실패했다. 결국에는 전쟁은 소모전으로 치달아 넬쥴이 승리했고 넬쥴은 극악한 공포의 군주들의 도움을 받아 무수한 언데드 전사들을 이끌고 아즈졸네룹을 공격해 마침내 거미 군주들을 격파하고 그들의 지하 사원을 허물어 버렸다.'),
(2042, '"네룹인들은 역병에 대해 면역성이 있었지만 점점 커가는 강령술의 힘을 빌려 넬쥴은 이 거미 전사들의 시체를 환생시키고 자신의 뜻에 굴복시킬 수 있었다. 그들의 끈기와 대담함에 대한 증언으로, 넬쥴은 네룹인들의 특이한 건축 스타일을 도입해 자신의 요새와 건물에 사용했다."'),
(2043, '자신의 왕국에 저항하는 자들이 없어지자 리치 왕은 이 세계에서 행할 진정한 임무를 수행할 준비를 하기 시작했다. 리치 왕은 자신의 광범위한 의식을 인간의 땅으로까지 펼쳐 자신의 부름을 듣는 모든 어두운 영혼들을 불렀다.'),
(2044, '리치 왕의 정신적 부름을 들은 자들 중에는 세계 각처의 강한 힘을 가진 개인들이 몇몇 있었다. 그 중 가장 두드러진 자는 달라란의 대마법사 켈투자드였는데 그는 달라란의 지도 의회인 키린 토의 상급 의원 중 하나였다. 켈투자드는 금지된 강령술에 대한 연구를 고집하다 오랫동안 이단자로 간주되어 왔었다.'),
(2045, '강령술의 마법 세계와 그 암흑의 불가사의를 모두 배우고 싶어한 그는 동료들의 계율을 시대에 뒤떨어지고 상상력이 결여된 것으로 보며 실망하고 있었다. 때마침 노스렌드에서의 강력한 소환을 들은 그는 이 수수께끼의 목소리와 대화하기 위해 모든 의지력을 쏟아 부었다. 켈투자드는 키린 토가 강령술에 내재된 힘과 지식을 이해하기에는 너무 보수적이라 판단하고 여기에서 탈퇴해 이 강력한 리치 왕에게서 배우기로 했다.'),
(2046, '켈투자드는 부와 정치적 명예를 버리고 키린 토의 관습을 저버린 채 달라란에서 영원히 떠나가 버렸다. 리치 왕의 끊임없는 음성에 이끌려 그는 자신의 많은 소유물들을 팔아 재산을 다른 곳에 보관해 두었다. 리치 왕에게 봉사하고자 혼자서 산을 넘고 물을 건너 마침내 노스렌드의 얼어 붙은 해안에 도착한 그는 얼음왕관에 도달해 전쟁으로 파괴된 아즈졸네룹의 폐허를 지나갔다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2047, '이곳에서 켈투자드는 넬쥴의 힘의 잔인함과 그 세력 범위를 직접 확인했고 이 수수께끼 같은 리치 왕의 편에 서는 것은 현명한 일이며 앞으로 많은 것을 얻을 수도 있음을 깨닫기 시작했다.'),
(2048, '"거친 북극 황무지를 몇 달 동안 오래 돌아다닌 켈투자드는 마침내 암흑 빙하, 얼음왕관에 도달했다. 그는 넬쥴의 암흑 요새에 당당히 다가갔다. 그런데 마치 그를 기다리고 있기라도 한 듯 언데드 경비병들이 아무 말 없이 그를 지나가게 해주었고 켈투자드는 이에 놀랐다."'),
(2049, '"켈투자드는 차가운 땅 속으로 깊숙이 내려가 빙하 바닥에 이르렀다. 그곳, 끝없는 얼음 동굴과 암흑 속에서, 그는 얼음 왕좌 앞에 엎드려 자신의 영혼을 죽은 자들의 어둠의 지배자에게 바쳤다."'),
(2050, '리치 왕은 새로운 신하를 보고 크게 기뻐했다. 그는 켈투자드에게 충성과 복종에 대한 보상으로 불로불사와 막대한 힘을 약속했고 암흑의 지식과 힘을 몹시 얻고 싶어한 켈투자드는 인간의 세계로 나가 리치 왕을 섬기는 새로운 교단을 설립하는 자신의 첫 임무를 받아들였다.'),
(2051, '"이 대마법사가 임무를 완수하는 것을 도와주기 위해 넬쥴은 켈투자드의 인간성을 그대로 두었다. 나이가 들었어도 아직 강한 카리스마를 갖고 있던 켈투자드는 환각 능력과 설득력을 이용해 로데론에서 시민 자격을 박탈 당하고 학대 받는 무리들에게 신뢰감을 심어 주라는 지시를 받았다. 일단 그들의 주목을 받게 된 후, 사회에 대한 새로운 이상과 그들의 왕이라 부를 새로운 인물을 제시하게 될 것이었다."'),
(2052, '변장을 하고 로데론에 되돌아온 켈투자드는 이후 3년 동안 자신의 재산과 지성을 이용해 비밀리에 비슷한 생각을 가진 남녀를 불러모았고 저주받은 자들의 교단이라고 불리는 이 단체는 수행사제들에게 넬쥴에 대한 봉사와 복종에 대한 보상으로 사회적 평등과 영생을 약속했다.'),
(2053, '시간이 흐르면서 켈투자드는 로데론의 너무 많은 짐을 지고 지쳐 버린 노동자들 중에서 수많은 지원자들을 찾을 수 있었다. 놀랍게도 켈투자드는 성스러운 빛에 대한 시민들의 믿음을 넬쥴의 어두운 그림자에 대한 믿음으로 바꾸어 놓는 목표를 아주 쉽게 달성했다. 저주받은 자들의 교단의 크기와 영향력이 점점 커지자 켈투자드는 로데론 권력층의 눈길을 피해 교단의 일을 비밀로 유지하려 했다.'),
(2054, '"로데론에서 있었던 켈투자드의 성공으로 리치 왕은 인간 문명에 대한 공격을 감행하기 위한 마지막 준비를 마쳤다. 그의 역병의 힘을 역병 가마솥이라는 이동 가능한 용기 여러 개에 담은 후, 넬쥴은 켈투자드에게 이 가마솥들을 로데론으로 수송하라고 명령했다. 그리고 그곳에서 이교도 집단이 장악한 여러 마을 안에 가마솥들을 숨겨 놓을 계획이었다."'),
(2055, '그러면 충성스러운 이교도들의 보호를 받은 가마솥은 전염병 생성기로 작동하게 되고 아무 것도 눈치채지 못하고 있는 로데론 북부의 농장과 도시들에 역병을 퍼뜨리게 되는 것이었다.'),
(2056, '"리치 왕의 계획은 완벽하게 성공하여 로데론 북부 마을들 중 다수가 거의 즉시 오염되었다. 노스렌드에서와 마찬가지로, 역병에 걸린 주민들은 죽음을 맞았고 그 후 리치 왕의 자발적인 노예로 되살아났다."'),
(2057, '켈투자드 수하의 이교도들은 기꺼이 죽어 어둠의 지배자의 충성스러운 신하로 다시 살아나기를 자처했다. 그들은 언데드로 불사의 몸이 될 수 있으리라는 희망에 기뻐 날뛰었다. 역병이 번지면서 북부 지역에 점점 더 많은 수의 흉포한 좀비들이 나타났다. 켈투자드는 점점 더 수가 불어나는 리치 왕의 군대를 지켜보며 `스컬지`라 이름 붙였다. 이는 곧 로데론 성문으로 진격해 이 세계에서 인류를 완전히 제거해 버릴 것이라는 의미를 담고 있었다.'),
(2064, '여러 달 동안 준비를 해오던 켈투자드와 그의 저주받은 자들의 교단은 마침내 로데론에 언데드 역병을 퍼뜨리며 첫 공격을 감행했다. 우서와 그의 성기사 동료들은 감염된 지역을 조사해 이 역병을 멈출 방법을 찾으려 했다. 그러나 그들의 노력에도 불구하고 역병은 점점 더 퍼지면서 얼라이언스를 분열시킬 지경에 이르고 있었다.'),
(2065, '언데드의 대열이 로데론 전역을 휩쓸고 다니자 테레나스의 외아들 아서스 왕자가 스컬지에 맞서 싸우기 위해 나섰다. 아서스는 켈투자드를 쓰러뜨리는 데 성공했지만 영토를 지키던 병사들이 하나씩 쓰러질 때마다 언데드 대열은 늘어만 갔다. 거의 천하무적으로 보이는 적을 만나 지치고 좌절한 아서스는 적을 제압하기 위해 갈수록 극단적인 조치를 취했다. 이에 아서스의 동지들은 그가 인간으로서의 모습을 잃어 가고 있다고 경고했다.'),
(2066, '"아서스의 두려움과 결의는 점점 파멸로 이어졌다. 그는 역병의 위협을 영원히 제거하기 위해 노스렌드까지 역병의 근원을 추적했다. 하지만 오히려, 아서스 왕자는 결국 리치 왕의 엄청난 힘 앞에 무릎을 꿇고 말았다. 아서스는 그의 백성을 구하는 길이라 생각하고 저주 받은 룬문자 검, 서리한을 집어들었다."'),
(2067, '이 검은 아서스에게 헤아릴 수 없는 강력한 힘을 부여했지만 대신 그의 혼을 빼앗아 리치 왕의 최정예 죽음의 기사로 만들어 버렸다. 혼을 빼앗겨 제정신을 잃은 아서스는 스컬지를 이끌고 자신의 왕국을 공격했다. 결국 자신의 아버지 테레나스 국왕을 살해한 아서스는 로데론을 리치 왕의 철통 같은 발 아래 굴복시켜 버렸다.'),
(2068, '"아서스는 자신이 적으로 생각한 모든 이들을 물리쳤지만 그 후에도 계속해서 켈투자드의 유령에게 시달렸다. 켈투자드의 유령은 리치 왕이 세운 계획의 다음 단계를 실행하기 위해서는 자신이 환생해야 한다고 얘기했다. 아서스는 그를 환생시키기 위해서 하이 엘프의 영원한 왕국, 쿠엘탈라스 안에 숨겨져 있는 신비한 태양샘으로 켈투자드의 시체를 가져가야만 했다."'),
(2069, '아서스와 그의 스컬지 군대는 쿠엘탈라스를 침공해 엘프족의 무너져 가는 방어 전선에 공격을 가했다. 실버문의 순찰대 사령관 실바나스 윈드러너의 용맹한 저항에도 불구하고 아서스는 결국 하이 엘프 군대를 전멸시키고 태양샘까지 도달했다. 아서스는 자신의 권위를 나타내기 위해 잔인하게도 실바나스의 쓰러진 육체를 밴시로 소생시켜 언데드로 영원히 쿠엘탈라스의 새로운 정복자를 섬기도록 만들었다.'),
(2070, '마침내 아서스는 켈투자드의 시체를 태양샘의 거룩한 물 속에 담갔다. 이로 인해 강력한 힘을 지닌 영원의 물은 오염되었지만 켈투자드는 마술사 리치로 환생했다. 훨씬 더 강력한 존재로 환생한 켈투자드는 리치 왕 계획의 다음 단계를 설명했다.'),
(2071, '아서스와 그의 언데드 군대가 남쪽으로 향했을 때, 쿠엘탈라스에는 살아남은 엘프가 단 한 명도 없었다. 9천 년 넘게 찬란했던 하이 엘프의 고향은 더 이상 존재하지 않았다.'),
(2072, '켈투자드가 다시 살아나자 아서스는 스컬지를 이끌고 달라란을 향해 남쪽으로 이동했다. 그곳에서 켈투자드는 강력한 메디브의 마법서를 탈취해 그 책을 이용해 아키몬드를 이 세계로 다시 소환했다. 이 시점부터 아키몬드는 불타는 군단의 마지막 침공을 직접 개시하게 된다. 키린 토의 마법사들마저도 메디브의 마법서를 지키지 못했고 곧 켈투자드는 마법을 수행하는 데 필요한 모든 준비를 갖추었다.'),
(2073, '"1만 년이 지난 후 강력한 악마 아키몬드와 그의 수하들이 다시 한번 아제로스 세계에 들어왔지만 그들의 최종 목적지는 달라란이 아니었다. 킬제덴의 직속 수하에 있는 아키몬드와 그의 부하 악마들은 언데드 스컬지를 따라 칼림도어로 향했다. 세계수, 놀드랏실을 파괴하러 가는 것이었다."'),
(2074, '이런 혼돈의 와중에서 불가사의한 예언자 하나가 필멸의 종족들을 인도하기 위해 나타났다. 이 예언자는 다름 아닌 최후의 수호자 메디브였다. 그는 과거에 저지른 자신의 죄악에 대한 속죄를 하기 위해 타계로부터 기적적으로 되돌아온 것이었다. 메디브는 호드와 얼라이언스에게 다가오는 위험에 대해 경고하며 서로 손을 잡을 것을 촉구했다.'),
(2075, '"하지만 수세대에 걸쳐 쌓인 서로 간의 증오때문에 오크와 인간의 동맹은 결코 이루어질 수 없었다. 메디브는 하는 수 없이 각 종족을 개별적으로 상대해 예언과 속임수를 써서 그들을 바다 건너에 있는 전설의 대륙, 칼림도어로 인도했다. 곧 오크와 인간들은 오랜 세월 동안 숨겨져 있던 칼도레이 문명을 마주하게 되었다."'),
(2076, '스랄이 이끄는 오크들은 칼림도어의 불모의 땅을 지나가며 여러 번 좌절을 겪었다. 케른 블러드후프와 그의 강한 타우렌 전사들의 도움에도 불구하고 많은 오크들이 오랜 세월 동안 자신들을 괴롭혀 왔던 사악한 피의 욕구에 굴복하기 시작했던 것이었다. 스랄의 최고 부관인 그롬 헬스크림마저도 자신의 본능에 굴복해 호드를 배반하고 말았다.'),
(2077, '헬스크림과 그의 충성스런 전쟁노래 부족 전사들은 잿빛 골짜기 숲을 은밀히 지나가던 중 고대 나이트 엘프족 파수꾼들과 충돌하게 되었다. 오크들이 또 다시 호전적으로 변한 것이라 확신한 반신 세나리우스는 앞에 나서 헬스크림과 그의 오크 부하들을 몰아내야 했다. 그러나 초자연적인 증오와 분노에 사로잡힌 헬스크림과 그의 오크 부하들은 간신히 세나리우스를 처치하고 고대 숲 지역을 타락시켰다.'),
(2078, '"결국, 헬스크림은 스랄을 도와 맨 처음 자신의 증오와 분노의 혈통으로 오크족에게 저주를 내렸던 악마 군주 만노로스를 물리침으로써 스스로를 구원했고  만노로스의 죽음으로 오크의 피의 저주는 마침내 종결되었다."'),
(2079, '메디브가 오크와 인간에게 동맹의 필요성에 대해 납득시키는 동안 나이트 엘프들은 비밀스러운 방법으로 불타는 군단과 싸웠다. 나이트 엘프 파수꾼들의 불멸의 대사제 티란데 위스퍼윈드는 악마들과 언데드가 잿빛 골짜기 숲에 퍼지는 것을 막기 위해 안간힘을 다해 싸웠다. 도움이 필요하다는 것을 깨달은 티란데는 천년 동안 잠들어 있는 나이트 엘프 드루이드들을 깨우기 위해 떠났다.'),
(2080, '자신의 아주 오랜 연인인 말퓨리온 스톰레이지를 불러낸 티란데는 방어 전선을 재정비하고 불타는 군단을 몰아내는 데 성공했다. 말퓨리온의 도움으로 불타는 군단과 스컬지 동맹군을 무찌르기 위해 이제 자연 그 자신이 직접 일어난 것이었다.'),
(2081, '긴 잠을 자고 있는 더 많은 다른 드루이드들을 찾던 말퓨리온은 자신의 형제인 일리단을 속박해 두었던 고대 감옥을 발견했다. 티란데는 일리단이 불타는 군단과의 전쟁에서 자신들을 도와줄 것이라 믿고 마술사인 그를 풀어 주었다. 일리단은 한동안 그들을 도와주었지만 결국 자신의 이익을 좇아 달아나 버렸다.'),
(2082, '나이트 엘프들은 더욱 분발하여 불굴의 투지로 불타는 군단과 싸웠다. 불타는 군단은 오랜 세월 동안 세계수의 힘의 근원이자 나이트 엘프 왕국의 중심인 영원의 샘에 대한 욕망을 결코 버리지 않았다. 세계수에 대해 계획한 공략이 성공할 경우 악마들은 말 그대로 이 세계를 갈가리 찢어 놓게 되는 것이었다.'),
(2083, '불타는 군단이 잿빛 골짜기를 침공하는 동안 일리단은 1만 년 동안 갇혀 있던 무덤 감옥에서 풀려 났다. 그는 한동안 동지들을 달래기 위해 노력했지만 곧 자신의 본 모습으로 되돌아가 굴단의 해골이라 불리는'),
(2084, '흑마법사 유물의 강력한 기운을 에너지를 집어삼켰다. 이렇게 함으로써 일리단은 악마적인 면모를 개발하고 엄청나게 증폭된 힘을 갖게 되었다. 또한 그는 굴단의 오랜 기억의 일부를 손에 넣었는데, 특히 함흑의 티탄, 살게라스의 시체가 안치되어 있다는 소문이 있는 섬인 살게라스의 무덤에 대해 알게 되었다.'),
(2085, '막대한 힘을 가지고 다시 한번 세상을 마음껏 누비게 된 일리단은 광대한 이 세상에서 자신만의 자리를 찾기 위해 떠났다. 그러나 일리단과 맞닥뜨린 켈제덴은 일리단이 거절할 수 없는 제안을 한 가지 했다. 킬제덴은 하이잘 산에서 아키몬드가 패배한 것에 분개하고 있었지만 복수보다는 걱정이 더 컸다. '),
(2086, '자신이 창조한 리치 왕이 제어하기 힘들 정도로 너무 강해지고 있음을 느낀 킬제덴은 일리단에게 넬쥴을 처단하고 언데드 스컬지를 영원히 파멸시켜 버릴 것을 지시했다. 그 대가로 일리단은 이에 동의하고 즉시 리치 왕의 영혼이 갇혀 있는 얼음 수정 통인 얼음 왕좌를 파괴하러 나섰다.'),
(2087, '일리단은 얼음 왕좌를 파괴하기 위해서는 강력한 유물이 필요하게 될 것을 알았다. 그리고 굴단의 기억에서 얻은 정보를 토대로 살게라스의 무덤을 찾아 이 암흑의 시체를 차지하기로 했다. '),
(2088, '그는 오래 전의 빛을 요구하며 뱀처럼 생긴 나가를 그의 바다 밑 소굴에서 나오도록 불러냈고 교활한 마녀, 여군주 바슈지의 인도를 받는 나가는 살게라스의 무덤이 있다고 소문 난 부서진 섬에 일리단이 갈 수 있도록 도와주었다.'),
(2089, '일리단이 나가와 함께 떠나자 교도관 마이에브 섀도우송이 그를 추격하기 시작했다. 마이에브는 지난 1만 년 동안 일리단을 감시해 온 교도관으로서 다시 일리단을 붙잡아 두게 될 것이라는 생각에 기뻐했다. 그러나 일리단은 마이에브와 그녀의 감시자들을 따돌리고 그들을 피해 살게라스의 눈을 차지하는 데 성공했다. 이 강력한 살게라스의 눈을 손에 넣은 그는 옛 마법사 도시, 달라란으로 갔다.  '),
(2090, '그 도시의 마력선들로 힘이 강화된 일리단은 살게라스의 눈을 이용해 노스랜드에 위치한 리치 왕의 머나먼 요새, 얼음왕관에 파괴적인 마법 주문을 사용했다. 일리단의 공격은 리치 왕의 방어막을 산산이 부수고 세계의 지붕마저 찢어 버렸다. 마지막 순간에 일리단의 파괴적인 마법 주문은 그의 형제 말퓨리온과 여사제 티란데가 마이에브를 도우러 옴으로써 중단되었다.'),
(2091, '얼음 왕좌를 파괴하지 못한 데 대해 킬제덴이 노하게 될 것을 안 일리단은 오크의 옛 고향 드레노어의 마지막 남은 부분인 바깥땅이라는 황야의 차원으로 도망쳤다.'),
(2092, '그곳에서 킬제덴의 분노를 피하며 자신이 취할 다음 행동을 생각해 볼 계획이었다. 일리단이 제지되는 것을 본 말퓨리온과 티란데는 고향인 잿빛 골짜기 숲으로 돌아와 그들의 동족을 돌봤다. 그러나 마이에브는 쉽게 포기하지 않고 일리단을 따라 바깥땅으로 가서 그에게 정의의 처단을 내리고자 했다.'),
(2093, '"이 즈음, 언데드 스컬지는 로데론과 쿠엘탈라스를 유독한 역병지대로 본질적으로 변형시켜 버렸다. 그곳에는 아주 소수의 얼라이언스 저항 세력만이 남아 있었다. 그 중 하나는 주로 하이 엘프들로 이루어진 무리로, 선스트라이더 왕조의 마지막 후손인 캘타스 왕자가 이끌고 있었다."'),
(2094, '캘타스는 그 자신도 상당한 실력을 지닌 마법사였다. 단절된 하이 엘프들은 자신들의 고향 땅을 잃은 것에 대해 슬퍼하며 쓰러져 간 동족들을 기리기 위해 스스로를 `블러드 엘프`라 부르기로 결정했다. 그러나 스컬지의 접근을 저지하기 위해 동분서주하는 동안 그들에게 힘을 주던 태양샘으로부터 단절되어 엄청난 고통을 겪었다.'),
(2095, '마법에 중독된 동족을 치료할 치료제를 찾기 위해 안간힘을 쓰던 캘타스는 상상도 할 수 없는 일을 저질렀다. 바로 힘을 얻을 수 있는 새로운 마력의 근원을 찾기 위한 기대로 자기 동족의 귀족 혈통을 받아들여 일리단 및 그의 나가족과 손을 잡은 것이었다. 나머지 얼라이언스 사령관들은 블러드 엘프를 반역자로 낙인 찍어 영원히 추방했다.'),
(2096, '더 이상 갈 곳이 없어진 캘타스와 블러드 엘프들은 일리단을 따라 바깥땅으로 이동하여 일리단을 다시 붙잡았던 감시자 마이에브와 맞섰다. 나가와 블러드 엘프의 연합 세력은 가까스로 마이에브를 무찔러 마이에브가 더 이상 일리단을 쫓아 다니지 못하게 만들었다. 바깥땅에 자리잡은 일리단은 다시 한번 리치 왕과 그의 얼음왕관 요새를 치기 위해 군대를 모았다.'),
(2097, '"리치 왕, 넬쥴은 자신의 시간이 얼마 남지 않았다는 것을 알았다. 얼음 왕좌 안에 갇힌 그는 킬제덴이 첩자를 보내 자신을 파멸시킬 것이라 생각했다. 얼음 왕좌는 일리단의 마법 주문의 영향을 받아 손상되었고 이에 따라 리치 왕은 날마다 그 힘을 잃어 가고 있었다. 스스로 자신을 구하기를 간절히 원하던 그는 가장 아끼는 필멸의 신하, 죽음의 기사 아서스 왕자를 곁에 불러들였다."'),
(2098, '"리치 왕이 쇠약해짐에 따라 그 자신의 힘도 약해진 아서스는 로데론에서 내란을 수습하고 있었다. 언데드 군대 중 절반이 밴시 실바나스 윈드러너의 지휘 아래 언데드 제국을 장악하기 위한 쿠데타를 일으킨 것이었다. 리치 왕의 부름을 받은 아서스는 역병지대 전역에서 전쟁의 물결이 거세어져 가는 와중에 스컬지를 자신의 부관, 켈투자드의 손에 맡기고 떠나야만 했다."'),
(2099, '"결국, 실바나스와 포세이큰이라 불리는 그녀의 언데드 반란군은 폐허가 되어 버린 로데론의 수도를 점령했다. 허물어진 이 도시 밑에 자신들의 보루를 건설한 포세이큰은 스컬지를 물리치고 이 땅에서 켈투자드와 그의 졸개들을 몰아낼 것을 맹세했다."'),
(2100, '쇠약해졌음에도 불구하고 자신의 주인을 구하겠다는 의지로 노스렌드에 도착한 아서스가 만나게 된 것은 그를 기다리고 있던 일리단의 나가와 블러드 엘프들뿐이었다. 아서스와 그의 네룹인 동지들은 얼음왕관 빙하로 가서 얼음 왕좌를 수호하기 위해 일리단의 군대와 경주를 벌이게 되었다.'),
(2101, '"비록 쇠약해진 상태였지만 아서스는 결국 일리단을 제치고 얼음 왕좌에 도착했다. 아서스는 자신의 룬문자 검, 서리한으로 리치 왕의 얼음 감옥을 부수고 넬쥴의 마법 투구와 흉갑을 꺼냈다."'),
(2102, '"상상을 초월할 정도로 강력한 투구를 머리에 쓴 아서스는 스스로 새로운 리치 왕이 되었다. 넬쥴이 계속 계획해 왔던 대로 넬쥴과 아서스의 영혼은 한데 어우러져 하나의 강력한 존재가 되었다. 아서스는 세계 역사상 가장 강력한 존재 중 하나가 된 반면, 일리단과 그의 군대는 치욕스럽게도 바깥땅으로 도망치듯 후퇴할 수밖에 없었다."')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2103, '"현재 소문에 의하면, 새로운 불멸의 리치 왕 아서스는 노스렌드에 거처하며 얼음왕관 요새를 재건하고 있다고 한다. 그가 신뢰하는 부관 켈투자드는 역병지대에서 스컬지를 지휘하고 있고, 실바나스와 그녀의 포세이큰 반란군은 전쟁으로 파괴된 왕국의 작은 부분인 티리스팔 숲만을 차지하고 있다."'),
(2104, '"필멸의 종족들은 비록 승리는 했지만 전쟁으로 갈갈이 찢긴 세계에 남아 있는 자신들을 발견했다. 스컬지와 불타는 군단은 로데론 문명을 거의 남김없이 파괴해 버렸고 칼림도어에서도 사정은 거의 마찬가지였다. 치유해야 할 숲과 묻어 두어야 할 원한, 그리고 정착해야 할 고향 땅이 있었다. 전쟁은 각 종족에게 깊은 상처를 남겼지만 모두 사심을 버리고 힘을 합쳐 새로운 시작을 도모했다. 이러한 노력은 얼라이언스와 호드 사이의 불편한 휴전 협정으로 시작되었다."'),
(2105, '스랄이 이끄는 오크족은 칼림도어 대륙에서 타우렌 동지들의 도움으로 새로운 삶의 터전을 잡았다. 오크들은 그들의 새로운 땅을 스랄의 살해된 아버지의 이름을 따 듀로타라 명명하고 그곳에 정착해 한때 영광스러웠던 자신들의 사회를 재건하고자 했다.'),
(2106, '"악마의 저주가 끝난 지금, 한때 호전적인 파괴자였던 호드 무리는 너그러운 상태로 변했다. 이제는 정복보다는 생존과 번영에 주력하게 된 것이다. 고귀한 타우렌과 머리 좋은 검은창 부족 트롤의 도움으로 스랄과 그의 오크들은 새로운 고향 땅에서 평화의 새 시대를 기대하고 있었다."'),
(2107, '제이나 프라우드무어가 이끄는 나머지 얼라이언스군도 칼림도어 남부에 정착했다. 그들은 먼지진흙 습지대 동부 해안에 굳건한 항구 도시 테라모어를 건설했다. 그곳에서 인간과 드워프 동맹은 그들에게 혹독하기만 한 땅에서 생존을 위해 노력했다. 듀로타와 테라모어의 수호자들은 모두 서로 간에 일시적인 휴전 상태를 유지했지만 식민지에서의 깨지기 쉬운 평온함은 오래 지속될 수 없는 것이었다.'),
(2108, '오크와 인간 사이의 평화는 칼림도어에 대규모 얼라이언스 함대가 도착하면서 깨어졌다. 제이나의 아버지인 총사령관 댈린 프라우드무어가 지휘하는 강력한 해군은 아서스가 왕국을 파괴하기 전에 로데론을 떠나 있었다. 프라우드무어 함장은 힘겹게 수개월 동안 항해하며 얼라이언스 생존자들을 찾고 있었다.'),
(2109, '"프라우드무어의 대규모 함단은 그 지역의 안정에 심각한 위협을 불러왔고 2차 대전쟁에서 영웅으로 명성을 얻은 제이나의 아버지는 호드의 강한 적으로, 오크들이 다시 땅에 발붙이기 전에 듀로타를 파괴해 버리려 했다."'),
(2110, '"총사령관 프라우드무어는 제이나에게 끔찍한 결정을 내리도록 했다. 그것은 그녀의 새로운 동족들을 배신하고 오크와의 전쟁에서 아버지를 돕느냐, 아니면 스랄과 오크족의 편에서 겨우 이루어 낸 얼라이언스와 호드 간의 깨지기 쉬운 평화를 지키기 위해 아버지와 싸우냐 하는 것이었다. 심사숙고 끝에 제이나는 후자를 선택했고 미쳐 버린 자신의 아버지를 물리치기 위해 스랄을 도왔다."'),
(2111, '"불행히도, 제이나가 아버지와 화해하거나 오크족이 더 이상 피에 굶주린 괴물이 아니라는 것을 증명해 보이기도 전에 프라우드무어 제독은 전장에서 숨을 거두었다. 그녀의 신의를 확인한 오크들은 제이나의 군대가 고향인 테라모어로 무사히 돌아갈 수 있도록 해 주었다."'),
(2131, '전사 트롬카. 자네의 용맹과 힘에 아첨할 생각은 없네. 이미 다 옛날 얘기니까. 최근에 인간 좀 죽였나? 많지는 않겠지. 힘이 빠지는군. 도전이 없으니 나약해지고 있어.\n\n내겐 일손이 더 필요해. 자네 아첨꾼들이 뭐라고 하든, 내가 해줄 수 있는 훈련이 자네에게 필요해. 그 말을 네 둔한 머리에 새겨넣을 때쯤이면, 동굴 바로 바깥 나무 그늘 아래에서 기다리고 있겠네.\n\n-프랑, 전사 훈련관'),
(2151, '"아렐라스 파이어리프\r\n붉은십자군의 고위 마법사\r\n쿠엘탈라스 시민\r\n강령술사 디샐븐과의 영원한 전투 속에 갇힘"'),
(2152, '제독 바리안 웨스트윈드\n붉은십자군 함대의 총사령관\n쿨티라스 시민\n노스렌드의 얼어붙은 해안에서 실종됨'),
(2153, '도르가르 스톤브로\r\n\r\n붉은십자군의 전사 \r\n\r\n붉은 집회의 군주 \r\n\r\n알터렉 산맥에서 마지막으로 목격됨'),
(2171, '펠라리 스위프트애로우\n\r붉은십자군의 순찰대장\n\r쿠엘탈라스 시민\n\r은빛소나무 숲에서 실종됨'),
(2172, ' 페렌 마커스\r\n\r\n붉은십자군 수도원의 대수도원장 \r\n\r\n스트라솔름 시민\r\n\r\n첫번째 대공습에서 붉은십자군 수도원을 방어하는 도중 전사함'),
(2173, '하르탈 트루사이트\r\n\r\n붉은십자군의 성기사\r\n\r\n아제로스 시민이자 은빛 성기사단원\r\n\r\n저주받은 도시, 스트라솔름으로 진입하는 모습이 마\r\n\r\n지막으로 목격됨'),
(2174, '"홀리아 선쉴드\r\n붉은십자군의 수호자\r\n공포의 군주 벨테리스를 처치하는 도중 전사함"'),
(2175, '외팔이 인바르\n붉은십자군의 암살단장\n달라란 시민\n노스렌드 해안에서 마지막으로 목격됨'),
(2176, '"스트롬가드의 오르만\r\n붉은십자군의 초대 총지휘관\r\n스트롬가드 시민\r\n얼음왕관 빙하 입구에서 실종됨"'),
(2177, '발리아 트윈블레이즈 \n붉은십자군의 전사\n알터랙 시민 \n동부 역병지대 깊숙한 곳에서 마지막으로 목격됨'),
(2178, '"야나 블러드스피어\r\n붉은십자군의 암살부단장\r\n달라란 시민\r\n티리스팔 숲에서 실종됨"'),
(2191, '"나이트 엘프가 불타는 군단의 분노를 불러내는 어리석은 짓을 범하기 훨씬 전인 16,000여 년 전, 트롤 종족은 당시 하나의 대륙이었던 칼림도어의 많은 부분을 지배했다. 그러다 쌍둥이 제국이 일어서게 되었으니, 남동부 밀림의 구루바시 제국과 중앙 산림지대의 아마니 제국이 그것이었다."'),
(2192, '"북쪽 멀리, 지금의 노스렌드로 알려진 지역에는 작은 부족들이 살았다. 이 부족들은 군드라크라는 작은 국가를 세웠지만 남부 제국들만큼 영토를 확장하거나 번성하지는 못하였다."'),
(2193, '"구루바시 제국과 아마니 제국은 서로를 미워했지만 전쟁을 치르는 일은 거의 없었다. 당시 두 제국에게 아즈아퀴르 제국이라는 커다란 공동의 적이 있었다. 아퀴르는 지능이 발달한 곤충들로서 머나먼 서쪽 지방을 지배했는데, 이들은 확장 능력이 엄청난데다 믿을 수 없을 만큼 사악했다. 아퀴르는 칼림도어 대륙에서 곤충이 아닌 생명체를 완전히 말살하겠다는 생각에 사로잡혀 있었다."'),
(2194, '트롤은 수천 년간 그들과 싸웠지만 완전한 승리를 거두지는 못했다. 하지만 결국 트롤의 끈질긴 투쟁으로 아퀴르 왕국의 시민들이 대륙의 먼 북부와 남부에 있는 거주지로 각각 흩어지면서 왕국은 둘로 분리되었다.'),
(2195, '"이로 인해 두 개의 아퀴르 도시국가가 일어섰으니, 북부 황무지의 아즈졸네룹과 남부 사막의 안퀴라즈가 그것이다. 트롤은 칼림도어 땅 속에 다른 아퀴르 거주지가 있을 것이라 추측했지만 확인되지는 않았다."'),
(2196, '곤충들을 몰아낸 두 트롤 제국은 다시 평상시의 모습으로 돌아갔다. 그러나 위대한 승리를 거두었음에도 불구하고 어느 제국도 원래 국경에서 멀리 영토를 확장하지는 못했다. 그러나 고대 서적에는 아마니 제국에서 갈라져 나온 소규모 트롤 부족이 대륙의 어두운 중심부에 그들만의 새로운 도시를 만들었다고 기록되어 있다.'),
(2197, '"이 용감한 개척자들은 그곳에서 무한한 영원의 샘을 발견했고, 이 영원의 샘 덕분에 엄청난 힘을 가진 종족으로 변하게 되었다. 이 모험심 강한 트롤이 나이트 엘프의 근원이었다는 얘기도 전해지지만 입증된 바는 없다."'),
(2198, '"나이트 엘프의 근원은 불분명하지만, 나이트 엘프가 힘을 갖게 된 것이 영원의 샘을 발견한 직후라는 사실은 확실하다. 트롤은 나이트 엘프의 영토 확장을 막아보려고 했으나 나이트 엘프는 강대한 제국을 건설하고 원시 칼림도어 대륙을 빠르게 점령해 나갔다. 미신을 믿는 트롤이 일찍이 상상하지도 못한 강한 마법을 휘두르던 나이트 엘프는 사악한 아퀴르마저 이루지 못한 일을 쉽게 이루고야 말았다. 바로 거대한 쌍둥이 제국을 무너뜨린 것이었다."'),
(2199, '"나이트 엘프는 트롤의 방어선과 보급망을 조직적으로 붕괴시켜 나갔다. 나이트 엘프의 파괴적인 마법에 맞설 수 없었던 트롤은 결국 나이트 엘프의 학살에 굴복하고 말았다. 나이트 엘프는 야만적인 트롤만큼이나 교활하고 잔인하다는 것이 입증되었으며, 이로써 트롤의 영원한 증오와 경멸을 사게 되었다. 구루바시 제국과 아마니 제국은 불과 몇 년 만에 산산조각나고 만 것이다."'),
(2200, '결국 나이트 엘프도 자신들이 조종하려던 신비의 불길에 휘말리게 되었다. 함부로 마법을 사용하다가 이 세계에 불타는 군단을 불러들이게 된 것이다. 이 악마들은 나이트 엘프의 문명을 무참히 파괴해 버렸다. 불타는 군단이 트롤을 공격했는지에 대한 기록은 남아 있지 않지만 전투는 대륙 전체로 퍼져나갔을 것이다.'),
(2201, '고대의 전쟁이라 불리는 이 끔찍한 사건으로 결국 영원의 샘이 파괴되었고 그 충격으로 칼림도어 대륙이 분리되었다. 대륙의 중심부는 바다 밑으로 꺼져버렸고 그 자리에는 몇 개의 갈라진 대륙만이 남게 되었다.'),
(2202, '"이렇게 해서 아마니 제국과 구루바시 제국의 상당 부분이 오늘날의 쿠엘탈라스와 가시덤불 골짜기에 각각 남게 되었다. 아즈아퀴르 왕국인 아즈졸네룹과 안퀴라즈도 오늘날의 노스렌드와 타나리스에 각각 생존해 있다.\r\n\r\n두 트롤 문명은 그들이 알았던 원시 세계의 엄청난 파괴로 인해 그 세력은 약해졌지만 불굴의 트롤은 자신들의 파괴된 도시를 재건하고 예전의 권력을 되찾으려 했다."'),
(2203, '세계의 대재앙 이후 수백 년 동안은 트롤에게 아주 힘겨운 시간이었다. 파괴된 왕국에서 흔히 볼 수 있는 기근과 공포 때문이었다. 절박해진 구루바시 트롤들은 고대의 불가사의한 힘에 도움을 구하였다. 양 트롤 왕국이 모두 고대 신을 믿었지만 특히 구루바시 트롤들은 암흑 신으로 기울게 되었다.'),
(2204, '"영혼의 약탈자 학카르는 사악하고 피에 굶주린 영혼으로, 트롤의 부름을 듣고 그들을 도와주기로 하였다. 학카르는 피의 비밀을 구루바시 트롤에게 전해주고 가시덤불 골짜기와 남해의 일부 섬까지 그들의 문명을 확장할 수 있도록 도와주었다. 학카르는 구루바시 트롤들에게 큰 힘을 안겨주었지만 그 대가로 점점 더 많은 것을 요구하기 시작했다."'),
(2205, '이 피에 굶주린 신은 매일마다 자신에게 영혼을 바칠 것을 요구했다. 그는 언젠가 물리적인 세계에 들어가 모든 생명체의 피를 들이킬 날을 꿈꾸었다. 시간이 흘러 자신들이 도움을 받은 괴물의 정체를 알게 된 구루바시 트롤은 학카르에게 등을 돌렸다. 가장 강력한 부족들은 학카르와 아탈라이라는 학카르의 사제들에 맞서 일어섰다.'),
(2206, '학카르의 추종자와 구루바시 부족의 나머지 트롤들 사이에 일어난 끔찍한 전쟁에 대해서는 거의 기록된 것이 없다. 이제 막 싹을 틔우기 시작한 제국은 분노한 신과 반항적인 그의 자식들이 풀어놓은 마법으로 파괴되고 말았다. 이길 가능성이 전혀 없어 보이던 전쟁에서 트롤은 학카르의 화신을 물리치고 그를 이 세계에서 추방하는 데 승리했다.'),
(2207, '"아탈라이 사제들도 결국 수도인 줄구룹에서 쫓겨나 지도에도 없는 북쪽 늪지대에서 살아갈 수 밖에 없게 되었다. 그들은 이 늪지대에서 자신들의 몰락한 신, 아탈학카르에게 신전을 지어바치고 그 주인의 임무를 계속해 나갔다."'),
(2208, '"나머지 구루바시 부족은 큰 내전으로 폐허가 되어버린 땅을 떠나 각자 자신들의 길을 갔다. 백골가루부족, 붉은머리부족, 검은창부족은 가시덤불 골짜기에서 각자의 땅을 차지했다. 파괴된 제국에는 불안한 평화가 찾아왔지만 어떤 이들은 학카르가 다시 이 세상에 태어날 것이며, 그날이 오면 학카르가 이 세계를 통째로 집어삼킬 것이라는 예언에 대해 말하기도 했다."'),
(2211, '"전쟁노래부족 족장 그롬마쉬 헬스크림, 여기 잠들다.\r\n\r\n우리 부족의 저주는 그에게서 시작되어 그에게서 끝났도다.\r\n그의 이름은 우리의 고대 언어로 ""거인의 가슴""이라는 뜻이니라.\r\n만노로스 앞에 홀로 서서 자신의 피로써 우리의 자유를 산 그는 이 이름을 수백 번 받아 마땅하도다.\r\n\r\n록타 오그아르, 내 형제여. 전쟁노래가 영원히 그치지 않기를.\r\n\r\n-호드 대족장, 스랄"'),
(2212, '나는 저주 받았소! 한때 뾰족바위일족의 위대한 오우거 마법사였던 나는 우로크 둠하울에게 도전했다 그에게 마법을 빼앗기고 저주까지 받았소. 이제 나는 이 비참한 생물의 형상으로 호드마르 전당을 돌아다녀야 하오!$B$B나를 도와주시오! 우로크와 맞서 싸워 내 마법을 돌려주시오! 우로크는 늘 숨어 지내면서 큰 도전을 받아야만 나타나므로 그를 처치하는 게 쉬운 일은 아닐 것이오.$B$B하지만 우로크가 가장 믿는 대군주 오모크를 처치하면 그것을 도전으로 여기고 나타날 거요.$B$B계속해서 읽어보면 무슨 뜻인지 알 거요.'),
(2213, '대군주 오모크는 뾰족바위일족을 다스리고 있지만 우로크의 마법을 통해서 다스리고 있을 뿐이오. 우로크는 오모크에게 마법을 걸어 자신에게 도전하는 오우거 모두를 이길 수 있도록 했소. 그는 이 마법을 많이 사용했고 오모크의 방 위에 있는 마력의 장소에 희생자들의 해골이 쌓여 있다오.$B$B바로 그곳으로 가야 우로크와 맞설 수 있소.'),
(2214, '방패부대 야영지에서 날카로운 장창을 하나 찾으시오. 뾰족바위 오우거 영토로 들어가는 입구 근처의 취침용 돗자리 곁에 쌓여있곤 하지.$B$B장창을 구하면 대군주 오모크에게 달려가서 그를 처치하고 그의 머리를 장창에 꽂아두시오.$B$B그러면 진짜 도전할 준비가 된 것이오.'),
(2215, '뾰족바위일족 영토 위쪽의 그물걸이 통로를 지나 마력의 장소로 가시오. 그곳에는 우로크의 적과 경쟁자의 해골이 쌓여있소. 그곳에 오모크의 머리가 꽂힌 창을 꽂아두시오!$B$B창을 꽂아두면 우로크가 반드시 나타날 것이오... 하지만 아마 졸개들을 먼저 보낼 거요. 그 졸개들을 모두 물리치면 우로크가 직접 나타날게요.$B$B우로크를 처치하고 내 마법을 회수하시오. 내가 마법을 돌려받으면 꼭 사례하겠소이다.'),
(2216, '"행운을 빌겠소. 그리고 우로크의 졸개들을 처치할 때 도움이 될만한 정보를 하나 알려주리다.$B$B오모크가 오우거를 처치할 때 사용하는 마법은 당신이 오모크를 죽이고 나서도 효력이 지속될 수 있소. 우로크의 졸개들과 싸울 때 오모크의 머리에 담긴 마력을 불러내야 하는데, 운이 좋으면 오모크가 우로크의 졸개들을 내리칠 수도 있소!$B$B상황에 딱 맞는 아이러니라고 생각하오."'),
(2217, '사랑하는 제시 모레일즈'),
(2231, '누락된 텍스트'),
(2232, '아가샴,$b$b우리 계획은 무슨 수를 써서라도 반드시 비밀로 해야 한다! 다른 타우렌 부족이 우리 관계를 알면 심각한 사태가 벌어질 거야.$b$b서명,$b$b선구자 엘름'),
(2233, '아가샴,$b$b우리가 함께 손을 잡으면 타우렌 부족을 다 모은 것보다 훨씬 강해질 것이다! 하지만 그러려면 그대의 절대적인 복종이 필요하다. 그대의 백성들은 우리 계획이 완성되어야만 보상을 받게 된다는 것을 기억해 두어라!$b$b서명,$b$b선구자 렉스 '),
(2234, '아가샴,$b$b로데론에서 온 우리 요원들이 곧 그대의 대표단과 만날 것이다. 회담을 가질 만한 장소를 찾거든 연락 주겠다.$b$b서명,$b$b선구자 가라쿠스')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2251, '사방에서 적이 쳐들어온다.$B$B눈을 보면 알 수 있다. 우리의 적인 나무구렁일족은 악하다.$B$B일족을 보호해야 한다. 반드시 눈사태일족을 보호해야 한다. 우리 땅에서 침략자들을 몰아내야 한다.'),
(2271, '"나타카, 버섯구름 봉우리에선 모두 무사하오. 켄타우로스가 가끔씩 공격을 해와 성가시긴 하지만 실제로 위협적인 것은 아니고 말 그대로 성가신 것 뿐이오. 하지만 켄타우로스 부족이 결합하고 있다는 소문이 들리는 듯하오.\r\n\r\n\r\n우리는 항상 켄타우로스처럼 무자비한 종족이 단결하면 어떤 위협이 될까 궁금했는데... 그런 생각은 될 수 있으면 하고 싶지 않소. 알다시피 그 어떤 것도 녀석들이 가진 순수한 증오를 뚫을 수는 없소. 서로에 대한 증오까지도 말이오.\r\n\r\n\r\n- 절벽파수꾼 롱혼\r\n"'),
(2291, '"대주교 알론수스 파올\r\n\r\n빛의 교회의 인자한 수호 성인.\r\n\r\n그는 로데론의 스트라솔름에서 자선 행위를 시작했으며 과거에도 스톰윈드 주민들의 좋은 친구였다. 2차 대전쟁 후의 암울한 시대에는 노스샤이어의 결사단의 개혁을 돕고 스톰윈드를 다시 건설하는데 필요한 막대한 자금을 모금했다.\r\n\r\n이 대성당은 성스러운 빛의 보루일 뿐만 아니라 한 인간의 고귀한 영혼과 아량에 대한 영구불변의 증거인 것이다."'),
(2292, '"린 가문의 국왕 레인 1세\r\n\r\n스톰윈드의 군주\r\n\r\n아제로스의 수호자"'),
(2293, '"얼라이언스 함대의 사령관\r\n\r\n스톰윈드의 친구"'),
(2294, '"여군주 마라 포드래곤\r\n\r\n스톰윈드의 고위성직자\r\n\r\n1차 대전쟁 후에 로데론으로 피난간 사람들의 수호 성인.\r\n\r\n그녀는 미래의 현명한 어머니상이었다. 성스러운 빛의 품에서 편히 쉬기를."'),
(2295, '기억의 시대 이전에 온화한 대지모신께서 여명의 금빛 안개 위로 입김을 불어넣으셨다. 황색 구름이 쉬러 오는 곳에는 바람결에 일렁이는 밀밭과 보리밭이 끊임없이 이어져 있었으니, 위대한 희망과 생명의 마구니, 이것이 대지모신의 근원이다.'),
(2296, '대지모신께서 그대가 생명을 불어넣은 대지를 굽어 보시니 오른쪽 눈인 안쉬(해)는 대지에 온기와 빛을 주고 왼쪽 눈인 무샤(달)는 새벽녘에 꿈틀대는 생물에게 평화와 수면을 주었다. 대지모신의 눈빛이 이렇게도 강렬하니 하늘이 한 번 돌 때마다 꿈을 위해 한쪽 눈을 감으셨다. 그리하여 사랑으로 가득 찬 그 눈빛으로 세상의 첫 날을 낮에서 밤으로 바꾸셨다.   $B'),
(2297, '오른쪽 눈이 금빛 여명을 비추고 있을 때는 대지모신의 온화한 손길이 금빛 평원을 어루만졌고 대지모신의 팔 그림자가 지날 때마다 고결한 사람들이 그 풍족한 대지에서 일어났다. 수할로(타우렌)도 일어나 사랑을 베푸시는 어머니께 감사의 기도를 올리게되니 그 끝없는 여명의 들판에서 대지의 자식들은 대지모신의 은총에 맹세하고 세상이 끝날 때까지 그 이름을 축복하기로 맹세했다.'),
(2298, '하지만 대지의 자식들이 여명의 들판을 배회할 때 세상의 밑바닥 깊은 곳에서 들려오는 어둠의 속삭임에 귀를 기울이게 되니 대지의 자식들은 어둠의 속삭임으로부터 전쟁과 책략을 배우게 되었다. 수할로 중 상당수가 어두운 그림자에 넘어가 악의와 사악함을 받아들이게 되고 더렵혀지지 않은 동지들을 배반한 후 그들의 순결한 영혼은 결국 평원을 표류하게 되었다.'),
(2299, '이 참상에 마음이 아픈 대지모신께서는 도저히 자식들이 타락하는 것을 보고만 있을 수 없으셨다. 비탄에 젖은 대지모신께서는 두 눈을 뽑아 별이 반짝이는 끝없는 하늘에서 회전하도록 두셨다. 이에 안쉬와 무샤는 서로 슬픔을 위로하려 했지만 하늘 너머로 서로 희미한 빛을 뒤쫒을 뿐이었다. 이들은 아직도 세상이 돌 때마다 서로 뒤쫓고 있다.'),
(2300, '눈이 멀었음에도 불구하고 대지모신께서는 세상을 사랑하는 마음을 버리지 못하셨으니 바람에 귀 기울여 여명의 들판을 가로질러 새어 나오는 소리를 들으셨다. 대지모신의 드넓은 마음은 항상 자식들과 함께 있었기에 사랑으로 가득 찬 지혜로움으로 그들을 버리지 않으셨다.'),
(2301, '대지모신께서는 순수한 자식들 중 용감한 이들에게 사냥에 대한 열정을 심어 주셨다. 첫 여명의 생물들이 사납고 포악했던 까닭이다. 그들은 대지모신으로부터 숨어 쌍의 어둡고 거친 곳에서 위안을 찾았다. 수할로는 눈에 보일 때마다 이 짐승들을 사냥해 대지모신의 축복으로 길들였다. '),
(2302, '하지만 한 위대한 영혼이 그들을 벗어났다. 그것은 바로 나이트 엘프에게는 말로른으로 알려진 아파로라는 새하얀 눈 같은 털을 가진 훌륭한 수사슴이었다. 그의 뿔은 창공에 닿을 듯했고 강인한 발굽은 안 다녀본 곳이 없었다. 수할로들은 아파로를 동트는 세상 끝까지 추적해 이 훌륭한 수사슴을 잡으려 했다.'),
(2303, '수사슴은 도망갈 구멍을 찾으려 하늘을 향해 뛰어올랐다. 확실한 탈출이었지만, 그만 강인한 뿔이 별에 걸려 꼼짝도 할 수 없게 되어버렸다. 이리 차고 저리 차고 발버둥을 쳤지만 아파로는 창공에서 헤어나올 수가 없었다. 바로 그때 여명을 향해 오빠 안쉬를 뒤쫒던 무샤가 그를 발견했다. 무샤는 몸부림치는 강인한 수사슴을 보고 그만 사랑에 빠져버렸다.'),
(2304, '영리한 달은 수사슴이 동생을 사랑해 외로움에서 벗어나게 해준다면 놓아주겠다는 거래를 했다. 무샤는 아파로와 사랑을 나누며 아이를 가졌다. 어떤 이는 반신반인이라고 하는 그 아이는 밤의 어두운 숲속에서 태어났다. 그 아이는 세나리우스라 불리며 깨어나는 세상과 천상계 사이의 별이 빛나는 길을 걸었다. '),
(2305, '세나리우스는 곧 자라서 아버지의 당당한 몸집을 가지게 되었다. 나무와 별의 형제이며 탁월한 사냥꾼인 그는 조화로운 여명의 노래를 부르며 먼 세상을 돌아다녔다. 모든 생물이 그의 기품과 아름다움 앞에 머리를 조아렸다. 달과 백색 수사슴의 아들만큼 아름다운 존재는 없었기 때문이다. '),
(2306, '마침내 세나리우스는 수할로들과 친구가 되었고 그들에게 변화하는 세상에 대해 얘기해 주었다. 대지의 자식들은 그를 형제로 여기고 생명의 들판과 위대한 대지모신의 사랑을 받고 있는 생물들을 같이 돌보기로 맹세했다. '),
(2307, '세나리우스는 대지의 자식들에게 나무나 식물과 대화를 나누는 법을 가르쳐 주었다. 수할로들은 드루이드가 되어 땅을 돌보는데 위대한 마법적 업적을 이루었다. 또한 수할로들은 여러 세대를 거쳐 세나리우스와 함께 사냥하며 깊은 곳에서 꿈틀거리는 어두운 그림자로부터 세상을 지켰다.'),
(2308, '여명의 안개가 걷히고 기억의 시대가 다가옴에 따라 반신반인 세나리우스는 세상의 들판을 따라 자신만의 길을 떠났다. 수할로(타우렌)들은 세나리우스가 떠나 너무 슬픈 나머지 그가 가르쳐 주었던 드루이드 지식을 거의 잊어버리게 되었다. 여러 세대가 지나면서 그들은 나무와 대지의 생물과 대화하는 법도 잊어버리게 되었다. 그리고 세상 깊은 곳에서 들려오는 사악한 속삭임이 다시 한 번 그들의 귓속으로 들어오게 되었다.'),
(2309, '대지의 자식들은 사악한 속삭임을 듣지 않으려 했지만 무서운 저주가 그들에게 내리고 말았다. 서쪽의 검은 땅에서 잔인한 켄타우로스가 달려온 것이다. 식인과 파괴를 일삼는 켄타우로스는 수할로들에게 역병과 같은 결과를 가져왔다. 용감한 자들과 사냥꾼들이 대지모신의 축복을 가슴에 담고 싸웠지만 켄타우로스를 물리칠 수는 없었다.'),
(2310, '그 후 사할로들은 조상들의 땅을 버리고 영원히 끝 없는 벌판을 배회해야만 했다. 하지만 언젠가 희망을 되찾을 것이라는 믿음이 있었다. 뿔뿔이 흩어진 수할로 부족이 대지모신의 포근한 품 안에 새로운 고향을 찾게 될 것이라는 믿음 말이다. '),
(2311, '이 온전한 프테라돈 뼈는 먼 운고로 분화구에서 발견되었다. 뼈의 구조로 봐서 이런 종은 아직 맞서본 적이 없는 것이 분명하다. 이 뼈는 기름진 운고로 지역의 토질 아래에서 몇 세기든 보존되었을 것이다.'),
(2350, '이 온전한 프테라돈 뼈는 먼 운고로 분화구에서 발견되었다. 뼈의 구조로 봐서 이런 종은 아직 맞서본 적이 없는 것이 분명하다. 이 뼈는 기름진 운고로 지역의 토질 아래에서 몇 세기든 보존되었을 것이다.'),
(2371, '다로우셔 연대기서쪽에\n\n있는 다로우미어 호수의 이름을 딴 다로우셔는 로데론 남쪽 산기슭에 자리 잡은 마을입니다. 소박하지만 근면한 주민들로 유명한 다로우셔는 제2차 전쟁이 발발하기 전까지 로데론 역사에서 주목받지 못했습니다.그 전쟁 동안\n\n영웅들이 탄생했고, 또 영웅들이 목숨을 잃었습니다.'),
(2372, '다로우셔 전투다로우셔\n\n전투는 제2차 전쟁 중반, 스컬지 군대가 로데론 전역을 휩쓸던 시기에 벌어졌습니다. 다로우셔는 얼라이언스 주력군과 단절되었지만, 마을에는 병력 한 개 중대와 실버 핸드 기사단 일부, 그리고 조셉 레드패스 대위가 이끄는 굳건한 지역 민병대가 주둔하고 있었습니다.'),
(2373, '스컬지의 첫 번째 다로우셔 공격은 드물었다. 해골과 시체 무리가 마을 외곽을 배회했지만 번번이 격퇴당했다. 하지만 스컬지는  \n\n수비대의 끈질긴 저항에 굴하지 않고 곧바로 반격에 나섰다. 첫 번째 공격이 끝난 직후 두 번째 공격이 시작되었다. 구울 군주 호르구스의 하수인인 챔피언 구울들이 언덕에서 포효하며 내려와 포위된 다로우셔 수비대와 격돌했다.'),
(2374, '수비대는 약해졌지만, 은빛 손의 제자인 성기사들이 구원에 나섰습니다. 그들의 지도자 데이빌 크록포드는 대로우셔 출신이었습니다. 그는 임박한 공격 소식을 듣고 추종자들을 이끌고 마을로 와서 수비대와 함께 호르구스의 하수인들을 막아냈습니다. 호르구스가\n\n직접 전투에 뛰어들자 데이빌과 마주쳤습니다. 몇 분 동안 치열한 전투 끝에 데이빌이 승리했지만, 치명적인 부상을 입고 얼마 지나지 않아 구울 군주를 물리치고 죽었습니다.'),
(2375, '전투는 계속되었고, 레드패스 대장은 용감하게 군대를 이끌었습니다. 만약 대장이 죽음의 기사 마르두크 더 블랙에게 타락하지 않았더라면 승리했을지도\n\n모릅니다. 전투가 한창일 때 마르두크는 레드패스에게 다가가 흑마법으로 그의 영혼을 찢어발겨 용감한 대장의 사악한 그림자로 만들어 버렸습니다.'),
(2376, '타락한 레드패스 대장은 다로우셔의 수비대원들에게 악의 기운을 퍼뜨렸고, 그들은 동맹을 배신하고 학살했습니다. 이어 다로우셔 마을을 공격하여 집에 숨어 있던 사람들을 모두 죽였습니다.\n\n남은 스컬지 군대는 타락한 레드패스 대장의 영혼과 함께 황폐해진 다로우셔 마을을 떠나 로데론으로 진격하여 제2차 전쟁의 고통과 죽음을 더욱 가중시켰습니다.'),
(2377, '"다로우샤이어 연대기\r\n\r\n서쪽의 다로미어 호수에서 그 이름이 유래한 다로우샤이어는 로데론의 남쪽 구릉지 안쪽에 위치한 마을이다. 다로우샤이어는 보잘것없지만 주민들이 근면하기로 소문이 자자하며 2차 대전쟁 이전에는 로데론 역사의 뒷전에 머물러 왔을 뿐이다.\r\n\r\n그 전쟁 중 많은 영웅들이 탄생했고 사라져 갔다."'),
(2378, '"다로우샤이어 전투\r\n\r\n다로우샤이어 전투는 스컬지 병력이 로데론을 쑥대밭으로 만든 2차 대전쟁이 한창 벌어지고 있던 도중 일어났다. 다로우샤이어는 대부분의 얼라이언스 병력과 단절되었지만 은빛 성기사단의 파견대와 경비대장 조셉 레드패스가 이끄는 든든한 민병대원이 마을을 지켜 주었다."'),
(2379, '"스컬지는 다로우샤이어에 산발적인 첫 공격을 시작했다. 소규모의 해골 부대와 좀비들이 습격하며 마을 외곽을 배회하다 격퇴되었다.\r\n\r\n그러나 스컬지는 병사들의 완강한 저항에도 주저하지 않고 첫 번째 공격을 한 지 얼마 지나지 않아 두 번째 공격을 해왔다. 놀 군주 호르구스의 부하인 놀 용사들이 소리를 지르며 언덕을 내려와 포위된 다로우샤이어의 병사들과 격돌했다."'),
(2380, '"민병대원들은 약해졌지만 은빛 성기사단의 성기사들이 구원이 되었다. 다로우샤이어 출신인 그들의 지도자 다빌 크록포드가 임박한 공격 소식에 추종자들을 데려와 병사들과 함께 호르구스의 부하들을 저지했다.\r\n\r\n마침내 호르구스가 직접 전투에 참가했을 때 그는 다빌과 맞닥뜨렸다. 장시간의 격투 끝에 마침내 다빌이 승리를 거두었지만 치명적인 부상을 입어 놀 군주를 굴복시킨 후 곧 죽음을 맞이하게 되었다."'),
(2381, '"전투는 계속되었고 경비대장 조셉 레드패스는 그의 민병대를 용감하게 이끌었다. 죽음의 기사 검은 마르두크가 경비대장을 타락시키지 않았더라면 전쟁에서 승리했을지도 모른다.\r\n\r\n격투 중 마르두크가 말을 타고 레드패스에게 접근하여 흑마법으로 레드패스의 영혼을 끌어내서 용감한 경비대장을 사악한 어둠의 존재로 만들었다."'),
(2382, '"타락한 경비대장 레드패스는 타락한 영혼을 다로우샤이어의 병사들에게 퍼뜨려 동지들을 배신하고 학살하게 만들었다.  그 후 그들은 집에 숨어 있던 다로우샤이어 주민들을 모두 학살했다.\r\n\r\n남은 스컬지 군대는 타락한 경비대장 레드패스의 영혼과 함께 참혹하게 유린된 다로우샤이어 마을을 떠난 후 로데론으로 쳐들어가 2차 대전쟁에 더 많은 고통과 죽음을 안겨 주었다."'),
(2383, '"약탈자 호르구스의 운명\r\n\r\n약탈자 호르구스는 다로우샤이어 전투에서 패배했지만 그가 지니고 있던 사악함은 완전히 사라지지 않았다. 승리한 스컬지 병력은 다로우샤이어의 전쟁터에서 그의 머리를 가져다가 살아있는 자들과 마주칠 때마다 그들에게 공포감을 심어 주었다.\r\n\r\n며칠 후 호르구스의 머리를 가지고 있던 스컬지 일당은 은빛 성기사단에 패배했고 호르구스의 머리는 검은나무 호수에 버려졌다."'),
(2384, '"검은 마르두크의 운명\r\n\r\n마르두크는 2차 대전쟁에서 살아남아 룬이 박힌 사악한 검으로 많은 이들을 고통과 죽음으로 내몰았다. 마르덕은 여전히 살아 있지만 코린 삼거리 근처에서 일어난 전투에서 그 검을 잃게 되었다. 드워프 대장이 마법의 방패로 그의 검을 산산조각내어 마르두크를 몰아냈고 결국 얼라이언스에게 승리를 안겨 주었다.\r\n\r\n마르두크의 검은 땅 밑으로 가라앉아 협곡을 빨아들이며 대지를 오염시켰고 현재의 오염의 흉터가 생기게 되었다."'),
(2385, '"다빌 라이트포지의 운명\r\n\r\n다빌 라이트포지는 다로우샤이어 전투에서 사망했지만 그의 용기는 전쟁기간 동안 얼라이언스를 고무시키기에 충분했다.\r\n\r\n한편 그가 쓴 책인 성기사의 성서가 붉은십자군에 의해 발견되었다. 현재 붉은십자군이 지배하는 하스글렌의 마을 회관에 보관되어 있으며 다빌의 힘을 본받으려는 십자군들이 종종 이 책을 읽기도 한다."'),
(2386, '"조셉 레드패스의 운명\r\n\r\n조셉 레드패스는 다로우샤이어 전투에서 사망했다. 그의 영혼은 타락하여 새로운 모습으로 태어났고 로데론에 가공할 악을 퍼뜨렸다.\r\n\r\n타락한 레드패스는 안돌할의 동쪽에 있는 가론의 흉가에서 마침내 얼라이언스에 패배했다. 그의 방패는 아직도 역병 걸린 농장에 있으며 스컬지의 앞잡이들은 여전히 그의 사악함에 대한 기억에 이끌리곤 한다."'),
(2391, '"카를린 레드패스의 운명\r\n\r\n경비대장 조셉 레드패스의 형제인 카를린은 다로우샤이어 전투에서 패배했다. 카를린은 심한 부상을 입었지만 죽지는 않았다.\r\n\r\n전투가 끝나고 며칠 후 은빛 여명회의 대원들이 코린 삼거리 근처에서 갈증과 열병으로 약해진 채 방황하고 있던 카를린을 발견하여 카를린을 치료하고 희망의 빛 예배당으로 데려갔다.\r\n\r\n그들의 자비에 감사하며 카를린은 은빛 여명회에 합류했고 이제 스컬지에 대항해 복수의 전투를 치르고 있다."'),
(2411, '오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오 우오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오오'),
(2413, '눈부신 눈...$B$B부족을 지켜야 한다. 강한 부족으로 만들어라. 강해져라.$B$B알 수 없다...'),
(2414, '화주.$B$B좀 더 만들어라. 화주를 좀 더 만들어라.$B$B화주가 눈사태일족을 강하게 한다. 적을 물리쳐라.$B$B눈사태일족에게는 동지가 없다. 눈사태일족은 강하다. 강해져라.'),
(2415, '좀 더... 좀 더 있어야 해...$B$B눈사태일족... 약하지... 않다...'),
(2431, '입대 날짜: 미상\n\n\n\n이름: 나타노스 마리스, 로데론의 인간 레인저 군주\n\n\n\n입대\n\n\n\n사유: 나타노스 마리스를 기사단에 받아들인 나의 결정에 대한 카엘타스 선스트라이더의 반대를 기록해 두었다. 또한 나타노스는 비록 인간이지만, 내가 훈련시켜 본 레인저 중 가장 재능 있는 인물 중 하나라는 점도 알아두어야\n\n\n\n한다.(계속)'),
(2432, '지난 몇 년간 이 업계에 종사하는 것이 그 어느 때보다 자랑스럽습니다. 암살자, 첩자, 정찰병에 대한 수요는 그 어느 때보다 높습니다. 전시에는 수요가 더 많을 거라고 생각하겠지만, 놀랍게도 전쟁 중에는 지금처럼 번성하지 못합니다. 오히려 평화가 찾아온 후 상황이 악화되기 시작합니다. 당신이$B$B이 지역에 와서 몇 가지를 배우려 한다는 이야기를 들었습니다. 시간이 되시면 수도원 뒤편 마구간으로 저를 찾아오십시오.$B$B- 요릭 케리단, 로그 트레이너'),
(2433, '당신은 이 편지가 왕이나 다른 누군가에게서 온 평범한 편지일 거라고 생각했겠죠? 글쎄, 사실 전 편지 위조에 대해 좀 안다. 당신이 이 편지를 꼭 받도록 하고 싶었거든. 괜히 눈에 띄면 안 되잖아? 난 앤빌마르$B$B안에 숨어 있어. 모닥불 근처에서 날 찾을 수 있을 거야. 준비되면 나와 얘기하자. 시간이 있을 때 간단히 자기소개를 하고 싶어서. -$B$B솔름 하그린, 도적 훈련가'),
(2434, '님, 안녕하십니까.$N 깊은 생각에 잠겨 있다가 문득 당신에게 편지를 써야 한다는 생각이 들었습니다. 우리$B$B문화에서는 많은 이들이 샤먼을 위대한 전쟁 지도자처럼 영적인 지도자로 칭송합니다. 또 어떤 이들은 검과 도끼를 사용하는 것이 더 고귀한 행위라고 생각하지만, 전투, 심지어 전쟁조차도 전문적인 기술을 가진 이들의 헌신으로 승리한다는 사실을 결코 잊어서는 안 됩니다.  님, 제가 당신에게 전하고 싶은 이야기는 바로 이것입니다. $N시련의 계곡 깊숙한 곳에 있는 동굴에서 저를 찾아주십시오.$B$B- 르와그, 도적 훈련가'),
(2435, '$g형제:자매;여, 이 룬이 무사히 도착하기를 바라네. 나는 지금 콜드리지 계곡 위쪽의 앤빌마 안에 있다는 걸 알려 주고 싶었어.$B$B우리가 서로 뭉치는 게 얼마나 중요한지는 자네도 잘 알겠지. 특히 평화가 위태로운 지금 같은 때에는 우리 같은 이들이 곁에 있는 게 더욱 중요하네. 시간이 나면 나를 찾아오게.$B$B-솔름 하그린, 도적 훈련관')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2436, '내 말을 무시하지 마시오, . $N지금은 모든 나라, 심지어 우리의 위대한 지하 도시까지, 온갖 책략과 기만의 시대입니다. 실바나스에게 충성하는 자들은 모두 포세이큰이 지배하는 새로운 시대를 만들기 위해 애쓰고 있습니다. 비록 우리에게 마법 능력이 없고 국경에서 무기를 들지는 않겠지만, 우리에게도 할 역할이 있습니다.데스넬 여관에서$B$B저를 찾아오시오. 그때 더 자세히 이야기하죠.-데이비드$B$B트리아스, 도적 훈련가'),
(2437, '"샤엘라, 친구. 이 도장을 찾았기를 바라오. 난 당신을 도와주라는 부탁을 받았소. 나도 알드랏실의 세계수에 있는 그늘 협곡에 있으니 훈련을 받고 싶으면 날 찾아오면 된다는 걸 알려 주려고 이 도장을 만들었소. $B$B지금 같은 어려운 시기에 은신술을 구사하는 이들이 서로 가까이 지내는 것이 현명하다고 생각하오. 그렇지 않으면 어떻게 텔드랏실과 우리 방식을 지키겠소?$B$B시간이 나면 날 찾아오시오.$B$B-상급 도적, 프라훈 섀이드위스퍼"'),
(2438, '"안녕하시오. 검은손 도적단의 안부 인사를 전하면서 시험의 골짜기가 당신의 솜씨를 발휘하기에 좋은 곳이 되길 바라오. 이제 당신은 시험을 치러야 할 때요. 보이지 않는 누군가가 끊임없이 당신을 지켜보고 있다는 것을 잊지 마시오.\r\n\r\n내 임무는 당신의 실력을 평가하면서 큰 일을 할 실력을 갖추었다 싶을 때 검은손 도적단에 보고하는 것이오.\r\n\r\n준비가 되면 동굴 막사 깊은 곳으로 날 찾아오시오. 기다리고 있겠소.\r\n\r\n- 상급 도적, 르와그\r\n"'),
(2439, '자, ,$c 오크의 비명 소리를 들어본 적 있나? 혹시 놀들이 목을 물어뜯으려 할 때 집을 지켜본 적은 있나? 끔찍하게 들리지 않나?음,$B$B사랑하는 사람들을 지키고 싶다면 내 도움이 필요할 거야. 노스샤이어 수도원 안에 내가 있지. 내 지식은 공짜는 아니지만, 자네가 충분한 경험을 가지고 있다면 스톰윈드와 그 너머를 위협하는 적들을 물리치는 데 도움이 될 여러 가지 무술과 기술을 가르쳐 줄 수 있어.$B$B레인 베셰르, 전사 훈련가'),
(2440, '주의:$B트란 코르만에게 즉시 보고하십시오. 그는 A3 건물(현지 주민들에게는 안빌마르로 알려져 있음)에 있습니다. 코르만과 연락이 닿으면 다가올 전쟁, 즉 우리의 고향 그노메레간을 되찾기 위한 전쟁을 준비하십시오! 모든 노력과$B$B필수 임무는 이 지시를 달성하는 데 집중해야 합니다. 이 지시가 완료되면 새로운 임무가 주어질 것입니다.'),
(2441, '"많은 부족들이 마법을 사용하거나 우리 선조의 영혼과 대화를 할 수 있는 것을 타고난 재능 있다고 하지만 자네 역시 그들에 못지 않는 재능이 있다는 것을 알아야 하네. 어떤 이들은 강한 무기를 휘두를 수 있는 힘이 없고, 어떤 이들은 암살자의 공격을 막아낼 기술이 없거나, 마법 시전자에게서 입은 육체적인 고통을 견뎌내지도 못한다네. 하지만 자네는 할 수 있지. 자네는 강해. 내가 더 강해지도록 도와주겠네. 나라체 야영지로 날 찾아오게.\r\n\r\n-상급 전사, 하루트 썬더혼"'),
(2442, '"마그니 폐하의 턱수염만큼이나 당신과 의논할 게 많은데 시간이 너무 부족하군. 가능한 한 빨리 눈마루 골짜기 위의 앤빌마로 날 찾아오시오. 당장 시작해야 하오.\r\n\r\n당신을 제대로 된 전사로 만들기 위해서 배울 것이 무척이나 많지만 지금은... 모두 필요 없는 일들이지. 당신이 중점적으로 익혀야 할 것은 무기를 제대로 쥐는 법, 방어구의 무게감, 그리고 적과 싸울 때 이마에 흘러내리는 땀 냄새 같은 것들이오. 그런 것들부터 차근차근 익히도록 합시다.\r\n\r\n- 스란 코르만, 상급 전사"'),
(2443, '우리 종족 중 많은 이들이 힘을 얻기 위해 신비롭고 신성한 힘에 의존하지만, 우리는 그보다 더 잘 알고 있지 않나, 그렇지 $c않나? 우리의 무기는 신성한 상징이고, 방패는 마법서이며, 갑옷은 지혜라는 것을 우리는 알고 있다. 우리는$B$B불멸의 존재일지라도 강하며, 앞으로 더욱 강해질 것이다. 데스넬$B$B여관에서 나를 찾아라. 그곳에서 이러한 문제들과 다른 여러 가지에 대해 더 자세히 이야기해 주겠다.$B$B- 대널 스턴, 전사 훈련가'),
(2444, ', 제 문장이 당신에게 잘 전달되기를 $c바랍니다. 우리 종족에게는 검과 글레이브, 그리고 모든 무기를 능숙하게 다루는 이들이 절실히 필요하기 때문에 편지를 씁니다. 아제로스의 다른 종족들과 다시 만나게 된 이후로 많은 일들이 일어났고, 그로 인해 우리는 더욱 다양한 종류의 수호자가 필요해졌습니다.바로 이 점에서$B$B당신이 필요한 것입니다. 더 자세히 말씀드리고 싶지만, 직접 만나서 이야기하는 게 좋을 것 같습니다. 알드라실 지하층에서 저를 찾아주세요.$B$B- 알리시아, 전사 훈련가'),
(2445, '"마법사의 길을 걷기 시작한 당신을 환영하오.$B$B앞으로 당신이 배워나가게 될 마법에는 다음과 같은 네 가지 규칙이 있소.$B$B   마법은 강력하다.$B   마법은 타락하게 한다.$B   마법은 중독성이 있다.$B   마법은 뒤틀린 황천에 사는 생물들을 시전자에게로 끌어 모은다.$B$B이 규칙들은 언제나 틀림없이 적용되는 것이오. 마법사로서의 길을 계속 걸어나가기로 했다면 이 규칙들이 당신의 운명을 지배하게 될 것이오.$B$B당신이 이 경고를 무시할 만큼 어리석다면 노스샤이어 수도원의 서재로 날 찾아오시오. 위층에서 당신을 기다리고 있겠소.$B$B- 상급 마법사, 켈덴 브레멘"'),
(2446, '새로운 마법 수련생 여러분께:$B여러분은 언젠가 새로운 거주지에 정착한 동족을 도울 기회가 올 때까지 노움 마릭 누리빗을 찾아가 가르침을 받아야 합니다. 두려움 없이 엄격한 시험 절차와 어려운 적응 과정을 각오하십시오. 새로운 거처를 찾고 지역 주민들과 교류하며 새로운 삶을 시작하게 될$B$B것입니다. 임무와 능력에 관한 질문은 마릭 누리빗에게 하십시오.'),
(2447, '마법과 함께 온다고 소문난 타락과 악은 우리가 이미 겪은 고통에 비하면 아무것도 아니야. 이제 우리는 희생자가 아니야, $n. 우리의 운명은 우리가 결정한다. 실바나스가 길을 열었어. 우리의 의지는 우리 것이며, 더는 그 망할 아서스의 노예가 아니라는 걸 증명했지.$B교회에서 나를 찾아와. 원한다면 더 가르쳐 주겠어...$B$B- 이사벨라, 마법사 훈련사'),
(2448, '자, 이제 깨어난 것을 환영한다, 친구. 충분히 강하다면 신비로운 비밀을 손에 넣을 수 있을 것이다. 준비가 되면$B$B마이아를 찾아라. 그녀는 너에게 마법과 너에게 맞서는 자들을 파멸시킬 주문에 대해 많은 것을 가르쳐 줄 것이다. 마이아는 시련의$B$B계곡에 있는 동굴 근처에 있다. 가서 그녀를 찾아라. 그리고 강해져라. 그런 다음 다른 마법사들에게 마법이 네 의지대로 움직인다는 것을 보여주어라... 그 반대가 아니라.'),
(2449, '"성스러운 빛의 추종자와 같은 사람들은 진정한 힘에 관심을 가지는 자들에게 어떤 형태의 비전술이든 연구해서는 안 된다는 생각을 심어 주는 사람들이 너무 많소. 하지만 이 세계 외부에서 온 것이라고 해서 모두 악한 것은 아니오. 모든 존재가 다른 이들을 제압하고 복종시키려고 애쓰는 것은 아니란 말이라오. 자신이 충분히 강하다면 바로 그런 존재들이 따르게 되어 있는 것이지.\r\n\r\n이에 대해 당신과 더 깊은 얘기를 나누고 싶소. 수도원 오른쪽 옆에 있는 묘지로 날 찾아오시오.\r\n\r\n- 상급 흑마법사, 드루실라 라 살르"'),
(2450, '주의:$B$B조용히 하세요! 주위를 둘러보지 마세요! 누군가 지금 이 순간 당신을 지켜보고$B$B있을지도 모릅니다. 제 $N이름은 알라마르 그림입니다. 저는 지식과 더 큰 힘을 갈망하는 자들을 훈련시킵니다. 당신에게 은밀히 연락하여 진정한 마법을 더 깊이 익힐 수 있도록 도와달라는 요청을 받았습니다.$B$B시간이 되시면 앤빌마 뒤편으로 오세요. -$B$B알라마르 그림, 워록 트레이너'),
(2451, ', 내가 만들 수 있는 가장 강력한 잉크로 이 메시지를 $N쓴다. 자네를 제외하고 감히 이 글을 읽는 자는 누구든 즉시 저주를 받게 될 것이다. 나는 그만큼 강력하다. 나는 마음대로 뒤틀린 황천에서 악마를 소환하고, 적들을 잠자는 동안이나 전장에서 괴롭힌다. 그리고 이제 자네도 내 길의 힘을 목격했으니, 내$B$B형제들은 기뻐하고 있다.길을 찾으면 동굴 깊숙한 곳에서 나를 찾아와라. 중요한 이야기를 나누고 싶네.$B$B-나르토크, 흑마법사 훈련가'),
(2452, '우리가 끔찍한 곤경에 처해 있다고 생각하지 않소? 어리석은 왕자에게 고통받고 사랑했던 이들에게 무시당하고 배척당하니 말이오. 아름다은 실바나스 여왕님 덕분에 마침내 의지를 갖추게 됐지만 그렇다고 우리가 얻은 게 뭐요? 주인이 바뀌어도 노예는 결국 노예인 셈이니...$B$B하지만 만약에 우리가 주인이 된다면 어떻겠소? 그렇지. 무슨 말인지 알지 않소?$B$B우리는 다른 포세이큰보다 훨씬 고립되어 있소. 그렇기에 좀 더 얘기를 나누어야 하니 죽음의 종소리 마을에 있는 예배당으로 날 찾아오시오.'),
(2453, '용맹한 전사들이 우리의 고향을 지키고, 샤먼들은 우리의 영혼을 인도하며 조상들의 과거를 보여줍니다. 그리고 드루이드들은 대지의 어머니의 뜻을 깨닫도록 도와줍니다.$B$B하지만 당신은 우리 부족의 사냥꾼 중 한 명이며, 사냥꾼들은 이러한 역할들의 다양한 측면을 배우고 융합합니다. 당신은 우리 부족의 심장을 대표한다는 것을 알게 될 것입니다. 우리 부족의 일부는 당신에게 지도를 구하고, 일부는 보호를 요청할 것입니다. 당신이 그에 대비할 수 있도록 돕는 것이 제 임무입니다. 나라체 캠프에서 저를 찾아주십시오.$B$B- 란카 파숏, 사냥꾼 훈련관'),
(2454, '걱정 마, 친구. 젠샨은 네가 사냥꾼의 길을 배우고 싶어 한다는 걸 알고 있어. 네가 들을 준비만 되어 있다면, 젠샨이 기꺼이 가르쳐$B$B줄게. 시련의 계곡에서 날 찾아와. 젠샨이 네 훈련을 시작하고 사냥꾼의 길이 얼마나 강력한지 보여줄게.$B$B- 젠샨, 사냥꾼 훈련관'),
(2455, '"동물 조련사에, 일급 사격수에, 그리고 인정받는 추적자에, 또 뭐가 되고 싶은 것이오? 모두 상당한 지혜와 엄청난 끈기가 필요한 일들이지.$B$B사냥꾼의 길은 결코 쉽지 않소. 우리 말단 소총병 실력만큼이라도 되려면 많은 훈련이 필요할 거요. 내가 여기 있는 이유도 다 그때문이지.$B$B눈마루 골짜기가 내려다 보이는 앤빌마에서 기다리고 있겠소.$B$B- 상급 사냥꾼, 토르가스 그림슨"'),
(2456, '엘룬이 너와 함께 $N있어, . 바람이 내게 속삭여 주는구나. 우리 차세대 헌터들을 양성하는 데 직접 참여할 수 있어서 기쁘구나.$B$B내가 듣기로는 네가 알드라실 근처에 있다고 하더구나. 시간이 되면 그 큰 나무 안에서 만나자.우리 원로들은 내게$B$B앞으로 닥칠 시련에 대비해 신입 헌터들을 제대로 훈련시키는 임무를 맡겼어. 자네는 이제 막 들어온 학생 중 하나이니, 나를 찾아오는 게 좋을 거야. 그때까지 잘 지내도록.-$B$B아얀나 에버스라이드, 사냥꾼 훈련관'),
(2457, '젠샨의 $g형제:자매; 중 한 명이 $g그의:그녀의; 실력을 시험하러 시련의 골짜기에 온다니 반갑구나. 젠샨도 기대하고 있어!$B$B자네가 얼마나 강하고 영리한 사냥꾼인지는 굳이 말할 필요도 없겠지. 이미 잘 알고 있을 테니까. 젠샨의 임무는 자네가 더 강하고 더 영리해지는 법을 가르치는 거야.$B$B시련의 골짜기에서 젠샨을 찾아. 잘 가르쳐 줄 거야. 가장 강력한 야수를 길들이는 법을 비롯해 여러 가지를 배울 수 있지.$B$B-젠샨, 사냥꾼 훈련관'),
(2458, '"지난 밤 꿈에 영혼들이 내게 나타나 당신이 올 것이며 당신을 돕는 것이 내 임무라고 말해 주었소. 자연, 영혼들, 대지모신, 그리고 심지어는 나이트 엘프까지, 우리가 함께할 짧은 시간 동안 의논해야 할 게 무척 많소이다. 하지만 이런 교훈들은 당신이 올 때까지 접어두도록 하지. 그리고 당신 앞에 놓인 난관에 대한 준비는 내가 전력을 다해 도와 주겠소.\r\n\r\n지혜가 당신을 인도하기를 바라오. 당신을 기다리고 있겠소.\r\n\r\n- 상급 두루이드, 가트 미스트러너"'),
(2459, '"당신이 준비가 되었다는 소식을 듣자마자 이 도장을 보냈소. 세나리우스의 모든 드루이드들이 새로운 드루이드가 늘어나고 있다는 것에 대단히 만족하고 있소. 정령들마저도 강화된 우리를 보고 더 강해진 것 같소. 때가 될 때까지 참을성 있게 기다린다면 우리의 힘도 예전의 위대함을 되찾게 될 것이오. 준비가 되면 알드랏실 꼭대기 근처에 날 찾아오시오. 당신이 그늘 협곡에서 지내는 동안은 내가 안내자가 되어 주겠소이다.$B$B-상급 드루이드, 마르단트 스트롱오크"'),
(2460, '"안녕하시오, 젊은 $c|1이여;여;. 바람이 당신이 올 거라는 소식을 전해 주었소. 대지는 당신의 강인함을 칭찬하더니 이제는 고대 영혼들이 당신이 이룰 업적에 대해 속삭이는군. 우리 타우렌들은 언제나 현명하고 위대한 지도자를 필요로 한다오. 지도자들은 종종 그 두 가지 미덕을 우리에게서 찾으려고 하지. 원한다면 주술사의 길을 더 가르쳐 주겠소.\r\n\r\n붉은구름 고원에 있는 나라체 야영지로 찾아오면 그때 더 얘기하기로 하겠소.\r\n\r\n-상급 주술사, 밀라 던스트라이더"'),
(2461, '록타르, $g형제여:자매여;. 정령들이 그대를 가까이 부르며, 내가 주술사의 길을 보여 주길 바라고 있네. 저 너머에서 지켜보는 조상들의 영혼도 그대가 우리 대열에 합류한 것을 자랑스러워하네.$B$B준비가 되면 동굴 입구 근처에서 나를 찾게. 그곳에서 우리 동족들을 훈련하고 있을 테니. 그때까지 바람이 그대의 등을 밀어 주기를.$B$B시크리크, 주술사 훈련사'),
(2462, '안녕, 형제 자매여.$gbrotha:sista; 정령들이 네가 우리 동맹을 도울 준비가 되었다고 하네. 넌 정령들과 깊은 유대감을 가지고 있고, 나와 처음 수련을 시작했을 때보다 훨씬 더 강력해졌지. 이제$B$B널 시련의 계곡에 있는 오크 주술사 훈련관 시크릭에게 보내겠다. 그녀는 네가 자기에게 배우러 올 거라는 걸 이미 알고 있어. 우리 조상들을 자랑스럽게 만들어주도록. 다시 만날 때까지, 불꽃이 너를 따뜻하게 해주고 바람이 네 등 뒤에서 불어오길.$B$B이시요'),
(2463, ', 이 편지가 자네에게 잘 $c전달되기를 바라네. 자네가 이처럼 깊은 신앙을 고백할 수 있다는 것은 큰 자부심을 느끼게 하는 일이네. 자네는 아제로스의 수호자 중에서도 가장 정예한$B$B자들 중 하나이기에 더욱 그러하네. 무엇보다 먼저, 우리 세계를 해치고 우리 가정에 타락을 가져오려는 자들과 맞서 싸우는 것이 자네의$B$B의무임을 명심하네. 당분간 자네의 훈련은 내가 맡게 되었네. 준비가 되면 노스샤이어 수도원 안에서 나를 찾아오게 하네.$B$B- 성기사 훈련관, 사무엘 형제'),
(2464, '"어떤 이들은 우리를 용보다 더 두려워하고, 또 어떤 이들은 최고의 실력을 자랑하는 대장장이보다도 우리를 부러워하지. 또 어떤 이들은 전투에서 우리가 보여주는 힘을 칭송하기도 하고, 어떤 이들은 우리의 신념을 매우 높이 평가하오. 심지어는 우리가 술을 더 잘 마신다고 질투하는 이들도 있소! 하지만 $c|1이여;여;, 이것만은 알아두시오. 당신은 아제로스의 최정예 수호자 중 하나요. 우리가 수호하는 성스러운 빛이 우리에게 힘을 주고 있지.$B$B이 땅에 대해 조금 더 알게 되면 그때 더 자세히 얘기해 주겠소. 눈마루 골짜기 위에 있는 앤빌마로 날 찾아 오시오.$B$B-상급 성기사, 브로모스 그럼너"'),
(2465, '"훌륭한 사제가 되려면 이 세상과 교감하는 것이 상당히 중요합니다. 지혜와 연민의 감정을 가지면 도움이 절실하게 필요한 이들을 도울 수 있습니다. 지나친 열의와 현명하지 못한 결단은 다른 이들이 강해지는 것을 방해하거나 심지어 해를 끼칠 뿐입니다.\r\n\r\n내 말을 이해할 수 있는 단계에 이르렀으니 도움이 되는 새로운 능력과 마법을 배워야 합니다. 당신을 가르치는 것이 내 역할입니다. 준비가 되면 노스샤이어 수도원의 서재로 나를 찾아오십시오.\r\n\r\n-상급 여사제, 아네타"'),
(2466, '"성스러운 빛이 우리를 환하게 비추고 매일같이 새로운 발견이 이루어지고 있으니, 지금이야말로 아이언포지의 자랑스러운 일원이 되기에 아주 적절한 때입니다. 탐험가 연맹에서는 아주 오래전에 잃어버린 수수께끼의 해답을 찾기 위해 날마다 노력하고 있습니다. 이제 당신도 우리의 일원이 되었으니 접경 지역을 위협하는 트로그와 다른 존재들에 맞서 함께 싸웁시다.$B$B시간이 날 때 찾아오십시오. 언덕 바로 위에 있는 앤빌마에 있겠습니다.$B$B- 상급 사제, 브란스토크 칼더"'),
(2467, '"자네의 영혼이 황천에서 풀려나지 않은 것을 축복으로 여기게. 내가 자네를 이 두루마리를 받을 만한 가치가 있는 자로 평가했다는 사실을 더 큰 축복으로 여기게나.\r\n\r\n\r\n자네가 한때 알았고 또 아꼈던 자들은 이제 모두 존재하지 않네! 앞으로 지금과 같은 부자연스러운 삶을 살기 위해서는 그런 사실을 수용하는 법도 배워야 하지. 먼저 그런 사실들을 극복하는 법부터 배우길 바라네.\r\n\r\n\r\n그러다가 이제 시험해 볼 때가 되었다 싶거든 데스넬에 있는 교회로 날 찾아오게나.\r\n\r\n\r\n- 상급 사제, 어둠의사제 듀스텐\r\n"'),
(2468, '"이 도장을 잊지 않고 확인했길 바랍니다. 그대가 온다는 소식을 정령들에게서 듣고 즉시 전갈을 보내는 것입니다. 당신에게 제 경험을 가르치며 그대가 더 중요한 일을 위해 텔드랏실을 떠날 준비를 할 수 있도록 제가 옆에서 도와드리고 싶습니다.$B$B지난 몇 년 동안 많은 일들이 일어났어요. 아제로스의 많은 종족을 돕기 위해 해야 할 일이 아주 많답니다. 준비가 되면 알드랏실 2층으로 절 찾아오세요.$B$B- 상급 사제, 샨다"'),
(2469, '부디 지금까지 영혼들이 너를 보호해 주었기를 바란다, 친구. 앞으로 많은 시험이 기다리고 있을 거야. 네가 준비되면 내 경험을 기꺼이 나눠줄게. 얼마나 빨리, 얼마나 강해질지는 네 몫이야. 난 네가 준비됐을 때만 안내해 줄 수 있어. 어떤 사람에게는 정말$B$B빨리 될 수도 있고, 어떤 사람에게는 그렇지 않을 수도 있어. 하지만 그런 건 걱정하지 마. 나를 찾아오면 더 자세히 이야기할 수 있을 거야.$B$B- 켄자이, 사제 훈련가'),
(2471, '수천 년 동안 우리는 외부와 단절된 채 살아왔습니다. 과거에 실수가 있었다는 것을 인정하는 첫 번째 사람이 되겠습니다. 인간은 결코 마법에 노출되어서는 안 됐습니다. 이 사실을 부인하지는 않겠지만, 선조들의 잘못 때문에 우리를 이렇게 고립된 존재로 내몰고 싶지는 않습니다. 쿠엘도레이와 이 세상의 다른 종족들이 공존한다면 얻을 수 있는 이점은 무궁무진합니다. 우리는 관용을 실천해야\n\n\n\n합니다.(계속)'),
(2472, '그러므로 나는 나다노스 마리스에 관한 캘타스의 요청을 거절한다. 그는 앞으로 더없이 귀중한 동맹이 될 것이다. 내 말을 명심하라.\n\n\n\n서명,\n\n\n\n실바나스 윈드러너\n\n실버문 순찰대 사령관'),
(2490, ', 이 부적이 당신에게 잘 $N전달되기를 바랍니다. 영혼들이 당신이 온다는 소식을 전해 주었고, 저는 즉시 소식을 전했습니다. 제 경험을 당신과 나누고, 더 중요한 일들을 위해 텔드라실을 떠날 준비를 하는 당신을 도울 수 있기를$B$B기대합니다. 지난 몇 년 동안 일어난 모든 일들을 고려할 때, 우리는 아제로스의 다른 종족들을 도울 수 있는 일이 많습니다. 준비가 되면 알드라실 2층에서 저를 찾아주세요.$B$B- 샨다, 사제 훈련가'),
(2491, '"그리쉬-\r\n\r\n\r\n자네의 휴가 신청을 허가한다. 가족과 함께 지내는 동안 자네 위치를 담당할 예비 타우렌 전사를 보낼 테니 일주일 후에 다시 보고하도록 하라!\r\n\r\n\r\n-마그그랜 어스바인더\r\n"'),
(2511, '안녕하세요, 자르그,$B$B보내 주신 스테이크는 정말 좋았습니다. 고기 사이 사이 기름도 적당하고 두툼하게 잘라서 멧돼지 기름이 싸셨더군요. 딱 제가 좋아하는 대로였어요. 나중에 스테이크를 먹을 때 마지막 뼈까지 깨끗이 깨물어 먹으면서 당신 생각을 할게요. 눈을 감고 당신의 튼튼하고 흉터가 남아 있는 손이 고기를 토막내고 자르는 모습을 떠올리겠어요...$B$B하하! 이러니까 당신이 사고나서 손가락 하나를 잃었던 때 생각이 나는군요... 오, 자르그! 그때 생각을 하니 어린애처럼 낄낄거리며 웃게 되네요.$B$B당신은 피를 흘릴 때 너무 귀여워요!$B$B -그리쉬카 '),
(2512, '"오스릭,\r\n\r\n우리에게 필요한 방어구 목록을 아래에 적어 놓았네.\r\n\r\n사슬 조끼 10개\r\n투구 20개\r\n방어구 키트 30개\r\n쇠사슬 장화 15개\r\n\r\n언제나 그렇듯이 자네에게 신세를 지는군. 서부 몰락지대에서 도적 떼들을 모두 소탕하는 날, 우리 집에 초청해서 한때 그렇게나 유명했던 서부 몰락지대만의 푸짐하고 맛있는 식사를 대접할 수 있게 된다면 내가 마음의 빚을 좀 갚을 수 있을 텐데 말이야.\r\n\r\n감시의 언덕 병참장교, 루이스"'),
(2513, '"네사, 소식을 듣게 돼서 반갑군요.\r\n\r\n보내 준 뼈와 비늘은 정말 놀라웠습니다. 본토 밖에서 그렇게 큰 물고기는 본 적이 없어요. 루테란 마을의 낚시꾼들은 매일 손쉽게 엄청난 양의 물고기를 잡아들이겠군요!\r\n그렇게 큰 물고기를 잡다니 부러우면서도 조금 걱정이 되네요. 새로운 세계수 때문에 물고기들이 그렇게 커진 것일까요? 만약 그렇다면 새로운 세계수가 또 어떤 다른 영향을 미치게 될까요?\r\n\r\n궁금해 하며, 레어드"'),
(2514, '"다음은 브록의 채광 및 측량 학부에서 장학생으로 선발되어 명예로운 광부의 곡괭이를 수여 받은 학생들의 목록이다.\r\n\r\n멜리아 스톤쉐이커\r\n바르딘 아이언밴드\r\n우미 토글볼트\r\n루미 토글볼트\r\n보렐 스틸스파이어"'),
(2515, '"고위집행관 하드렉의 명령으로 공동묘지의 재고를 유지하기 위해 다음과 같은 물품이 필요함을 공포한다.\r\n\r\n장검 12개\r\n단검 9개\r\n원형 방패 8개\r\n도끼 15개\r\n화살 1000개\r\n\r\n본 내용은 어둠의 여왕 폐하께서 직접 내리신 명령으로 간주하여야 할 것이며 이 임무를 담당하는 자와 여왕 폐하의 명을 거역하거나 달리 방해하는 자는 여왕 폐하의 부름을 받게 될 것이다."'),
(2531, '이 3 페이지 문서는 비어 있습니다.'),
(2551, '"라요,$B$B우린 이 훌륭한 모험가에게 큰 신세를 졌습니다. 이 모험가를 실리더스에 있는 당신을 도울 인력으로 파견합니다. 부디 그곳의 비밀을 밝혀 내려는 당신의 노력에 이런 훌륭한 인력을 잘 활용하기를 바랍니다. 세나리온 의회에서는 일의 진척 상황에 대한 소식을 애타게 기다리고 있습니다.$B$B세나리우스의 가호가 있기를...$B라빈"'),
(2571, '"겨울맞이 축제$B$B많은 문화권에서는 아제로스 왕국의 겨울을 변화의 시기로 간주하고 있다. 특히 드워프와 타우렌은 천지를 눈으로 뒤덮음으로써 새로운 시작을 알리는 겨울맞이의 전설을 축제의 시기로 여기며 손꼽아 기다린다. 이 전설에 대한 이해는 아제로스 종족마다 크게 다르지 않으나, 이 축제의 시기를 지내는 방법은 종족의 개성만큼이나 다양하다."'),
(2572, '"겨울 할아버지의 전설$B$B""겨울맞이""라는 말은 많은 문화권에서 겨울 할아버지라 불리는 초자연적 존재를 칭하는 데서 생겨났다고 한다. 그가 얼어붙은 이 땅 위를 걸을 때면 그의 망토는 겨울 그 자체가 되어 휘날렸다. 그가 깨어나면 온 세계가 눈으로 뒤덮이니 이를 일컬어 겨울 할아버지가 겨울의 장막으로 대지를 덮는 것이라 했다. 아제로스의 일부 지역은 만년설에 싸여있다고는 하나 이 시기는 대지에 부활과 재생의 시간이다."'),
(2573, '드워프$B$B자신들의 뿌리를 찾는 데 무엇보다 열성적인 드워프는 겨울 할아버지라는 존재 자체를 기념하며 이 시기를 보낸다. 드워프는 겨울 할아버지가 아제로스의 고대인인 티탄이 인간화한 것으로 보고 있다. 드워프는 자신들이 이 신화적인 존재와 어느 정도 혈연이 있다고 주장하는 만큼 눈 덮인 자신들의 고향인 던 모로를 겨울 할아버지의 축복이라 여긴다.'),
(2574, '"타우렌$B$B타우렌과 겨울에 대한 그들의 주술신앙적 이해, 그리고 최근 나타나기 시작한 드루이드의 노력은 겨울맞이의 전설과 잘 들어맞는다. 그러나 이들은 전설의 소생적인 측면에만 관심을 기울인 채 전설의 숭배는 그들이 자연과 완벽하게 조화를 이루지 못한다고 보는 종족들에게 맡겨두고 있다. 많은 타우렌은 이 시기를 멀고어에서 새로운 고향의 축복에 대해 감사하는 시기라고 생각한다."'),
(2575, '축제$B$B일년 중 이 시기에 축제를 벌인다는 것은 전설의 근원을 따르는 것이다. 겨울 할아버지가 잠에서 깨어나 겨울을 몰고 아제로스를 거닐 때 그를 환영하는 자에게는 자비를 베풀었다고 한다. 이렇게 해서 겨울맞이 축제는 공동체의 주민들이 함께 모여 자신들이 가진 것을 나눈다는 의미를 갖게 되었다. 통상적으로는 하루 동안 축제를 즐기면서 모두 대지의 소생을 기대하는 마음으로 변화를 반긴다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2576, '"최근의 동향$B$B다른 문화권에서도 겨울맞이 축제를 커다란 전통으로 인정하기 시작했으나, 똑같은 전설에서 기반이 되었지만 의미가 변질된 의식들도 있었다. 최근에는 축하와 선물 교환 외에는 전통과 전혀 관련이 없는 관습들까지 가세하는 동향을 보이기 시작한 것이다. 심지어는 겨울 할아버지의 사진까지 사용되는데, 초자연적인 티탄의 모습보다는 상업적 영웅이나 선구자의 모습에 더 가깝다."'),
(2591, '"뾰족바위 골짜기 깊숙한 곳에 마라우돈의 성전이 있다. 그게 그렇게 큰 죄가 아니라면 내가 왜 켄타우로스가 아닌 자에게 이런 부탁을 하는 것인지 금방 알게 될 것이다.$B$B그 성전은 영혼과 우리의 성스러운 사제만이 거닐 수 있는 곳으로, 그곳에는 이름 없는 예언자라 불리는 자가 있다. 그는 영혼과 관련된 일에 있어서는 최고일 뿐 아니라 모든 일족 중에서 가장 연륜이 높은 자다."'),
(2592, '"그 예언자는 강한 힘을 지녔고 우리 선조의 영혼과도 의사소통을 할 수 있다만 그는 바보다! 자신이 지닌 진정한 힘을 전혀 깨닫지 못하고 있지. 그는 영혼의 아뮬렛이라는 걸 지니고 있는데, 그의 힘은 대부분 그 아뮬렛에서 나오는 것이다.\r\n\r\n나는 그 아뮬렛이 강하긴 하지만 불완전하다는 것을 알아냈지."'),
(2593, '"그 아뮬렛에는 다섯 가지 보석이 빠져 있는데 그 보석들을 찾아 다시 집어넣으면 지금의 형상이 지니고 있는 힘보다 훨씬 강력한 힘을 발휘할 거다. 내가 그 다섯 개의 보석을 찾긴 했는데 그것들을 모으려면 네 솜씨가 필요하다. 이름 없는 예언자를 처치하는 것도 그의 시체에서 물건을 훔치는 것도 명백한 이단 행동이지만, 내가 지금부터 부탁할 일은 켄타우로스로서 생각만해도 천벌을 받을 만한 일이다."'),
(2595, '"마라우돈의 동굴에는 첫번째 칸의 영혼들이 떠돌고 있다. 우리의 창조모와 창조부의 첫 후손들이자 우리의 위대한 지도자이기도 하지. 이름은 각각 겔크, 콜크, 마그라, 마라우도스, 벵이라고 하는데, 바로 이 영혼들이 잃어버린 보석들을 하나씩 지니고 있다."'),
(2596, '"영혼의 아뮬렛을 이용해 이 영혼들이 나타나도록 한 다음 그들에게서 보석을 빼앗아 와라! 그런 다음 보석들을 영혼의 아뮬렛에 넣어 내게 가져 오너라. 결속의 아뮬렛을 갖게 되면 나는 모든 일족들을 개혁시킬 수 있을 만큼 강해질 것이고, 그리하면 우리는 마침내 선조들이 바라던 후손이 될 수 있을 것이다."'),
(2611, '...바로 그곳에서 전설적인 붉은 군주의 검, 애쉬브링어를 찾을 수 있을 겁니다.$B$B평범한 낚시 날에 이렇게 놀라운 일을 겪을 수도 있다니, 놀랍지 않나요?'),
(2631, '<The pages are covered in ancient elven runes.>$B$B이 책에는 강력한 마법약을 제작하는 데 필요한 재료들을 모으고 만들어내는 과정에서 일어난 사건들의 기록이 담겨 있다.$B$B우리의 적들이 이 책에 결코 접근하지 못하게 하소서. $B$B쿠엘탈라스에 다시 한번 창백한 달빛이 비치는 것을 볼 수 있게 하소서.$B$B켈타스의 은총이 아니었다면 죽음을 맞이했을 것입니다.$B$B일리단의 영광을 위해 적을 죽일 수 있게 하소서.$B$B-카리엘 윈탈루스 님'),
(2632, '<이 페이지에 쓰여진 내용은 이해할 수 없습니다.>'),
(2633, '<책장에는 고대 엘프의 룬 문자가 빼곡히 적혀 있다.>$B$B이 책에는 상급 비전 마법을 만드는 데 필요한 재료를 수집하고 제작하는 과정에서 벌어진 일들이 기록되어 있다.$B$B우리의 적들이 이 성서를 결코 손에 넣지 못하기를. $B$B내가 살아서 쿠엘탈라스에 다시 창백한 달빛이 비치는 모습을 볼 수 있기를.$B$B캘타스의 은총을 위해 죽을 수 있기를.$B$B일리단의 영광을 위해 죽일 수 있기를.$B$B-대가 카리엘 윈탈루스'),
(2634, '<잉크가 소용돌이 치며 페이지 주위로 이동합니다. 당신은 책이 당신을 조롱하고 있다는 느낌을 갖습니다.>'),
(2635, '<The pages are covered in ancient elven runes.>$B$B이 책에는 강력한 마법약을 제작하는 데 필요한 재료들을 모으고 만들어내는 과정에서 일어난 사건들의 기록이 담겨 있다.$B$B우리의 적들이 이 책에 결코 접근하지 못하게 하소서.$B$B쿠엘탈라스에 다시 한번 창백한 달빛이 비치는 것을 볼 수 있게 하소서.$B$B켈타스의 은총이 아니었다면 저는 죽었을 것입니다.$B$B일리단의 영광을 위해 저는 적을 죽일 것입니다.$B$B-카리엘 윈탈루스 님'),
(2636, '<이 페이지들을 보니 엄청난 고통을 느낍니다.>'),
(2637, '포로르의 용 사냥 총서는 글이 빼곡히 적힌 두꺼운 책입니다. 하지만 안타깝게도 글씨가 깨져 보여서 무슨 말인지 전혀 알 수 없습니다.'),
(2653, '<이 페이지들을 보니 엄청난 고통을 느낍니다.>'),
(2654, '"<HTML><BODY><H1 align=""center"">군 계급에 관한 논문</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src=""InterfacePvPRankBadgesPvPRankAlliance""/>\r\n<BR/>\r\n<P align=""right"">얼라이언스와 호드의</P>\r\n\r\n<P align=""right"">군 계급에 관한</P>\r\n\r\n<P align=""right"">정보를 소개합니다.</P>\r\n\r\n<P align=""right"">각각 장교와 일반 병사,</P>\r\n\r\n<P align=""right"">두 부분으로 나누어져 있으며</P>\r\n\r\n<P align=""right"">높은 계급에서 낮은 계급 순서로 나열되어 있습니다.</P>\r\n\r\n<P align=""right"">얼라이언스여, 영원하라!</P></BODY></HTML>"'),
(2655, '<HTML>\n<BODY>\n<H1 align="center">얼라이언스 장교 계급</H1><BR/>\n<P align="center">제 1 장</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">최고사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">야전사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">작전사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">부사령관</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2656, '<HTML>\n<BODY>\n<H1 align="center">얼라이언스 장교 계급</H1><BR/>\n<P align="center">제 2 장</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">기사단장</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">기사대장</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">상급기사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">기사</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2657, '<HTML>\n<BODY>\n<H1 align="center">얼라이언스 사병 계급</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">하급기사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">정예근위병</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">근위병</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">파수병</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">정찰병</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2658, '<HTML>\n<BODY>\n<H1 align="center">호드 장교 계급</H1><BR/>\n<P align="center">제 1 장</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">대장군</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">장군</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">전투사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">부사령관</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2659, '그 눈을 들여다보면 거대한 전투의 이미지가 머릿속을 가득 채웁니다..$b$b. 이 무시무시한 전투는 로데론 어딘가에서 벌어지고 있는 듯합니다...$b$b수많은 시체들 한가운데 홀로 서서 스컬지의 물결을 막아내는 한 여인의 모습이 희미하게 보입니다... 그녀는$b$b 절망적으로 수적으로 열세입니다...$b$b그녀의 손에서 뻗어 나온 빛의 촉수들이 수백 마리의 언데드를 베어 넘깁니다.'),
(2660, '<HTML>\n<BODY>\n<H1 align="center">호드 사병 계급</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">정예투사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">하급투사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">기사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">그런트</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">척후병</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2661, '<HTML>\n<BODY>\n<H1 align="center">호드와 얼라이언스의 군사계급 </H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRankHorde" align="left"/>\n<BR/>\n<P align="right">트롬카! 이 책에는</P>\n<P align="right">위대한 호드와</P>\n<P align="right">나약한 얼라이언스의</P>\n<P align="right">군사 계급이</P>\n<P align="right">정리되어 있다.</P>\n<P align="right">먼저 호드의 군사 계급을,</P>\n<P align="right">그 다음에 얼라이언스의 계급을 기록했으며</P>\n<P align="right">각각 장교와 사병 계급으로 구분되어 있다. 가장 높</P>\n<P align="right">은 계급이 제일 위에! 아래에 낮은 계급이 온다!</P>\n</BODY>\n</HTML>'),
(2662, '<HTML>\r\n<BODY>\r\n<H1 align="center">호드 장교 계급</H1><BR/>\r\n<P align="center">제 1 장</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">대장군</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">장군</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">전투사령관</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">사령관</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">부사령관</P><BR/><BR/>\r\n</BODY>\r\n</HTML>'),
(2663, '<HTML>\n<BODY>\n<H1 align="center">호드 장교 계급</H1><BR/>\n<P align="center">제 2 장</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">백인대장</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">용사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">혈투사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">투사</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2664, '<HTML>\n<BODY>\n<H1 align="center">호드 사병 계급</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">하급투사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">정예수호병</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">수호병</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">그런트</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">척후병</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2665, '<HTML>\n<BODY>\n<H1 align="center">얼라이언스 장교 계급</H1><BR/>\n<P align="center">제 1 장</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">최고사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">야전사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">작전사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">사령관</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">부사령관</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2666, '모든 것이 헛수고였던 것$b$b같군... 잠시 후, 여사제는 자신을 둘러싸고 있던 농민들의 시체에 둘러싸인다... 쓰러진$b$b자들이 되살아났다.'),
(2671, '유혹자 시몬:$B$B시몬은 운고로 분화구를 더럽히고 있을 것이다. 그녀의 변장에 속지 마라. 조심스럽게 접근하여 결투를 신청하라.'),
(2672, '미치광이 클린프란:$B$B클린프란은 불타는 초원을 배회합니다. 조심스럽게 접근하여 그의 본모습을 드러내도록 하십시오.'),
(2673, '솔레노르 더 슬레이어:$B$B실리투스의 메마른 풍경 속에 악마 솔레노르 더 슬레이어가 도사리고 있다. 틀림없이 변장한 그는 위험한 존재다. 그에게 다가가 변신을 강요하라.'),
(2674, '파멸을 불러오는 아르토리우스:$B$B아르토리우스는 윈터스프링에서 그가 닿는 모든 것에 타락과 파멸을 불러온다. 그를 찾아내어 처치하라.'),
(2675, '사냥꾼이여, 경고하건대, 이 악마들은 그들의 방식대로 싸워야 한다. 만약 그들이 너보다 약하다고 느끼면 도망칠 것이다.$B$B혼자 가라.'),
(2676, '<HTML>\r\n<BODY>\r\n<H1 align="center">얼라이언스 군사계급</H1><BR/>\r\n<P align="center">장교 계급</P><BR/>\r\n<P align="center">최고사령관</P>\r\n<P align="center">야전사령관</P>\r\n<P align="center">작전사령관</P>\r\n<P align="center">사령관</P>\r\n<P align="center">부사령관</P>\r\n<P align="center">기사단장</P>\r\n<P align="center">기사대장</P>\r\n<P align="center">상급기사</P>\r\n<P align="center">투사</P><BR/>\r\n<P align="center">사병 계급</P><BR/>\r\n<P align="center">하급기사</P>\r\n<P align="center">정예근위병</P>\r\n<P align="center">근위병</P>\r\n<P align="center">파수병</P>\r\n<P align="center">정찰병</P><BR/>\r\n</BODY>\r\n</HTML>'),
(2677, '<HTML>\n<BODY>\n<H1 align="center">호드 군사계급</H1><BR/>\n<P align="center">장교 계급</P><BR/>\n<P align="center">대장군</P>\n<P align="center">장군</P>\n<P align="center">전투사령관</P>\n<P align="center">사령관</P>\n<P align="center">부사령관</P>\n<P align="center">백인대장</P>\n<P align="center">용사</P>\n<P align="center">혈투사</P>\n<P align="center">투사</P><BR/>\n<P align="center">사병 계급</P><BR/>\n<P align="center">하급투사</P>\n<P align="center">정예수호병</P>\n<P align="center">수호병</P>\n<P align="center">그런트</P>\n<P align="center">척후병</P><BR/>\n</BODY>\n</HTML>\n'),
(2691, '공포의 말을 길들이려면 다음 세 가지를 해야 합니다.$B$B대소환의 원을 생성하십시오.원 안에서$B$B조로스로 가는 차원문을 열고 공포의 말을 그 안으로 끌어들이십시오.공포의 말을$B$B쓰러뜨린 다음, 그 영혼을 지배하십시오.다음 페이지에서$B$B각 단계를 수행하는 방법을 자세히 설명하겠습니다. 쉽지는 않겠지만, 당신은 이미 충분한 능력을 갖추고 있습니다. 집중력과 기술을 발휘한다면 공포의 말을 당신의 것으로 만들 수 있을 거라고 확신합니다.계속$B$B읽어보세요.$B-모르줄 블러드브링어'),
(2692, '의식 도구들의식을$B$B시작하기 전에 다음 마법 도구들을 준비해야 합니다.이브이의 항아리$B$B검은 자석$B오로티안 상형문자내$B하인$B$B고르지키가 대가를 받고 이 도구들을 구해줄 것입니다. 이 모든 도구 없이는 의식의 어떤 단계도 시도하지 마십시오. 각각의 도구는$B$B필수적입니다.다음 페이지에서 각 도구의 사용법을 설명하겠습니다.'),
(2693, '대결속의 원은 마력이 강한 장소에서 만들어야 합니다.$B$B엘드레탈라스, 즉 혈투의 전장 깊숙한 곳에 그런 장소가 있습니다. 그곳에는 막강한 힘의 존재 이몰타르가 갇혀 있으며, 그의 감옥 받침대 위에서 대결속의 원을 만드는 의식을 치러야 합니다.$B$B받침대까지 싸워 올라가 제이비를 항아리에서 풀어주십시오.'),
(2694, '종, 바퀴, 그리고 양초제이브를$B$B풀어준 후, 그는 종, 바퀴, 그리고 양초를 놓을 것이고, 원이 나타날 것입니다. 이것이 의식의 시작입니다. 주의를 기울여야 합니다. 앞서 언급한 물건들은 엄청난 에너지를 전달하며 고장이 나기 쉽습니다. 고장이 나면 의식이 완전히 실패하기 전에 검은 자석을 사용하여 재빨리 다시 작동시켜야 합니다.만약$B$B세 가지 물건 모두 다시 작동시키기 전에 고장 나면, 의식은 종료되고 처음부터 다시 시작해야 합니다.'),
(2695, '종, 바퀴, 양초는 의식의 에너지를 전달하는 것 외에도 각각 고유한 속성을 지니고 있습니다. 데트무라의$B$B종은 울릴 때 원 안에 있는 마법사들에게 활력과 에너지를 부여합니다. 검은 행진의$B$B바퀴는 회전할 때 원 안에 있는 자들을 위험으로부터 보호합니다. 종말의$B$B양초는 탈 때 원 안으로 들어오는 적들에게 불가사의한 에너지를 날립니다.$B$B이러한 축복 때문에 의식 동안 이 모든 물건들이 제대로 작동하는지 확인하는 것이 매우 중요합니다.'),
(2696, '또한 종, 바퀴 또는 양초가 작동하지 않을 경우 재가동하는 데 사용되는 검은 자석에는 영혼 조각이 필요하다는 점에 유의해야 합니다. 자석을 사용하여 의식 도구를 재가동할 때마다 영혼 조각 하나가 소모되므로 의식을 시작하기 전에 충분한 영혼 조각을 확보해 두십시오.'),
(2697, '의식 완료하기원$B$B테두리를 따라 나타나는 마법 룬을 통해 진행 상황을 확인할 수 있습니다. 룬 아홉 개가 나타나면 의식이 완료되고, 새롭게 강화된 원에서 에너지가 솟아오르는 것을 볼 수 있습니다.그 후,$B$B크소로스의 상형문자를 소환하여 크소로스로 통하는 차원문을 열고 공포의 말을 끌어들일 수 있습니다.공포의$B$B말을 물리치고 그의 영혼을 해방시키세요. 영혼과 대면하면 영혼은 당신에게 매혹될 것이며, 당신은 그 소환의 비밀을 보상으로 받게 될 것입니다.'),
(2731, '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P align="left">듀로탄, 여기 잠들다 - 서리늑대 부족의 초대 족장이자 영예로운 대족장 스랄님의 부친. 그는 우리 중 가장 용감한 자였다. 그는 우리 민족을 노예로 만들어 버리려는 자들에게 배반 당했고, 우리가 자유를 얻을 수 있도록 하기 위해 자신의 목숨을 바쳤다. 우리는 그를 추모하며 그의 유산은 그의 아들을 통해 우리에게 전수되었다.\r\n </P><BR/>\n<P align="left">서리늑대부족 예언자 드렉타르 </P>\n</BODY>\n</HTML>'),
(2770, '<HTML>\n<BODY>\n<H1 align="center">호드 군사 계급</H1><BR/>\n<P align="center">장교</P><BR/>\n<P align="center">대장군</P>\n<P align="center">장군</P>\n<P align="center">전투사령관</P>\n<P align="center">사령관</P>\n<P align="center">부사령관</P>\n<P align="center">백인대장</P>\n<P align="center">용사</P>\n<P align="center">혈투사</P>\n<P align="center">투사</P><BR/>\n<P align="center">사병</P><BR/>\n<P align="center">하급투사</P>\n<P align="center">정예수호병</P>\n<P align="center">수호병</P>\n<P align="center">그런트</P>\n<P align="center">척후병</P><BR/>\n</BODY>\n</HTML>'),
(2771, '양파 껍질 벗기기$B스톰파이크 해체 가이드 $B- 드렉타르 지음$B$B이 책에는 전투 전술과 정치에 대한 풍부한 지식이 담겨 있습니다. 노련한 병사는 경험의 어깨에 의지하는 병사입니다. 이 책이 알터랙 계곡 전투에서 당신의 길잡이가 되어 줄 것입니다.$B'),
(2772, '제1장 - 최전선$B$B스톰파이크 군대를 격파하는 것은 마치 양파 껍질을 벗기는 것과 같습니다. 핵심에 도달하려면 먼저 가장 바깥쪽 껍질부터 벗겨내야 합니다.$B$B주로 스톰파이크 산악병과 얼라이언스 파수꾼으로 구성된 최전선은 대장의 벙커와 연결되어 있습니다. 발린다 스톤하스 대장은 이 부대에 힘을 실어주고 포위 공격 시 증원군을 지원합니다. 대장을 공격하면 최전선 병력은 무너질 것입니다.$B$B'),
(2773, '제2장 - 쌍둥이 탑$B$B반다르 스톰파이크는 결코 어리석지 않고 교활한 적수임이 분명하다. 최전선을 돌파한 후에도 부차적인 방어 목표물들을 파괴해야 한다. 던 발다르 외곽의 스톰파이크 경비병들과 스톰파이크 순찰대를 통제하는 것은 바로 스톤하스와 아이스윙이라는 쌍둥이 탑이다.'),
(2774, '이 두 탑이 모두 요새화되고 밴더의 엘리트 지휘관 중 한 사람이 통치하기 때문에 병사를 조심하십시오. 당신 군대가 요새화를 위반한다면, 사령관이 침묵했는지 확인하십시오. 이것 역시 스톰 파이크의 해체의 일부가 될 것입니다.$B'),
(2775, '제3장 - 네 명의 지휘관$B$B스톰파이크의 세 번째 껍질은 네 명의 지휘관으로 이루어져 있습니다. 이 점에서 반다르는 우리 영광스러운 프로스트울프의 방어 체계를 모방했습니다. 물론 그는 다르게 생각하겠지만… 이야기가 옆길로 새는군요. $B$B네 명의 지휘관은 던 발다르를 맹렬히 지키는 스톰파이크 근위병들의 흐름을 조종합니다. 그들을 모두 침묵시키면 스톰파이크 근위병들은 무너질 것입니다. $B$B그다음에는 껍질 하나만 남았습니다.$B'),
(2776, '제4장 - 던 발다르 벙커$B$B여러분도 이미 눈치채셨겠지만, 스톰파이크의 방어선은 강력한 한 방에 전군이 전멸하는 것을 막기 위해 구축되었습니다. 혹시 궁금해하실까 봐 미리 말씀드리지만, 우리 군대 역시 정확히 같은 방식으로 배치되어 있으며, 저는 우리의 방어 구조를 바꿀 생각이 없습니다. 그들이 우리를 모방했는데, 우리가 왜 바꿔야 합니까?$B')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2777, '어디까지 얘기했더라? 그래, 던 발다르에 위치한 던 발다르 벙커는 반다르에서 가장 신뢰받는 정예 경비 부대인 스톰파이크 디펜더스를 통제하고 있지. 저 두 개의 탑을 파괴하면 반다르를 지원하기 위해 파견된 증원군은 더 이상 나타나지 않을 거야.'),
(2778, '에필로그$B$B이 모든 일을 마치고 나면 양파의 중심, 즉 달콤한 심만 남게 됩니다. 반다르 스톰파이크는 무방비 상태로 홀로 남겨질 것입니다. 군사 규정에 따라 처형을 집행하기 전에 항복을 요구해야 합니다. 그를 만나면 항복 이야기를 꼭 꺼내십시오... 그리고 나서 그를 처치하십시오.'),
(2779, '서리늑대 아티초크: 스톰파이크의 영광 이야기\n- 반다르 스톰파이크 지음\n\n서리늑대란 무엇일까요? 간단합니다. 서리늑대는 우리의 주권적 제국주의를 막으려는 야만인들입니다.\n\n아티초크처럼 서리늑대는 가시투성이의 단단한 방어막을 가지고 있으며, 아티초크처럼 겉껍질을 벗겨내면 속살이 드러나 마늘 소스에 찍어 먹을 수 있습니다.\n\n정말 맛있죠!'),
(2780, '제1장 - 최전선\n\n프로스트울프 방어선의 최전선은 프로스트울프 전사들로 이루어져 있습니다. 이 전사들은 갈반가르 대장의 요새인 아이스블러드 주둔지에서 최전선으로 배치됩니다. 이 방어선을 무너뜨리는 가장 효율적인 방법은 아이스블러드 주둔지를 파괴하는 것입니다.\n\n요새를 포위 공격하고 갈반가르 대장을 처치하십시오. 그러면 최전선이 무너질 것입니다.'),
(2781, '제2장 - 얼음 피와 탑 지점\n\n첫 번째 층을 파괴하면 \'아티초크\'의 두 번째 층이 드러납니다. 최전선 근처에 있는 서리늑대 탑들을 파괴하면 후방에서 몰려드는 군단병과 순찰대의 진격을 크게 약화시킬 수 있습니다.\n\n이 탑들은 드렉타르의 정예 사령관들이 각각 주둔하고 있는 견고한 요새입니다. 이들을 처치해야만 서리늑대 방어선을 신속하게 무너뜨릴 수 있습니다.'),
(2782, '제3장 - 네 명의 사령관\n \n이 안내서의 조언을 잘 따라왔다면, 이제 드렉타르의 사령관 두 명을 처치했을 것입니다. 훌륭한 활약입니다, 병사! 그들의 결의는 이미 약해지고 있습니다. 이제 남은 두 명의 사령관을 모두 처치하여 지휘 계통을 완전히 무너뜨려야 합니다.\n\n네 명의 사령관을 모두 처치하면, 서리늑대 요새를 지키는 서리늑대 군단병들은 뿔뿔이 흩어져 지휘권을 잃게 될 것입니다. 이제 당신이 노릴 차례입니다!'),
(2783, '제4장 - 동쪽과 서쪽 서리늑대 탑\n\n이제 승리까지 남은 장벽은 단 하나, 드렉타르의 가장 신뢰받는 강력한 수비대, 서리늑대 수호자들입니다.\n\n서리늑대 수호자들은 동쪽과 서쪽 서리늑대 탑에 예비대로 대기하고 있다가 출격합니다. 이 탑들을 파괴하면 남은 서리늑대 수호자들이 수치심에 도망치는 모습을 볼 수 있을 것입니다.'),
(2784, '에필로그\n\n"아티초크 심장부에 마늘 버터와 마요네즈를 듬뿍 발라라. 숙성된 진한 에일 맥주를 곁들이면 더욱 맛있을 것이다."\n\n드렉타르는 이제 두 마리의 잡종견과 함께 홀로 남았다. 전투에 도움이 될 서리늑대 구호소를 점령하고 드렉타르를 처치하라. 장군이 쓰러지면 이 땅은 마침내 정당한 주인인 스톰파이크에게 돌아갈 것이다.'),
(2785, '당신께 부르짖나이다. 줄다자르의 잔자여.\n당신의 도움을 청하는 자들을 축복하소서, 로아 잔자시여. 잔달라 부족과 동맹을 맺으려는 이들을 축복하소서.\n이 고난의 시기에 우리를 도와 주소서. 우리를 도우소서, 로아여. 우리의 적들을 쳐부술 힘을 주소서. 다시 한번 혈신을 물리칠 수 있는 힘을 우리에게 주소서.\n'),
(2786, '가시덤불 골짜기 낚시 대회!$B일요일 오후 2시부터 4시까지$B$B무법항를 제외한 가시덤불 골짜기 해안 어디에서든 낚시를 즐겨보세요! 해안을 따라 나타나는 맛있는 물고기 떼를 찾아보세요! 찌를 물고기 떼에 정확히 꽂으면 일반 가시덤불 골짜기 물고기가 아닌 특별한 물고기를 낚을 수 있습니다. 맛있는 물고기 40마리를 먼저 잡는 사람은 무법항에서 물고기를 \'피쉬마스터 배스베이트\'로 교환하여 상품을 받을 수 있습니다!   $B$B40마리를 먼저 잡지 못하더라도 물고기를 교환하여 현금을 받을 수 있으며, 특별한 물고기를 낚으면 특별한 상품을 받을 수도 있습니다!$B'),
(2787, '그의 이름은 아제로스의 암흑기에 빛을 가져왔고,$B$B그의 용맹함은 비참한 고통의 벽을 무너뜨렸도다.$B$B은빛성기사단의 가장 큰 공포는 장차 이 세계를 위해$B$B자신을 희생하게 될 기사를 배출할 것일지니.'),
(2788, '그는 자신의 명예를 높이려 하지 않았으며,$B$B동쪽 위에 군림하려 하지도 않았도다.$B$B오히려 로데론을 위해 싸울 것을 택했으니$B$B이는 자신의 동족이 더 이상 싸우지 않게 되기를 바랐음이라.'),
(2789, '이 가장 성스러운 기사의 슬픈 이야기는$B$B결코 그의 부정한 죽음으로 끝나지 않으리라.$B$B우리는 그를 기리고, 그에게 감사를 표할지니!$B$B우서 경은 언제나 영광, 그리고 빛과 함께하리라!'),
(2790, '그의 이름은 쇠하지 않을 것이요.$B그의 희생은 언제나 우리의 길을 인도하리.$B한때 우리의 명예를 앗아갔던 숨 막히는 족쇄는$B$B더 이상 우리를 구속하지 못하느니.'),
(2791, '호드를 위한 그의 외침이 들리는가?$B"승리가 아니면 죽음뿐!"$B$B죽음에 맞서 보여 준 그의 용기와 힘을 반그시 기억 할지니.$B그의 꿈이 현실이 되었음이로다.'),
(2792, '곳곳에 위험이 만연해 있고,$B적들은 우리에게 다시 한번 족쇄를 채우려 하니...$B$B전투를 할 때면 기억하라!$B반드시 해야 할 일을 해냈던 영웅을!$B그롬 헬스크림이여, 영원하라!'),
(2793, '흐르는 모래 전쟁 이후 거의 천 년의 세월이 흘렀다. 실리더스 사막 한가운데에서 벌어진 그 전쟁에서 판드랄 스테그헬름은 참담한 비극과 엄청난 정신적 고충을 겪었다. 결과적으로 대드루이드로서의 명예가 실추된 것도 바로 이 사건 때문이 아닐까 생각된다.'),
(2794, '아주 오래전 퀴라지라는 지능이 발달한 고대 곤충류가 칼림도어를 점령하고 쳐들어왔다. 이때 퀴라지를 막기 위해 나선 것은 거만한 제국주의 사상에 찌든 스테그헬름과 그의 나이트 엘프 군대였다.$B'),
(2795, '실리더스에서 아버지와 아들은 밀려드는 곤충 떼에 맞서 용감히 싸웠다. 그러나 안퀴라즈의 요새에서 수많은 실리시드 무리가 쏟아져 나와 침략자 퀴라지 무리를 지원하기 시작했다. 마침내 실리더스 전체가 곤충 떼에 포위되고 말았다.$B'),
(2796, '이때 스테그헬름은 평생을 후회할 결정을 내리게 된다. 자신의 아들인 발스탄에게 마파람 마을의 나이트 엘프 전초기지를 사수하라는 명령을 내린 것이었다. 불행히도 발스탄은 마파람 마을이 안퀴라즈 군대에 함락되던 날 전사하여 짧은 생을 마감하고 말았다.$B'),
(2797, '복수심에 불타오른 판드랄 스테그헬름은 결사적으로 항전했지만 실리더스에서 참해하여 나이트 엘프와 칼림도아는 이미 엄청난 타격을 입은 뒤였다.$B$B격렬한 전투는 수개월 동안 계속되었고, 결국 실리더스의 모든 지역이 퀴라지의 손아귀에 넘어갔다. 스테그헬름과 그의 군대는 타나리스로 후퇴해야만 했다. 많은 전사들이 목숨을 잃었고, 무고한 민간인들도 수없이 학살되었다. 판드랄 스테그헬름은 결국 자신의 오만함으로 인해 모든 것을 잃어버린 것이다.'),
(2798, '스테그헬름은 자존심에 큰 상처를 입었다. 그 후 또 다시 그를 공포의 도가니로 몰아넣은 두 번째 사건이 타나리스에서 발생했다. 이에 스테그헬름은 노즈도르무의 후손인 아나크로노스에게 청동용군단의 지원을 요청하려 했다.'),
(2799, '처음에 아나크로노스는 청동용군단이 미개한 종족을 지원할 수는 없다며 거절했으나 퀴라지 군대가 시간의 동굴을 공격하자 나이트 엘프 군대와 연합 전선을 펼치기로 합의했다.'),
(2800, '하지만 아나크로노스는 강력한 청동용군단조차 퀴라지를 막기에는 역부족이라는 것을 깨닫는다. 그가 숨결을 내뿜을 때마다 곤충 떼 50마리가 사라졌지만 곧이어 100마리가 달려드는 상황이었다. 나이트 엘프의 방어선이 점점 북쪽으로 밀리면서 페랄라스의 황야까지 위협을 받는 상황에 이르자 아나크로노스는 위상의 자손들을 깨우기로 결심했다.'),
(2801, '그는 우선 이세라의 용군단을 불렀다. 먼저 메리스라가 에마랄드의 꿈에서 깨어나 그의 부름에 응답했고 알렉스트라자와 말리고스의 용군단도 깨어났다.'),
(2802, '안퀴라즈 요새에서 수천 미터 상공에 있는 실리더스의 하늘 위로 용들이 몰려들었다.$B$B그중에는 시간의 위상이자 노즈도르무의 후손인 아나크로노스가 있었다. 에메랄드의 꿈에서 깨어난 자연의 위상이자 이세라의 후손인 메리스라도 있었다. $B$B붉은용군단에서 생명의 위상이자 알락스트라자의 후손인 캘레스트라즈를 대표로 보냈다. 그리고 마법의 위상이자 말리고스의 후손인 아리고스가 푸른 용군단의 대표로 왔다.$B'),
(2803, '용들은 안퀴라즈에서 실리시드와 퀴라지 무리가 끝도 없이 쏟아져 나오는 장면을 목격하고 아무리 많은 군대를 동원하더라도 이 전쟁을 끝낸다는 것은 불가능 하다는 사실을 깨달았다. 신전 안에는 수만마리가 넘는 퀴라지 군대가 대기하고 있었으며, 시시각각 엄청난 유충이 부화하여 이 세상을 파괴할 준비를 하고 있었다.$B'),
(2804, '안퀴라즈의 남쪽 신전에서 퀴라지의 것과는 다른 마력이 희미하게 분출되고 있다는 사실을 가장 먼저 알아챈 것은 아리고스였다. 용들은 그 마력의 근원을 알아내기 위해 신전 안으로 들어가려 했지만 아무도 성공하지 못했다. 그토록 완벽하게 자신을 보호하는 것으로 보아 어마어마한 힘을 가진 존재임이 틀림없다. 아마도 곤충들, 퀴라지 전체를 통제하는 존재일 것이다.'),
(2805, '용들은 신속하게 대처하지 않으면 이 세계에 또 다른 재앙이 닥치게 되리라는 것을 잘 알고 있었다. 그들은 심사숙고 끝에 마력의 근원을 지키고 있는 군대를 저지하는 것이 최선의 방법이라는 결론을 내렸다.'),
(2806, '나이트 엘프와 용군단은 모두의 정기를 그러모아 거대한 마법의 장벽을 만들기로 했다. 안퀴라즈의 성벽 안에 실리시드와 놈들의 우두머리를 모두 가두고 이후의 침략도 방어하는 것이다. 안퀴라즈 그 자체가 거대한 감옥이 되는 것이다.'),
(2807, '1일차.$B우리의 순례가 끝났습니다. 드디어 실리토스에 도착했습니다. 이곳에서 우리는 접촉을 시도할 것입니다. 우리는 기념비적인 사업을 위해 여러 곳에서 모여 협력하고$B$B있습니다. 엄청난 기대감이 공기를 가득 채우고 있습니다. 내일 우리는 그들과 소통할 수 있는 장치를 만드는 데 모든 에너지를 쏟을 것입니다.$B$B내일 우리는 바람의 돌을 만들 것입니다!'),
(2808, '2일차$B바람의 돌 위치를 두고 큰 논쟁이 벌어지고 있다. 우리 가운데 가장 현명한 자들조차 옛 예언이 가리키는 장소가 정확히 어디인지 확신하지 못한다.$B$B나는 처음부터 북쪽을 주장한 무리에 남았다. 시간이 지나면 우리가 옳았다는 것이 분명해질 것이다. 이곳에서 에너지 선이 해로운 각도로 교차한다는 주장은 어리석고 순진하다.$B$B벌써 필요한 건축 자재를 빠른 속도로 모으고 있다.'),
(2809, '15일째.$B우리의 헌신이 결실을 맺었습니다. 우리가 바람의 돌 건설을 완료한 첫 번째 캠프입니다. 다른 바보들이 우리와 함께했더라면 일주일도 안 돼서 끝냈을 텐데! 내일은$B$B카줌 남작을 소환하는 의식을 시작할 겁니다. 그는 이 시스템을 가장 먼저 시험해 보고 싶어 했고, 화를 잘 내는 성격이라 거절할 수가 없었습니다. 그가 우리를$B$B매우 만족스러워할 거라고 생각합니다.'),
(2810, '황혼의 망치단 모든 구성원에게 즉시 배포하십시오.$B$B배신자 오르텔을 찾는 작업이 매우 순조롭게 진행되고 있습니다. 정찰병들은 그의 위치를 ​​서부 몰락지대의 동굴망으로 좁혔습니다.$B$B오르텔의 배신은 용서받을 수 없으며, 그의 탈출은 우리 조직에 큰 안보 위험을 초래합니다.$B$B오르텔의 행방에 대한 정보를 은폐하는 자는 누구든지 엄벌에 처할 것입니다.-$B$B황혼의 군주 에버룬'),
(2811, '모든 트와일라잇 해머 대원들에게 즉시 배포하십시오.$B$B실리투스의 현 상황을 고려하여, 진정한 신봉자 경전의 배포는 최소 4명 이상의 무장한 트와일라잇 해머 대원의 호위 하에 이루어져야 합니다.$B$B이 새로운 방침을 위반하는 대원은 즉시 처벌될 것입니다.$B$B-트와일라잇 로드 드삭'),
(2812, '황혼의 망치단 모든 단원들에게 즉시 배포하십시오.다음$B$B정보는 심연 의회의 주인들과 소통하기 위한 바람의 돌 사용법에 관한 것입니다.바람의 돌을 경솔하게$B$B사용하는 자는 가장 고통스러운 방식으로 처벌받을 것입니다.-$B$B황혼의 수호자 하분스'),
(2813, '심연의$B$B기사단입문자는 일상적인 의식을 위해 심연의 기사단과 접촉할 수 있습니다. 바람의 돌을 사용할 때는 방어 마법이 발동되지 않도록 항상 적절한 복장을 착용하십시오.감독관이 없는$B$B예기치 못한 비상 상황이 발생할 경우, 심연의 기사단을 소환할 수 있는 권한이 부여됩니다.소환$B$B의식에 대한 자세한 내용은 지난달 \'진정한 신봉자\'를 참조하십시오.'),
(2814, '심연의 공작$B$B계급장을 소지한 수행사제만 심연의 공작과 접촉할 수 있다. 계급장은 원래 발급받은 당사자만 사용할 수 있다.$B$B심연의 공작과 승인 없이 접촉하거나 계급장을 무단 사용하는 황혼의 망치단원은 내가 직접 징계할 것이다.'),
(2815, '심연 군주 최고 평의회오직$B$B황혼 군주만이 스칼드레녹스 왕자, 월락시스 대원수, 카줌 남작 또는 스콜 경에게 연락할 수 있습니다.$B$B어떤 경우에도 황혼의 망치단의 하위 계급 구성원은 최고 평의회와 소통을 시도할 수 없습니다. 외부인이 이러한 방식으로 바람의 돌을 사용하는 것이 적발될 경우, 그 자리에서 재로 변하게 될 것입니다.'),
(2816, '컬트의 현황, 제92권형제들이여,$B$B기쁜 마음으로 여러분께 인사드립니다. 우리 컬트의 현황은 더할 나위 없이 훌륭합니다. 우리는 군단이 되었고, 우리의 목표는 결실을 향해 점점 더 가까워지고 있습니다.$B$B새로운 신도들이 계속해서 모여들고 있습니다. 그들은 다크쇼어에서 우리 군주들을 찬양하고, 작열하는 협곡에서 환희에 찬 황홀경에 빠져 절하며, 검은심연에서 우리 주인의 종 아쿠마이를 껴안습니다. 참으로, 형제자매들이여, 머지않아 충성스러운 무리가 아제로스 전역을 뒤덮을 것입니다!'),
(2817, '컬트 현황, 제127권정말$B$B기쁜 날입니다! 우리는 실리투스에서 시험을 통과했습니다!$B$B우리 최북단 진영의 파괴 소식은 불신자들의 마음을 흔들겠지만, 이 학살을 비극으로 여겨서는 안 됩니다. 절대 아닙니다!'),
(2818, '심연의 최고 의회 구성원 중 하나가 우리의 피를 흘린 것은 축복이다! 우리는 쓰러진 동료들을 부러워해야 한다. 그들의 영혼이 이제 가장 정의로운 짐승의 뱃속에 거하고 있으니$B$B말이다! 고대 신들에게 찬양을! 그들의 종들에게 찬양을! 황혼의 망치에게 찬양을!'),
(2819, '컬트의 현황, 제233권형제자매들이여,$B$B또다시 기회가 찾아왔습니다! 사악한 자연 숭배 집단인 세나리온 서클이 우리에게 첩자를 보내고 있습니다. 그들은 우리가 붉은 유혹석을 소환하는 것을 막으려 합니다. 우리는 결코 이를 용납할 수 없습니다!붉은 돌은 우리의$B$B새로운 동맹에게 매우 중요합니다. 세나리온 서클의 앞잡이들이 성공하도록 내버려 둘 수 없습니다. 굳건히 버티십시오, 나의 충실한 친구들이여! 굳건히 버티십시오!'),
(2820, '그들이 우리를 사랑한다는 것을 어떻게$B$B알 수 있을까요? 어떤 이들은 고대 신들과 그들의 하수인들이 어떻게 우리를 사랑할 수 있는지 의아해할지도 모릅니다. 그들은 우리를 죽이지 않나요? 그들은 모두에게 고통과 괴로움을 안겨주지 않나요? 악의에 가득 찬 존재들이 어떻게 마음속에 사랑을 알$B$B수 있을까요? 이 질문에 대한 답은 간단합니다. 너무나 간단해서 굳이 말할 필요도 없을 정도입니다.'),
(2821, '믿음. 믿음은 우리에게 섬김의 기쁨을 쏟아붓게 하는 근원입니다. 믿음은 실리투스의 가장 추운 밤에도 우리를 따뜻하게 해 줄 것입니다. 믿음은 종말의 날이 올 때 주님의 은총을 지켜 줄 것입니다. 믿음이$B$B우리를 구원할 것입니다.'),
(2822, '당신은 이 장부에 적힌 단어를 하나도 이해할 수 없군요. 무슨 언어로 쓰여 있는지조차 모르잖아요!'),
(2825, '엘프들의 가장 암울한 순간에 쿠엘탈라스 왕가의 마지막 혈통, 캘타스 선스트라이더가 나타났다. 흔히 캘이라 불리던 그는 한때 백성을 지탱하던 마법 없이는 살아남은 이들이 오래 버티지 못할 것을 알았다. 쓰러진 동포들을 기려 백성의 이름을 블러드 엘프로 바꾸고, 끔찍한 마법 갈증을 달래기 위해 주변의 신비한 힘은 물론 악마의 힘까지 끌어 쓰는 법을 가르쳤다.'),
(2829, '일기야,$B$B오늘, ​​내 숙적 나라인 수스팬시가 사형 집행식에 자기 대신 부하들을 보내 나를 속이려 했어. 그것도 바로 자기가! 믿을 수 있어?$B$B그 빌어먹을 오두막에서 그를 유인해내려고 온갖 악랄한 계획을 세웠는데, 이런 짓을 하다니? 정말… 너무 화가 나서 더 이상 쓸 수가 없어. 나중에 다시 쓸게.'),
(2830, '일기야,$B$B지난번 일기를 쓰고 나서 분노에 휩싸여 은신처를 떠났어. 정말 화가 많이 났었지. 내 분노를 더 잘 표현하기 위해 부하들의 유니폼을 새로 디자인하기로 했어. 기분이 조금 나아지긴 했는데, 뭔가 부족한 것 같아. 금방 돌아올게...'),
(2831, '일기야,$B$B괜찮아. 이제 괜찮아. 내 부하 하나를 혼쭐내 냈거든. 으음...$B$B그런데 좀 미안한 마음이 드네. 잠깐만! 젠장, 난 사악한 천재였잖아! 진짜 사악하다고! 너무 실망스러워. 금방 돌아올게.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2832, '일기야,$B$B그를 껴안아주고 계속 잘하라고 격려해 줬어. 이제 기분이 좀 나아졌어. 이건 우리 둘만의 비밀이야,$B$B일기야. 어, 어디까지 얘기했더라? 아, 맞다, 나라인! 아! 그 자식 정말 싫어. 우리가 그놈레간 기계공학 연구소 학생이었을 때, 모든 시험 점수를 망쳐놓은 게 바로 나라인이었잖아.$B$B날 학교에서 낙제시키려는 건가? 내 생각엔 그놈레간은 마땅한 벌을 받은 거야!$B$B오늘은 여기까지야. 잘 자, 일기야!'),
(2833, '일기야,$B$B내가 늙었나 봐. 나라인과 그의 속임수에 대해 얘기했던 걸 완전히 잊고 있었어. 어쨌든 나라인 행세를 하는 가짜를 보고 너무 화가 나서 넘버 투에게 그 바보를 없애버리라고 명령했지! 비비는 내 비행기에$B$B올라타서 그 귀중하고 멍청한 드라코닉 책을 찢어발기기 시작했어. 잘난 척쟁이 같으니! 누가 드라코닉을 읽어? 정말 그 자식이 너무 싫어!'),
(2834, '일기야,$B$B미안해, 잠들어 버렸어. 그래서 화가 나서 날아다니면서 그 빌어먹을 책의 챕터들을 마구 던져버렸지. 다크위스퍼에서 내 발밑에 악마가 보이길래, 책 첫 장을 마법의 회오리바람으로 만들어서 악마의 몸을 산산조각 내버렸어! 속이 후련했어. 마법 + 종이 = 재밌다!그 덕분에 기분이$B$B너무 좋아져서 동부 왕국으로 날아가기로 했어. 첫 번째 목적지는 용암의 심장부였지. 나라인이 항상 그곳에 대해 얘기했었거든! "용암의 심장부 어쩌고저쩌고, 라그나로스 어쩌고저쩌고..."'),
(2835, '음, 있잖아? 그가 그렇게 좋아한다면, 용암 핵으로 가서 재더미에서 책을 되살려내는 것도 좋아할지도 몰라! 하하!근처에 있는 김에, 빅터$B$B네파리우스의 연구실에 있는 그 침 흘리는 기술자들이 이 드래곤 관련 물건에 쓸모가 있을지도 모른다고 생각했지. 폭탄 투하!'),
(2836, '이건 일종의 스포츠처럼 되어가고 있었다. 그 빌어먹을 책을 쪼개는 데 완전히 빠져버렸어! 다음$B$B몇 장은 쉬웠다. 악취 나는$B$B시체들이 썩어가는 곳이자 내가 먹어본 최고의 칠리가 있는 언더시티가 한 챕터였다. 치즈의 수도 스톰윈드가 나머지 한 챕터였다. 일기장아, 스톰윈드 치즈를 언더시티 칠리에 넣어본 적 있어? 어이없네! 뭔가 이상하다는 생각이 들지 않니?'),
(2837, '이쯤 되니 피곤해져서 비행기를 돌려 집으로 향했지만, 그 전에 두 군데 더 들렀다. 오염된 흉터에서 카자크 경과 그의 악마들을 잠깐 훑어보고(그는 내가 이렇게 하는 걸 싫어한다), 오닉시아의 굴뚝에도 한 번 더 들렀다. 피곤해.$B$B자러 가야겠다.'),
(2838, '관계자 여러분께,\n\n우리가 함께하는 이 게임들이 얼마나 즐거운지 모릅니다. \n\n만약 당신이 이 편지를 읽고 있다면, 당신은 기적이나 신의 개입으로 저를 물리치셨을 거라고 짐작할 수밖에 없습니다. 터무니없는 소리인 건 알지만, 세상엔 더 이상한 일도 많이 일어나니까요.'),
(2839, '인생의 모든 일들이 그렇듯, 이 슬픈 이야기에도 비극과 혼돈, 악 속에는 찬란한 희망이 숨어 있습니다. 당신은 저를 죽였지만, 너무나 느리고 무질서한 방식으로 죽였기에 저는 이 편지를 쓸 시간을 벌었습니다. 그 후에야 비로소 당신이 이 세상을 구할 유일한 희망을 파괴할 수 있었습니다. 부서진 붉은 수정 가루만이 당신의 홀 조각에서 남은 전부입니다.'),
(2840, '제 보물창고에서 발견할 수 있는 네메시스와 스톰레이지 무기를 마음껏 즐기십시오. 제 아버지께서 이루지 못하신 일을 제가 해냈다는 사실에 큰 기쁨을 느낍니다.\n\n\n진심으로,\n\n빅터 네파리우스 경\n"네파리안"'),
(2841, '굴뚝나무 목장조합을 대신하여 이 일을 맡아줘서 고맙네. 정확히 누가 멧젠을 납치했는지는 모르지만 일단 조사를 시작하는 것이 좋겠지!$B$B시간은 돈이라고, 친구! 그리고 이번 사건에서만큼은 시간이 더욱 귀하니 최선을 다해 조속히 해결해주게. 멧젠을 데려간 놈들은 어떤 일이든지 서슴지않고 저지를 수 있는 녀석들이란 말이네.$B$B자, 다음 장에는 각각 놈들이 몸값을 요구하기 위해 남기고 간 단서가 있네. 친구여, 부디 행운을 비네...'),
(2842, '순록을 산 채로 돌려받고 싶다면 몸값을 빨리 마련해야 할 것이다. 우리 남쪽바다 해적단은 빚을 늦게갚는 자들을 좋아하지 않는다. 그리고 너의 조합에서 그 짐승이 얼마나 소중한 존재인지 잘 알고 있다.$B$B1000골드를 가지고 타나리스의 해적단 소굴 입구로 오너라. 순록을 구출하려는 섣부른 시도를 할 경우, 어여쁜 멧젠은 우리 해적의 방식대로 아주 끔찍하게 처형당할 것이다. 뱃전 밖으로 나온 짧은 판자 위를 천천히 걷는 것이지!$B$B우리의 경고를 잊지 마라.$B$B남쪽바다 해적단...'),
(2843, '너의 소중한 순록은 여기 이글거리는 협곡의 혹심한 열기를 오래 견뎌내지 못할 것 같다... 그러므로 지체하지 말고 우리의 요구조건을 들어주는 것이 현명한 처사일 것이다.$B$B별루비 5개와 7000골드를 가져와라. 너희 조합의 인장이 찍히지 않은 평범한 가방에 담아서 이번 주 안까지 돌다지 고개로 가는 문 앞에 놓아둘 것!$B$B우리의 요구조건을 들어주지 않을 땐, 맷젠은 검은무쇠단 드워프의 전통대로 겨울맞이 축제 만찬의 주요리가 될 것이다.$B$B음, 순록 꼬치구이라...'),
(2844, '겨울 할아버지의 순록들은 독수리보다 더 빠르다네.$B$B호루라기를 불며 큰 소리로 이름을 부르시지.$B$B머써, 칠튼, 조던, 카플란, 이랴!$B$B네이글, 팔도, 굿맨, 맷젠도 힘차게 날아라!$B$B굴뚝 꼭대기까지, 저 성문을 넘어가자!$B$B지금이다! 신나게! 신나게! 달리자!$B'),
(2846, '연구를 통해 나의 백성들에게 안전한 마력을 보충해 줄 원천을 찾는 것이 나의 간절한 소망이다. 지금 우리는 태양샘을 잃었기 때문에 비전 마법의 유혹에 굴복하지 않고도 삶을 이어갈 수 있는 새로운 방법을 찾아야만 한다.$B$B신도레이는 다시 한 번 찬란한 영광을 누리리라!'),
(2847, '아직까지 운이 따르지 않는 것 같다. 내가 접근할 수 있는 것이라면 아무리 보잘것없는 마법이라도 첨탑을 통해 보내야만 한다. 하지만, 몇 가지 재미있는 생각이 있다. 제자 중 똑똑한 몇 명에게 시켜보고 어떤 결과가 나타날지 봐야겠다.'),
(2848, '아주 오랜만에 쓰는 것 같다. 아직도 쓸 만한 방법을 찾지 못했다. 어제 선스트라이더 섬에 있는 제자 펠렌드렌이 스승의 충고를 듣지 않아 사고가 발생했다는 전갈을 받았다.$B$B노력을 배로 해야겠다.'),
(2849, '아무 성과도 없다. 그러나 절대 포기하지 않을 것이다. 남쪽으로 쫓겨난 이 마당에 신도레이가 마법에만 의존할 수는 없지 않은가.$B$B아주 새로운 방법을 고안했다. 성공한다면 그동안 감춰두었던 타락한 마력 원천에서 `불순물`을 걸러낼 수 있을 것이다. 신중히 진행해야 한다.'),
(2850, '놀랍다! 비록 추출한 마력의 양은 극히 미미했지만 우리는 성공했다. 다른 일을 진행하고 있는 제자들을 불러들여 이 새로운 연구에 투입해야겠다.$B$B운만 약간 따라준다면 실험 절차를 좀 다듬어서 동시에 두 마리 토끼를 잡을 수도 있을 것 같다. 우리에게 필요한 충분한 힘의 원천은 물론 앞으로 우리에게 닥칠지도 모를 사악한 마력에 대항하는 방법도 얻을 수 있으리라 기대한다!'),
(2851, '이럴수가! 새로운 실험을 진행하던 중 내가 가장 아끼는 제자 텔레타욘이 갑작스럽게 말라비틀어지기 시작했다. 동족 모두에게 영향을 미칠 수도 있는 지경까지 이른 것 같았다. 내가 막으려고 시도했을 때는 이미 너무 늦었다. 내가 할 수 있는 일이라고는 그의 고통을 덜어 주는 것뿐이었다.$B$B새로운 발견에는 대가가 따르는 법이다. 그래도 이번에는 너무 고통스럽다.'),
(2852, '참기 어려운 고통이다... 제자 두 명이 또 죽었다. 우리는 아주 조심했다... 도대체 뭐가 잘못된 것인지 알 수가 없다.$B$B이 연구를 중단하고 처음부터 다시 시작해야겠다.'),
(2853, '내가 결정을 너무 늦게 내렸다. 세 번째 제자가 내게 알리지도 않고 다른 제자들과 잘못된 연구를 계속 진행해 온 것이다. 이 상황을 수습할 방법을 모색해야 한다. 하지만, 그보다 급한 일은 아직 영향을 받지 않은 제자들을 떼어 놓는 것이다.$B$B원정순찰대 산장으로 휴가를 가서 문제를 해결할 새로운 방법을 찾아오겠다고 해야겠다.$B$B이 끔찍한 실수를 보상할 방법을 찾아야만 한다.'),
(2854, '<HTML>\n<BODY>\n<H1 align="center">호드 장교 계급</H1><BR/>\n<P align="center">2부</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">백인대장</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">부대원</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">혈투사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">투사</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2855, '<HTML>\n<BODY>\n<H1 align="center">호드 사병 계급</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">정예투사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">하급투사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">기사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">그런트</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">척후병</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2856, '<HTML>\n<BODY>\n<H1 align="center">얼라이언스 장교 계급</H1><BR/>\n<P align="center">2부</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">기사단장</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">기사대장</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">기사중위</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">기사</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2857, '<HTML>\n<BODY>\n<H1 align="center">얼라이언스 사병 계급</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">상급기사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">기사대장</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">기사</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">상병</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">정찰병</P><BR/><BR/>\n</BODY>\n</HTML>'),
(2858, '<HTML>\n<BODY>\n<H1 align="center">\n앤서니 레이 스타크\n</H1>\n<H2 align="center">\n1961 - 2005\n</H2>\n</BODY>\n</HTML>'),
(2859, '<HTML><BODY><H1 align="center">기원의 화로: 설명서</H1><BR/><P align="center">유령 출몰지 찾기</P><BR/><P align="center">소개</P><BR/><P align="left">이 책에는 군주 발타라크의 아뮬렛 사건에 얽혀 쓰러지거나 타락한 영혼들이 머무는 장소가 기록되어 있습니다. 당신은 이미 나의 옛 동료들을 구해냈지만, 한때 그들의 영혼을 뒤틀었던 악의 끔찍한 메아리가 그 유령 출몰지에 아직도 남아 있으리라 생각합니다. 군주 발타라크의 영혼은 그만큼 사악하고 강력했습니다.</P><BR/><P align="left">또한 이 화로로 군주 발타라크를 불러낼 수도 있습니다. 다만 이전과 마찬가지로 극도의 주의를 기울여야 합니다.</P><BR/></BODY></HTML>'),
(2860, '<HTML><BODY><H1 align="center">소개, 계속...</H1><BR/><P align="left">화로 자체는 부름의 화로와 똑같이 작동합니다. 다섯 곳의 유령 출몰지 가운데 어디든 범위 안에 놓기만 하면 죽은 자의 영혼을 불러냅니다.</P><BR/><P align="left">덧붙이자면, 당신이라면 궁금해할 것 같아 알려드리는데, 도발의 깃발도 검은바위 나락의 투기장에서 비슷하게 사용할 수 있습니다. 그곳에 갈 기회가 생길 때마다 텔드렌과 그 졸개들에게 내 몫까지 따끔한 교훈을 주십시오.</P><BR/><P align="left">더 자세한 내용을 알고 싶다면 계속 읽어 보십시오.</P><BR/></BODY></HTML>'),
(2861, '<HTML><BODY><H1 align="center">이살리엔</H1><BR/><P align="center">나이트 엘프 달의 여사제</P><BR/><P align="left">이살리엔이 일행을 떠나기로 했을 때, 그녀는 한때 엘드레탈라스라 불렸던 몰락한 나이트 엘프의 고대 도시 혈투의 전장으로 순례를 떠날 생각이었습니다. 그곳에는 여전히 방대한 지식을 간직한 도서관이 남아 있으며, 소수의 나이트 엘프가 밀려드는 위협을 막아내며 성역을 지키고 있습니다. 그녀는 자신의 혈통에 대한 답과, 어쩌면 아뮬렛 조각에 관한 단서까지 찾으려 했습니다. 이살리엔은 팔린 트리셰이퍼와도 매우 가까운 친구였습니다.</P><BR/></BODY></HTML>'),
(2862, '<HTML><BODY><H1 align="center">이살리엔, 계속...</H1><BR/><P align="left">안타깝게도 이살리엔과 동료 히포그리프 엠피리언이 도시에 들어서던 중 칼날바람 알진과 그의 하수인들에게 습격당했습니다. 그녀는 그곳에서 쓰러져 다시는 일어나지 못했습니다. 어쩌면 이살리엔이 군주 발타라크가 자신의 정수 일부를 아뮬렛에 담기 위해 사용한 사악한 마법의 비밀을 더 알아내지 못한 것이 오히려 다행인지도 모릅니다.</P><BR/><P align="left">칼날바람 알진이 머무는 야외 방도 이러한 유령 출몰지 가운데 하나입니다.</P><BR/></BODY></HTML>'),
(2863, '<HTML><BODY><H1 align="center">모르 그레이후프</H1><BR/><P align="center">타우렌 드루이드, 첫 번째 희생자</P><BR/><P align="left">모르 그레이후프는 장막의 칼날단에서 언제나 든든하고 믿음직한 동료였습니다. 안타깝게도 군주 발타라크의 사악한 하수인들에게 가장 먼저 쓰러진 이도 그였습니다.</P><BR/><P align="left">발타라크에게서 달아날 때 우리는 그의 유령 암살자와 추적자들로 이루어진 군대에게 쫓기고 있었습니다. 검은바위 첨탑에서의 탈출은 말 그대로 아수라장이었습니다. 도중에 모르가 발을 헛디뎌 떨어졌는데, 나는 누군가 그를 밀었다고 의심합니다. 어쨌든 그는 첨탑 아래쪽 깊은 곳으로 추락했습니다.</P><BR/></BODY></HTML>'),
(2864, '<HTML><BODY><H1 align="center">모르 그레이후프, 계속...</H1><BR/><P align="left">나중에 우리는 모르가 그 추락에서 살아남았다는 사실을 알게 되었습니다. 하지만 내 좋은 친구에게 행복한 결말은 없었습니다. 그는 타즈알라오르의 트롤들에게 붙잡혔습니다. 얼마 지나지 않아 대장군 부네에게 고문을 받던 중 발타라크의 암살자들이 들이닥쳐 결국 그를 죽였습니다.</P><BR/><P align="left">모르 그레이후프의 영혼의 메아리를 불러내려면 대장군 부네의 방이 바로 유령이 출몰하는 장소입니다.</P><BR/></BODY></HTML>'),
(2865, '<HTML><BODY><H1 align="center">자리엔과 소도스</H1><BR/><P align="center">남매이자 붉은십자군의 예비 단원</P><BR/><P align="left">자리엔과 소도스는 내가 아는 사람 가운데 손꼽히게 편협한 두 사람이었습니다. 하지만 전투 실력은 뛰어났고 집안도 부유했습니다. 아마 장막의 칼날단을 이끌던 안시온이 그들을 계속 데리고 있었던 것도 그 때문이었겠지요.</P><BR/><P align="left">두 남매는 결국 붉은십자군의 가르침과 사상에 매료되었습니다. 여행 중 마주치는 스컬지를 처치할 때면 늘 유별난 열정을 보였고, 그 집안이 붉은십자군과 연관되어 있다는 소문도 있었습니다.</P><BR/></BODY></HTML>'),
(2866, '<HTML><BODY><H1 align="center">자리엔과 소도스, 계속...</H1><BR/><P align="left">그렇게 두 사람은 붉은십자군에 들어가려는 자들이 치러야 하는 시험에 도전하게 되었습니다. 특히 기사단의 자리에 관심이 많았는데, 그 자리를 얻으려면 더 어려운 시험을 통과해야 했던 모양입니다. 나중에 밝혀진 바로는 소도스가 최종 시험에서 탈락했습니다. 하지만 자리엔은 이를 받아들이지 않았고, 소도스도 자신과 함께 기사가 되어야 한다며 공개적으로 반발했습니다. 우리가 알아낸 바로는 대십자군 사령관 다스로한이 자기 방 한가운데서 두 사람을 그 자리에서 죽였다고 합니다.</P><BR/><P align="left">따라서 또 하나의 유령 출몰지는 스트라솔름 붉은십자군 성채 안의 붉은 왕좌입니다.</P><BR/></BODY></HTML>'),
(2867, '<HTML><BODY><H1 align="center">코르모크</H1><BR/><P align="center">두 머리 오우거 강령술사</P><BR/><P align="left">코르모크를 어떻게 설명해야 할까요? 두 머리를 가진 주문술사 오우거였는데, 원래부터 그렇게 나쁜 녀석은 아니었습니다. 처음 그를 데려왔을 때는 불타는 평원에서 맡은 일 때문에 붙잡은 포로였습니다. 그런데 그곳에서 우리가 궁지에 몰렸을 때 빠져나오는 데 결정적인 도움을 주었고, 그 뒤로 일행의 손꼽히는 마법사가 되었습니다.</P><BR/><P align="left">이상한 점은 두 머리의 성격이 완전히 달랐다는 것입니다. 한쪽은 늘 명랑하고 조금 어리숙했지만, 다른 한쪽은 교활하고 계산적이었으며 눈빛은 거의 죽은 사람처럼 보였습니다. 솔직히 꽤 섬뜩했지요.</P><BR/></BODY></HTML>'),
(2868, '<HTML><BODY><H1 align="center">코르모크, 계속...</H1><BR/><P align="left">여행을 계속하면서 코르모크는 강령술 계통의 마법을 접하게 되었습니다. 불행히도 그 소름 끼치는 쪽 머리는 죽은 영혼을 되살리는 데 남다른 재능을 보였고, 그 일 자체를 비뚤어진 즐거움으로 여겼습니다. 특히 정화의 섬에 추방된 영혼들을 불러내 자기 명령에 따르게 하는 것을 좋아했습니다.</P><BR/><P align="left">일행이 해산된 뒤 코르모크는 \'교육\'을 더 받겠다며 스칼로맨스에 들어갔습니다. 유령 암살자들은 학교 안으로 너무도 쉽게 숨어들었고, 새 스승 라스 프로스트위스퍼가 보는 앞에서 코르모크를 죽였습니다.</P><BR/><P align="left">따라서 라스 프로스트위스퍼의 방 역시 화로를 제대로 사용할 수 있는 유령 출몰지 가운데 하나입니다.</P><BR/></BODY></HTML>'),
(2869, '<HTML><BODY><H1 align="center">군주 발타라크</H1><BR/><P align="center">용혈족 귀족이자 검은바위 첨탑의 전 장군</P><BR/><P align="left">드라키사스 장군 이전에는 막대한 힘을 지닌 용혈족 흑마법사 군주 발타라크가 있었다. 첨탑의 지배자가 바뀌는 일은 드물지 않았지만, 불행히도 우리는 이번 권력 교체에 한몫하게 되었다.</P><BR/><P align="left">무법항의 고블린 밀수업자 겸 마법사 그렘니크 리즐스프랭은 우리에게 발타라크의 마법서를 훔쳐 달라고 의뢰했다. 그가 연구하려 했는지 팔아넘기려 했는지, 아니면 둘 다였는지는 모른다. 이제는 중요하지도 않다. 중요한 건 우리가 검은바위 첨탑 상층부에 잠입해 발타라크 군주를 그의 소굴에서 처치했다는 사실이다. 진짜 난리는 그때부터 시작됐다.</P><BR/></BODY></HTML>'),
(2870, '<HTML><BODY><H1 align="center">군주 발타라크, 계속...</H1><BR/><P align="left">우리는 발타라크가 영혼을 다루는 마법에 얼마나 깊은 지식을 지녔는지 전혀 몰랐습니다. 알았다면 애초에 그 일을 맡지도 않았겠지요. 하지만 우리는 일을 맡았고, 결국 그것이 우리가 맡은 마지막 일이 되고 말았습니다.</P><BR/><P align="left">군주 발타라크를 쓰러뜨리고 그의 마법서를 빼앗은 뒤, 코르모크는 발타라크의 아뮬렛에서 뭔가를 느꼈던 모양입니다. 그는 자기 몫의 전리품으로 그것을 가져가겠다고 고집했고, 곧 격렬한 말다툼이 벌어져 거의 싸움으로 번졌습니다. 그때는 그 아뮬렛 안에 발타라크의 영혼 상당 부분이 깃들어 있다는 사실을 몰랐습니다. 나중에야 알게 되었고, 결코 반가운 발견은 아니었습니다.</P><BR/></BODY></HTML>'),
(2871, '<HTML><BODY><H1 align="center">군주 발타라크, 계속...</H1><BR/><P align="left">우리는 아뮬렛을 여러 조각으로 나누고 새로 일어난 발타라크의 유령과 그의 유령 암살자 군대에게서 달아났습니다. 그런데 아뮬렛을 두고 다투며 낸 소음 때문에 첨탑에 남아 있던 수비병들까지 깨어나고 말았습니다!</P><BR/><P align="left">거의 모두가 검은바위에서 빠져나와 이제 안전하다고 생각했습니다. 하지만 죽어서도 발타라크는 우리가 어디에 숨든 하수인들을 보내왔습니다. 그 임무가 끝난 뒤 장막의 칼날단은 곧 흩어졌고, 그러자 우리는 정말 손쉬운 먹잇감이 되고 말았습니다.</P><BR/><P align="left">짐작하셨겠지만, 군주 발타라크의 거처였으며 지금은 검은바위 첨탑의 괴수가 머무는 방이 마지막 유령 출몰지입니다.</P><BR/></BODY></HTML>'),
(2872, '모든 건장한 남녀 여러분께:\n\n스컬지가 돌아왔습니다. 우리는 사소한 다툼을 접고 이 위협에 맞서 싸워야 합니다. 은빛 새벽은 스컬지의 위협에 맞서 싸우고자 하는 자는 누구든 외면하지 않을 것입니다.\n\n우리 땅을 지키고자 하는 이들은 동부 역병지대의 빛의 희망 예배당에 집결하고 있습니다. 우리는 함께 승리할 것입니다.\n\n기록 보관자\n은빛 새벽'),
(2873, '누락된 텍스트'),
(2878, '사랑하는$B$B에밀리, 며칠 전, 우리는 왕의 명령에 따라 고향으로 돌아가기 위해 이 황량한 곳에서 야영지를 철수했습니다. 주변 환경은 삭막했지만, 저는 마음이 가벼웠습니다. 해안까지 이어지는 혹독한 여정과 길고 고된 항해 끝에 당신의 품에서 위안을 찾을 수 있을 거라고 믿었기 때문입니다.$B$B오늘 해안에 도착해 보니 우리의 배, 돌아갈 수단은 새까맣게 탄 잔해뿐이었습니다. 우리는 이곳을 떠날 수 없고, 이 심연의 황무지 한가운데로 계속 나아갈 수밖에 없습니다. 에밀리, 당신을 지키기 위해$B$B세상 끝까지 왔는데… 이제 와서… 온 마음을 다해 로데론에 당신과 함께 남았더라면 좋았을 텐데 하는 생각이 듭니다. 깨어 있는 모든 순간이 당신$B$B생각으로 가득합니다. 사랑하는 당신은 이 얼어붙은 땅에서 제게 따뜻함을 주는 존재이며, 누구도 그것을 빼앗아 갈 수 없습니다.$B$B맥스웰'),
(2880, '루벤,$B$B이 편지를 당신이 영영 보지 못할지도 모른다는 것을 알지만, 저는 하스글렌 성벽을 끊임없이 두드리는 소리를 들으며 가만히 있을 수가 없습니다. 언데드들이 마을 밖에서 쉴 새 없이 공격해 오고 있고, 우리는 증원군이 도착할 때까지 마을 사람들을 지켜야 하는 임무를 맡았습니다. 지난번 공격에서 다리가 부러져서,$B$B저는 그저 검을 옆구리에 꽂고 무력하게 앉아 있습니다. 방어선이 뚫릴 때를 대비해서 말이죠. 쓸데없는 잡담은 없습니다... 오직 전투와 죽음의 소리만 들릴 뿐입니다. 공기는 공포로 가득 차 있습니다. 아서스 왕자님께서 여기 계십니다.$B$B병사들과 함께 최전선에서 싸우고 계십니다. 그분이 안 계셨다면 우리는 오래전에 함락되었을 겁니다. 이 땅과 백성에 대한 그분의 사랑은 전염성이 강합니다. 저는 기꺼이 그분을 섬기며, 제 생을 다할 때까지 그럴 것입니다. 전투는 점점 더 격렬해집니다.$B$B다리가 부러졌든 아니든, 저는 여기 앉아 있을 수 없습니다. 모든 검이 필요합니다. 이 글이 당신이 더 행복한 시기에 당신에게 닿기를 바랍니다.$B$B당신의 친구,$B리그렘'),
(2881, '$b$b"헬리아나,$b$b" "당신의 바람과는 달리, 나 바르구스는 아직 살아 있습니다. 이 우스꽝스러운 갑옷을 입고 시골을 돌아다니는 건 정말$b$b싫습니다. 최근 명령에 따르면 곡식인가 뭐 그런 핑계를 대며 안도르할로 가야 한다는데, 내가 왜 하필 안도르할의 식량 창고에 신경을 써야 합니까? 군대에 있다는 것 자체가 어처구니없습니다. 헬리아나 이모,$b$b안심하십시오. 당신의 유산을 되찾으러 반드시 돌아오겠습니다. 설령 심하게 다치고 식량도 없이 남겨진다 해도, 복수심이 나를 앞으로 나아가게 할 겁니다."$b$b"바르구스"$b$b'),
(2882, '사랑하는 아멜리아,$B$B오늘 밤 나는 영원히 잊히지 않을 끔찍한 광경을 목격했다.$B$B스트래솔름은 불타고 있다… 그리고 그 책임은 우리에게$B$B있다. 오늘 밤, 우리 군주께서는 우리를 도시 거리로 이끌었다. 그는 마을 사람들의 집에 쳐들어가… 잠자는 그들을 죽이라고 명령했다. 아서스 경께서는 그들이 역병에 걸렸으니 우리를 죽이기 전에 먼저 죽여야 한다고 말씀하셨다. 그것은 학살이었다.$B$B수백 명이 자신들을 지키겠다고 맹세한 자들의 칼에 소리 없이 죽어갔다. 나는 더 이상 견딜 수 없었다. 도망쳤다. 비록 내가$B$B탈영병일지라도, 나는 그런 만행을 저지를 수 없었다. 모든 집에서 나는 죽어가는 희생자들의 얼굴 위에 당신의 얼굴, 우리 아이들의 얼굴을 떠올리지 않을 수 없었다. 만약 그것에 맞서는 것이 반역이라면, 그렇게 되더라도 감수하겠다. 나는$B$B제때 당신에게 돌아갈 길을 찾기를 바라지만, 길이 위험하다. 내가 없는 동안 우리 아이들에게 내 사랑을 전해 주세요.$B$B제임스'),
(2883, '삼라,$B$B우리 주군 아서스를 따라 북쪽으로, 끝없이 북쪽으로 향하는 동안 내 마음은 무거워진다. 한때 빛으로 빛나던 그 젊은 성기사의 영혼이 어두워지는 것을 느낀다. 그의 열정은 내가 짐작할 수 없는 어떤 악몽에 가려져 있다… 곧 얼어붙은 황무지에$B$B상륙할 것이다. 그의 부하들 중 많은 이들이 추위와 썩어가는 짐승들과의 전투로 병들어 가지만, 아서스는 얼음 속에서 찾는 것이 전세를 바꿀 것이라고 말한다. 하지만 나는 그의 말에서 아무런 위안도 얻지 못했다. 그 말을 한 후… 그의 비뚤어진 입술에 걸린 섬뜩한 미소는 어떤 눈보라보다도 더 깊은 오싹함을 안겨주었기 때문이다. 삼라, 우리를 위해,$B$B그리고 우리 세상을 위해 기도해 주오.$B$B토르갈'),
(2884, '사랑하는$B$B파멜라에게, 내일 우리는 안도르할에서 최후의 결전을 벌일 거야. 사랑하는 너에게 보내는 이 편지가 마지막 편지가 될까 봐 두려워. 언데드들은 지치지 않고, 우리는 그저 인간일 뿐이니, 그들을 막아낼 수 없을 것 같아. 하지만 걱정하지 마. 우리가 죽음을 맞이할지라도, 우리의 희망은 여전히 ​​강해. 빛은 반드시$B$B승리할 거야! 그리고 사랑하는 파멜라, 그 어둠의 공포가 우리 성벽을 무너뜨리고 우리를 덮칠 때, 내 마지막 생각은 죽음이 아닐 거라는 사실에 위안을 얻어. 네가 내 품에 안겨 있는 모습을 떠올리며, 마침내 평화를 찾을 거야.$B$B크리스토프'),
(2885, '안녕하세요, $N. 그 쪽지에서 몇 가지 정보를 찾아냈습니다.$B$B제임스에 대해서는 아쉽게도 알아낸 것이 거의 없습니다. 하지만 아멜리아의 가족에 대해서는 조금 찾았습니다.$B$B아멜리아와 아이들은 전쟁에서 살아남지 못했지만, 오빠 알렉산더 칼더는 살아 있습니다. 아이언포지의 쓸쓸한 뒷골목에서 불타는 군단의 위험한 마법을 연구하고 있으니 그곳에서 찾을 수 있을 겁니다.$B$B아멜리아에게는 가까이 지내던 사촌도 있었습니다. 지금은 데즈 스노우베인이라 불리는 여인으로, 오그리마에서 아라시 분지 전투 참여를 독려하고 있습니다.$B$B다음에 그 근처에 가면 둘 중 한 명을 찾아가 보세요. 적어도 잃어버린 아멜리아의 소식에는 분명 관심을 보일 겁니다.'),
(2886, '안녕하세요, $N. 제 조사 결과가 궁금하실 것 같아 알려드립니다.$B$B알고 보니 루벤과 리그렘 모두, 말하자면, 남은 가족이 있습니다. 그들이 이미 잃어버린 병사의 운명을 알고 있더라도 한 번 찾아가 보는 것은 의미가 있을 겁니다.$B$B루벤의 전처 조안나 화이트홀은 언더시티 전쟁 지구에서 대부분의 시간을 보냅니다. 이 소식을 얼마나 반길지는 모르겠군요.$B$B리그렘의 고모는 스톰윈드의 고아원 원장이 되었습니다. 꽤 훌륭한 자리이지요.$B$B앞으로 어떤 길을 걷든 당신의 앞날에 행운이 함께하기를 바랍니다.'),
(2887, '$N, 이 편지가 무사히 닿기를 바랍니다. 좀 조사해 본 끝에 당신이 찾아낸 쪽지를 쓴 이들에 관한 정보를 알아냈습니다.$B$B삼라의 아버지는 자신의 신앙을 따라 썬더 블러프로 순례하는 포세이큰과 트롤들을 이끌고 있습니다. 이름은 마일스 웰시이며, 환영의 웅덩이에서 다른 언데드들과 함께 있을 겁니다.$B$B토르갈에게는 사촌 엘리사 듀마스가 남아 있습니다. 듣기로는 사람을 잘 만나지 않는 성격이며, 다르나서스의 달의 신전에서 나날을 보낸다고 합니다.$B$B가능하다면 그들을 찾아가 보세요, $N. 토르갈이나 삼라에게 무슨 일이 있었는지 아직 듣지 못했을지도 모릅니다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(2888, '수호자가 당신이 발견한 편지를 전해 주었습니다, $N. 그 뒤에 알아낸 소식도 궁금하실 것 같군요.$B$B편지에 언급된 \'바르구스\'의 마지막 생존 가족을 추적한 결과, 실리더스 사막의 세나리온 요새에 살고 있다는 사실을 알아냈습니다. 이름은 가론 허친스입니다.$B$B다음에 황무지로 갈 일이 있으면 그와 이야기해 보세요. 우리가 알아낸 이야기를 듣고 싶어 할지도 모릅니다.'),
(2889, '안녕하십니까. 스컬지에서 발견하신 그 편지를 드디어 살펴볼 시간이 생겼습니다. 꽤 오랜 시간이 걸렸지만, 고인의 살아있는 친척을 찾은 것 같습니다. 맥스웰의 여동생인$B$B자레나 크롬윈드라는 분이 무법항에서 작은 무기 제작소를 운영하고 있습니다. 두 분이 얼마나 가까웠는지는 잘 모르겠지만, 혹시 그곳을 지나가시게 되면 만나 뵙도록 하겠습니다. 요즘 세상에 이런 미스터리를 해결하는 건 정말 귀중하고 드문 일입니다.'),
(2890, '드디어 당신이 싸웠던 옛 병사에 대한 정보를 좀 찾아냈습니다. 이 가문의 가계도가 제대로 기록되어 있지 않아 추적하기가 어려웠지만, 마침내 혈연관계가 있는 사람을 찾았습니다. 빛의 희망$B$B예배당 관리인 알렌이 사실 크리스토프의 아들이라는 사실을 믿으시겠습니까? 아버지 소식을 들으면 마음이 좀 편해질지도 모르겠습니다. 혹시라도 역병지대에서 다시 은빛 새벽단에 합류하게 된다면, 부디 그와 이야기를 나눠주세요. 큰 도움이 될 겁니다.'),
(2945, '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align="center">\n가시덤불 골짜기의 푸른 언덕\n</H1>\n<BR/>\n<H3 align="center">\n헤멧 네싱와리 지음\n</H3>\n</BODY>\n</HTML>'),
(2946, '첫째 날은 보통 그렇듯이 순조롭게 지나갔다. 우리는 기지 구축을 위해 필요한 준비를 하는 데 대부분의 시간을 보냈다. 나는 담수가 흘러드는 강어귀 가에서 이상적인 장소를 찾아 냈다. 근처에 낡고 버려진 부두가 있는걸로 보아 이곳은 예전에 어떤 종족이 거주하던 곳인 것 같다. 그러나 원래 누가 살던 땅이었는지는 시간이 흘러야만 알 수 있을 것이다.'),
(2947, '이번 사냥 여행을 위해 나는 아제크루아크 양과 얼가딘 경, 그리고 나의 믿음직한 하인 바닐 스톤팟과 함께 이곳에 왔다. 난 아제크의 아버지와 함께 얼라이언스를 수호하기 위해 많은 전투를 치렀다.  그녀가 성장한 모습을 보니 감개가 무량하다. 그녀의 아버지는 그녀에게 무기 사용법을 제대로 가르쳤다. 활 다루는 솜씨를 보면 그녀의 몸에 엘프의 피가 흐르고 있는게 아닐까 하는 생각이 들 정도다.'),
(2948, '얼가딘 경은 인간 귀족 출신이다. 그의 부친 얼가딘 백작은 후덕한 심성으로 잘 알려져 있다. 2차 대전쟁 이후 스톰윈드 재건이 진행되는 동안 석공 길드의 작업 환경 개선을 위해 로비를 펼치며 노력한 것도 얼가딘 백작이었다.'),
(2949, '스톰윈드가 석공 길드를 배반한 이후 여러 해 동안 얼가딘 경은 왕국 내에서 귀족의 역할에 대해 비판을 가해왔다. 그는 더 이상 아버지의 혈통으로 이어받은 귀족 평의회의 지위를 지킬 마음이 없었다.'),
(2950, '여기서 다른 화제로 넘어가도록 하겠다. 이런 이야기를 하는 것은 정치 논문이나 전기 같은 것을 쓰기 위해서가 아니다. 이 책은 가시덤불 골짜기의 푸른 언덕에서 대단한 사냥을 하던 시절의 내 경험을 이야기하기 위한 것이다.'),
(2951, '우리는 아침 일찍 일어났고 바닐은 아침 식사를 준비하기 시작했다. 아제크는 주의가 좀 흐트러진 것 같았다. 오늘은 긴 여행을 해야 하고 사냥 또한 위험할 것이었다. 집중하지 않으면 쉽게 불행한 결과를 가져올 수 있는 것이다. 하지만 아제크는 휴대용 식기를 헹구기 위해 강가에 서 있는 바닐에게 눈을 뗄 수 없는 모양이었다. 내가 아제크에게 오늘 있을 사냥에 집중하지 않는 것에 대한 우려를 표하려는 순간, 그녀가 화살통에서 화살 하나 꺼내더니 불쌍한 바닐을 향해 쏘는 것이었다.'),
(2952, '바닐이 놀라 입을 벌린 채로 옆으로 비켜서자 아제크의 화살이 정확하게 미간 한가운데 박힌 거대한 민물악어가 수면으로 떠올랐다. 우리는 무성하게 우거진 정글을 해치고 서쪽을 향해 출발했다. 한 발짝씩 신중히 내딛으며 사냥감을 찾아 무성한 수풀 사이로 천천히 이동했다. 실망스럽게도 오전은 그렇게 조용히 지나갔다.'),
(2953, '골짜기에는 바람 한 점 불지 않았고 별다른 움직임이 없었다. 오후에는 사냥 여행의 긴장이 풀어져 바닐은 더 이상 야수가 사냥감을 뒤쫓듯 조심스럽게 발걸음을 내딛지 않고 있었다. 그는 자주 마른 잎이나 떨어진 나무가지를 밟아 큰 소리를 내며 길을 따라 되는대로 성큼성큼 걸어갔다. 바닐이 한 발짝 발을 헛디디자 얼가딘 경은 그 큰 손으로 바닐의 어깨를 잡았다. 아제크와 나는 그가 다만 부주의한 바닐에게 꼭 필요한 따끔한 질책을 하는 거라고 생각하며 별생각 없이 쳐다보았다. 하지만 얼가딘 경은 머리로 천천히 근처에 쓰러져 있는 나무를 가리켰다. 거기엔 면도날 같이 날카로운 송곳니 바로 위로 두 개의 검은 눈이 뚫어질 듯 무섭게 우릴 쏘아보고 있었다.'),
(2954, '그 짐승은 가시덤불호랑이 수컷이었다. 내가 총을 겨누기도 전에 얼가딘 경은 석궁을 들어 그 짐승을 쏘았다. 화살은 빗나갔지만 놈의 왼쪽 옆구리에 큰 상처를 냈다. 호랑이는 도망치려고 헛된 시도를 해보았지만 부상이 너무 치명적인 것이었다. 놈이 잠시 비틀거린 후 바닐이 도끼를 던져 놈을 완전히 처치해 버렸다.'),
(2955, '놈의 죽음으로 원정대는 축제 분위기에 휩싸였다. 바닐은 모두가 즐길 수 있도록 벌꿀술을 따라 주었으나 축제는 오래가지 못했다. 시체를 다시 기지로 보내기 위해 준비하느라 모두 방심하고 있던 중에 끔찍한 으르렁거리는 소리가 들려 온 것이었다.  내 생애에서 피가 얼어 붙는 것처럼 그렇게 섬뜩한 소리는 다시 들어 보지 못했다.'),
(2956, '석양빛에 윤곽이 빛나는 바위 절벽 위에서 지금까지 본 것 중 가장 큰 고양잇과 사냥감을 발견했다. 나는 내 라이플 총으로 서투르게 한 발 쐈지만 놈은 꿈쩍도 하지 않았다. 놈은 처음 보다 더 큰 소리로 한번 더 으르렁거리고는 사라져 버렸다.$B$B우리는 소지품을 챙겨 무거운 마음으로 야영지로 돌아왔다.'),
(2957, '나는 대원들에게 다음 날은 아제로스 전역에서 모피 수요가 대단히 높은 표범을 사냥할 것이라 약속했다. 얼라이언스를 위해 용감하게 자신의 삶을 희생하고 있는 모든 전문 사냥꾼, 덫사냥꾼, 가죽 상인들을 생각한다면 이런 수요는 당연한 보상이라 할 수 있다.'),
(2958, '아제크와 얼가딘 경은 드워프 라이플을 사용하여 효과적으로 사냥하는 방법을 꼭 배우고 싶어하고 있다. 나는 그 두 인간 친구들에게 그들이 가진 사정 거리가 짧은 무기들을 야영지에 두고 오도록 했다. 바닐과 나는 그들에게 아이언포지의 최상급 소총을 지급했다.'),
(2959, '오늘은 새로운 퓨마 흔적을 쫓아 남쪽으로 사냥을 나갔다. 출발한 지 얼마 되지 않아 우리는 밧줄로 만들어진 멋진 다리가 놓인 계곡에 이르렀다. 기술이 낳은 이 경이로운 다리를 보는 순간 나는 이 지역을 묘사한 바닐의 글을 떠올리지 않을 수 없었다. 종종 트롤 원주민들은 원시적이고 교육 받지 못한 종족이라 생각했지만, 뛰어난 기술로 만들어진 다리를 올려다 보면서 나는 이 불가능해 보이는 일을 이뤄낸 트롤 건축가들의 솜씨를 인정하게 되었다.'),
(2960, '그 후 얼마 지나지 않아 아제크는 남서쪽으로 표범을 뒤쫓았다. 우리는 언제라도 사냥감을 공격할 수 있도록 사격 태세를 갖추고 조용히 걸어갔다. 근처 숲에서 들린 나뭇가지가 부러지는 소리에 우리는 바로 신경을 곤두세웠다. 거기에 무언가가 있었다. 단호한 눈짓 한 번으로 바닐에게 내 뜻을 충분히 전할 수 있었다. 바닐은 천천히 총을 내렸다. 이번 사냥은 우리를 위한 것이 아니라, 우리의 인간 동료들을 위한 것이었다.'),
(2961, '셀 수 없이 많은 표범들이 이미 우리에게 희생당했다. 이번 사냥은 그들을 위한 것이었다. 아제크와 얼가딘 경은 균형을 잡고 서서 흔들리는 나무 밑에서 털을 곤두세우고 있는 거대한 놈에게 총을 겨누었다. 한낮의 태양은 따갑게 내리쬐고 있었다. 핀을 뒤로 당기는 얼가딘 경의 관자놀이에서 땀 한 방울이 천천히 흘러내렸다. 방아쇠를 당기는 소리와 함께 두꺼운 식물이 갈라지고 이 거대하고 아름다운 검은 표범이 곧 평원 위에 쓰러졌다.\r\n'),
(2962, '우리의 인간 친구들은 나무들 사이로 숨어 달리는 표범을 쫓으며 눈을 훈련시켰다. 총이 든 통은 서로 잘 묶여 있었다. 바닐은 간절한 눈빛으로 날 쳐다봤지만 나는 고개를 저었다. 이번 사냥감은 인간 친구들을 위한 것이지 바닐이나 내가 낄 자리가 아닌 것이다. 얼가딘은 요란하게 총을 쐇지만 모두 빗나갔다. 그리고 그는 총격의 심한 반동에 미처 대비하지 못했던 것 같다'),
(2963, '그의 총이 반동으로 그의 팔 안에서 심하게 흔들렸다. 그리고 통이 옆으로 떨어져 아제크는 총 아래로 굴러갔다. 아제크는 바로 그 순간 방아쇠를 당겼다. 갑자기 굴러온 통으로 조준이 흐트러져 총알은 뚜렷한 소리를 내며 나무 있는 곳을 향해 발사되고 말았다. 새 떼가 울부짓으며 하늘로 날아올라 사방으로 흩어졌다. 나무에서 연기가 나고 있었다 우리는 거대한 나뭇가지가 똑바로 떨어져 달아나는 표범의 등을 부러뜨리는 광경을 두려워하며 지켜보았다.\r\n'),
(2964, '몇주가 지나면서 표범과 호랑이 가죽이 상당히 많이 모였다. 이제 사냥감의 수준을 좀 더 높여 랩터를 사냥할때가 왔다고 판단했다. 인간 친구들은 바닐과 내가 제공한 훈련에 대해 고마워하긴 했지만 소총을 사용한 사냥은 그만 하기로 결정했다. 아제크는 시위가 팽팽하게 잘 조절된 활을 사용하는 데 훨씬 더 익숙했고, 얼가딘 경은 항상 그의 견고한 석궁을 들고 사냥에 나섰다.'),
(2965, '우리는 해가 뜨자마자 트카시 폐허를 지나 남쪽을 향해 출발했다. 바닐은 붉은머리부족과 마주치게 되지 않을까 걱정했다. 나는 바닐에게 붉은머리부족은 그들 일쪽의 숙적인 백골가루부족을 처치하는 데 여념이 없을 거라고 상기시켜 주었다. 물론 바닐은 전혀 안심하지 않았지만, 나는 장전된 총, 화약을 가득 담은 가방, 그리고 세명의 뛰어난 사냥꾼이 있어 어떤 적이 습격해 온다 해도 걱정이 없었다.'),
(2966, '나는 전장에서 수없이 지옥을 드나들었다. 바로 사방에서 공격해 오는 불타는 군단이란느 지옥의 군대를... 그들에 비하면 난폭한 트롤 무리는 던모로의 언덕을 뛰어다니는 토끼만큼 이나 안전하다고 할 수 있다.$B$B우리는 아무 문제 없이 트카시 폐허를 지나왔고 이로써 바닐도 많이 안심하게 되었다. 대해를 향해 서쪽으로 계속 가면서 바로 남쪽에 보이는 줄쿤다의 폐허의 가장자리를 지나쳤다. 높은 해안 절벽을 올라가던 도중에 첫 랩터 사냥감을 발견했다.'),
(2967, '아제크가 성공을 인정하듯 내게 고개를 끄덕이자 얼가딘 경은 열렬히 "만세"를 외쳤다. 나는 축하의 담배를 한 대 피울 생각으로 파이프를 찾기 위해 짐을 뒤졌다. 바닐은 랩터의 시체를 가져오기 위해 서둘러 언덕을 올라가기 시작했다. 나는 어려운 사냥에 성공할 때면 어김없이 찾아오는 뿌듯한 만족감을 느끼며 쓰러진 짐승을 바라보았다. 하지만 영광의 순간은 그리 오래가지 않았다. 지평선으로 시선을 돌렸을때, 불쌍한 바닐 바로 위 언덕에 몇개의 그림자가 나타났기 때문이다.'),
(2968, '"도망쳐, 바닐!" 나는 소리쳤다. 아제크, 얼가딘 경, 그리고 나는 바닐의 뒤를 쫓아오는 랩터들을 향해 일제히 총탄과 화살, 그리고 석궁용 짧은 화살을 계속 쏘아 댔다. 그 혼란스러운 사오항에서 우리 중 누군가가 한 놈을 처치했다. 우리의 재빠른 조준 사격으로 바닐은 도망칠 수 있었다.$B$B그는 언덕 아래로 도망쳐 와서 우리와 다시 합류했다.\r\n'),
(2969, '우리는 정글 속으로 도망쳤다. 그러나 포악한 채찍꼬리랩터 무리가 계속 우리를 쫓아왔다. $B$B사냥꾼들이 오히려 사냥감이 되어 버린 것이었다.\r\n'),
(2970, '나는 해안가에 랩터로부터 숨을 곳이 있기를 바라면서 동료들을 바다쪽으로 안내했다. 그런데 서둘러 도망쳐 오는 바람에 북쪽으로 너무 멀리 도망쳐 와 위태로운 고지까지 오고 말았다. 이미 실수는 저질러졌고 그건 모두 내 잘못이었다. 우리는 깎아지는 절벽 끝에 멈춰 섰고, 랩터들은 겨우 몇 발자국 뒤에 있었다.'),
(2971, '난 천천히 총을 들고 앞으로 나아갔다. 난 이 용감한 사냥꾼들을 죽음의 위기에 몰아넣고 말았다. 따라서 그들을 보호하기 위해서라면 목숨이라도 내놓고 싶은 심정이었다. 채찍꼬리랩터들은 특히 사나울 뿐 아니라 피에 대한 그칠 줄 모르는 굶주림으로 알려져 있다.놈들은 수적으로도 우리보다 훨씬 우위였다. 나와 내 동료들이 희생되기 전에 놈들을 처치하지 못하면 나는 저주를 받아 마땅했다.'),
(2972, '아제크와 얼가딘 경은 무기를 든 채 내 양 옆에 서 있었고 우리의 등 뒤는 바다였다. 바닐은 한숨을 내쉬며 도끼를 꺼내 들었다. 채찍꼬리랩터들은 우리 바로 앞에 까지 와 있었다. 그리고는 속도를 줄여 천천히 움직이기 시작했다. 놈들은 우리가 꼼짝없이 갇혀 버렸다는 사실을 알고 있었기 때문에 서두르지 않고 먹잇감에게 다가오고 있던 것이다.'),
(2973, '그런데 그때 깆거 같은 일이 일어났다. 저쪽에서 우리 쪽으로 커다란 백호의 사나운 표호가 분명하가 들려 왔던 것이다. 많은 숫자에도 랩터들은 몸을 돌려 사방으로 흩어지기 시작했다 호랑이는 날쌔게 우리를 지나쳐 랩터 한 마리를 덮쳤는데, 이 모습이 우리에겐 아주 잠깐 뭔가 하얀 것이 섬광 처럼 빠르게 지나가는 걸로만 보였을 뿐이었다. 어떤 명령도 필요 없었다.'),
(2974, '우리는 속도를 늦추지 않고 전력을 다해 달려 야영지로 돌아왔다. 그날 밤 우리는 이상한 운명의 장난 덕에 겨우 목숨을 건졌다는 생각으로 모닥불 주위에 조용히 둘러앉아 있었다. 이런것이 바로 위대한 사냥꾼이 겪에 되는 위험이다. 우리는 그러한 위험으로부터 빠져 나옴으로써 운명의 장난을 즐기는 것이다. 하지만 우리 각자는 언젠가 운명의 날카로운 이빨을 직면하게 될 것이다. 나는 드워프로서 가시덤불골짜기의 푸른 언덕에서 그러한 운명의 순간을 맞이하지 않았다는 사실에 감사할 따름이다.$B$B-끝-'),
(3456, '4월 9일 05:31~10:50, 아이스포인트 록으로 보급품 수송\r\n\r\n4월 13일 05:12~09:20, 윈터스프링 북쪽 아이스포인트 록에 기지 구축\r\n\r\n4월 18일 20:03~22:14, 윈터스프링 정찰\r\n\r\n5월 3일 06:04~ 아이스포인트 록으로 비행'),
(10000, '고블린들은 본래 탐욕스러운 본성대로, 언제나 이득이 될 만한 유물과 유적을 찾아 헤매왔습니다. 벤처 무역 회사의 무역왕이 탐욕에 눈이 멀어 고블린 무리를 돌발톱 산맥 깊숙한 곳으로 보낸 것도 바로 그 때문이었습니다. 전해지는 이야기에 따르면, 어떤 정체불명의 인물이 고블린들에게 절대 열어서는 안 되는 무덤이 있는데, 그 무덤 안에는 엄청난 금을 순식간에 모을 수 있는 방법이 숨겨져 있다고 알려주었다고 합니다.\r\n\r\n고블린이 아니었다면 틀림없이 도망치고 입 밖에 내지 않았겠지만, 금이라면 고블린도 쉽게 설득당하는 법입니다.'),
(10001, '그들의 임무는 혹독한 것으로 드러났고, 많은 이들이 그 산맥에서 죽음을 맞이했다. 사나운 야생 동물에게 잡아먹히거나, 무덤을 지키는 나이트 엘프의 손에 죽거나, 혹은 스스로 만들어낸 함정에 빠지기도 했다.\r\n\r\n무덤으로 천천히 나아가는 동안, 일부는 공포에 굴복했다. 그곳에는 어둠의 무언가가 도사리고 있었다. 몇몇은 남의 금화를 위해 목숨을 바칠 가치가 없다고 생각하여, 얼마 남지 않은 수단을 가지고 무리를 지어 듀로서로 향했다.'),
(10002, '<Your new friend looks a little dehydrated.>새 친구가 약간 탈수 증세를 보이는 것 같네요.'),
(10010, '전직 반장 네르트 블래스텐톰이 이끄는 반란 고블린들은 레이저 힐 마을 근처에 비행기를 추락시켰습니다. 그곳에서 네르트는 호드의 깃발 아래 숨으려는 계획에 도움이 될 만한 지인을 만났습니다.\r\n\r\n그 마을의 요리사는 네르트가 과거 라쳇에서 오크들에게 모조품을 팔려던 보잘것없는 상인 시절에 만났던 사람이었습니다.'),
(10011, '그를 따르는 몇몇 고블린들의 도움으로 네르트는 경비병들에게 뇌물로 줄 멧돼지를 사냥하여 그들의 땅을 통과할 수 있도록 했습니다.\r\n\r\n그의 부하인 아그네스가 특별한 향신료 주머니를 가지고 있었던 덕분에 오크 요리사 네르트는 평범한 식사를 풍성한 잔치로 탈바꿈시켰습니다.\r\n\r\n지역 경비병들에게 뇌물을 주려는 계획에 성공한 고블린들은 호드의 땅을 안전하게 통과할 수 있었고, 앞으로 누릴 수 있는 보호를 받게 되었습니다.'),
(10020, '호드에게 자신과 전 직원들이 그들을 도울 능력이 있음을 증명해야 한다는 것을 알고 있던 네르트는 가즈로우를 만나기 위해 라쳇으로 향했습니다. 가즈로우는 호드 내부에 인맥이 있었고, 벤처 무역 회사의 악명 때문에 그들을 추방하거나 최악의 경우 죽이려 드는 자들에게 맞서기 위한 좋은 수단이 될 수 있었습니다.\r\n\r\n가즈로우는 처음에는 동의하지 않았습니다. 그는 이 난민들을 도울지 말지 며칠 동안 고민했습니다. 결국 그는 호드에 고블린의 손길이 부족하다고 결론짓고 네르트를 불러들여 호드에 합류하기로 결정한 고블린이라면 누구든 가입할 수 있는 노조를 결성하자고 제안했습니다.'),
(10021, '네르트는 이 상황에 당황했지만, 절호의 기회라고 생각하고 계획에 동참하기로 했다. 그렇게 새로운 노동조합, 듀로서 노동조합이 탄생했다. 이 새로운 고블린 집단은 호드에 합류하고자 하는 전 세계의 고블린들을 받아들였다.\r\n\r\n듀로서 노동조합의 최고 감독관이라는 칭호를 얻은 네르트는 곧 호드에게 자신의 동족의 가치를 증명할 기회를 맞이하게 될 것이다.'),
(10030, '듀로타 노동조합이 창설되고 가즈로우가 호드 대족장 앞에서 그들을 보증해 주자, 네르트는 임무만 기다리면 되었다. 그는 부하 몇 명을 듀로타에 남겨 필요한 일들을 돕게 하고, 나머지는 칼림도르로 보내 명성을 높이도록 했다. 네르트와 소수의 부하들은 더스탈로우 습지에 정착하여 머드스프로켓이라는 새로운 호드 정착지를 세웠다.\r\n\r\n몇 달 동안 고블린들은 험난한 환경에 적응해야 했다. 지역 야생 동물들의 공격에 시달렸을 뿐만 아니라, 오닉시아의 자손들을 물리치기 위해 정교한 도구를 제작해야 했다.'),
(10031, '마침내, 오랜 기다림 끝에 대족장은 듀로서 노동조합에 호드의 수도 오그리마 근처에 항구를 건설하라는 명령을 내렸습니다. 항구 건설은 엄청난 노력이 필요한 작업이었지만, 블레이드피스트 만 인근에 석유 자원이 없었더라면 훨씬 더 오랜 시간이 걸렸을 것입니다.\r\n\r\n많은 헌신과 엄청난 노동 끝에, 고블린의 주요 도시가 될 항구가 마침내 완공되었습니다. 네르트는 이 항구에 스파크워터 항구라는 이름을 붙였고, 이로써 자신과 듀로서 노동조합의 이름을 호드의 역사에 새겨 넣었습니다.'),
(10032, '최근 스톰윈드 시 재무부의 과도한 규제로 인해 쉘 사는 사무실을 무법항 자유 무역항으로 이전할 수밖에 없었습니다.\r\n\r\n이러한 상황에 불만을 느끼신다면, 여러분이 마땅히 누려야 할 부를 가로막으려는 스톰윈드 요새의 무능한 관료들에게 여러분의 의견을 표명해 주십시오!'),
(50065, '교수님은 다른 사람들에게 변장하는 법을 가르쳤다고 말씀하셨습니다. 그들이 어디에 있는지는 알려주지 않으셨지만, 어떤 변장을 했는지 적힌 목록을 주셨습니다. 저는 그들이 잠입했던 곳들을 찾아가 그들을 찾아야 합니다. 어쩌면 그들도 저에게 변장하는 법을 가르쳐 줄지도 모릅니다. • 데피아즈즈 $B$B풋패드 • 검은무쇠 $B드워프 • $B사우스시 해적 • $B달라란 마법사 • $B스톤스플린터 트로그 $B• 비밀결사대 하이웨이맨'),
(50066, '빨간 버튼! 당연히 시동이죠! 레버는 조향 장치입니다.\r\n\r\n가는 길에 바위에 부딪히지 않도록 조심하세요. 랜드마크를 맞춰 점수를 얻고, 저 난쟁이들을 혼내주세요! 만약 경주용 자동차가 폭발했는데 보험이 없다면, 당신의 소지품은 크루작과 고블린 엔지니어링 팀에게 넘어갈 겁니다.\r\n\r\n경주용 자동차 내구 충돌 테스트를 진행해 주셔서 정말 감사합니다!\r\n\r\n최고예요!'),
(50067, '빨간 버튼! 당연히 시동이죠! 레버는 조향 장치입니다.\r\n\r\n가는 길에 바위에 부딪히지 않도록 조심하세요. 랜드마크를 맞춰 점수를 얻고 고블린들을 박살내세요! 만약 경주용 자동차가 폭발했는데 보험이 없다면, 당신의 소지품은 게리 크래시배시와 그놈 엔지니어링 팀에게 넘어갈 겁니다.\r\n\r\n경주용 자동차 내구 충돌 테스트를 진행해 주셔서 감사합니다!\r\n\r\n정말 최고예요!'),
(50080, '쉬머링 플랫츠 — 사막 생물들의 울음소리와 모래폭풍 소리는 이제 사라졌습니다. 강력한 엔진 소리에 쫓겨난 전갈들의 덜컹거리는 소리도 더 이상 들리지 않습니다. 전 세계의 엔지니어들이 한때 탁 트인 평원을 가로지르는 가장 빠른 기계를 만들기 위해 모여들고 있는 가운데, 가젯잔 타임즈는 현장 작업팀과 특별한 인터뷰 기회를 얻었습니다.\r\n\r\n"우리가 여기서 이루고자 하는 목표는 단순히 지상 최고 속도 기록을 세우는 것만이 아닙니다." 위대한 브라스볼츠 형제의 조수인 그레고르 피즈워즈는 가젯잔 타임즈에 이렇게 말했습니다. "물론 역사에 길이 남을 훌륭한 그놈 공학 작품을 만들고 싶기도 하지만, 더 중요한 건 고블린들을 이기는 겁니다!"'),
(50081, '그놈족 엔지니어들이 \'레이서\' 개발에 상당한 진전을 이룬 것은 사실이지만, 그들의 기술 발전을 한 발짝도 놓치지 않은 것은 바로 돈벌이가 될 만한 것을 알아보는 안목을 가진 고블린족이었다.\r\n\r\n"그놈족은 제대로 작동하는 것을 만드는 법이 없어." 고블린족 작업반원 중 한 명인 에드 스프로켓이 말했다. "그들은 자잘한 것들을 만지작거리느라 시간을 너무 많이 허비해서 더 큰 프로젝트를 진행하고 있다는 사실을 잊어버려. 내부 조명을 조절하는 작은 부품이나 좌석 쿠션 같은 것들은 좋은 아이디어일지 몰라도, \'그것\'이 움직이지 않으면 시간 낭비일 뿐이지."'),
(50082, '그놈족과 고블린족은 오랫동안 이 반짝이는 평원에서 서로 경쟁하듯 더 나은 스피드 레이서를 만들려고 애써 왔습니다. 과연 얼마나 진전이 있었을까요?\r\n\r\nG.T.는 브라스볼츠 형제 중 한 명에게 이 질문을 던지려 했지만, 그들은 의외로 대답을 꺼렸습니다. 대신 어린 피즈워즈가 다시 입을 열었습니다.\r\n\r\n"음, 기계화 경주차 시절에서 정말 많이 발전했죠!" 그는 웃으며 말했습니다. "아직 할 일은 많지만, 상당한 진전을 이뤘고 곧 획기적인 발전을 이룰 거라고 생각합니다."')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(50083, '그는 이 기회를 틈타 G.T.에게 기계식 비행선에서 괄목할 만한 발전을 이룬 그놈족 경주용 탈것을 살짝 보여주었다.\r\n\r\n"물론, 물탱크와 비행선을 섞어 놓은 것처럼 생겼지만," 그는 긴장한 듯 웃으며 말했다. "기본 구조에 큰 변화가 있어서 훨씬 더 좋아질 거야."\r\n\r\n"줄무늬 덕분에 더 빨라질 거라고!"\r\n\r\n당분간은 고블린 기술이 그놈족을 크게 두려워할 필요가 없어 보였다.'),
(50085, '피는 빨갛고, 친구\r\n트롤의 피부는 파랗다\r\n네가 이걸 읽고 있다면\r\n네게 저주를 걸겠다'),
(50086, '광폭화는 붉게 빛나고\r\n하트송은 파랗게 빛나\r\n아무도 날 매혹시킬 수 없어\r\n네가 하는 방식대로'),
(50087, '피는 붉고,\r\n잔달라의 하늘은 파랗다\r\n이게 네 기분을 돋운다면,\r\n내 부두 마법을 받아가 봐'),
(50088, '장미는 빨갛고\r\n붓꽃은 남색이야\r\n널 바라볼 때 내가 할 수 있는 말은\r\n타즈딩고뿐이야'),
(50100, '수확을 하기 전에 씨앗을 뿌리고 정성껏 가꿔야 합니다.\r\n\r\n가장 먼저, 그리고 아마도 가장 쉽게 시작할 수 있는 작물은 호박일 것입니다. 잘 익은 호박에서 씨앗을 얻어야 합니다. 거의 모든 농부들은 잘 익은 호박만 수확하고, 다음 수확을 위해 새로 자란 호박의 씨앗을 채취합니다.'),
(50101, '두 번째는 아주 비슷하지만 관리하기가 조금 더 복잡한 수박입니다. 수박을 재배하려면 씨앗이 필요하고, 씨앗을 구하는 곳도 비슷합니다. 어떤 농부들은 이 달콤하고 커다란 열매만 전문적으로 재배하기도 합니다. 수박은 흔하지 않지만 동부 왕국 전역에서 매우 유명합니다.'),
(50102, '버섯은 정말 흥미롭고 완전히 다른 이야기입니다. 네, 여러분도 버섯을 키울 수 있습니다! 하지만 버섯 포자는 매우 특별하고 종류가 매우 다양합니다. 버섯 연구에 평생을 바친 전문가들을 찾아보셔야 할 겁니다. 버섯은 제대로 관리하면 잘 자랍니다. 하지만 때로는 해충처럼 번식하기도 하므로 어떤 경우에도 피해야 합니다. 항상 조심하세요.'),
(50103, '같은 방법으로 직접 키울 수 있는 마지막 작물은 산딸기 씨앗입니다. 이 씨앗은 자연 언덕에서 자라는 것으로 알려져 있는데, 세상에는 언덕이 많지만 모든 언덕이 산딸기가 자라기에 적합한 것은 아닙니다. 던홀드 요새 근처에서 와일드해머 중 한 명과 거래할 기회가 있었는데, 그 덕분에 산딸기 씨앗을 꽤 많이 얻을 수 있었습니다. 그가 어디서 씨앗을 구했는지는 모르지만, 모든 씨앗이 상태가 좋았고, 발아도 잘 되고 신선했기 때문에 아마 그 근처에서 구할 수 있을 거라고 추측할 뿐입니다. 직접 찾아보셔야 할 겁니다. 그 지역은 사나운 야생 동물과 끔찍한 괴물들이 우글거리는 곳이니 조심하세요. 너무 멀리 가면 위험할 수 있습니다.'),
(50500, '마법사 브롬리에게\r\n\r\n보내주신 레이 샤드는 정말 놀라웠습니다. 명가족이 마법을 다루는 방식은 언제나 제게 흥미로웠는데, 이번 레이 샤드 발견은 달라란 연구에 큰 도움이 될 것입니다.\r\n\r\n하지만 보내주신 이유가 그것 때문만은 아닙니다. 레이 샤드를 연구해 보니, 수정에 외계 마법의 흔적이 남아 있어 마법의 효능을 약화시키고 있는 것을 발견했습니다. 이는 아즈샤라 지역에서 누군가 마법을 조작하고 있다는 것을 거의 확실하게 증명하는 것입니다. 당신의 생각대로 말입니다.'),
(50501, '좋은 소식을 전해드렸지만, 나쁜 소식도 전해야겠습니다. 그 외계 마법은 용족의 속성이라는 것이 확실합니다. 수많은 사례와 연구를 통해 이를 입증했으니, 저는 완전히 확신합니다. 그 지역에서 활동하는 유일한 집단은 푸른 용군단뿐입니다. 그들이 왜 그곳에서 활동하는지는 말씀드릴 수 없지만, 그들의 마법이 파편에 남아 있기 때문입니다. 이 문제를 해결하는 데 행운을 빌며, 푸른 용군단과 혼자 맞서기보다는 외부의 도움을 구하는 것이 좋겠습니다.\r\n\r\n친구, 달라란의 대마법사 안시렘 룬위버 드림.'),
(50502, '브롬리, 안녕! 필요한 물품을 담은 상자를 배달원을 보냈어! 오래 기다리게 해서 미안해. 우리와 너 사이에는 위험이 도사리고 있거든! 마법으로 도와줘서 다시 한번 감사해. 덕분에 우리 계획이 순조롭게 진행됐어!\r\n\r\n플랙스위스커 전선의 지그노 플랙스위스커 드림.'),
(50503, '지그노에게.\r\n\r\n물품 보내주셔서 감사합니다. 당신과 당신의 노움들이 건강하게 잘 지내고 계시고, 과학이라는 위대한 분야를 계속 발전시켜 나가고 있다는 소식을 듣게 되어 기쁩니다. 제가 제작을 도왔던 로봇에 대한 소식이 있습니다. 레트레스 성소의 나가를 방문했을 때 해안가에서 그 로봇을 발견했습니다. 로봇이 고장 나서 작동하지 않는 것으로 보아 나가들은 로봇을 건드리지 않은 것 같습니다. 이 정보가 도움이 되기를 바라며, 앞으로도 행운이 함께하길 기원합니다.\r\n\r\n마법사 브롬리, 키린 토르.'),
(50504, '아즈샤라 정찰 (22.03 04:22-05:55)\r\n\r\n윈터스프링 정찰 (01.04 14:33-15:03)\r\n\r\n아즈샤라의 푸른 용 정찰 (06.04 15:22-15:51)\r\n\r\n윈터스프링 북쪽 아이스포인트 바위 정찰 (07.04 05:22-09:31)'),
(50505, '그노메레간의 팅크마스터 오버스파크께.\r\n\r\n수개월 동안 당신에게서 아무런 소식도 듣지 못했습니다. 선원들의 사망과 물자 부족으로 우리의 상황은 점점 더 불안정해지고 있습니다! 제가 직접 편지를 보낼 수 없어 이 보고서를 전달하는 자에게 대신 전해 달라고 부탁했습니다. 그노메레간에서 지원 병력이 어디 있는지, 또는 왜 이렇게 오랫동안 아무 소식도 없는지 알려주십시오.\r\n\r\n또한, 팅커스파크 트랜스폰더 예비품을 신속히 요청합니다. 우리의 트랜스폰더는 오래전 나가의 습격으로 분실했습니다.\r\n\r\n기그노 플랙스위스커!'),
(50506, '플랙스위스커 전선의 기그노 플랙스위스커에게.\r\n\r\n그놈레건의 참혹한 상황을 알려드리게 되어 마음이 너무나 아픕니다. 도시는 파괴되었고, 한때 존재했던 모든 것은 더 이상 남아 있지 않습니다! 트로그의 침략 이후 터널은 상상을 초월하는 방사능에 오염되었습니다.\r\n\r\n우리 동족 중 많은 이들이 아직 그곳에 남아 방사능에 심하게 오염되어 끔찍한 나병 노움으로 변해버렸습니다! 탈출에 성공한 나머지 우리는 아이언포지에 팅커 타운을 건설했고, 현재 그곳이 우리의 새로운 보금자리입니다. 편지에 당신이 고향으로 돌아갈 수 있도록 충분한 동전을 동봉했습니다. 어떻게든 방법을 찾아 팅커 타운으로 돌아오십시오.'),
(50507, '성기사 자나토스의 이야기\r\n\r\n저와 제 동료들은 동쪽으로 향하던 중 황무지 성역의 길 잃은 자들의 공격을 받았습니다. 많은 이들이 목숨을 잃었고, 보급품도 약탈당했습니다. 저는 간신히 탈출하여 임시 캠프를 차리고 간신히 생존하고 있습니다. 곧 휴식을 취하고 돌아오겠습니다.'),
(50508, '칼, 오랜만이구나. 잘 지내고 있다는 걸 알려주려고 연락했어. 정말 오랜만에 보는구나. 다시 만나게 되어 정말 기쁘다.\r\n\r\n쿨 티라스를 떠난 후, 함대는 오랫동안 바다를 항해했어. 얼마 전 공격을 받아 배가 파괴되었고, 지금은 가시덤불 골짜기 계곡 해안의 라피디스 섬에 정박 중이야. 배가 수리되면 집으로 돌아갈 거고, 예전처럼 꼭 들러서 인사할게.\r\n\r\n형 아놀드 드림.'),
(50509, '동생아, 정말 오랜만에 보는구나. 나는 지금 함대원들과 함께 남해 근처 가시덤불 골짜기 베일 해안가의 라피디스라는 섬에 고립되어 있다. 우리는 이곳을 우리 집처럼 여기고 꽤 오랫동안 지내왔으며, 지금 배를 수리하고 있다.\r\n\r\n수리가 끝나면 너와 칼을 만나러 들를 거야. 그날이 정말 기다려지고, 너도 잘 지내고 있기를 바란다.\r\n\r\n형 아놀드 드림.'),
(50510, '로룩 포레스트스트라이더에게\r\n\r\n당신의 의심이 맞았던 것 같습니다. 뭔가 끔찍한 것이 공기 중에 도사리고 있는 듯합니다. 한때 매우 친절했던 퍼볼그들이 사악하게 변해, 눈에만 보이려 합니다.\r\n\r\n땅 자체가 메말라 가고 있습니다. 거대한 분화구들이 곳곳에 생겨났고, 야생 동물들조차 퍼볼그들처럼 광기에 휩싸인 듯합니다. 이곳의 수호자라고 알려진 자를 만나보려 했지만, 혼자서는 너무 위험한 곳이라 갈 수 없었습니다.\r\n\r\n이곳에 끔찍한 일이 벌어졌습니다. 뭔가 조치를 취해야 합니다.\r\n\r\n페란 스트롱윈드 드림.'),
(50511, '대드루이드 판드랄 스태그헬름께\r\n\r\n애쉬엔베일에는 타락이 만연해 있습니다. 날이 갈수록 야생 동물들은 더욱 공격적으로 변하고, 퍼볼그들은 더욱 뻔뻔스러워졌습니다. 그들은 더 이상 숲의 친구가 아니며, 감히 모습을 드러내는 자들에게 무기를 들고 달려들고 있습니다.\r\n\r\n버려진 마을에는 어둠의 의도가 담긴 장신구들과 조잡한 룬 문자가 새겨진 돌들이 널려 있고, 그들이 탐닉하는 수액조차 오염되었습니다.\r\n\r\n그들은 길을 잃었고, 우리는 이 문제를 해결해야만 합니다. 그렇지 않으면 숲 전체가 이러한 광기에 휩싸일 것입니다.\r\n\r\n팔단 문섀터'),
(50512, '$N, 신병이 사냥에 대한 열정을 보인다는 이야기를 듣게 되어 기쁩니다.\r\n\r\n비록 우리가 살아생전에 드워프나 하이 엘프처럼 뛰어난 명사수라고 자부하지는 못했지만, 야생을 사랑하고 동물들과 오랜 시간 충실한 동반자를 만들며, 바람 한 줄기, 강물의 소리 하나하나에서 자연의 리듬과 부름을 느끼는 것을 자랑스럽게 여겼습니다. 이러한 모든 것들이 우리 삶에 더할 나위 없는 기쁨을 가져다주었습니다.'),
(50513, '자연에 적응하는 것은 우리의 가장 위대하고 고귀한 목표 중 하나였지만, 영원한 죽음 이후의 세계를 경험하면서 우리는 더 이상 자연에 적응할 수 없게 되었습니다. 오히려 자연이 우리에게 적응해야 할 것 같습니다. 공동묘지에서 만나자. 그곳에서 내가 과거의 경험과 살아남아 리치 왕에게 복수할 수 있는 몇 가지 비법을 알려주겠다.\r\n\r\n밴시 여왕을 위하여, 포세이큰을 위하여.'),
(50514, '강력한 금속을 단련하고 어둠의 마법으로 강화하는 것이 우리 작업의 핵심입니다. 검에 마법의 룬을 새기기 위해서는 우리 종족에게 풍부한 막대한 자원이 필요합니다.\r\n\r\n어둠의 룬은 검 표면에 새겨지고 극한의 온도로 가열되어야 하며, 그 힘이 약해지지 않도록 검의 정중앙에 새겨야 합니다.\r\n\r\n마법이 걸린 가죽을 손잡이에 감싸서 무기의 마법적 효능과 균형을 확보해야 합니다.\r\n\r\n'),
(50515, '이것들은 룬검의 진정한 창조를 위해 반드시 익혀야 할 첫 번째 기술들이며, 우리의 위대한 마법을 터득하고자 하는 자라면 누구든 이러한 방법들을 배울 수 있다.\r\n\r\n충성스러운 자로서 이러한 지식을 얻고자 하는 자는 이 세상에 있는 나의 서재를 찾아오라. 나는 협곡 속 그림자 속에 숨어 있으며, 내 하인이라 불리는 자들과 함께 있다.'),
(50516, '아주 오래전, 하이 엘프들은 인간 동맹들과 함께 우리에게 마법의 비밀을 가르쳐 주었습니다. 그들은 우리에게 마법의 규칙과 마법이 사람을 미치게 만들 수 있다는 것을 설파했죠! 하지만 그 말을 믿지 마세요. 우리는 엘프와는 다릅니다. 그들에게서 같은 약점을 물려받지 않았으니까요. 올바른 길을 걷는다면 마법이 무기만큼이나 강력한 도구라는 것을 알게 될 겁니다.\r\n\r\n준비가 되면 앤빌마르 안에서 저를 찾아오세요. 기다리고 있겠습니다!\r\n\r\n- 마렉 스트롬너, 마법사 훈련가'),
(50517, '스톰윈드의 마커스 조나단 장군께\r\n\r\n시간이 흐를수록 위험은 더욱 커지고, 식량은 점점 더 구하기 어려워지고 있으며, 우리 병력은 그 어느 때보다 부족합니다. 로데론의 희망은 오직 제 곁에서 신념을 위해 싸우는 용감한 병사들에게 달려 있습니다.\r\n\r\n얼라이언스의 지도자로서, 저는 병사 여러분께 로데론 전쟁에 힘을 보태줄 것을 요구합니다. 우리 병력의 어려움을 덜어줄 식량과 보급품을 보내주십시오. 이 요구에 응한다면, 승리했을 때 여러분은 큰 보상을 받을 것입니다.\r\n\r\n진심으로, 로데론 군대 사령관 사일러스 대위 드림.'),
(50518, '로데론의 사일러스 대위님께\r\n\r\n귀하의 요청을 들어드릴 수 없음을 알려드리게 되어 유감입니다. 보급품을 전달하거나 병력을 북쪽으로 이동시킬 확실한 방법이 없으며, 저에게는 그러한 결정을 내릴 권한이 없습니다.\r\n\r\n귀하와 귀하의 가족분들은 무의미한 죽음을 피하기 위해 스톰윈드로 후퇴하시기를 권고드립니다. 만약 제 권고를 따르지 않으신다면, 저는 빛의 축복만을 전해드릴 수 있을 뿐입니다.\r\n\r\n스톰윈드 장군 마커스 조나단 드림'),
(50519, '<일지의 첫 페이지가 찢겨 나갔다>.'),
(50520, '31일차: 날씨가 너무 안 좋네요. 드럼통 안의 연료가 얼기 시작했어요. 특히 이렇게 추운 날씨에 혼자 일하니 정말 힘드네요! 피즐파이프가 어서 돌아와서 도와주면 좋겠어요.\r\n\r\n45일차: 식량이 거의 다 떨어져 가고 있어요. 텐트 안에 갇혀 사방에서 몰아치는 바람을 이불과 모피로 뒤덮고 눈보라가 제발 그치기만 바라고 있어요.\r\n\r\n48일차: 드디어 날씨가 맑아졌어요! 텐트 주변에 쌓인 눈을 좀 치울 수 있었고, 몇 주 만에 처음으로 따뜻한 음식을 해 먹었어요. 날씨가 계속 좋았으면 좋겠네요!'),
(50521, '52일차: 좋은 날씨는 끝났고, 다시 눈이 내리기 시작했는데, 정말 사납게 쏟아지네요! 비행기를 고쳐보려고 애썼지만, 사흘 동안 햇볕이 쨍쨍했는데도 시동이 걸리지 않았어요. 곧 고쳐지길 바라야겠어요.\r\n\r\n54일차: 폭풍우를 뚫고 나가서 스팬플럭스 콘덴서에 문제가 있다는 걸 발견했어요. 영하의 온도에 맞게 만들어진 게 아닌 것 같아서 완전히 해동해야 할 것 같아요. 텐트 안으로 가져와서 따뜻하게 해주고 있는데, 부디 효과가 있기를 바랍니다.\r\n\r\n53일차: 젠장, 피즐파이프, 도대체 어디 있는 거야? 동전 던지기 한 번이 이렇게 큰 불행을 가져올 줄 누가 알았겠어! 그놈레건으로 돌아가면 네놈에게 온갖 빚을 지게 될 거야.'),
(50522, '59일째: 스팬플럭스 커패시터를 이용한 제 노력은 거의 허사였습니다. 날씨가 좋았던 단 하루뿐이었는데, 그마저도 비행기가 이륙하는 데 성공하지 못했습니다. 시동이 걸리려는 소리는 들렸지만요.\r\n\r\n62일째: 너무 배가 고파요. 먹을 것도 거의 다 떨어져서 부스러기만 먹고 있어요. 이번 임무는 완전히 실패했고, 그놈레간에게서도 오랫동안 소식이 없네요. 내일은 무슨 일이 있어도 비행기에 남은 연료를 넣고 시동을 걸어볼 겁니다. 제발 성공하길!'),
(50523, '63일째: 자, 또 끔찍한 눈이 내리는 최악의 날이군! 추위에 질릴 대로 질렸어. 이제 이 망할 비행기를 고쳐야겠어. 어디 있든 피즐파이프 영감, 행운을 빌어줘.'),
(50524, '맥코이I님께,$B$B 최근 공급 문제로 어려움을 겪고 있습니다. 악성 댓글 공격부터 배송 지연까지 여러 문제가 있었는데, 보내주신 덕분에 많은 도움이 되었고 문제가 해결되었습니다. 곧 모든 물품을 받으실 수 있을 겁니다.\r\n\r\n\'윈칭\' 윌리 드림.'),
(50525, '호드의 용사이자 레이드 전사였으며 친구였던 프로슬리를 기리며. 그는 영원히 우리 마음속에 기억될 것입니다.'),
(50526, '속눈썹 나무는 세월이 흘러내린 수많은 상처로 뒤덮여 있다. 어떤 상처는 아직도 수액이 뚝뚝 떨어지고, 어떤 상처는 희미하고 유령 같은 흉터로 남아 있다. 나무 살점에 새겨진 한 이름은 여전히 ​​피를 흘리고 있다. "아리엘레."'),
(50527, '위대한 노파는 듀로서에 도착한 이후 오크들을 예의주시해 왔으며, 지금이 바로 그들이 가장 약해진 때입니다. 그들의 적들은 땅을 그들에게 등을 돌리게 하고, 이 땅이 다시 우리의 것이 되기를 갈망하고 있습니다.\r\n\r\n우리의 새로운 동맹들은 우리가 가시덤불 굴에서 오크들의 시선을 차단한다면 위대한 멧돼지의 귀환을 목격하겠다고 맹세했습니다. 우리의 의식이 뿌리내리는 동안 오크들의 주술사는 아무것도 모를 것입니다. 위대한 멧돼지의 귀환을 위해 싸우고 죽어라!'),
(50528, '다로우게이즈 탑\r\n\r\n아라토리오 제국 시대, 트롤 전쟁 이전 인간 부족들이 통일되던 시기에 건설된 유서 깊은 감시탑입니다. 군사 초소 역할을 했으며, 로데론의 깃발 아래에서도 그 역할을 다했지만, 통치하던 귀족들이 무역 불황으로 어려움을 겪으면서 쇠락의 길을 걷게 되었습니다. 그러다 제2차 세계 대전 당시 호드의 공격을 받고 매복 장소로 이용되기도 했습니다.'),
(50529, '알렉산드로스 모그레인이 스칼렛 크루세이드를 이끌던 시절, 이곳은 스칼렛 크루세이드의 전초 기지가 되어 엠버 포인트라는 새로운 이름을 얻었습니다. 그러나 알렉산드로스가 배신당한 후, 아르젠트 크루세이드가 이곳을 점령하고 스컬지와의 전투를 위한 전초 기지로 아르덴트 워치로 개명했습니다. 아르젠트 뱅가드가 해산된 후, 이곳은 또 다른 성기사단인 크루세이드의 깃발 아래 재건되었습니다.'),
(50530, '은빛 선봉대\r\n\r\n은빛 십자군의 해외 작전 대대인 은빛 선봉대는 술푸라스를 휘두르는 성기사 아우렐리안의 지휘 아래, 호드와 얼라이언스 모두를 환영하며, 단 조건은 스컬지를 처치하고 소속 기간 동안 불가침 조약을 준수하는 것이었습니다. 이들은 아제로스 전역에서 스컬지 요새 및 점령 지역, 특히 거대한 낙스라마스 네크로폴리스에 대한 공격을 포함한 다양한 임무를 수행했습니다.'),
(50531, '안타깝게도 아르젠트 뱅가드는 해산되었지만, 은퇴한 성기사 아우렐리안은 뱅가드가 부재중인 동안 다로우게이즈를 보호하고 활용하기 위해 아르덴트 워치를 크루세이드라는 다른 성기사로 이관하는 것을 감독했습니다.'),
(50532, '십자군\r\n\r\n제2차 전쟁 당시 동맹국들의 지휘 아래 성스러운 군사 기사단으로 활동했던 사제, 성직자, 수도사, 성기사으로 구성된 기사단. 은빛 손 기사단이 분리되고 은빛 십자군과 광신적인 분파인 붉은 십자군이 창설되면서 해체되었다.'),
(50533, '"스칼렛"이나 "아르젠트" 같은 별칭 없이, 우리는 은빛 손과 함께했던 이전의 본래 질서로서 다시금 십자군 원정을 시작합니다. 아제로스 전역에 만연한 호드의 새로운 이단자들과 고대의 언데드 및 악마 적들의 위협에 맞서, 우리는 얼라이언스 내에서 십자군 원정을 다시 활성화했습니다.'),
(50534, '센트리 포인트 타워 상황 보고\r\n\r\n야생 동물들이 문제를 일으키고 있지만, 현재까지는 잘 대처하고 있습니다. 해안을 따라 이동하는 미르핀 떼가 조만간 테라모어에 문제를 일으킬 가능성이 있습니다.\r\n\r\n사기는 높으며, 물자도 충분합니다.\r\n\r\n월리스 크로스 함장'),
(50535, '노스 포인트 타워 상황 보고\r\n\r\n북쪽 황야를 배회하는 블러드펜 랩터 무리의 공격으로 한 명이 전사하고 세 명이 부상을 입었습니다.\r\n\r\n최근 호드 순찰대가 정찰을 나갔고, 미리 경고를 받기 위해 전방에 경계병과 초병을 배치했습니다.\r\n\r\n사기는 유지되고 있지만, 보급품이 부족해지고 있어 식량을 요청합니다.\r\n\r\n하커 대위.'),
(50536, '사랑하는 형님, 오랜만에 뵙게 되어 정말 기쁩니다. 편지를 보내려고 마음은 했지만, 마땅한 방법이 없어서 미뤄왔습니다.\r\n\r\n이 편지가 형님께 닿기를 바라며, 제가 잘 지내고 있다는 것을 전해 주시기 바랍니다. 테라모어를 지키는 일은 정말 보람 있는 일이었고, 이제 이곳이 제 진정한 고향이 되었습니다. 함께 복무하는 동료들은 제가 만난 최고의 동료들이니, 걱정하지 마세요. 저는 정말 든든한 지원을 받고 있습니다.\r\n\r\n형님의 사업이 성공했다는 소식을 듣고 정말 기뻤습니다. 언젠가 다시 만나 예전처럼 함께 축하할 수 있는 날을 손꼽아 기다리겠습니다.\r\n\r\n월리스 크로스'),
(50537, '슈레더 테크\r\n\r\n솔직히 \'슈레더\'라는 이름은 마케팅 측면에서 좀 아쉬운 선택이라고 생각했습니다. 이 기계들은 고블린 노동자 50명의 값어치를 할 뿐 아니라, 톱질, 찢기, 파쇄, 분쇄, 부수기, 으깨기 등 온갖 작업을 할 수 있죠. 독자 여러분, 그 가능성은 거의 무궁무진합니다.\r\n\r\n혹시 투자자이신가요? 아니면 이 멋진 기름 먹는 기계에서 퓨즈를 훔쳐 암시장에 팔아넘기려는 얄팍한 수법의 소유자이신가요? 뭐, 저는 판단하지 않습니다. 오히려, 만약 당신이 하나라도 구해오신다면 저도 기꺼이 사겠습니다... 어쨌든, 최근 투자자 명단은 다음과 같습니다.'),
(50538, '애쉬엔베일, 워송 벌목 캠프. 이 작업 규모는 정말 경이롭습니다. 강 건너편에서 오크와 엘프가 서로 칼부림을 벌이는 모습도 꽤 재미있죠.\r\n\r\n돌발톱 산맥, 윈드셰어 절벽의 투자개발회사. 뭐, 환경운동가들이 또 숲을 베어버렸네요. 하지만 누가 신경 쓰겠어요? 원래 그 계곡은 끔찍하게 못생겼었는데, 산업화 덕분에 훨씬 보기 좋아졌죠.\r\n\r\n가시덤불 골짜기 계곡, 나즈페리티 호수 근처의 투자개발회사. 지질학자들이 연구에 매진할 수 있도록 이 짐승들이 덤불을 헤치고 나아가고 있습니다. 거기서 아름다운 수정들을 발견한다는 소문도 들었어요.\r\n\r\n서부 몰락지대? 서부 몰락지대 어딘가로 최첨단 장비 하나가 배송되었다는 소식을 들었는데, 어디로 갔는지, 누가 가지고 있는지는 소식이 없네요. 이상하네요, 흔적도 없이 사라졌어요…'),
(50539, '채석장\r\n\r\n독자 여러분, 제가 바로 그곳에 있었습니다! 불타는 초원을 가로질러 플레임 크레스트에 있는 동료를 만나러 가는 길이었죠. 상황을 묘사해 보자면, 태양은 높이 떠서 작열하고 있었고, 땅은 타르처럼 새까맣게 타오르고 있었으며, 야생 동물들은 흉측하고 위험하기 짝이 없었습니다.\r\n\r\n그때 갑자기, 쾅! 제가 들어본 것 중 가장 큰 폭발음이었습니다. 땅이 진동할 정도였죠. 당연히 저는 이런 놀라운 폭발의 원인이 무엇인지 알아내야만 했습니다. 지평선 너머 동쪽 언덕에 있는 채석장에서 짙은 녹색 연기가 피어오르는 것이 보였습니다. 그 어떤 냄새와도 비교할 수 없는 독특한 냄새에 코가 찡긋거리고 눈물이 핑 돌았습니다. 더 가까이 가지는 못했지만, 채석장 입구 쪽을 보니… 그 기묘한 검은무쇠 드워프들이 어슬렁거리고 있었습니다. 경계를 지키며, 그 이상한 드워프 방언으로 서로에게 소리치고 있었죠!'),
(50540, '무슨 일인지 물어보니, 그 지역에서 사람들이 바위투성이 길을 따라 오가는 모습이 자주 목격되었다고 하더군요. 채석장이 더 이상 버려진 상태는 아닌 것 같습니다. 문제는 뭘 하고 있냐는 거죠. 그 지독한 냄새는 처음 듣는데, 화약 냄새는 아니었어요. 폭발음도 예전보다 더 잦고 격렬해 보였는데, 단순히 광물을 캐내려고 바위를 부수는 소리만은 아니었던 것 같습니다. 용감하지만 (동시에 멍청하기도 한) 고블린 한 마리가 현장 감독인 바르굴을 만나 무슨 일이 벌어지고 있는지 알아보려 했지만, 돌아오지 않았습니다. 솔직히 뭘 기대했던 걸까요?\r\n\r\n제가 아는 건, 활동이 있는 곳에는 생산이 있고, 생산이 있는 곳에는 사업이 있고, 사업이 있는 곳에는 금이 있다는 겁니다! 모험가 여러분들이 시간과 노력을 어디에 쏟아야 할지 제가 왈가왈부할 생각은 없지만, 저라면 거기 있는 드워프들을 만나 무슨 일이 벌어지고 있는지 알아보고, 어쩌면 초기 투자자가 될지도 모르겠네요! 아니면 최소한 그들의 비밀이라도 팔아넘기거나요. 제게는요. 이상적으로는요.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(50541, '비행선 사고\r\n\r\n시간과 편의를 위해서라면 사람들이 얼마나 많은 고생을 감수하는지 정말 놀랍습니다. 저는 오래전부터 비행선 운송 회사의 주식을 보유하고 있었습니다. 비행선은 오크, 고블린, 심지어 거대한 타우렌까지 대륙을 횡단하는 데 없어서는 안 될 필수품이었죠! 똑똑한 사람이라면 누구나 가치 있는 투자라고 생각했을 겁니다.\r\n\r\n하지만 이제 경쟁자가 나타났습니다. 어떤 신참들이 카르가스까지 비행선 운송 사업을 시작한 겁니다! 맞습니다, 사막의 먼지와 바람, 모든 비행선의 천적인 그곳을 이 멍청이들은 완벽한 목적지로 택한 거죠.\r\n\r\n말할 것도 없이 결과는 끔찍합니다. 매일같이 비행선 갑판에서 튕겨져 나온 시체들이 사막의 뜨거운 햇볕에 말라가고 있다는 보고가 쏟아져 들어옵니다! 추락과 폭발 사고까지 발생하고 있다니, 정말 끔찍하네요.'),
(50542, '고블린의 공학 기술에 대해 뭐라고 하든 상관없지만, 지금까지 비행선에서 발생한 사망 사고는 모두 사람들이 비행선이 자기 집 위를 지나갈 때 뛰어내려 시간을 단축하려다 벌어진 일이나, 가끔씩 뻔뻔하게 정신 조종 마법에 걸린 경우뿐이었습니다. 물론, 저희는 이에 대해 어떠한 책임도 지지 않습니다. 탑승 약관에 명시되어 있는 내용입니다.\r\n\r\n더 이상 설명할 필요는 없겠죠. 그들의 교통수단을 이용하는 건 미친 짓입니다. 정해진 항로를 이용하세요. 안전에 유의하시고, 살아남으세요! 저희에게 맡겨주세요, 그들이 아니라!'),
(50543, '<복잡한 도표에는 여러 마법 속성이 녹은 용암과 섞이는 과정이 그려져 있다.>\r\n\r\n헤이트포지 맥주는 상층부가 극비리에 진행하려는 계획의 암호명이다. 이 문서를 연구하는 자는 누구든 입을 다물어야 한다.\r\n\r\n이 문서의 비밀을 누설하는 자는 법의 심판장에서 재판을 받게 된다.\r\n\r\n\r\n\r\n헤이트포지 화학자여. 도표와 그림을 연구하고 실험을 계속하라. 실패는 용납하지 않는다!!!'),
(50544, '새로운 호드의 대족장 스랄께.\r\n\r\n제 이름은 카르팡입니다. 저는 아웃랜드 출신으로, 검은바위산 아래에서 동족과 싸웠지만, 그들은 더 이상 예전 같지 않습니다.\r\n\r\n검은바위 부족과 옛 호드는 외부의 영향에 물들어 타락했습니다. 당신도 잘 알고 계시리라 믿습니다. 저는 제 동족과 함께 새로운 미래를 만들고자 하며, 이 편지를 당신께 전하는 것은 큰 위험을 무릅쓰는 일입니다.\r\n\r\n저는 당신의 새로운 호드에 충성을 맹세하고, 제 동족을 구하고자 합니다.\r\n\r\n대족장 카르팡 드림.'),
(50545, '전쟁 지도자 카르팡께.\r\n\r\n당신의 편지를 읽고 귀 기울여 들었습니다.\r\n\r\n호드는 고난과 역경에 익숙합니다. 우리 모두는 당신처럼 힘겨운 싸움을 하고 어려운 결정을 내려야 했습니다. 우리는 전쟁으로 피폐해진 이 세상을 위해 지혜와 명예라는 가치를 공유하는 평등한 집단입니다.\r\n\r\n만약 당신이 대족장인 저에게 진정으로 충성을 증명하고 싶다면, 당신에게 요구할 것이 있습니다.\r\n\r\n황혼의 망치단이 당신의 지역에 모습을 드러내기 시작했습니다. 그들은 이 세상에 위협이 됩니다. 그들을 제거해 준다면, 당신의 말이 진실임을 알게 될 것입니다.\r\n\r\n스랄, 호드 대족장.'),
(50546, '노동자를 위한 규칙\r\n\r\n감독관의 엄격한 감시 아래 열심히 일하라. 일을 하지 않으면 노예가 될 것이다.\r\n\r\n하루 일과는 바굴 블랙해머의 명령이 있어야 비로소 완료된 것으로 간주된다.\r\n\r\n감독관은 생산량 증대를 위해 존재하는 사람들이니, 절대로 그들에게 의문을 제기하지 마라.\r\n\r\n'),
(50547, '부상 발생 시 반드시 성직자에게 보고하십시오.\r\n\r\n작업반장에게 일일 지시사항을 받으십시오.\r\n\r\n작업 진행 중에는 어떠한 종류의 편지도 작성하지 마십시오.\r\n\r\n섀도우포지의 지시는 반드시 따라야 합니다.\r\n\r\n'),
(50548, '불의 군주께서 우리 모두를 지켜보시니, 이곳에는 실패란 있을 수 없다.'),
(50549, '보스,\r\n\r\n내 사보타주 작전이 성공하고 있어. 날마다 무기고에서 무기가 사라지고 있는데 아무도 눈치채지 못하고 있군. 머지않아 병사들은 나무 막대기로 싸우게 될 거야.\r\n\r\n더 이상 여기에 숨을 수 없어. 이 배신자들과 함께 단 한순간이라도 더 머무른다는 생각만 해도 속이 메스꺼워. 나와 할란을 자네와 자네 부하들에게 보내주게. 곧 우리는 테라모어 병사들보다 수적으로 우세해질 거야. 그리고 그때…\r\n\r\n그는 복수할 거야.\r\n\r\n콜드웰.'),
(50550, '닐스 형제님께\r\n\r\n형제님께서 제공해주신 정보는 카버 몰슨이라는 범죄자를 검거하고 정의의 심판을 받게 하는 데 결정적인 역할을 했습니다. 마침내 이스턴 가족 살인 사건의 복수가 이루어졌고, 형제님의 헌신적인 노력 덕분에 서부 몰락지대 마을은 조금이나마 희망을 되찾았습니다.\r\n\r\n이 편지를 전해준 사람이 서부 몰락지대 옛 교회의 열쇠도 찾았다고 합니다. 이 모든 일이 마무리되고 마을이 원래대로 돌아오면 형제님께서 다시 찾아주시기를 간절히 바랍니다.\r\n\r\n그리안 스타우트맨틀'),
(50551, '이 글은 내가 감히 그 이유를 묻지도 못하는 (내 월급과는 전혀 상관없는 일이니까) 회사에서 고용한 그 얼간이 같은 놈들 모두에게 하는 말입니다.\r\n\r\n너희 꼴통 엔지니어들은 항상 배관 근처에 있어야 해. 누구든 게으름을 피우거나 빠지거나, 아니면 금괴 하나라도 부러뜨리면 너희 모두가 그 대가를 치르게 될 거야!'),
(50552, '그리고 혹시라도 임금이나 계약 문제로 내게 시비를 거는 멍청이가 또 있다면, 그놈들을 묶어서 불타는 계곡의 괴물들에게 먹이로 던져줄 테니 조심해라.\r\n\r\n추신: 더 열심히 일해라. 이 프로젝트를 빨리 끝내야 한다.\r\n\r\n추신: 호드의 움직임을 항상 경계하라.\r\n\r\n-오일마스터 히글 와이어퓨즈'),
(50553, '이 통지서를 받으셨다면 당신은 승진 대상자로 선정되셨습니다! 물론 급여 인상은 없겠지만, 어쨌든 승진이 확정된 겁니다. 투자개발회사의 파우더 타운 진압 부대에 합류하게 되셨고, 때가 되면 당신과 동료들은 노동조합을 결성하기로 한 멍청한 내쉬와 그의 얼간이 동료들을 처리하러 파견될 것입니다.'),
(50554, '그렇게 멍청하게 금을 전부 혼자 차지하지 않을 수 있다니! 물론 내가 그런 짓을 한다는 건 아니지만. 모든 직원은 똑같이 대우받고, 내 월급이 당신보다 훨씬 많다는 생각은 절대 하지 마세요!\r\n\r\n추신: 폭탄을 몸에 두르고 회사의 더 큰 이익을 위해 자신을 희생하면, 당신의 연봉은 가족에게 지급될 겁니다. 그리고 언더마인의 다른 시민들과 마찬가지로 두 달간 무료 의료 혜택을 받을 수 있을 거예요.'),
(50555, '추신: 이 글을 읽고 나면 태워버려, 이 멍청아.\r\n\r\n- 오일마스터 히글 와이어퓨즈'),
(50556, '오일마스터를 존중하십시오.\r\n\r\n게으름 피우지 마십시오.\r\n\r\n오일마스터를 존중하십시오.\r\n\r\n점심시간 없음!\r\n\r\n오일마스터를 존중하십시오...\r\n\r\n작업 중 흡연 및 음주 금지!\r\n\r\n오일마스터를 존중하십시오.'),
(50557, '그 도깨비에 대한 바보 같은 농담은 하지 마!\r\n\r\n석유 사장님을 존경해라.\r\n\r\n임금이나 계약 조건에 대해 묻지 마라.\r\n\r\n석유 사장님을 존경해라.\r\n\r\n산업재해는 없다.\r\n\r\n석유 사장님을 존경해라.\r\n\r\n마지막 규칙: 석유 사장님을 존경해라.'),
(50558, '건물은 세월이 흐르면 ​​무너지고 썩어가지만, 강철은 영원하다. 코르탄 왕국은 건설된 나라가 아니라 단련된 나라였다. 어떤 대장간의 불길도 백성들의 열정보다 뜨겁게 타오를 수 없었고, 어떤 망치도 그들의 의지보다 강렬하게 내리칠 수 없었으며, 어떤 금속도 백성들의 결의만큼 망치질을 견뎌낼 수 없었다. 코르탄과 그 백성들은 진정한 단련된 강철과 같았고, 마치 잘 다듬어진 칼날처럼 피와 전쟁을 알 운명이었다.'),
(50559, '그러나 전쟁은 이 세상에서 죄악이며, 우리의 죄는 참으로 컸습니다. 가뭄, 기근, 역병, 편집증. 하나하나가 코르탄 백성의 의지를 시험했고, 전투는 우리 왕국의 강철에 흠집을 남기고 우리의 규율을 무디게 했습니다. 건물은 세월이 흐르면서 무너지고 썩어갈 수 있지만, 검은 결국 사라져 녹슬고 땅속에 묻혀 영원히 잊히는 운명입니다.'),
(50560, '이 기록이 코르탄과 아조타에 대한 증거가 되게 하라. 모든 검은 결국 마지막으로 내려놓아지지만, 진정으로 위대한 검은 그 이름과 후세에 전해질 유산을 남긴다. 코르탄의 검은 더 이상 피를 흘리게 하거나 적들을 무릎 꿇게 하지는 않겠지만, 그 이름은 영원히 기억되어야 한다. 잊히지 않도록 하라. 그렇지 않으면 이전의 검보다 더 무시무시한 검이 다시 나타날 것이다.'),
(50561, '미래를 위한 투자와 새로운 부의 창출 방법을 찾고 계십니까? 새로운 시대가 열렸습니다! 현명한 투자자들을 위한 새로운 세계의 문이 활짝 열렸습니다!\r\n\r\n쉘코인은 세상을 뒤흔들 새로운 마법 화폐입니다. 이제 금만이 유일한 거래 수단이 아닙니다. 가치 있는 신비한 화폐가 그 자리를 대신할 것입니다. 바로 지금, 상상하지 못했던 부를 거머쥘 기회입니다.\r\n\r\n지금 쉘코인에 투자하고 초기 투자자가 되십시오!'),
(50562, '새로운 전리품과 영광의 시대가 도래했습니다! 혁신적인 신화폐, 쉘코인이 등장하여 새로운 시대를 열었습니다. 이제 모든 젊은이들과 현명한 투자자들에게 새로운 세상에서 기회를 잡을 수 있는 문이 활짝 열렸습니다.\r\n\r\n이 새로운 화폐는 이미 세상을 뒤흔들 기세입니다. 더 이상 금만이 유일한 거래 수단이 아닙니다. 이 신비로운 화폐가 곧 금을 대체할 것입니다. 지금 투자하여 꿈에도 생각지 못했던 지위와 권력을 손에 넣으세요.\r\n\r\n호드의 형제자매들이여, 미래의 후원자가 되어 쉘코인을 구매하세요!'),
(50563, '스타윈드 사령관님,$B$B 간단히 말씀드리겠습니다. 어린 자매들을 불필요하게 전투에 내몰기 위해 권력을 남용한 당신의 파렴치하고 경솔한 행위가 여사제들과 최고 파수꾼에게 보고되었습니다. 수 세기 동안 당신이 저질러 온 행적을 명심하십시오.'),
(50564, '당신을 모든 지도자 직책에서 해임하는 것이 타당하다고 판단합니다. 다르나서스로 돌아가 새 임무를 받으십시오. 마지막 명령은 모든 파수꾼에게 숲의 노래 성소를 영원히 떠나라고 알리고, 당신의 불명예가 그들에게까지 영향을 미치지는 않을 것임을 설명하는 것입니다.$B$B대드루이드 판드랄 스태그헬름.'),
(50565, '브롤탄 아이언글레이드,$B$B 당신이 남부 애쉬엔베일 전투 참전을 거부한 동기를 짐작할 수는 없습니다. 그것이 비겁함 때문이든, 정치적 책략 때문이든, 배신 때문이든, 제가 판단할 문제는 아닙니다. 하지만 당신은 포레스트 송, 아스트라나르, 또는 칼림도르에 있는 어떤 칼도레이 시설로도 돌아가서는 안 됩니다.'),
(50566, '나머지 드루이드들도 이전에 협조하지 않았기에, 사령관 스타윈드의 지휘 하에 파수꾼들의 보호 아래 포레스트 송을 떠날 것입니다. 엘룬께서 당신을 용서하시기를 바랍니다.$B$B대제사장 티란데 위스퍼윈드.'),
(50567, '오늘 우리는 그들의 희생을 기리고, 그들의 헌신과 흔들림 없는 결의, 그리고 길네아의 본질을 구현했던 불굴의 정신을 기억하기 위해 이 자리에 섰습니다. 조국과 $B$B동료 시민에 대한 그들의 헌신은 비할 데 없었습니다. 하지만 그들의 희생은 헛되지 않았습니다. 길네아는 이제 그 어느 때보다 강해졌습니다. 이 용감한 병사들은 우리에게 영감을 주고 앞으로 나아갈 길을 제시하는 영원한 유산을 남겼습니다. 우리는 재건하고 $B$B앞으로 나아가겠다는 결의를 굳건히 지켜야 합니다. 우리는 회복력이 강하고 의지가 강철 같다는 것을 증명했습니다. 길네아는 반드시 $B$B이겨낼 것입니다. 이 어려운 시기에 저에게 보내주신 신뢰에 감사드립니다. $B$B여러분의 왕 - 젠'),
(50568, '원래 아라토르 제국에 속했던 일곱 나라 중 길네아는 독립을 위해 가장 치열한 투쟁을 벌여야 했던 나라로 꼽힙니다. 로데론은 귀족들의 영향력을 통해 자유를 쟁취할 수 있었지만, 길네아의 백성들은 독립을 위해 엄청난 희생을 감수해야 했습니다.'),
(50569, '이러한 사건들의 정확한 날짜는 세월 속에 묻혀버렸지만, 길네아가 알터랙이나 쿨 티라스와 같은 다른 주요 국가들보다 먼저 독립을 쟁취했다는 사실은 길네아에게 큰 자부심의 원천입니다. 길네아 사람들은 아라토리아 귀족의 굴레에서 벗어나 자치의 모든 혜택을 누린 최초의 민족 중 하나였습니다.'),
(50570, '전설에 따르면, 길네아를 다스렸던 그레이메인 왕조는 나라 남쪽 변방의 보잘것없는 땅을 소유한 미천한 귀족 가라론에 의해 세워졌습니다. 시간이 흐르면서 가라론의 영향력은 커졌고, 그는 뛰어난 전사이자 현명한 재판관, 그리고 명예로운 상대로 명성을 떨쳤습니다. 그의 업적은 생전에 이미 전설이 되었습니다. 그러나 그는 조국을 착취하고 억압하려는 부패한 아라토리아 귀족들에게 점점 염증을 느끼게 되었습니다.'),
(50571, '결국 가라론은 길네아의 뜻을 같이하는 영주들을 규합하여 부패한 아라토리아 왕 토라딘 3세와 그의 추종자들에 맞서 반란을 일으켰다. 많은 영주들이 반란에 가담하는 것을 주저했지만, 가라론은 그들을 설득하는 데 성공했고 마침내 스스로 길네아의 왕임을 선언했다.'),
(50572, '이는 아라토르가 용납할 수 없는 모욕이었고, 아라토르는 길네아를 진압하기 위해 군대를 파견했습니다. 반도 곳곳에서 수많은 전투가 벌어졌지만, 길네아 병사들의 용맹함에도 불구하고 전세는 불리해 보였습니다. 아라토르는 수적으로 우세하여 길네아 군대를 압도할 수 있었습니다. 레이븐스우드 전투에서 길네아는 패배했고, 군대는 뿔뿔이 흩어져 희망을 잃은 듯 보였습니다.'),
(50573, '하지만 젊은 길네아의 왕은 굴하지 않았습니다. 그는 전열을 재정비하고 병사들의 사기를 북돋았습니다. 최후의 전투는 스틸워드 언덕에서 벌어졌습니다. 그레이메인은 언덕 꼭대기에 방어 진지를 구축하고 기병대는 인근 숲에 숨겼습니다. 아라토리아군은 길네아군보다 네 배 이상 많고 장비도 훨씬 우수했기에, 아군을 돌보지 않고 가라론의 진지를 향해 돌격했습니다. 길네아군은 용감하게 싸워 수천 명의 아라토리아군을 죽였지만, 역부족이었습니다. 적군은 언덕으로 몰려들어 그레이메인의 군대를 포위하려 했습니다.'),
(50574, '다행히 숲 속에 숨어 있던 기병대가 나타나 전세를 역전시켰다. 그들은 숲에서 뛰쳐나와 아라토리아 군대를 향해 돌격했다. 갑작스러운 공격에 당황한 아라토리아군은 진형이 무너졌다. 후퇴를 시도했지만, 길네아군은 자비를 베풀지 않고 이전의 패배에 대한 복수를 다짐했다. 수천 명의 아라토리아인이 목숨을 잃었고, 그중에는 자비를 구걸했지만 받아들여지지 않은 토라딘 3세 왕도 있었다.'),
(50575, '결국 길네아스가 승리했고, 아라토르의 어린 왕자는 곧 평화를 청하러 왔다. 길네아스는 독립을 쟁취하여 달라란에 합류한 독립 인간 국가 중 하나가 되었다. 가라론은 새로 건국된 나라의 왕이 되었고, 그레이메인 왕조가 탄생했다.'),
(50576, '새롭게 건국된 길네아 왕국이 번영하기 시작했을 무렵, 또 다른 시련에 직면하게 되었습니다. 길네아의 땅을 탐낸 달라란의 귀족들은 아무런 경고나 선전포고 없이 길네아를 공격했습니다. 이는 교전 수칙을 명백히 위반한 행위였으며, 달라란 사람들의 비열한 본성을 드러낸 것이었습니다. 달라란의 마법사들은 자신들의 마법 능력으로 쉽게 승리할 수 있다고 믿고 길네아 군대의 전력을 과소평가했습니다. 에본미어 전투는 달라란 병사들의 처참한 학살로 끝났고, 그들의 마법사들은 길네아 시에서 국경까지 나무에 매달려 교수형에 처해졌습니다. 이는 다시는 길네아에 접근하지 말라는 경고의 메시지였습니다.'),
(50577, '달라란과의 전투에서 승리했음에도 불구하고, 젊은 길네아의 왕은 오래도록 쉴 수 없었습니다. 길네아의 여러 귀족들이 왕에게 항상 충성했던 것은 아니었고, 일부는 그의 통치에 반기를 들었습니다. 그러나 가라론 왕은 막강한 권력을 지녔고, 총애하는 장군 레이븐우드 경의 도움을 받아 $B$B모든 반란을 진압했습니다. 이후 가라론 왕은 길네아의 행정 개혁에 힘썼습니다. 그는 많은 새로운 법률을 제정하고 남부 지역의 가난한 백성들을 도왔습니다. 그의 통치 아래 길네아는 그 어느 때보다 강대해졌으며, 그는 쿨 티란과 알테라시 형제들의 독립 전쟁을 지원하기도 했습니다.'),
(50578, '그러나 비극이 닥쳐왔습니다. 가라론 왕은 불과 몇 년 전까지만 해도 자신을 지원했던 알테라크 귀족들에게 43세의 나이로 암살당했습니다. 이 사건은 두 나라 사이에 수십 년간 지속된 대규모 전쟁을 촉발시켰고, 두 왕국 모두를 황폐화시켰습니다. 길네아스와 알테라크의 전쟁은 인간 7왕국 역사상 가장 피비린내 나고 잔혹한 전쟁 중 하나였으며, 그 여파는 앞으로 수 세기 동안 이 지역에 지울 수 없는 상처를 남겼습니다.'),
(50579, '갈등 속에서도 가라론 왕의 유산은 살아남았습니다. 그는 백성의 독립을 위해 싸우고 폭정과 억압에 맞선 정의롭고 명예로운 통치자로 기억됩니다. 그의 지도력과 군사적 역량은 그레이메인 왕조를 세우는 데 기여했고, 이 왕조는 이후 여러 세대에 걸쳐 길니아스를 통치하게 되었습니다. 가라론은 사후에도 길니아스 백성들에게 희망과 영감의 상징으로 남았으며, 백성들은 그가 세상을 떠난 후에도 오랫동안 그의 업적을 기렸습니다.'),
(50580, '길네아 깃발에 새겨진 룬 문자의 기원은 오랫동안 미스터리에 싸여 있었으며, 아직까지 완전히 밝혀지지 않았습니다. 그 기원과 의미에 대해서는 다양한 이론이 존재하는데, 어떤 이들은 그것이 최초의 그레이메인을 상징한다고 주장하는 반면, 다른 이들은 현명한 펠라르가 만들었다고 주장합니다. 또 다른 이들은 그것이 빛의 도래 이전에 인간이 숭배했던 원시 신의 상형문자였을지도 모른다고 추측합니다.'),
(50581, '저명한 탐험가이자 고고학자인 저는 이 상징의 진정한 기원과 그것이 인류 전체에 갖는 의미를 밝히고자 했습니다. 그러나 길네아스의 초기 역사에 대한 연구는 많은 부분이 부실하게 기록되어 있고 서로 모순되는 정보가 많아 난관에 봉착했습니다.'),
(50582, '그럼에도 불구하고, 저는 길네아의 초대 왕인 가라론 그레이메인이 아라토르 건국 후 약 100년 만에 아라토르로부터 독립을 선언했으며, 그의 검 손잡이에 이미 길네아 룬 문자가 새겨져 있었다는 사실을 발견했습니다. 이는 해당 상징이 길네아 국가 건국 이전부터 존재했으며, 그레이메인 가문과 관련이 있었을 가능성을 시사합니다.'),
(50583, '하지만 제 연구 결과, 아라토리안 이전 시대의 유물에서도 동일한 상징이 발견되었습니다. 의식용 단검과 항아리부터 동물 두개골에 이르기까지 다양한 유물들이 길니아 왕국 안팎의 여러 지역에서 출토되었습니다. 따라서 이 유물들이 모두 그레이메인 가문의 소유였을 가능성은 낮습니다. 오히려 이 상징은 쿠엘도레이로부터 마법을 배우기 이전 시대의 원시적인 마법 의식에 사용되었을 가능성이 있습니다.'),
(50584, '하이 엘프가 등장하기 이전 인간 마법의 역사는 잘 알려져 있지 않지만, 트롤이나 코볼드의 원시적인 마법과 유사했을 것으로 추정됩니다. 따라서 이 상징은 특별한 의미를 지니고 있었으며, 어떤 원시 신이나 존재와 관련이 있었을 가능성이 높습니다.'),
(50585, '더 연구를 진행한 결과, 저는 쿠엘탈라스에 도착하여 원시 인류의 역사를 밝혀줄 두 개의 엘프 문서를 접하게 되었습니다. 특히 한 스케치는 길네아 문장과 매우 ​​흡사했고, 함께 적힌 글에는 그 상징이 어둠의 마법을 사용하고 이계의 존재를 소환하는 강력한 마법사들이 사용했던 것으로 추정되었습니다. 문서에는 마법사의 종족이 명시되어 있지 않았지만, 저는 그들이 인간이었을 것이라고 추론했습니다.'),
(50586, '유감스럽게도, 엘프들이 제가 발견한 것에 대한 두려움 때문에 조사를 계속하는 것을 금지했기에 제 연구는 중단되었습니다. 이후 제1차 전쟁을 비롯한 여러 사건들이 제 관심을 요구했고, 저는 연구를 잠시 중단할 수밖에 없었습니다.'),
(50587, '이러한 난관에도 불구하고, 저는 이 인간 마법사들의 정체와 그들이 지닌 힘, 그리고 길네아 왕실이 왜 그 상징을 문장으로 선택했는지에 대한 진실을 밝히겠다는 결심을 굳건히 하고 있습니다. 아직 밝혀내야 할 것이 많으며, 끈기와 인내심을 가지고 노력한다면 반드시 해답을 찾을 수 있을 것이라고 확신합니다.'),
(50588, '옛날 옛적에 다나바르라는 용감한 길네아 어부가 살았습니다. 그는 아내와 아들과 함께 해안 마을 시헤이븐에 살았습니다. 그러나 어느 날, 무르굴이라고 불리는 어인들이 바다에서 길네아를 침략하는 끔찍한 비극이 닥쳤습니다. 다나바르의 아내와 아들은 그 공격으로 목숨을 잃었고, 그에게는 딸만 남았습니다.'),
(50589, '당시 길네아는 북부 대재앙 이후 군대가 크게 약화되어 방어가 허술했다. 남아 있는 소수의 병력은 육상 국경을 지키고 있었지만, 바다에서 오는 진정한 위협을 인지하지 못하고 있었다.'),
(50590, '다나바르는 작살과 몇 가지 간단한 도구를 이용해 최대한 많은 어부들을 모아 민병대를 조직했습니다. 그들은 함께 공세를 펼치며 무르굴의 침략에 맞서 방어선을 구축했습니다. 점점 더 많은 사람들이 다나바르의 민병대에 합류했고, 마침내 왕립군은 침략 소식을 접하고 남쪽으로 이동하여 그 위협에 맞서 싸우기 시작했습니다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(50591, '아군의 지원으로 무르굴군은 전열을 무너뜨리고 바다로 후퇴하게 되었습니다. 하지만 다나바르는 단순한 승리 이상의 것을 원했습니다. 아내와 아들의 죽음에 대한 복수를 갈망했던 것입니다. 그래서 그는 어부들을 규합하여 적의 어선에 올라타 작살을 들고 적을 공격했습니다.'),
(50592, '뛰어난 사격 솜씨로 그들은 무르굴을 끈질기게 추격하여 심해까지 몰아붙였다. 다나바르와 그의 어부들은 후퇴하는 무르굴의 대부분을 학살했고, 그는 영웅이 되어 길네아로 돌아왔다. 왕은 다나바르의 용맹함에 감사하며 그에게 기사 작위를 수여했다. 그는 원래 생선 장수였던 직업을 빗대어 \'전쟁광\'이라는 별명을 얻게 되었다.'),
(50593, '다나바르는 딸과 함께 길네아 시티로 이주하여 왕실을 섬겼습니다. 시헤이븐은 재건되지 못했지만, 그의 딸은 훌륭하게 성장하여 훗날 레이븐우드 가문과 결혼했습니다. 길네아가 다시는 바다를 두려워하지 않도록, 왕은 다나바르의 용맹함을 기리기 위해 검은 함대의 창설을 명했습니다.'),
(50594, '길네아스라는 새로운 왕국에 동이 트기 시작하자, 수많은 이야기와 노래가 고귀한 가라론을 기리기 위해 만들어졌습니다. 그는 불과 피를 통해 자신이 태어난 땅의 독립을 쟁취하는 데 성공했습니다.'),
(50595, '역사 기록에는 알드린이 반란군의 장군으로 언급되지만, 그의 진정한 모습에 대해서는 소문과 신화만이 전해져 내려온다. 전해지는 이야기에 따르면, 알드린은 늑대뱀 신화에 바쳐진 제물로 레이븐스우드에 버려진 불운한 아이들 중 하나였다. 온갖 역경과 운명을 딛고 살아남은 알드린은 그레이메인 가문의 귀족에게 입양되어 술잔 시종의 아들로 태어났다.'),
(50596, '자신의 본성에 배신당한 알드린은 양아버지의 임무를 이어받을 수 없었을 것이다. 그의 소명은 전투였고, 그 소명은 젊은 그레이메인을 설득하여 그를 개인 경호원으로 고용하게 만들었다. 그 후 두 십 대는 라이벌로서 강도 높은 전투 및 전략 훈련을 통해 유대감을 형성하게 되었다. 그 라이벌 관계는 서서히 형제애로 발전했다.'),
(50597, '가라레온이 자신의 영지를 다스리는 자리에 오르던 날, 그는 알드린을 자신의 기사로 임명했고, 훗날 아라토르 대제국을 무너뜨릴 반란군의 총사령관으로 삼았다. 가라레온이 왕국의 검이라면, 알드린은 방패였고, 가라레온이 재판관이라면, 알드린은 사형집행인이었다.'),
(50598, '세월이 흐르면서 그들의 우정은 더욱 깊어졌고, 가라론이 길네아 왕국을 건국했을 때, 알드린은 레이븐셔의 영주이자 레이븐우드 요새의 정당한 지도자로 임명되었습니다. 전략적으로 국경 지대에 위치하고 대양으로 둘러싸인 레이븐우드 요새에서, 알드린은 가문의 가장 고귀하고 명예로운 전통을 지켜나가기로 결심했습니다. 바로 모든 레이븐우드가 마지막 한 사람이 왕국을 지킬 때까지 왕국의 방패가 되어야 한다는 것이었습니다. 그리고 법을 어기는 자들은 왕의 명령을 거역하느니 차라리 자신의 날개를 자를 각오가 되어 있는 까마귀의 분노와 충성심에 직면해야 할 것입니다.'),
(50599, '가라레온의 마지막 생명이 꺼진 날, 알드린은 어린 왕자의 스승이자 멘토가 되었습니다. 그는 후계자가 아버지의 유산을 이어받을 준비를 갖추도록 도왔을 뿐만 아니라, 자신의 혈육을 어린 왕자의 제자로 삼고 자신의 모든 혈통이 그레이메인을 영원히 섬기겠다고 맹세하게 했습니다.'),
(50600, '이 두 가문 사이의 유대는 역사를 통해 더욱 굳건해질 것이다. 그레이메인은 언제나 길네아스의 왕좌에 서 있을 것이며, 레이븐우드는 언제나 그들의 곁을 지킬 것이다.'),
(50601, '수 세기 동안, 은빛소나무 숲의 울창한 숲은 길네아의 영광스러운 역사 속에서 끊임없는 분쟁의 대상이었습니다. 우리 나라는 달라란, 알터랙, 그리고 로데론의 탐욕스럽고 권력에 굶주린 자들로부터 이 땅을 지켜내야 했습니다. 한때 평화로웠던 이 땅을 보존하기 위한 우리의 고귀한 노력에도 불구하고, 이 야만적인 적들은 이곳을 거대한 무덤으로 바꿔놓았고, 그들의 끝없는 권력욕 때문에 수많은 용감한 길네아 여인들이 과부가 되었습니다.'),
(50602, '은빛소나무 숲은 아라토리아의 왕자 레나롤 1세가 우리에게 하사했고, 현명하고 정의로운 우리 왕 가랄론께서 이를 확정해 주셨기에, 정당하게 길네아의 땅입니다. 우리는 달라란의 저주받은 마법사들과 알터랙의 무자비한 야만인들의 수많은 공격으로부터 은빛소나무 숲을 지켜냈습니다. 모든 공격에 맞서 흔들림 없는 저항을 펼쳤고, 조상의 땅을 지키기 위해 언제나 굳건히 자리를 $B$B지켰습니다. 파라드 실버레인이 건설한 실버레인 요새는 이 땅을 묵묵히 지키는 파수꾼처럼, 감히 우리의 주권을 침범하려는 모든 적들로부터 이 땅을 보호하고 있습니다.'),
(50603, '은빛소나무 숲을 우리가 차지하는 데 가장 큰 위협은 바로 아라토리아 귀족들이 이전에 길네아스를 짓밟으려 했던 바로 그 자들이 세운 신생 왕국 로데론에서 비롯되었다. 이 탐욕스럽고 파렴치한 자들은 은빛소나무 숲의 풍요롭고 비옥한 땅을 차지하기 위해서라면 농민들의 피를 흘리는 것도 서슴지 않았다.'),
(50604, '뱀의 해에, 사악한 아르테리안 로르다놀 왕자가 이끄는 로르다리온 군대는 만 명이 넘는 중장보병, 사천 명의 기병, 그리고 이만 명의 경보병을 이끌고 은빛소나무 숲으로 국경을 넘었습니다. 그들은 가을까지 큰 저항 없이 진격했지만, 혹독한 겨울 날씨에 부딪혀 봄이 올 때까지 기다릴 수밖에 없었습니다.'),
(50605, '현명한 베렌 그레이메인 왕께서 기다려온 순간이었습니다. 우리 병력은 고작 2만 5천 명에 불과했지만, 혹독한 겨울 날씨에 익숙하지 않은 로데리오인들보다 훨씬 더 겨울 전투에 잘 대비되어 있었습니다.'),
(50606, '겨울이 맹위를 떨치자 길네아 군대가 공격해왔습니다. 우리는 로데론으로 향하는 보급로를 차단하여 적군 병사들을 굶주리게 하고 사기를 저하시켰습니다. 그들은 보급품을 구하기 위해 인근 마을과 도시를 습격할 수밖에 없었고, 본진에는 소수의 병력만 남게 되었습니다. 그러던 중, 일 년 중 가장 긴 밤, 초승달이 뜬 칠흑 같은 어둠 속에서 베렌 왕은 로데론 진영에 기습 공격을 감행했습니다.'),
(50607, '우리 병사들은 비할 데 없는 열정과 힘으로 싸웠고, 일부 목격자들은 베렌 왕이 직접 전투에서 어둠의 힘을 휘둘러 쓰러진 로데론 군대의 혈통을 조종했다고 주장했습니다. 결국 $B$B로데론 군대는 거의 전멸하거나 후퇴했고, 아르테리안 왕자는 포로로 잡혀 몸값을 요구받았습니다. 이는 길네아의 큰 승리였으며, 아르테리안의 석방을 위해 막대한 전쟁 배상금이 지불되었습니다. 그는 꼬리를 내리고 로데론으로 돌아갔고, 다시는 은빛소나무 숲에 발을 들여놓지 못할 것이라는 두려움에 사로잡혔습니다.'),
(50608, '비록 은빛소나무 숲을 로데론의 메네틸 가문에 빼앗겼지만, 길네아인들은 이 땅이 마땅히 우리에게 속한다는 믿음을 굳건히 지키고 있습니다. 우리는 사악한 메네틸 가문으로부터 은빛소나무 숲을 해방하고, 그 정당한 주인인 길네아인들에게 되돌려주기 위해 계속해서 노력할 것입니다.'),
(50609, '위대한 역사가들은 인간 왕국들 사이에서 이 사실을 비밀로 하고 싶어했지만, 레이븐우드 가계도에 실버레인 가문의 피가 섞여 있다는 것은 널리 알려진 사실이었다. 확실한 것은 은빛소나무 숲 숲이 길네아의 땅이었다는 것이다. 이 땅에서 벌어진 전투는 운명처럼 두 왕조를 하나로 묶어버렸다.'),
(50610, '전해지는 이야기에 따르면 은빛소나무 숲과 로데론 사이의 대규모 전투 중 하나에서, 실버레인 요새의 방어는 칼리반 1세 남작이 이끌었으며, 그는 마지막 피 한 방울까지 자신의 영지를 지켰다고 합니다. 캐스텐 레이븐우드 경이 전투 한복판에 도착했을 때는 이미 너무 늦었습니다. 칼리반은 이미 목숨을 잃은 후였습니다. 남작의 딸인 알니라 부인은 길네아를 위해 자신을 희생한 귀족에게 마지막 모욕을 주려는 로데론 군대로부터 그의 시신을 지키고 있었습니다.'),
(50611, '카스텐은 말을 타고 알니라를 에워싼 병사들을 향해 돌진했다. 그녀 바로 옆에 착지했을 때, 그는 여인이 생각만큼 무력하지 않다는 것을 깨달았다. 전투의 혼란 속에서도 그녀는 가장 가까이 있던 병사의 심장에 단검을 꽂아 넣었던 것이다. 그녀의 용기에 감탄한 카스텐은 부하들에게 공격을 명령했다. 로데론 군대는 속수무책이었고, 흔적도 없이 전멸당했다. 실버레인 성으로 $B$B돌아왔을 때, 승리의 함성은 들리지 않았고, 오직 칼리반의 죽음을 애도하는 침묵만이 감돌았다. 알니라는 아버지의 뒤를 이어 실버레인 성의 남작이자 은빛소나무 숲의 통치자가 되었다.'),
(50612, '카스텐은 성을 떠나지 않았다. 전투 중에 만난 젊은 여인에게 마음을 빼앗겼기 때문이다. 그는 왕에게 까마귀를 보내 알니라를 잠시 동안 통치자로 키워내겠다고 공언했다. 오랫동안 그는 그녀에게 구애했고, 결국 그녀는 그의 사랑에 빠졌다. 하지만 그녀는 결혼을 받아들이지 않았다.'),
(50613, '얼마 후, 카스텐은 무거운 마음으로 레이븐우드 요새로 돌아왔다. 알니라가 자신의 청혼을 받아들여 주기만 한다면 무엇이든 했을 테지만, 그녀의 속셈 또한 이해했다. 자신과 결혼하면 그녀는 실버레인 요새를 떠나 백성들을 버려야 한다는 것을 알고 있었기 때문이다.'),
(50614, '얼마 지나지 않아 로데론 군대가 두 번째 공격을 감행했습니다. 갑작스러운 침략 소식을 들은 카스텐은 서둘러 왕에게 달려가 알니라를 도울 수 있도록 허락해 달라고 간청했습니다. 왕은 카스텐이 왕국에 남아 알니라가 괜찮을 거라고 장담하려 했지만, 카스텐은 간절히 부탁했습니다. 그는 왕에게 알니라에 대한 사랑을 고백했고, 며칠 전 알니라가 임신했다는 소식을 전해왔다고 말했습니다. 왕은 카스텐과 그의 부하들이 떠날 수 있도록 허락했고, 로데론 군대는 궤멸되었습니다.'),
(50615, '전투가 끝난 후, 마지막 시도로 카스텐은 알니라에게 다시 한번 청혼했습니다. 감정에 북받친 알니라는 무릎을 꿇고 울기 시작했습니다. 두 사람은 미래에 대해 오랫동안 이야기를 나누었습니다. 결국 결혼하지 않기로 했고, 서로를 향한 사랑만으로도 충분하다고 생각했습니다. 몇 달 후, 알니라가 쌍둥이를 낳았습니다. 한 아이는 알니라와 함께 살며 실버레인의 가문을 잇고, 다른 아이는 아버지와 함께 살며 레이븐우드의 가문을 잇게 되었습니다.'),
(50616, '그들은 평생 다른 사람과 결혼하지 않았습니다. 그 때문에 당시 많은 사람들은 그들의 자녀를 사생아로 여겼습니다. 진실은 알니라가 카스텐보다 오래 살다가 세상을 떠난 후에야 밝혀졌습니다. 두 형제는 처음에는 적응하기 어려웠지만 시간이 지나면서 관계가 깊어졌고, 그 관계는 여러 세대에 걸쳐 이어졌습니다.'),
(50617, '제3차 전쟁 발발 전날 밤, 맑은 밤하늘 아래 겐 그레이메인 왕은 높은 테라스에서 자신의 왕국을 바라보고 있었다. 거대한 성벽 그림자 아래에서 차가운 바람을 타고 검은 까마귀 한 마리가 날아와 위풍당당한 왕 옆에 앉았다. 그리고 초록빛 섬광과 함께 그 모습은 후드를 쓴 남자의 형상으로 변했다.'),
(50618, '겐 왕은 마법사를 발코니에서 던져버리려던 찰나, 마법사가 허리를 굽혀 용서를 빌었다. 그는 자신의 이름을 밝히지 않고 예언과 경고만을 전했다. 그는 북방의 역병, 사나운 오크, 악마와 산 자들, 그리고 아주 오래된 악의 귀환에 대해 이야기했다. $B$B그는 왕에게 서쪽, 미지의 땅 칼림도르로 도망치라고 말했다.'),
(50619, '왕은 웃음으로 화답했다. "도망치는 것은 비겁한 짓이다." 그는 대답했다. "내 성벽을 보라. 돌의 견고함에 놀라지 말고, 성벽을 지키는 병사들을 보라. 길네아 사람들! 철처럼 단단하고 사자처럼 용감하다. 가서 그들에게 그들의 고향은 지킬 가치가 없다고 전하라. 아내들을 난민으로, 자식들을 거지로 만들라고 전하라. 가라! 거기서 길네아의 대답을 들을 수 있을 것이다!"'),
(50620, '예언자는 고개를 숙이고 왔던 길로 $B$B돌아갔다. 그러나 몇 달이 지나면서 그 낯선 이의 예언은 하나둘씩 현실이 되었다. 먼저 오크의 귀환, 그다음 역병의 도래. 아름다운 도시 스트라솔름이 불타 없어졌다는 소식이 퍼지자, 겐 왕은 결의를 다지고 모든 외부인의 출입을 막기 위해 성문을 닫았다.'),
(50621, '왕의 칙령에 항의하는 자들이 왕의 자문위원회에 있었다. 그중에서도 가장 강력한 반대자는 바로 왕세자 리암이었다. 그는 제이나 프라우드무어 여사가 로데론의 생존자들을 모아 서쪽 칼림도르로 항해하고 있다는 소식을 전했다. 그는 아버지에게 무방비 상태의 난민들을 호위할 의장대를 보내달라고 청원했다. 그러나 왕은 로데론 사람들이 옮길 수 있는 전염병이 길니아스로 다시 퍼질 위험이 있다는 이유로 거절했다.'),
(50622, '다른 선택의 여지가 없어진 리암 왕자는 아버지 몰래 길네아의 영주들에게 도움을 구하러 갔다. 그의 견해에 $B$B동의하는 사람은 거의 없었지만, 그중 다리우스 레이븐우드 경과 겔노르의 제롤드 경이 가장 영향력이 컸다. 레이븐우드 경은 비밀리에 함대를 준비했고, 제롤드 경은 약속된 명예 호위대로 자원할 용맹한 겔노르 드워프와 인간들을 모았다.'),
(50623, '그리하여 길네아 여단이 탄생했고, 리암 왕자는 길네아 해안에서 최고의 영예를 안겨주며 이 부대의 이름을 지어주었습니다. 겐 왕이 음모를 알아차렸을 때는 이미 배와 병사들, 그리고 보급품들은 지평선 너머로 멀리 떠나고 없었습니다. 왕세자를 포함한 모든 음모 가담자들은 가혹한 처벌을 받았지만, 전사들은 그럼에도 불구하고 제이나 프라우드무어의 휘하에 들어가게 되었습니다. 그들은 마지막까지 제이나에게 충성을 다했다고 전해집니다.'),
(50624, '참혹했던 세 망치 전쟁 이후, 와일드해머에 충성을 맹세했던 산악 드워프 부족들은 옛 고향인 그림 바톨, 칼바노스트, 던 키타스를 버리고 새로운 땅을 찾아 북부 왕국들을 떠돌아다녔습니다.'),
(50625, '대부분의 와일드해머족은 훗날 맹금의 봉우리가 될 지역에 정착했지만, 칼바노스트와 던 키타스의 드워프들은 동족과 헤어져 종종 인간 영토로 들어가며 계속해서 탐색을 이어갔다.'),
(50626, '그곳에서, 강력한 칼바노스트의 하늘 왕 모르그린은 로데론과 알터랙의 인간들을 상대로 전쟁을 벌여 그들의 재산을 약탈하여 자신의 영토를 $B$B회복했습니다. 반면, 더욱 아름다운 던 키타스의 하늘 왕 레도란은 그곳에서 멀리 서쪽으로 날아가 길네아의 도시 겔노르에 도착했습니다.'),
(50627, '레도란은 길네아인들에게 자신의 종족이 만든 많은 장신구를 선물했고, 길네아인들은 드워프 장인의 솜씨에 감탄하며 그것들을 $B$B소중히 여겼다. 레도란이 준 선물 중 가장 값진 것은 그레이메인 여왕 엘레나 선량왕에게 선물한 보석 박힌 미스릴 왕관이었다. 엘레나는 그 왕관에 너무나 매료되어 통치 기간 내내 왕관을 벗지 않았다.'),
(50628, '레도란과 그의 백성들이 떠날 준비를 할 때, 엘레나 여왕이 그들을 멈춰 세웠습니다. 엘레나 여왕은 길네아 백성들에게 베푼 그들의 관대함에 보답하기 위해 그들에게 겔노르에 거처를 마련해 주고, 레도란에게는 자신의 궁정에서 일할 자리를 선물했습니다. 드워프들은 기꺼이 이를 받아들였고, 레도란은 언제나 엘레나 여왕의 신뢰와 조언을 따랐습니다.'),
(50629, '2세기가 넘는 세월이 흐르면서 겔노르의 드워프와 인간은 서로의 풍습을 많이 $B$B받아들였습니다. 드워프들은 빛을 숭배하게 되었는데, 교회가 아닌 조각된 돌 동굴에서 의식을 치렀습니다. 인간들은 훌륭한 목공예가이자 그리핀 기수가 되었지만, 천둥망치보다는 긴 창을 더 선호했습니다. 오늘날까지도 $B$B드워프와 인간은 겔노르에서 하나의 길네아 혈족으로 살아가며, 세상이 멸망할 때까지 그들의 운명은 얽혀 있다고 전해집니다.'),
(50630, '구세주 교황은 길네아 땅을 걸었던 가장 거룩한 분이셨습니다. 그의 축복받은 설교를 통해 우리 나라에 구원을 가져다주셨고, 거룩한 빛으로 우리의 영혼을 밝혀주셨습니다. 우리의 맏형께서 거룩한 평안을 누리시기를, 그리고 가장 암울한 날들이 우리 도시를 덮칠 때, 그의 거룩한 기억이 고통받는 우리 마음에 위안을 가져다주기를 기도합니다.'),
(50631, '길네아 땅의 하늘이 어두워졌다. 다리우스 영주는 자신에게 충성하는 모든 하급 귀족들을 궁궐로 소집했다. 길네아 시에서 곧 방문이 있을 예정이었다.'),
(50632, '여왕 미아가 세상을 떠난 후 우리 땅에는 많은 것이 변했습니다. 알테라시 기생충들은 왕의 귀에 독을 뱉으며 레이븐우드 경이 배후에서 $B$B조종했다고 주장했습니다. 하지만 레이븐우드의 이름은 배신자들의 피로 씻겨졌습니다.'),
(50633, '"확실하십니까, 영주님? 할로우 가문이 정말로 이 악랄한 음모의 배후입니까?$B$B" "틀림없습니다, 칼리반. 그들은 악의를 품고 이 땅의 통치권을 빼앗으려 하고 있습니다. 젠의 상처받은 마음을 이용해 그의 정신을, 어쩌면 몸까지도 조종하려 들었을 겁니다. 그들이 왕에게 닥쳤다고 주장하는 병이 무엇인지는 알 수 없습니다." 잠시 침묵이 흐르고,$B$B 죽음과 맞닥뜨린 한 여인이 영주의 대연회장을 가득 채웠다. $B$B새로운 할로우 섭정 영주의 전령인 게인 윌로필드가 도착한 것이다.'),
(50634, '차가운 성문이 오만한 전령에게 열렸다. 그는 고개를 숙이지도, 인사를 건네지도 않고 영주의 자리 앞에서 비웃으며 말했다. "레이븐우드 성과 레이븐셔 영지의 영주이신 다리우스 레이븐우드 경께, 저는 리건 윌로필드입니다. 길니아의 새로운 통치자들로부터 온 전언을 전하러 왔습니다." "무슨 이유로 우리에게 이런 영광을 주었단 $B$B말인가, 영지도 없는 영주이자 명예도 없는 기사여?" 리건은 얼굴을 찌푸렸다.$B$B "레이븐우드, 당신은 의자에 앉아 얼마나 거만하게 보이는가. 하지만 내가 전하는 전언은 당신의 오만과 허영보다 훨씬 더 고귀한 것이다."'),
(50635, '궁정에서 경멸의 웅성거림이 퍼져나갔다.$B$B "알터랙의 더러운 놈들이 자네에게 무슨 전갈을 전하라고 시켰나, 오만한 $B$B리건?" "말을 조심해야겠소,$B$B 폐하." "내 주군을 모욕하는 말을 한 번이라도 더 한다면 이 칼로 자네 목을 베어버리겠소." 한 신하가 말했다. $B$B다리우스는 충성스러운 친구를 진정시키기 위해 손을 들었다. $B$B"내 부하의 오만함에 대해 사과하오. 충성과 우정이 우리를 묶어주고 있음을 자네도 잘 알겠소. 섭정 폐하의 은혜로운 말씀을 간절히 듣고 싶소."'),
(50636, '리건은 목을 가다듬으며 말했다. "전하께서는 작명식에 당신께서 불참하신 것에 대해 불만을 표하셨습니다. 그분들은 길네아의 방패와 평화롭게 지내기를 바라실 뿐이며, 이처럼 어려운 시기에 서로 적대해서는 안 된다고 주장하십니다." "그렇다면 내 영지 $B$B안에 있는 군대는 어떻게 되는 겁니까? 그들이 나를 섬기러 온 것 같지는 $B$B않은데요." "바로 그겁니다, 전하. 그들은 모티머 경께서 당신께서 따님과 결혼해 달라는 요청을 받아들이신다면 보내주시는 선물입니다.$B$B" 다리우스 경의 침묵에 리건의 혈관 속 피는 얼어붙었다.'),
(50637, '두 사람이 말을 꺼내기도 전에 로리온 자작이 다리우스 앞에 무릎을 꿇고 피 묻은 검을 건넸다. "이 검은 적군 사령관의 피로 물들었습니다." 다리우스는 로리온을 $B$B쳐다보며 물었다. "그럼 나머지는 어떻게 되었나?" $B$B"항복한 자들은 지하실로 끌려갔고, 나머지는 사슬에 묶여 피투성이가 될 때까지 매질을 당했습니다." $B$B레간은 몸을 떨며 말했다. "폐하, 이게 무슨 뜻입니까?"'),
(50638, '다리우스는 로리온의 손에서 검을 빼앗아 리건에게 겨누며 말했다. "저 옆구리에 있는 두 명과 성벽에 쇠사슬로 묶인 자들을 데려다가 교수형에 처해라. 리건, 네가 겸손한 태도로 내게 왔더라면 목숨을 살려주었겠지만, 맙소사. 로리온, 기둥 하나와 못 세 개, 망치를 구해와서 이 입만 나르는 자를 십자가에 못 박아라. 할로우 일족은 공포에 떨게 될 것이고, 심지어 빛조차도 내 분노에 떨게 될 것이다!"'),
(50639, '그리하여 제1차 반란이 시작되었다. 다리우스는 남은 병사들을 모두 모았다. 그의 통치 아래 있던 백성들은 그의 땅에 대한 사랑에 감명을 받으면서도 그의 잔혹함에 두려움을 느꼈다. 그러나 두려움 너머에는 존경심이 있었다. 그들은 절박한 상황에는 절박한 행동이 필요하다는 것을 알고 있었고, 지금도 알고 있다.'),
(50640, '정의로운 반란군은 전투에서 승리했지만, 그 대가는 너무나 컸다. 레이븐우드 요새는 파괴되었고, 그곳에서 죽은 자들은 모두 아군과 적군을 구분하지 못하게 되었다. 알테라시 할로우 악당들의 어둠의 마법에 걸려 복수심에 불타는 유령으로 변해버린 것이다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(50641, '레이븐우드 경과 할로우 가문 사이에 조약이 체결되었습니다. 다리우스는 자신의 딸 엘레나를 할로우 가문의 젊은 귀족과 결혼시키기로 했습니다. 엘레나는 다리우스가 때를 기다리며 불안정한 휴전을 맺을 수 있도록 자신을 희생했습니다. 하지만 그레이메인은 $B$B언제나 우리의 왕좌에 앉을 것입니다. 우리는 반드시 그렇게 할 것입니다. 성문은 무너질 것이고, 우리는 옛 동맹의 도움을 받을 것입니다. 우리는 결코 조국을 포기하지 않을 것입니다. $B$B이 땅에서 가장 큰 나무를 찾아보십시오. 그것이 바로 우리 위대한 민족의 위엄을 보여주는 것입니다.'),
(50642, '수십 년에 걸친 집중적인 연구를 통해, 일반적으로 혈마법이라고 알려진 것이 우리 세계에서 유래한 것이 아니라는 사실이 명백해졌습니다. 이 마법에 통달했다고 주장하는 자들은 본질적으로 오크족 흑마법사와 유사하며, 뒤틀린 황천에서 능력을 끌어내는 자들입니다.'),
(50643, '수많은 고난과 역경을 딛고 이룩한 마법의 근원을 밝히는 것이 바로 그 핵심 과제였다. 이 마법은 피라는 연료를 필요로 하며, 마법사들에게 차원 너머의 힘을 사용할 수 있게 해준다는 것은 분명했다. 하지만 이 "피의 차원"과의 연결 고리가 어떻게 형성되는지는 여전히 불분명했다.'),
(50644, '처음에 저는 구루바시 트롤과 그들의 블러드링커들의 관습을 깊이 파고들었지만, 그들의 방식은 제가 아는 것과는 달랐습니다. 그들의 마법은 이 피의 차원과는 관련이 없었고, 대부분의 트롤 마법처럼 그들의 피의 신으로부터 힘을 얻었기 때문입니다. 그래서 저는 이 연구 방향을 곧바로 포기했습니다.'),
(50645, '언제나처럼, 우리의 하이 엘프 동료들은 매우 귀중한 존재였습니다. 전설적인 대격변 이전 시대의 것으로 추정되는 그들의 고대 문서에는 (만약 그런 전설을 믿는다면) 마법사들이 보르겐도르라고 불리는 피의 차원에서 힘을 끌어내는 방식이 자세히 기록되어 있었습니다. 언급된 의식들은 제 임무와도 일치하는 듯했습니다. 엄청난 양의 피를 사용하는 의식은 시전자의 신체적 힘, 지능, 민첩성을 향상시킬 수 있었습니다. 하지만 문서에 따르면, 이러한 의식은 광기, 환각, 늑대 같은 괴물로의 변신 등 수많은 부작용을 동반했습니다.'),
(50646, '시간이 흐르면서 그들의 실험은 비극적인 결과를 초래했고, 그들이 풀어놓은 어둠의 에너지로 인해 그들의 몸과 마음은 뒤틀리고 타락했습니다. 살아남은 자들은 사냥당하고 고향에서 추방당했으며, 그들의 혈마법에 대한 지식은 세월 속에 사라졌습니다.'),
(50647, '내가 직접 조사를 해야 한다는 것이 분명해졌다. 의식에 필요한 피를 어떻게 얻었는지는 독자가 알 필요는 없지만, 무고한 사람들에게는 아무런 해를 끼치지 않았다는 점만은 알아두면 된다. <The book now describes Blood Magic rituals with detail.>'),
(50648, '이러한 행위는 반드시 근절되고 금지되어야 한다는 점을 강조하고 싶습니다. 제가 겪은 고통은 형언할 수 없었고, 얻은 이득은 미미했으며, 에메랄드 불꽃에 휩싸인 세상의 끔찍한 모습은 말할 것도 없습니다. 저는 미래 세대가 이러한 행위에 가담하지 않도록 경고하기 위해 이 지식을 기록했으며, 키린 토가 이 비밀을 영원히 지켜주기를 간절히 바랍니다.'),
(50649, '<일기장의 전반부는 지극히 평범하다. 한 젊은이가 성장하며 겪은 고뇌, 가족과 농장을 부양하는 일, 생계, 꿈과 포부, 싹트는 사랑, 좋아하는 음식, 애완동물과 말에 관한 이야기가 적혀 있다.>$B$B<그러다 갑자기 단정한 잉크 글씨가 훨씬 굵은 글씨로 바뀐다. 검고 번져 있으며, 마치 유령의 손가락으로 써 내려간 듯하다.>'),
(50650, '1일차.$B$B 그 아이는 순수함이 너무나 사랑스러웠다. 우리는 그 아이가 버드나무 아래에서 곤히 잠들도록 내버려 두었다. 우리 몸으로는 이제 더 이상 그 아이를 따뜻하게 해 줄 수 없었지만, 아이는 모닥불에 몸을 녹였다. 우리는 그 아이의 어린 숨결에 코가 벌렁거리는 $B$B모습을 지켜보았다. 그런데 우리는 어떻게 보답받았을까? 그 아이는 모닥불을 끄려고 발로 차 버렸다. 한여름의 뜨거운 열기 속에서 불길은 번져 내 버섯 고리들과 버드나무 껍질, 여린 풀잎들을 태워버렸다…'),
(50651, '4일째 $B$B우리는 슬퍼하며 애도의 노래를 불렀다. 그 버드나무는 나의 것이었으니, 그것은 나의 복수다. 나는 그의 냄새를 따라 그의 농장으로 돌아갔다. 나는 그 소년을 관찰했다. 그는 이미 모든 것을 잊은 듯했다. 나는 그에게 기억하게 만들 $B$B것이다. 밤에 나는 창문을 아주 조심스럽게 두드렸다. 세게 두드렸다. 나는 미소 지었다. 나는 장막 너머로 그에게 손을 흔들었다. 아, 그의 이마에 맺힌 땀! 아, 그의 눈에 담긴 두려움! 아, 그의 심장이 얼마나 힘겹게 뛰었는지!'),
(50652, '15일째.$B$B 그는 거의 잠을 자지 못했다. 나는 항상 그에게 내가 지켜보고 있다는 것을 상기시킨다. 문을 긁는 소리, 촛불의 깜빡임, 목덜미에 스치는 숨결, 안개 속의 두 눈. 그의 정신이 날이 갈수록 지치고, 혼미해지는 것을 느낄 수 있다.$B$B 그는 너무 피곤해서 서서 잠들어 버렸다. 나는 그의 마음속으로 들어가 그의 생각을 억누르고, 그의 희망을 짓밟았다. 그의 체온이 너무나도 기분 좋게 떨어졌다. 나는 앞으로 그의 꿈속으로 더 많이 들어가야겠다...'),
(50653, '32일째.$B$B 그의 부모님과 친구들은 뭔가 잘못됐다는 걸 알고 있어요. 저는 그에게 말하지 말라고 했죠. 만약 그가 말한다면, 저는 너무나 속상하고 화가 날 거예요. 그러면 저는 그가 가장 사랑하는 사람들에게까지 저주를 퍼뜨릴 수밖에 없을 테니까요. 그렇게 하고 싶지 않아요. 그의 부모님은 너무 연세가 많으셔서 춤 파트너로는 적합하지 않을 거예요. 그리고 그의 어린 연인은 제 취향이 아니고요. 오늘 $B$B그가 집으로 돌아오자 저는 보이지 않는 차가운 손가락으로 그의 금발 머리를 쓰다듬었어요. 아직 해 질 녘이 채 되지 않았는데, 제가 이렇게 일찍 그에게 나타난 건 처음이었죠. 그는 도망치지도 않았어요. 그는 자신의 운명을 받아들이고 있는 것 같아요.'),
(50654, '56일째.$B$B 그는 거의 죽어가고 있다. 소년은 눈 밑에 다크서클이 짙고, 머리카락은 희끗희끗하며, 말을 더듬고 감히 눈을 바닥 위로 들지 못한다. 그의 의지는 거의 꺾였다. 이제 나는 밤뿐 아니라 낮에도 그에게 속삭이기 시작했다. 우리와 함께해... 우리와 함께해... 그는 우리와 함께할 것이다. 그는 내 버드나무 $B$B주위에서 우리와 함께할 것이다. 그는 우리의 원 안으로 들어올 것이다. 그는 검은 왈츠를 출 것이다. 그는 우리와 영원히, 영원히, 영원히, 영원히, 영원히, 영원히, 영원히, 그리고... (이 문장은 50페이지에 걸쳐 반복된다.)$B$B<The same words are repeated for fifty pages.>'),
(50655, '엘드레탈라스는 부분적으로는 아즈샤라 여왕의 가장 귀중한 소유물과 비밀을 보관하기 위한 금고로 건설되었습니다. 지역 교육의 필요성이 곧 대두되었지만, 도시에는 이를 확립할 수 있는 정식 통치자가 없었습니다.'),
(50656, '그녀의 사촌인 토르텔드린은 그녀를 대신하여 도시를 다스리는 임무를 맡았고, 그러한 신성한 임무에 대한 보상으로 왕자라는 왕족 칭호를 받았다.'),
(50657, '토르텔드린 왕자는 지역 교육의 필요성을 인식하고 엘드레탈라스 인근 언덕에 모든 중요한 과목을 가르치는 아카데미 건설을 시작했습니다. 아카데미 자체는 수라마르 인근의 나르탈라스에 버금가는 위엄을 자랑했으며, 거대한 건물과 탑들은 설립자들의 화려함을 반영했습니다.'),
(50658, '아카데미는 \'고요의 땅\'이라는 뜻의 로나에탈라스라는 이름을 지었다. 이곳에는 영원의 샘과 연결된 힘의 원천과 수많은 고서가 소장된 거대한 도서관이 자리하게 되었다.'),
(50659, '엘드레탈라스의 인구가 증가함에 따라 젊은 귀족들은 로나에탈라스의 전당에서 마법을 배웠습니다. 이곳에서 교육받았다는 것은 명성과 명예의 상징이었습니다.'),
(50660, '로나에탈라스는 천년이 넘는 세월 동안 언덕에 자리 잡고 있었으며, 그 위엄은 멀리까지 알려져 있습니다. 제국의 가장 먼 곳까지도 여왕 폐하의 위대함을 보여주는 이 놀라운 장소들이 있습니다.'),
(50661, '수 세기 전, 최초의 타우렌 부족은 우리 종족처럼 자연의 야생적이고 길들여지지 않은 힘과 조화를 이루며 비옥한 멀탄 땅에 정착했습니다. 이 고귀한 존재들은 처음에는 세련되지 못했지만, 우리와 마찬가지로 자연에 대한 깊은 경외심을 가지고 있었습니다. 우리 드루이드들의 가르침은 그들에게 농업, 목축, 심지어 문자까지 전수해 주었습니다.$B$B 그들의 영적인 헌신은 자신들의 전통을 넘어 세나리우스와 엘룬에게까지 확장되었습니다. 그리하여 동맹이 맺어졌고, 이는 상호 성장과 번영을 촉진했습니다. 때때로 오해가 조화를 깨뜨리기도 했지만, 칼도레이와 타우렌은 평화롭게 공존했습니다.'),
(50662, '그러나 역사의 흐름은 모레룸(현재의 데솔레이스)에서 온 켄타우로스 부족의 도래로 운명적인 전환점을 맞이했습니다. 이 무자비한 세력은 타우렌족을 맹렬히 공격하여 그들의 풍요로운 평원을 빼앗고 황량한 불모지로 추방하려 했습니다. $B$B용감한 타우렌족은 압도적인 열세 속에서도 용맹하게 싸웠지만, 전세는 그들에게 불리하게 돌아섰습니다. 날이 갈수록 그들은 절망의 벼랑 끝으로 밀려났습니다.'),
(50663, '연대의 순간, 파수꾼 군대는 타우렌 동맹을 지키기 위해 나섰습니다. 하나로 뭉친 그들은 결연한 의지로 이 강력한 적에 맞설 준비를 했습니다. 하지만 $B$B안타깝게도 켄타우로스의 맹렬함은 파수꾼들을 완전히 허를 찔렀습니다. 빠르고 무자비한 켄타우로스의 개활지 전투 방식은 파수꾼들의 일반적인 매복과 게릴라 전술을 무력화시켰습니다. 수많은 용감한 자매들이 쓰러졌고, 그들의 희생은 영원히 애도될 것입니다.'),
(50664, '이 암울한 상황 속에서, 샨드리스 페더문은 무거운 마음으로 전략적 후퇴를 명령하는 어려운 결정을 내렸습니다. 파수꾼들은 익숙한 잿빛 골짜기의 품속으로 돌아와 재집결했고, 타우렌은 홀로 끔찍한 운명에 맞서 싸워야 $B$B했습니다. 결국 타우렌은 조상의 고향을 잃고 동쪽의 황량한 불모지를 떠돌게 되었으며, 영원히 그들의 추방의 저주를 안게 되었습니다.'),
(50665, '우리 공동 역사의 이 비극적인 장은 우리의 가장 깊은 수치심을 증명하며, 더 많은 생명을 잃을지도 모른다는 두려움에 사로잡혀 고귀한 동맹국들을 배신한 행위입니다. 우리는 비록 우리의 생존은 지켰을지 모르지만, 그 대가는 우리의 명예와 진실성이었습니까?'),
(50666, '성모님께서 행동에 나서실 준비를 마쳤습니다. 머지않아 우리의 굴욕적인 패배는 뒤집히고 필멸자들에게 복수할 것입니다. 당신도 이 일에 중요한 역할을 해야 합니다. 병력을 소집하십시오. 남쪽의 병력과 함께 엘프들을 공격하십시오. 당신의 양동 작전은 성모님의 계획에 매우 중요합니다. 주력 부대의 일부도 성문을 통해 당신에게 파견될 것입니다. 실패하지 마십시오. 실패의 대가가 무엇인지 당신은 잘 알고 있을 것입니다.'),
(50667, '이시덴 페레놀드의 탈출에 관한 소식은 엄격히 통제하고 유포하지 않도록 지시한다. 모티머와 셀리아 할로우가 그의 현재 상황을 전혀 알지 못하도록 해야 한다. 그들은 이시덴 페레놀드가 여전히 드라이록 구덩이에 수감되어 있다고 믿게 해야 한다. 하지만 우리의 $B$B첩보는 다른 이야기를 하고 있음을 알려야 한다. 우리는 이시덴의 탈출이 알터랙 출신의 충성파들에 의해 계획되었을 가능성이 높다고 의심한다. 그는 외딴 황량한 섬 톨 바라드에 은신처를 찾았을지도 모른다.'),
(50668, '이러한 상황 전개에 대응하여 이시덴 페레놀데의 행방을 조사하고 찾기 위해 수색대가 파견되었습니다. 유감스럽게도 수색대로부터 어떠한 연락이나 보고도 받지 못했으며, 그들의 상황은 여전히 ​​알려지지 않았습니다. 이 $B$B복잡한 사건들을 헤쳐나가는 과정에서, 우리는 이 민감한 정보를 다룰 때 최대한 신중하고 조심해야 한다는 점을 강조합니다. 의도치 않은 정보 유출은 광범위한 정치 지형과 우리 왕국의 안정에 심각한 악영향을 미칠 수 있습니다.$B$B 승인: $B$B마크 드라이록.'),
(50669, '내가 직접 눈으로 보지 않았더라면, 필멸의 인간들이 얼마나 나약한 존재인지 결코 이해하지 못했을 것이다. 아버지께서는 우리 형제에게 이 더러운 왕국을 지키라는 임무를 맡기셨다. 알터랙 왕국에서 영향력 있는 인물인 프레스토 경이 보낸 그레이메인 성채의 신하로서, 우리 형제는 재빨리 신임을 얻는 귀족의 반열에 올라 왕의 신하가 되었다. 그때부터 우리는 $B$B서서히 왕의 마음에 반란의 기운을 불어넣어, 왕과 백성 사이에 갈등을 조장하기 시작했다. 어리석은 인간들이여, 그들은 자신들의 행동이 얼마나 큰 무게를 짊어져야 할지 결코 알지 못했을 것이다.'),
(50670, '우리가 겐을 그의 가장 신뢰하는 사람에게 등을 돌리게 하고, 그 과정에서 그의 아내까지 죽인 후, 왕은 너무나 낙담하여 내가 손길 한 번과 다정한 말 한마디로 그를 내 손아귀에 넣을 수 있었다. 그 당시에는 반란 외에는 별다른 일이 없었다. 다만 우리가 소위 군주라는 자의 자식들을 감금하고 끔찍한 죽음을 맞이할 것이라고 거짓말을 한 적이 있었다. 그들은 어리석은 페레놀데 때문에 바다에서 실종되었는데, 겐이 그를 왕국에 들인 덕분이었다고 우리는 $B$B그에게 거짓말을 했다. 왕은 나에게 너무나 의존하게 되어 나는 그를 침실로 몰아넣었고, 길네아스는 나와 내 동생의 손에 맡겨졌다.'),
(50671, '아아, 우리는 목표를 달성했지만 아버지에게서는 아무 소식도 들려오지 않았다. 그는 어디에 있는 걸까? 우리는 목표를 완수했다. 나라를 장악하고 서서히 안에서부터 썩어 들어가게 만들었다. 그래서 우리는 기다리고 또 기다리고 또 기다렸다. 도시에 고립된 동안 많은 일들이 일어났다. 어리석은 내 동생은 인간들의 욕망에 탐닉하기 시작했고, 나는 우리의 왕을 감시하는 책임을 맡았다. 물론, 행복하게도 그를 미치게 만들어 우리의 통제하에 두는 것이었지만 말이다. 아버지가 계획을 포기했다고 확신한 모티머는 아버지가 돌아오든 말든 이 삶이 너무 좋다고 생각했고, 그래서 우리 둘 다 이곳에서 계속 살면서 이곳을 우리의 보금자리로 삼기로 했다.'),
(50672, '하지만 어느 순간, 우리는 여전히 지도력의 필요성을 느꼈습니다. 매일 왕께서 제게 지시와 지도를 구하시는 모습을 보면서, 스스로 결정을 내릴 생각이 전혀 없어 보였습니다. 그 순간, 저는 질투심에 사로잡혔습니다. 왕께서는 너무나 의존적이셨지만, 동시에 지도에 대한 갈망은 바로 제가 부족했던 부분이었습니다. 아버지께서는 왜 우리를 버리셨을까요? 어디서 더 나은 지도력을 찾을 수 있을까요? 어떻게 그런 것을 믿을 수 있을까요?'),
(50673, '하지만 운명은 나를 위해 모든 것을 결정지었다. 밤이 되자 그것은 으르렁거리며 방 안의 공기를 마치 이미 자기 것인 양 들이마셨다. 벽을 기어 다니는 끔찍한 괴물, 은빛소나무 숲 숲에서 온 늑대인간을 보자 그는 자신을 라이칸 신부라고 칭했다. 누더기 옷을 입고 진흙과 피로 뒤덮인 그는 피의 설교자이며, 자신의 세계와 우리 세계 사이의 장막을 뚫고 우리도 그가 가져다준 선물을 누릴 수 있게 되었다고 주장했다.'),
(50674, '탐욕의 씨앗과 광신적인 마법사 우르와 그의 자칭 제자 아루갈의 어리석은 행동, 즉 늑대인간을 아제로스로 소환한 자들의 짓으로 인해, 아버지 라이칸과 같은 끔찍한 존재가 우리 땅에 발을 들일 수 있게 되었습니다. 그는 우리에게 자신보다 먼저 아제로스에 들어온 늑대인간들은 단지 파수꾼일 뿐이며, 야만적이고 생각 없는 보병일 뿐이라고 말했습니다. 그들은 언젠가 이 땅이 정복을 통해 축복받을 만큼 가치 있는 곳이 될 것이라고 했습니다.'),
(50675, '처음에는 스스로를 프리코리치라고 칭하는 자는 차라리 만나지 않았으면 좋았을 존재였지만, 곧 그 존재가 지닌 엄청난 힘과 그와 동맹을 맺는 것이 나와 내 동생에게 얼마나 큰 이득이 될지 깨달았다. 그의 가르침을 통해 우리는 새로운 목적과 방향, 그리고 지침을 얻었다. 우리는 서서히 귀족, 경비병, 심지어 왕까지도 날것의 살과 피를 먹도록 타락시켜 그들을 이전보다 더 강하고 중독되게 만들었다. 사실, 이 인간들만큼 생존을 위해 극단적인 행동을 하는 필멸의 종족은 없을 것이다.'),
(50676, '인간들은 진정한 신념이 없다. 평민들을 가축처럼 취급하고, 납치해서 접시에 담아 내놓다니. 솔직히 말해서, 나는 내 업적에 자부심을 느꼈다. 여전히 왕좌에 앉기를 바라는 이 인간들이 사랑하는 왕을 궁지로 몰아넣었으니 말이다. 그들은 여전히 ​​그가 단지 병들었거나 우리, 모든 악의 근원에게 사로잡혔을 뿐이라고 희망을 품고 있다. 정작 자신은 그들을 배신했는데 말이다.'),
(50677, '지루한 삶을 뒤로하고 마침내 동맹의 대의를 위해 싸우기로 결심했다는 소식을 들었습니다. 당신이 석궁을 들고 스스로를 사냥꾼이라고 칭할 줄 누가 상상이나 했겠습니까? 제가 처음 여정을 시작했을 때가 떠오르는군요. 당신에게는 제대로 된 $B$B지도와 흔들림 없는 손길이 필요할 겁니다! 수도원 뒤편 마구간 옆에서 저를 찾을 수 있을 겁니다. 준비하십시오. $B$B용감한 요나.'),
(50678, '친구, 여기선 너무 길게 쓰지 않으려고 해. 졸마진이 레반투스크 마을에서 나를 보내 어린 녀석들에게 지옥 마법을 가르치라고 했어. 네가 이 글을 읽을 때까지 살아 있다면, 뒤틀린 황천의 의지를 손끝으로 소환할 재능이 있다는 뜻이지. 하지만 조심해, 친구. 지옥불은 $B$B일반 불보다 훨씬 더 뜨겁게 타오르거든! 나는 지금 동굴에서 쉬고 있는데, 그곳은 은신처라 불리는 곳이야. 이상한 증후군이라도 있는 듯한 흑마법사 한 명이 옆에 있는데, 자기가 무슨 선택받은 자라고 믿고 있어. 네가 그 녀석처럼 지루한 사람이 아니길 $B$B바랄 뿐이야. (나머지 페이지는 머리가 큰 오크를 상징하는 그림으로 덮여 있다.)'),
(50679, '$n, 자네가 무기를 다루는 솜씨를 보니, 가능성이 보이군.조금만 $B$B훈련시키면 자네를 훌륭한 전사로 만들 수 있을 걸세! 누가 알겠나, 어쩌면 나중에는 강력한 전사가 될지도 모르고, 아니면 아제로스 곳곳을 누비는 모험가가 될지도 모르지. 어떤 길이 되든, 돈만 충분히 주면 자네의 미래를 위한 든든한 발판을 마련해 줄 수 $B$B있네.집행관 기지, 전사 훈련관.'),
(50680, '$n러스트게이트 능선에 소문이 돌고 있소. 어떤 천재 마법사가 탄광을 휩쓸고 다녔다는 소문 $B$B말이오. 마법은 멋지긴 하지만, 다듬어지지 않은 능력으로는 돈을 벌 수 없소. 게다가 우리도 아마추어처럼 보일 뿐이지. 마법 실력을 갈고닦아 더 많은 돈을 벌고 싶다면, 러스트게이트 탑에 있는 나에게 연락하시오. 돈도 좀 챙겨오는 거 잊지 마시오! 마법사 $B$B훈련가, 위제트 아이스휘슬.'),
(50681, '$n, 탄광에서 들려오는 아름다운 굉음을 들었어. 네가 낸 소리인 줄 알았지. 다른 놈들은 형편없는 굉음만 내고 너무 지루했거든.$B$B다양한 기술과 사격법으로 더 큰 굉음을 내는 법을 배우고 싶지 않아? 이 주변 야생 동물들을 상대하는 데 도움이 될 만한 몇 가지 기술을 가르쳐 줄 수 있어. 누가 알아, 언젠가는 너만의 애완동물을 갖게 될지도 모르지! 언제든 연락 줘. 필요한 모든 걸 알려줄게.$B$B메이튼 붐라이플, 헌터 트레이너.'),
(50682, '$n, 탄광에서 허드렛일을 하는 특히 민첩한 고블린에 대한 소문이 돌고 있습니다. 제 생각에는 자네는 더 큰 운명을 $B$B타고난 것 같네.A 도적은 우리 고블린에게 딱 맞는 능력을 많이 갖고 있지. 우리의 교활함, 재빠른 손놀림, 그리고 도덕을 쉽게 무시하는 성향은 완벽한 자질이야. 돈 버는 새로운 비법을 몇 가지 배우고 싶다면 기꺼이 가르쳐주지. 물론 적절한 대가를 지불해야겠지만.$B$B 레이리 퀵텅, 도적 훈련가.'),
(50683, '$n, 그림자에는 묘한 매력이 있지 않습니까? 당신이 화살을 휘두르는 모습을 보니 장래가 유망해 보입니다!이 $B$B세상에서 겸손한 자가 가장 유리한 위치에 있습니다. 그 점을 잘 활용하면 눈 깜짝할 사이에 권력과 금이 당신의 품으로 들어올 겁니다. 흑마법사의 능력을 배우고자 하는 열망을 보여주세요. 제게 돈을 지불하면 악마술을 가르쳐 드리겠습니다.암리 $B$B데몬딜, 흑마법사 훈련가.'),
(50684, '와인은 진정한 마법사였습니다. 어두운 겉모습 아래에는 우리가 만난 가장 진실한 사람이 숨어 있었죠. 그가 없으니 마법사 채팅방은 예전 같지 않을 겁니다.'),
(50685, '갈리프레이를 길드에서 만나 게임에 대해 모든 것을 가르쳐주고 친구로 여길 수 있었던 것은 큰 영광이었습니다. 부디 영원한 백늑대를 타고 함께하길!'),
(50686, '태양샘의 소멸은 우리 모두에게 영향을 미쳤고, 그 영향은 사람마다 달랐습니다. 마법을 일상적으로 사용할 수 없게 되었죠. 안타깝게도 몇몇 이들은 상황의 심각성을 잘못 판단하여 굶주림에 사로잡혀 시들어 버렸습니다. 장래가 촉망되는 $B$B마법사 견습생인 당신에게도 앞으로 험난한 시간이 기다리고 있을 겁니다. 마법이 당신의 주된 힘의 원천인 만큼, 자신의 한계를 이해하고 절제하는 능력이 필수적입니다. 본관 지하에서 저를 찾아오십시오. 그곳에서 우리의 여정을 시작할 수 있습니다.'),
(50687, '빛이 너와 함께하길, 수련생이여. 나는 너와 같은 성기사, 로르타스다. 이 편지는 내가 아카데미에 왔다는 것을 알리고 너에게 조언과 훈련을 제공하기 위해 쓴다. 너도 알다시피, 우리는 피할 수 없는 새로운 상황에 처해 있다. 하지만 우리는 이 불가피한 상황의 도래를 늦출 $B$B수는 있다. 빛은 우리에게 수양과 구원을 제공하지만, 우리가 진정으로 추구하는 것은 속죄와 정의다. 그 찬란함 아래에서, 빛은 우리에게 오랫동안 묵혀둔 스컬지의 빚을 갚을 기회를 줄 것이다. 나는 본관 지하층에서 찾을 수 있을 것이다.'),
(50688, '태양의 축복이 $B$B함께하길. 또 한 분의 신앙인이 우리 대의에 합류하게 되어 기쁩니다. 우리 백성 중 많은 이들이 재앙의 공격 이전에도 빛을 받아들이기를 꺼려했습니다. 어떤 신자들은 조국을 잃은 후 신앙을 버리기도 했습니다. 하지만 가장 어두운 $B$B동굴 속에서도 빛의 작은 빛은 빛납니다. 그러므로 당신과 저는 우리 백성을 다시 신앙으로 인도하고 이 역경의 시기를 헤쳐나갈 수 있도록 돕는 임무를 맡았습니다. 태양샘은 사라졌지만 태양은 여전히 ​​밝게 빛나고 있습니다. 우리가 여기 있는 이유는 바로 지금 우리 백성에게 필요한 도움과 치유, 그리고 지원을 제공하기 위함이라는 것을 잊지 마십시오. 저의 지도나 조언을 구하시려면 본관 지하에서 저를 찾아주십시오.'),
(50689, '도둑, 악당, 무법자: 조국이 함락되기 전, 이 이름들이 당신을 규정했습니다. $B$B운명은 당신에게 미소 짓는 듯합니다. 더 큰 대의를 위해 기꺼이 헌신한다면 아무도 당신의 과거에 연연하지 않을 테니까요. 하지만 당신을 기억하는 저는 당신의 변화된 마음에 관심이 있습니다. $B$B두려워하지 마십시오. 제 분노는 가라앉았고, 저는 당신이 실버문의 가장 어두운 면을 견뎌낼 수 있을지에 관심이 있습니다. 저와 함께 이 어둠을 헤쳐나가십시오. 당신은 결코 부자가 되지는 못하겠지만, 다시는 굶주림에 시달리지 않을 $B$B것입니다. 저는 골든 레인저의 왼쪽에 있습니다.'),
(50690, '분노는 당신을 갉아먹지 않는 한 가장 강력한 무기가 될 수 있습니다. 우리가 겪은 손실에도 불구하고, 많은 이들이 절망에 굴복하여 의지를 다해 되찾고 복수하려 하지 않는다는 것을 모르십니까? 제 칼날은 $B$B가을 낙엽처럼 우아하고 균형 있게 휘몰아칩니다. 저와 함께 칼날을 단련한다면 당신의 칼날도 그렇게 될 것입니다. 분노를 도구로 여기십시오. 분노를 길들여 당신의 손에 쓰러지는 자들이 당신의 솜씨에 경외감을 느끼게 하십시오. 골든 레인저 왼쪽에 있는 작은 건물에서 기다리겠습니다.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(50691, '동료 레인저 훈련생이여, 반갑습니다. 당신의 당당한 태도와 우리 명예로운 형제들의 발자취를 따르려는 당신의 결의에 깊은 감명을 받았습니다. 쿠엘탈라스가 $B$B함락되기 전, 저는 파스트라이더 부대의 신병이었습니다. 파스트라이더는 우리 영토와 명예를 지키기 위해 국경 너머로 모험을 떠나는 숙련된 레인저 부대였습니다. 이 어려운 시기에 파스트라이더의 유산은 퇴색되었지만, 저는 우리가 함께라면 비록 점진적일지라도 그 유산을 되살릴 수 있다고 믿습니다. 저를 만나십시오. 브린틸리엔 외곽 어딘가에 있을 겁니다.'),
(50692, '이 편지의 내용을 모두 암기한 후에는 파기하십시오. $B$B무도회 준비는 완료되었습니다. 즉시 대표단을 알라탈라스로 보내십시오. 엘딘은 선택지가 아닙니다. 그는 이미 신원이 확인될 것입니다. 가장 신뢰하는 사람 중 한 명을 선택하여 이동 중에 눈을 $B$B가리도록 하십시오. 내일까지 기다리겠습니다. 만약 지연되거나 제시간에 알라탈라스에 도착하지 못할 경우, 제가 직접 연락하겠습니다. 좋은 결과가 있기를 $B$B바랍니다.'),
(50693, '죽음을 두려워하지 않고 용기를 보여준 쿠엘탈라스의 전사들에게 영원한 경의를 표합니다. 영원한 태양의 찬란한 품이 당신들의 여정을 인도하여 별들 사이로 당신들의 용맹이 울려 퍼지게 하기를 기원합니다. 시간의 흐름 속에 새겨진 당신들의 유산은 우리 마음속에 영원히 꺼지지 않는 불꽃으로 남아 있을 것입니다. 황혼의 품속에서, 우리는 쿠엘탈라스의 전사들이 보여준 불굴의 정신과 희생을 영원히 기억할 것을 선언합니다.'),
(50694, '우리는 전우들의 희생으로 하나 된 고향에 있습니다. 가장 암울한 날에도 이 $B$B도시를 우리의 안식처로 삼을 수 있기를 바랍니다. 어둠 속에서 우리의 등불이 되어 언제나 우리가 돌아올 수 있는 곳이 되어주기를 바랍니다. 우리 와일드해머는 $B$B그림 바톨을 영원히 우리의 조상의 고향으로 기억할 것입니다.'),
(50695, '어떤 상황에서도 임무에 대해 누구에게도 말해서는 안 된다. 이 일은 투자개발회사 요원들이 직접 내린 기밀 임무다. 이 단순한 임무에 실패한다면 언더마인으로 돌아올 생각도 하지 마라. 반역죄로 그 자리에서 처형될 것이다. 듀로타 노동조합을 무너뜨리려는 우리의 계획에 협조하는 것이 네 신상에 좋을 것이다. - X'),
(50696, '죽음의 고개의 공기는 거칠고 냉혹하다. 오크 침공 전의 이곳을 기억한다. 울창하고 푸르렀으며, 그랜드 햄릿에서 불어오는 기분 좋은 바람이 지나던 곳이었다. 하지만 이제 그런 모습은 아무것도 남지 않았다. 내 스승과 그의 죄가 남긴 파괴의 흔적뿐이다.'),
(50697, '6인 의회는 로서가 카라잔을 공격하던 혼란 속에 남겨진 위험한 유물들을 회수하는 일을 도와 달라고 요청했다. 좋은 기억과 나쁜 기억이 뒤엉킨 이곳으로 돌아오는 것은 내키지 않는다. 과거를 되새기는 일은 마음을 아프게 하고, 늙은 몸은 여정의 고단함에 신음한다. 그래도 반돌이 함께라 다행이다. 그 역시 이곳으로 돌아오고 싶어 하지는 않지만. 안토니다스는 내가 회수한 유물의 보관을 그에게 맡겼다. 나도 할 수 있는 일이지만 대마법사의 판단을 믿는다.'),
(50698, '붙잡힌 영혼들이 텅 빈 복도를 떠돈다. 낯익은 이도, 모르는 이도 있다. 성주 모로스의 목소리도 희미하게 들은 듯하지만 모습은 보이지 않았다. 스승 밑에서 엄격하게 수련하던 시절, 그의 유머는 한 줄기 햇살 같았다. 언젠가 그의 영혼도 안식을 찾을 수 있기를.'),
(50699, '상층부는 잠겨 있었지만 다행히 아직 열쇠를 가지고 있다. 분위기가 다르다. 훨씬 적대적이다. 남겨진 공포에 기습당하지 않도록 조심해서 나아가야 한다.'),
(50700, '스승의 도서관은 대부분 멀쩡히 남아 있다. 카라잔이 황폐해졌는데도 이렇게 보존된 것이 놀랍다. 언젠가 시간과 키린 토 동료 마법사 몇 명을 데려올 수 있다면, 이 지식을 달라란으로 옮기는 것은 의회와 학생들에게 큰 도움이 될 것이다.'),
(50701, '묵직한 고서들 사이에서 수수께끼 같은 장치를 발견했다. 아케이나이트로 만들어졌고 강력한 수호 마법이 걸려 있으며 상태도 완벽하다. 스승에게 중요한 물건이었다는 데 의심의 여지가 없다. 마음이 그렇게 말한다. 생김새로 보아 보석을 고정하는 일종의 걸쇠인 듯하다.'),
(50702, '메디브의 유물을 몇 점 더 수집했다. 이곳에는 여전히 저주가 깃들어 있으니 무사히 빠져나가려면 서둘러야 한다. 반돌은 밖에 숨어 나를 기다리고 있고, 우리는 안전하게 달라란으로 돌아갈 것이다. 그 모든 일이 벌어진 뒤에도 스승의 가까운 친구였던 사람과 함께 여행한다는 것은 묘한 일이다. 그래도 서로의 처지를 이해하기에 함께하는 것이 위안이 된다.'),
(50703, '또 다른 존재가 가까이 있다. 적대적이다. 잠시 그 기운이 스승과 똑같이 느껴졌지만 곧 달라졌다. 애초에 그럴 리도 없었겠지만. 지나간 시대의 기운이라고 해야 할까. 어쨌든 돌아가는 길에도 경계를 늦추지 않겠다-$B$B<일지는 여기서 갑자기 끝납니다. 다행히도 이것이 카드가의 마지막이 아니었다는 사실은 알고 있습니다.>'),
(50704, '12일째$B$B로데론에서의 패배는 참혹했지만 굴단의 배신만큼은 아니었다. 그의 병력이 함께했다면 도시를 잿더미로 만들고 승리했을 것이다! 하지만 나 자신을 속이는 것뿐이다. 굴단은 호드에 대한 맹세를 지킬 자가 아니었고, 둠해머는 그를 믿은 바보였다.'),
(50705, '15일째$B$B돼지 같은 인간들이 우리를 수용소에 몰아넣고 있다. 저들의 원시적인 말은 알아들을 수 없지만 듣기만 해도 역겹다. 진짜 돼지처럼 배를 갈라 버리고 싶다.'),
(50706, '20일째$B$B이 \'수용소\'에서의 삶은 비참하다. 도살을 기다리는 가축이 된 기분이다. 많은 형제들도 같은 생각이며 저들에게 맞서 싸우고 싶어 한다.'),
(50707, '22일째$B$B봉기가 있었다. 드레그가 뜻을 함께하는 오크들을 모아 사슬을 끊고 탈출하려 했다. 몇 시간이 지났고 이제 그의 시체에서 악취가 나기 시작한다. 뜨거운 햇볕도 상황을 더 낫게 해 주지는 않는다.'),
(50708, '26일째$B$B날이 갈수록 새로운 오크들이 들어온다. 오늘은 젊은 오크 하나가 찾아왔다. 간수들의 애완견 같은 녀석이다. 인간의 말을 알아듣는다는 점은 쓸모가 있을지도 모른다.'),
(50709, '33일째$B$B지쳐 간다. 드레노어를 떠난 뒤 이렇게 약하고 무기력했던 적은 없다. 영광스러운 전사로 죽을 수 있다는 흥분과 위험이 사라지니 삶이 완전하지 않은 듯하다. 지금 네 곁에 있을 수 있다면 좋으련만, 멜라르. 인간들의 수도에서 명예로운 전사의 죽음을 맞는 네 모습을 보았을 때 얼마나 가슴이 뛰었던지.'),
(50710, '34일째$B$B계속 네 생각이 난다, 나의 반려자여. 놈들 열 명을 함께 끌고 협곡 아래로 굴러떨어지고, 그 괴물이 마침내 너를 쓰러뜨리던 모습이라니. 장관이었다. 하지만 이제 승리와 명예를 외치는 네 목소리를 들을 수 없다는 사실이 마음에 큰 구멍을 남긴다. 스톰윈드에서 얻은 전리품 중 반짝이는 목걸이를 네게 건네던 날, 네가 특별한 존재라는 걸 알았다. 네가 희생자들의 뼈를 계속 목에 걸고 다니긴 했지만, 그 선물을 받아 준 것이 나는 여전히 기뻤다.'),
(50711, '38일째$B$B둠해머가 왔다. 부서진 동족인 우리를 바라보았다. 그의 얼굴에는 혐오가 떠올랐고, 나도 같은 감정이다. 더는 오래 버티지 못할 것 같다. 아니, 애초에 버티고 싶은지도 모르겠다.'),
(50712, '<나머지 일지는 점점 깊어지는 무기력함을 기록하다가 갑자기 끝납니다.>'),
(50713, '파도가 내게 속삭인다. 줄다자르에서 배를 띄운 뒤로 마음이 편치 않다. 그분이 나를 부른다. 우상을 돌려놓으라고 하신다, 친구. 다시 깊은 곳에서 그분을 끌어내야 한다. 우상은 반드시 복원되어야 한다.'),
(50714, '우리 여정도 곧 끝난다. 가시덤불의 요잠바 섬에 정착할 예정이다. 로아 학카르, 혈신이자 얼굴 없는 자가 균형을 깨뜨리고 모든 트롤을 위협하고 있다. 라스타칸께서 남은 아탈라이를 아제로스에서 완전히 쓸어 버리라고 우리를 보내셨다.'),
(50715, '위대한 클라코라의 우상 윗부분과 아랫부분이 어디 있는지 나는 안다. 신성한 존재, 위대한 심연의 로아! 그분께 걸맞은 제물을 바치면 나를 은총으로 뒤덮어 주실 것이다! 나는 그분의 화신으로 올라서 예언자 줄보다도 더 강해질 것이다!'),
(50716, '내일 첫 포로를 심문한다. 내가 자원했다. 그놈이 켈렘보에 대해 알고 있기를 바란다. 반드시 정보를 뽑아내겠다.'),
(50717, '알고 있었다! 그놈이 알고 있었다! 켈렘보는 줄구룹으로 도망쳤지만 겁쟁이의 벌로 히드라 가즈란카에게 잡아먹혔다!'),
(50718, '켈렘보, 미준타, 간테. 이제 우상 조각이 있는 곳을 전부 안다. 어리석은 트롤들, 심연의 집게발의 분노를 사고도 그 강대한 발톱에서 안전하다고 생각하다니. 줄구룹의 혼란이 가라앉으면 켈렘보의 조각을 가져오겠다. 하지만 다른 둘은...'),
(50719, '미준타는 아주 북쪽으로 달아나 드라카리에게 숨으려 했다. 한심하군. 깊은 곳의 속삭임에 따르면 그녀는 목적지에 닿기도 전에 얼음 섬에서 죽었다. 간테는 파라키에게 가서 그들의 족장에게 존경받는 자가 되었다. 타나리스 동쪽의 섬에 자리 잡았다니 우상 조각도 그곳에 있을 것이다.'),
(50720, '느껴진다! 로아의 힘이 나를 부른다. 그 유혹이 나를 깊은 곳으로 끌어당긴다. 거기서 그분의 우상을 찾게 될 것이다. 오, 클라코라여! 전능한 로아여, 당신이 보여 주신 그대로 당신께 걸맞은 제단을 세우겠습니다! 저주받은 여왕의 이름을 딴 땅의 해안에! 당신의 광휘는 그녀보다 훨씬 찬란합니다! 오만한 왕 라스타칸보다도 위대합니다!!!'),
(50721, '<문서는 낡고 반쯤 소화된 흔적이 있으며, 한 장에 수많은 글이 빼곡합니다. 위쪽에는 피 묻은 지문 같은 것이 남아 있습니다.>'),
(50722, '*개구리를 조심할 것!'),
(50723, '나는 \'보르겐도르\'라 불리는, 어둠 너머 먼 곳에 자리한 피의 세계에 감춰진 수수께끼를 풀기 위해 학문적 생애를 바쳤다. 그 탐구는 나를 지식의 어두운 회랑으로 이끌었고, 그곳에서 나는 종종 혈마법의 달콤한 속삭임에 사로잡힐 뻔했다. 하지만 굳은 의지로 그 유혹을 물리쳤고, 이제 겸손한 기록자로서 보르겐도르와 그 고대 신화의 이야기를 밝히고자 한다.'),
(50724, '위험으로 가득한 보르겐도르에는 끝없는 피의 갈증에 사로잡힌 늑대 인간들이 살고 있다. 그 사회에서는 혈마법이 절대적인 힘이며, 적을 파괴하고 약자를 굴복시키는 무기로 쓰인다. 이 어두운 마법은 그들의 문화를 좀먹는 재앙이지만, 세계를 집어삼키려는 사악한 \'에메랄드 불꽃\'에 맞서기 위해 절박하게 받아들인 힘이기도 하다.'),
(50725, '눈치 빠른 독자라면 \'에메랄드 불꽃\'이라는 말이 어딘가 익숙할 것이다. 그렇다. 이 사악한 세력은 과거 오크들을 우리 세계로 이끈 수수께끼의 힘, 바로 불타는 군단이다. 보르겐도르의 늑대 인간들은 수년간 군단과 끝없는 전쟁을 벌여 왔으며, 적과 다를 바 없는 어둠의 마법에까지 의지하고 있음에도 서서히 패배하고 있다.'),
(50726, '나의 연구 목적은 현재 늑대 인간 사회를 지배하는 혈마법만 알아내는 데 있지 않았다. 에메랄드 불꽃의 재앙이 닥치기 전 그들이 누구였는지, 그 기원을 알고 싶었다. 고대 두루마리에서 건져 올린 얼마 안 되는 정보와 잠을 괴롭힌 환영을 통해, 아주 오래전 늑대 인간들은 옛 엘프들처럼 달을 숭배했다는 사실을 알게 되었다.'),
(50727, '그들은 한때 하늘을 가로지르던 푸른 달을 신성한 여신으로 숭배하고 사랑했다고 전한다. 이 천상의 유대는 내 호기심을 자극했다. 아제로스에서도 가장 위태로운 시대에 모습을 드러내는 푸른 달과 놀랄 만큼 닮았기 때문이다. 보르겐도르의 푸른 달과 우리의 달이 같은 존재일 수 있을까?$B$B목숨과 정신을 걸고 보르겐도르 깊숙이 들어가 그들의 하늘을 직접 보았다. 하지만 내 눈앞에 떠오른 것은 평온한 푸른 달이 아니라, 세계 전체를 진홍빛으로 물들이는 피처럼 붉은 달이었다.'),
(50728, '그러나 희망이 완전히 사라진 것은 아니었다. 운 좋게도 그들의 혈법사 한 명과 대화를 나눌 수 있었다. 그 만남의 자세한 내용은 악의 손에 들어가서는 안 되기에 비밀로 남겨 두겠다. 다만 한 가지는 확실하다. 나는 그들의 달의 여신이 돌아와 구원을 가져온다는 예언을 들었다. 푸른 달이 다시 나타나 에메랄드 불꽃의 손길이 닿지 않은 새로운 세계로 향하는 문을 열고, 늑대 인간들이 그곳에서 새 삶을 시작하게 된다는 예언이었다.'),
(50729, '그들은 푸른 달이 자신들을 그 안식처로 인도할 것이라 믿었다. 그리고 나는 불길한 가능성을 생각하지 않을 수 없었다. 그 길의 끝이 우리의 세계라면? 그러니 푸른 아이를 경계하라. 그것은 늑대 인간이 우리 세계에 도래한다는 징조일 수 있다. 고통받는 종족에게 한때 희망의 등불이었던 천상의 징조가 이제는 우리 운명 위에 그림자를 드리운다. 예언이 실현되어 두 세계 사이의 문이 찢겨 열린다면, 우리는 그들의 도착에 대비해야 한다.'),
(50730, '이 글을 쓰는 지금 깃펜이 떨린다. 두려움 때문이 아니라 책임의 무게 때문이다. 금지된 고서, 비전의 속삭임, 마법 그 자체가 보여 준 환영을 거쳐 어렵게 얻은 이 지식은 어둠에 맞설 이들을 비추는 등불이 되어야 한다.'),
(50731, '늑대 인간들은 에메랄드 불꽃과의 전쟁에 몰려 절망적인 선택을 했지만, 그 안에는 파괴뿐 아니라 구원의 가능성도 남아 있음을 기억하라. 한때 숭배하던 달의 부드러운 빛 아래 살던 사회는 이제 혈마법의 그림자에 잠겨 있다. 그러나 예언은 재탄생을 말한다. 늑대 인간만이 아니라 어쩌면 우리 세계에도 구원이 될 수 있는 기회다.'),
(50732, '이 책을 덮으며 독자에게 간청한다. 낡은 페이지에 담긴 교훈을 마음에 새겨라. 보르겐도르의 이야기는 이세계 존재와 비전의 수수께끼를 기록한 단순한 연대기가 아니다. 이것은 경고다. 밤하늘을 바라볼 때 우리의 운명에 다른 세계가 손을 뻗을 가능성을 잊지 말라. 우주는 광대하고 그 비밀은 셀 수 없이 많으니 우리는 늘 경계해야 한다.'),
(50733, '이제 깃펜을 내려놓는다. 내 평생의 연구가 이 책의 양피지에 새겨졌다. 어둠 너머로 떠난 이 여정은 우리 세계와 다른 세계 사이를 가르는 장막이 얼마나 얇은지 보여 주었다. 그 너머에는 장엄하면서도 끔찍한 존재들이 넘쳐 난다. 푸른 아이를 경계하라. 그 빛은 새로운 시대의 새벽을 알릴 수도, 우리 시대의 황혼을 알릴 수도 있다.$B$B영원한 지식의 탐구와 엄숙한 경고를 담아,$B$B어둠 너머의 연대기 작가, 잊힌 지식의 수호자 우르.'),
(80150, '이봐 친구! 언더마인에 사는 그리지야. 나 기억나?\r\n\r\n네가 그 무기를 휘두르며 널 괴롭히려던 녀석들을 혼내주는 걸 봤다고 알려주려고 이 편지를 쓰는 거야. 우리가 꼬맹이였던 시절, 네가 날 호브고블린에게서 구해줬던 옛날 생각이 나더라!\r\n\r\n네 덕분에 열심히 훈련해서 훌륭한 싸움꾼이 됐고, 이제는 다른 고블린들에게 싸우는 법을 가르치고 있지. 나중에 놀러 와서 네가 휘두르는 그 무기를 어떻게 쓰는지 좀 가르쳐 줄게. 돈 지갑 꼭 챙겨 와!'),
(80151, '도둑놈! 파렴치한 놈! 노움의 자식!\r\n\r\n네가 여기 근처에서 어슬렁거린다는 소문 못 $N들었어, . 레이티 퀵텅과 같은 작전에 감히 얼굴을 내밀다니, 정말 뻔뻔하군.\r\n\r\n내 계획을 훔쳐갔잖아! 아제로스 이쪽에서 가장 큰 강도 사건이었는데! 난 엄청난 부자가 되어 흔적도 없이 사라질 수 있었는데!\r\n\r\n네가 일을 망쳐서 모든 걸 망쳐버렸지. 결국 잡혔으니, 투자개발회사에서 일하는 건 네 의지가 아니었겠지.\r\n\r\n어쨌든, 무너진 동굴로 와서 내게 빚진 돈을 돌려줘! 진짜 도적에게서 한두 가지 배울 게 있을지도 모르지.'),
(80152, '에:$N\r\n\r\n저는 메이튼 붐라이플입니다. 이 지역의 사냥꾼이죠. 믿기 어려우시겠지만, 원래는 헤멧 네싱워리와 함께 가시덤불 골짜기 베일에서 사냥을 할 예정이었습니다. 하지만 투자개발회사에 진 빚 때문에 이 험악한 곳으로 끌려오게 되었죠.\r\n\r\n여기서는 독수리나 까마귀밖에 사냥할 게 없지만, 그렇다고 해서 명사수가 되지 말라는 법은 없습니다. 아까 당신이 사격 자세를 취하는 걸 봤는데, 저와 함께 훈련하면 실력이 늘 것 같더군요. 단 몇 코인만 내면 진짜 명사수가 될 수 있습니다.'),
(80153, '안녕,$N ! 내 이름은 위젯 아이스휘슬이야.\r\n\r\n듣자하니 너도 나처럼 머리가 좋고 마법에 소질이 있다고 하더군. 어느 날 뭔가를 폭파시키고 싶다는 소원을 너무 간절히 빌다가 손에 불이 붙었다는 얘기도 들었어! 맞지?\r\n\r\n생각만 열심히 하면 뭐든지 할 수 있다는 게 참 신기하지. 예를 들어 이 멍청이들이 모여 있는 이 건물이 갑자기 불타오르는 것처럼 말이야. 이 끔찍한 곳은 정말 최악이야.\r\n\r\n나한테 놀러 와. 같이 마법 얘기 좀 하자! 너한테 새로운 주문 몇 개 가르쳐주면 이 건물이 불타는 생각을 잊을 수 있을 것 같아.\r\n\r\n아, 그리고 돈 좀 챙겨 와!'),
(80154, '안녕,$N . 나는 암리 데몬딜, 뛰어난 흑마술사다.\r\n\r\n처음 네가 다른 하찮은 자들과 함께 일하는 모습을 봤을 때, 나와 비슷한 기운을 느꼈지. 악마를 소환하고 지옥불을 다루는 데 필요한 재능을 갖췄다고 생각하는데!\r\n\r\n흥미롭군. 네 실력이 어느 정도인지 직접 보고 싶어. 내 동굴로 와서 한번 해보자.'),
(80226, '안녕, !\r\n$N\r\n내 이름은 루비나 선스원이다! 자네의 활약을 흥미롭게 지켜봐 왔네. 자네는 훌륭한 레인저지만, 고향을 잃은 슬픔 때문에 훈련이 완전히 끝나지 않았군.\r\n\r\n20년 전, 제2차 전쟁 당시 파스트라이더들은 우리 고향에서 가져온 씨앗 하나를 로지 밖에 심었네. 이제 그 나무는 단순한 상징을 넘어, 언젠가 우리 고향을 되찾을 수 있을 거라는 희망을 품고 있지.\r\n\r\n우리 민족을 어디에 살든 지키는 것은 모든 레인저의 의무야.\r\n\r\n내가 자네의 훈련을 이어갈 수 있도록 도와주겠네. 준비가 되면 로지 안으로 들어와.'),
(80227, '발라 대시, $N. 선블러드 가문의 마지스터 알라쇼르가 당신을 부르는 영광을 누리게 되었습니다. $B$B저는 당신이 일반 난민보다 조금 나은 수준의 마법 실력을 갖고 있다는 것을 알고 있습니다. 요즘 마지스테리움은 예전의 모습을 잃어버렸습니다. 쿠엘탈라스의 마지스터로서 저는 이런 상황을 더 이상 두고 볼 수 $B$B없습니다.조국에 무슨 일이 일어났든 간에, 저와 마지스테리움의 의무는 결코 멈추지 않았습니다.제게 $B$B오십시오. 그러면 당신을 제 제자로 삼겠습니다. 제 훈련을 견뎌낼 수 있다면, 당신은 유능한 마법사가 될 것입니다. 재건된 마지스테리움에 걸맞은 마법사로 말입니다.$B$B로지 안에서 저를 찾으십시오.')
INSERT INTO `locales_page_text` (`entry`, `Text_loc1`) VALUES
(80228, '$N, 나는 성스러운 로르타스라 불린다. 한때 은빛 손 기사단의 일원이었다.$B$B기사단과 로데론 왕국이 몰락하기 전, 나는 어둠을 몰아내는 용감한 빛의 종복, 성기사로 알려져 있었다. 자네의 길은 나와 비슷한 길을 걷고 있네. 자네는 빛의 의지와 뛰어난 무술 실력을 겸비하고 있군.은빛 손 기사단의 은신처로 $B$B찾아오시오. 내가 가진 모든 것을 다해 자네를 훈련시켜 주겠네.'),
(80229, '빛이 함께하기를, $N.$B$B나는 마엘라 선스원입니다.$B$B한때 쿠엘탈라스의 사원에서 성직자로 서품받아 태양의 빛을 설파하는 법을 배웠습니다. 대사제 벨로비르와 같은 전당을 거닐기도 했지요.$B$B하지만 이제 사원은 폐허가 되었고 태양의 온기마저 버림받았으니, 그 시절이 사라졌다는 사실이 몹시 슬픕니다.$B$B당신 안에서 헌신과 신앙의 불꽃을 보았습니다.$B$B오두막으로 와서 나와 이야기하십시오. 기꺼이 당신의 길을 인도하겠습니다. 언젠가 우리 백성이 빛뿐 아니라 우리의 미래에 대한 믿음까지 되찾을 수 있도록 말입니다.'),
(80230, '안녕,$N . 자네가 유용한 인재일 것 같아 편지를 쓰네.\r\n\r\n여기 있는 사람들은 모두 명예, 청렴, 태양 같은 허황된 소리를 늘어놓겠지만, 난 그렇지 않아. 우리 부족을 안전하게 지키려면 강경한 방법이 필요하다는 걸 알고 있지.\r\n\r\n우리 부족에게는 그림자 속에서 은밀히 정보를 수집하고, 보고하고, 심지어 위협을 사전에 차단할 수 있는 사람이 필요해. 자네에게서 내가 추구하는 질서에 대한 소질을 느꼈네.\r\n\r\n날 찾아오게 해 주면 그만한 가치를 느끼게 해 줄게. 로지 안에서 기다리게.'),
(80231, '반갑습니다,$N !\r\n\r\n저는 탈라시안 군대의 검사, 발라노스 던파이어입니다.\r\n\r\n쿠엘탈라스가 함락된 후, 제 임무는 남은 땅과 유산, 그리고 어디에 있든 우리 백성을 지키는 것입니다.\r\n\r\n그 임무에는 우리의 대의를 수호할 새로운 전사들을 훈련시키는 것도 포함됩니다.\r\n\r\n, 저를 $N찾아오십시오. 제가 당신의 미숙한 몸을 하이 엘프를 지킬 수 있는 전사로 단련시켜 드리겠습니다!'),
(80300, '가즈토글이 아즈샤라에서 전하는 보고서입니다!\r\n\r\n업무에 차질이 생겼습니다. 제 조수 프릭스가 맡은 일을 거의 다 망쳐놓았고, 심지어 우리가 받은 측량 장비까지 잃어버릴 뻔했습니다.\r\n\r\n프릭스는 사티로스들에게 죽임을 당했고, 측량 장비는 다행히 그들의 손에서 되찾았습니다. 이제 하루빨리 제게 필요한 새 조수를 구해야겠습니다!'),
(80301, '레이샤드를 이용한 실험은 완전히 무용지물로 판명되었습니다. 엘다라스 유적 주변의 레이샤드 자체가 불안정하여 사용하면 사라져 버립니다.\r\n\r\n에테리얼의 정수를 이용한 실험 역시 기대에 미치지 못했습니다.\r\n\r\n에너지는 있었지만, 그 에너지는 매우 미약했고, 마치 노움들이 말하는 것처럼 희미했습니다.'),
(80305, '형님, 안녕하십니까?\r\n\r\n편지가 형님에게 잘 도착했기를 바랍니다. 저는 스파크워터의 고블린들과 함께 일하며 잘 지내고 있습니다. 형님께서 제 사업이 어리석다고 하셨지만, 돈은 꽤 많이 벌고 있습니다!'),
(80306, '듀로서의 날씨는 여전히 덥고 태양이 몹시 뜨겁습니다.\r\n\r\n당신의 성공을 듣게 되어 기쁘고, 앞으로도 좋은 일만 가득하길 바랍니다.\r\n\r\n곧 소식을 들을 수 있기를 기대합니다. 계속 연락하며 지내요.\r\n\r\n루그나르.'),
(80308, '루그나르, 슬픔의 늪의 무성한 잡초 사이에서 네 글을 읽으니 참 좋았어.\r\n\r\n휴가를 받아 곧 오그리마로 떠날 예정이야. 오랜만에 만나게 되어 정말 기쁘고, 너에게 해주고 싶은 이야기가 많아.\r\n\r\n네 형제 줄'),
(80309, '제가 진행한 모든 계획 중 유일하게 성공한 것은 이 지역 천둥머리의 하늘폭풍뿔이었습니다. 그 에너지는 실로 엄청났으며, 스파크워터에서도 시험해 볼 가치가 충분합니다. 조만간 시험용 표본을 보내드리겠습니다!\r\n\r\n보고자: 가즈토글'),
(80310, '예언에 따르면 신들은 불충실한 자들을 버리고, 듣지 않는 자들을 파멸시킬 것이다.\r\n\r\n세상은 변하고 영혼들은 타락하여 내면에서 분열될 것이다.\r\n\r\n바위는 시들고, 바람은 사라지고, 물은 메말라 버릴 것이다. 종말의 경고에 귀 기울여라. 우리의 도움이 필요한 것은 바로 만물의 근원이기 때문이다.'),
(80311, '사장님, 배송이 늦어서 죄송합니다. 다음에는 절대 늦지 않도록 하겠습니다! 늦어진 것에 대한 보상으로 추가 금액을 동봉했습니다.\r\n\r\n타를로.'),
(80320, '스노우비어드 대위님께.\r\n\r\n아이언포지와 메네틸 항구를 잇는 보급선이 날로 위협받고 있습니다. 드래곤모 오크들의 공격으로 인해 보급품 수송대가 쉴 새 없이 바빠지고 있으며, 대위님께 도달하는 것조차 위험천만한 일이 되었습니다.\r\n\r\n드래곤모 오크들이 우리 땅을 위협하고 있는데, 이들을 소탕하기 위해서는 더 많은 지원이 절실히 필요합니다. 혹시 여분의 병력이 있다면 지금이 바로 지원해 주실 때입니다.\r\n\r\n스토우트피스트 대위 드림.'),
(80322, '스토우트피스트 대위님, 유감스럽게도 도움을 드릴 수 없게 되었습니다. 드래곤마우가 우리 둘 모두에게 위협적인 존재이긴 하지만, 산악 지역에 병력이 턱없이 부족하여 공격에 나설 여력이 없으며, 산악병들을 대위님께 보내드릴 수도 없습니다.\r\n\r\n이 문제를 잘 해결하시기를 바라며, 마그니의 수염을 걸고 아이언포지에서 우리 둘 모두에게 지원군이 오기를 간절히 기도합니다.\r\n\r\n아이언포지 군대 스노우비어드 대위 드림'),
(80324, '안녕하세요. PAGES의 바르토스입니다! 기울임 진동 방지기 두 개를 제작하는 데 필요한 부품은 다음과 같습니다.\r\n\r\n철제 지지대 16개\r\n강력한 자석 6개\r\n청동 회전 장치 2개\r\n퓨즈 배선 2개'),
(80325, '이게 전부일 겁니다!\r\n\r\n행운을 빌고, 서두르세요. 할 일이 많으니까요!\r\n\r\n바르토스 썬더크랙, 호크스 비질의 전설, 공학의 거장'),
(80326, '바르토스, 원로원이 호크스 비질로 향하는 이 모든 물자에 대해 알게 되면 몹시 화를 낼 겁니다. 공항 유지비가 만만치 않거든요! 제가 보내드린 물자를 최대한 오래 쓰신 후에 추가 요청을 하세요.\r\n\r\n당신의 친구, 오리온 콜본'),
(80327, '라몬 3세 공작께,\r\n\r\n다시 한번 모든 것에 감사드립니다. 제 안전을 위해 스톰윈드를 떠난 후로는 몸을 사려 깊게 해야 했습니다.\r\n\r\nSI:7이 저를 감시하고 있는 것 같지만, 지금까지는 발각되지 않고 방 안에 은둔해 있었음을 말씀드립니다.'),
(80328, '당신의 도움은 정말 결정적이었고, 그 끔찍한 감옥에서 제 목숨을 구해줬습니다.\r\n\r\n삼촌께서도 당신을 훌륭한 친구라고 부르셨다면 자랑스러워하셨을 겁니다. 곧 연락 주시기를 바랍니다. 제가 언제 이곳을 떠날 수 있을지 잘 모르겠습니다.\r\n\r\n친구, 마틴 코린스'),
(80329, '라이크 사령관님께\r\n\r\n이 봉투를 소지한 자에게 이 메시지를 전달하도록 위임했습니다.\r\n\r\n사령관님께서 조사하고 계신 할러스 애쉬버클은 가명을 사용하고 있으며, 그의 본명은 마틴 코린스입니다. 그는 로데론 출신으로 제3차 전쟁 발발 당시 탈출했습니다.\r\n\r\n마틴은 부유한 가문 출신으로 스톰윈드 귀족들과 긴밀한 관계를 맺고 있었습니다.'),
(80330, '그러한 인연 덕분에 마틴은 무고한 사람들을 살해하고 금지된 마법을 사용한 죄로 스톰윈드에서 처형당하는 것을 면할 수 있었습니다.\r\n\r\n만약 매의 감시소를 괴롭히는 사악한 마법이 있다면, 저는 그 책임이 마틴에게 있다고 의심할 것입니다.\r\n\r\n마틴 코린스는 감옥에서 풀려나면서 \'조건\'으로 스톰윈드에서 추방당했고, 얼라이언스가 점령한 모든 영역에서 흑마법을 포기해야 했습니다.'),
(80331, '스톰윈드의 재판권을 당신에게 넘겨주어 이 자에게 정의를 구현하게 하노라. 오랜 기다림 끝에 마침내 심판을 받게 될 것이다.\r\n\r\n그가 당신의 땅에 가져올지도 모르는 모든 어둠으로부터 땅을 해방시키시오.\r\n\r\n마티아스 쇼, 스톰윈드 7지부장'),
(1000063, '관중들은 진짜 전투를 보고 싶어 한다! 조작하지 마!'),
(1000243, '붉은 십자군의 방어벽, 재앙에 맞서다\r\n\r\n붉은 십자군의 성기사이자 은빛 손의 기사여, 적과의 전쟁에서 명예롭게 싸우셨도다.\r\n\r\n당신만큼 두려움 없이 끈질기게 임무를 수행한 사람은 없었소. 당신의 미덕은 모든 십자군에게 귀감이 되었고, 당신의 결정은 영원히 잊히지 않을 것이오.\r\n\r\n당신은 우리 십자군의 주먹이었으며, 악을 막아낸 방벽이었소.\r\n\r\n삶에서 보여주셨던 그 열정으로 새로운 시작을 향해 나아가시기를.'),
(1000244, '입문자의 서약\r\n\r\n나는 십자군에 헌신하고 그 대의를 위해 내 목숨을 바치겠다. 나는 의심 없이 복종하고, 내 백성을 위한 부름에 응하겠다.\r\n\r\n십자군 기사의 서약\r\n\r\n내 백성의 땅을 지키는 것이 나의 신조이다. 로데론은 십자군이며, 십자군은 로데론이다. 나는 전우들에게 해를 끼치는 모든 자에게 정의를 구현하겠다. 나는 과거의 영광을 되살리는 자이다.'),
(1000245, '기사의 서약\r\n\r\n고귀한 것은 내가 수호하리라.\r\n더럽혀진 것은 내가 파괴하리라.\r\n신성한 것은 내가 지키리라.\r\n\r\n형제자매들에게 이 맹세를 진실로 하리라.\r\n\r\n선교사의 서약\r\n\r\n옛 전통을 계승하고 거룩한 교회의 전통을 지키며, 이 성전에서 우리의 무기를 신성하게 하고 축복하는 것이 나의 임무이니라. 속이는 자들과 이단자들, 그리고 불신자들을 정화하는 것이 나의 사명이니라.'),
(1000246, '빛은 한때 생명과 아름다움으로 가득했던 이 황폐하고 재앙에 휩싸인 땅에서 우리를 지켜주는 수호자입니다. 우리는 어둠 속의 등불이며, 빛은 그 어둠을 막아내는 존재입니다. 빛은 과거의 영광과 우리가 만들어갈 새로운 로데론의 미래를 보여주는 빛나는 본보기입니다. 우리 기사단의 성기사와 사제들은 수많은 형제자매들이 목격했듯이, 그 위대함을 파괴적인 힘으로 휘두릅니다.\r\n\r\n우리는 바로 그 빛에 우리의 희망과 기도, 그리고 믿음을 두어야 합니다.'),
(1000247, '이 질서의 창조를 연결했던 등불이자, 수많은 고난과 시련 속에서도 여전히 우리를 하나로 묶어주는 버팀목입니다. 수없이 파멸의 위기를 넘기고, 우리 주변 왕국이 무너져 내리는 와중에도 우리는 굳건히 서 있습니다.\r\n\r\n만일 어둠이 덮쳐오는 때가 오더라도,'),
(1000248, '빛은 언제나 당신을 통해 비추고 있음을 기억하십시오. 당신의 희생은 빛의 은총으로 온전히 보상받을 것입니다.\r\n\r\n빛은 우리를 버리지 않으며, 잊지 않습니다. 이 빛을 영원히 우리 마음속에 간직합시다.\r\n\r\n세상이 아무리 어두워도, 빛은 언제나 다시 빛날 것입니다.\r\n\r\n~스크라이브 다폴트'),
(1772030, '그림 바톨 기념비\r\n\r\n이곳은 우리 역사상 가장 큰 역경에 맞서 무고한 사람들을 지키기 위해 싸우다 목숨을 바친 이들을 기리는 곳입니다. 한때 위대했던 우리 전당에서 침략자들에 맞서 싸우다 전사한 이들을 영원히 기억하겠습니다.\r\n\r\n당신들을 결코 잊지 않겠습니다.')
